  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N = ni()
    val P = Array.ofDim[Int](2, N + 1)
    REP(2 * N) { i =>
      val c = nc()
      val a = ni()
      val x = if (c == 'B') 0 else 1
      P(x)(a) = i + 1
    }

    val inv = Array.ofDim[Int](2, N + 1)
    REP(2) { x =>
      val bit = new BIT(2 * N, 0)(_+_)
      REP(N, 1) { i =>
        inv(x)(i) = i - 1 - bit.sum(P(x)(i))
        bit.add(P(x)(i) - 1, 1)
      }
    }

//    REP(2) { x =>
//      debug(s"inv[$x]")
//      debug(inv(x))
//    }

    val oppo = Array.ofDim[Int](2, N + 1, N + 1)
    REP(2) { x =>
      val bit = new BIT(2 * N, 0)(_+_)
      REP(N, 1) { i =>
        bit.clear()
        REP(N, 1) { j =>
          bit.add(P(x^1)(j) - 1, 1)
          oppo(x)(i)(j) = j - bit.sum(P(x)(i))
        }
      }
    }
//
//    REP(2) { x =>
//      debug(s"oppo[$x]")
//      REP(N + 1) { i =>
//        debug(oppo(x)(i))
//      }
//    }

    // i: B, j: W
    val dp = Array.fill[Int](N + 1, N + 1)(1e9.toInt)
    dp(0)(0) = 0

    REP(N + 1) { i =>
      REP(N + 1) { j =>
        if (i > 0) {
          val dest = i + j
          val cur = P(0)(i) + inv(0)(i) + oppo(0)(i)(j)
          val move = cur - dest
          dp(i)(j) = min(dp(i)(j), dp(i - 1)(j) + move)
        }
        if (j > 0) {
          val dest = i + j
          val cur = P(1)(j) + inv(1)(j) + oppo(1)(j)(i)
          val move = cur - dest
          dp(i)(j) = min(dp(i)(j), dp(i)(j - 1) + move)
        }
      }
    }

//    debug("DP")
//    REP(N + 1) { i =>
//      debug(dp(i))
//    }

    out.println(dp(N)(N))
  }


  class BIT(n: Int, zero: Int)(f: (Int, Int) => Int) {
    def this(n: Int) = this(n, 0)(_ + _)

    private val N = {
      val a = Integer.highestOneBit(n)
      if (a == n) a else a << 1
    }
    private val bit = if (zero != 0) Array.fill[Int](N + 1)(zero) else Array.ofDim[Int](N + 1)

    def clear(): Unit = {
      java.util.Arrays.fill(bit, zero)
    }

    /**
      * 1 index
      * addとindex違うよ
      * cumsumなんかといっしょ
      */
    def sum(i: Int): Int = {
      assert(i <= n)
      var x = i
      var s: Int = 0
      while(x > 0) {
        s = f(s, bit(x))
        x -= x & -x
      }
      s
    }

    /**
      * 0 index
      */
    def add(i: Int, a: Int): Unit = {
      assert(i < n)
      var x = i + 1
      while(x <= N) {
        bit(x) = f(bit(x), a)
        x += x & -x
      }
    }

    def sumAll: Int = sum(n)

    /**
      * [l, r)
      */
    def query(l: Int, r: Int)(sub: (Int, Int) => Int): Int = {
      assert(r > l)
      sub(sum(r), sum(l))
    }
  }

