int n;
PP p[4000];
int DP[2001][2001];
int main() {
  cin >> n;
  for (int i = 0; i < 2 * n; ++i) {
    int a = Next<char>() == 'B';
    int b = Next<int>() - 1;
    p[i] = PP(a, b);
  }

  for (int i = 0; i < 2 * n; ++i) {
    for (int j = 0; j < 2 * n; ++j) {
      DP[i][j] = INF;
    }
  }
  DP[0][0] = 0;

  for (int i = 0; i < 2 * n; ++i) {
    for (int j = 0; j < 2 * n; ++j) {
      int cnt = 0;
      for (int k = 0; k < 2 * n; ++k) {
        if (p[k].first == 0 && p[k].second == i) {
          DP[i + 1][j] = min(DP[i + 1][j], DP[i][j] + cnt);
        }
        if (p[k].first == 1 && p[k].second == j) {
          DP[i][j + 1] = min(DP[i][j + 1], DP[i][j] + cnt);
        }

        if (p[k].first == 0 && p[k].second >= i) ++cnt;
        if (p[k].first == 1 && p[k].second >= j) ++cnt;
      }
    }
  }

  cout << DP[n][n] << endl;
  return 0;
}

