#include <bits/stdc++.h>
using namespace std;

const int MAX = 2005;
int N, memo[MAX][MAX], cost[2][MAX][2*MAX], f[2][MAX];
pair<int, int> A[2*MAX];

int Solve(int a, int b) {
        if (a == N && b == N) return 0;

        int &ret = memo[a][b];
        if (ret != -1) return ret;

        ret = 1e8;
        if (a != N) ret = min(ret, Solve(a+1, b) + cost[0][a+1][f[0][a]] + cost[1][b][f[0][a]]);
        if (b != N) ret = min(ret, Solve(a, b+1) + cost[0][a][f[1][b]] + cost[1][b+1][f[1][b]]);
        return ret;
}

int main() {
        scanf("%d", &N);

        for (int i=0; i<2*N; ++i) {
                char c;
                scanf(" %c%d", &c, &A[i].second);
                A[i].first = c == 'B';
                A[i].second -= 1;
                f[A[i].first][A[i].second] = i;
        }

        for (int t=0; t<2; ++t) for (int num=0; num<N; ++num) {
                int x = 0;
                for (int i=0; i<2*N; ++i) {
                        if (A[i].first == t && A[i].second >= num)
                                ++x;
                        cost[t][num][i] = x;
                }
        }

        memset(memo, -1, sizeof(memo));
        printf("%d\n", Solve(0, 0));
        return 0;
}

