struct Node
{
	int mode;
	int val;
	Node* pre;
	Node* nxt;
	Node():pre(NULL),nxt(NULL){};
};

typedef Node* node;
inline node newnode(){return new Node();}
inline void link(node nd)//Link a node after nd
{
	nd->nxt->pre=newnode();
	nd->nxt->pre->nxt=nd->nxt;
	nd->nxt->pre->pre=nd;
	nd->nxt=nd->nxt->pre;
}
inline void del(node nd)//Delete the node after nd
{
	nd->nxt=nd->nxt->nxt;
	delete nd->nxt->pre;
	nd->nxt->pre=nd;
}

node head,tail;
int n;
int ans=0;
int xx[2]={1,1};

int main()
{
	n=read();
	head=newnode();
	tail=newnode();
	head->nxt=tail;
	tail->pre=head;
	for(int i=0;i<2*n;i++)
	{
		char c;
		int d;
		scanf(" %c%d",&c,&d);
		link(tail->pre);
		tail->pre->mode=(c=='B');
		tail->pre->val=d;
	}
	for(node it=head->nxt;it!=tail;it=it->nxt)
	{
		node it2;
		int cnt=0;
		for(it2=it;it2!=tail;it2=it2->nxt,cnt++)
			if(xx[it2->mode]==it2->val)
				break;
		xx[it2->mode]++;
		ans+=cnt;
		link(it->pre);
		it->pre->mode=it2->mode;
		it->pre->val=it2->val;
		it=it->pre;
		del(it2->pre);
	}
	printf("%d\n",ans);
	return 0;
}

