void in(){
    ios::sync_with_stdio(false);
    cout.tie(0);
    cin.tie(0);
    cin >> n;
    for(long long i = 0; i < 2 * n; i++){
        char c;
        cin >> c >> a[i];
        if(c == 'W')
            idx[a[i] - 1][0] = i + 1;
        else
            idx[a[i] - 1][1] = i + 1;
    }
}

void solve(){
    while(now[0] + now[1] < 2 * n){
        if(now[0] == n)
            swp(1);
        else if(now[1] == n)
            swp(0);
        else{
            if(idx[now[0]][0] < idx[now[1]][1])
                swp(0);
            else
                swp(1);
        }
    }
}

void swp(long long color){
    add(idx[now[color]][color]);
    ans += idx[now[color]][color] - get(idx[now[color]][color]);
    now[color]++;
}

void add(long long x){
    for(; x < maxn; x += x & -x)
        fen[x] += 1;
}

long long get(long long x){
    long long s = 0;
    for(; x; x -= x & -x)
        s += fen[x];
    return s;
}

void out(){
    cout << ans;
}

