void update(int t, int l, int r, int br, int code)
{
    seg[code][t]++;
    if(l==r)
        return;
    int mid=(l+r)/2;
    if(br<=mid) update(2*t,l,mid,br,code);
    else update(2*t+1,mid+1,r,br,code);
}

int sum(int t, int l, int r, int L, int R, int code)
{
    if(l>=L && r<=R)
        return seg[code][t];
    if(L>r || l>R)
        return 0;
    int mid=(l+r)/2;
    int s1=sum(2*t,l,mid,L,R,code);
    int s2=sum(2*t+1,mid+1,r,L,R,code);
    return s1+s2;
}



