int lowbit(int x) {return x & (-x);}
void Insert(int id,int x) {
    while(x <= N) {
	tr[id][x]++;
	x += lowbit(x);
    }
}
int Query(int id,int x) {
    int res = 0;
    while(x > 0) {
	res += tr[id][x];
	x -= lowbit(x);
    }
    return res;
}
void Solve() {
