	    Insert(0,a[i]);
	}
	else {
	    for(int j = 0 ; j <= N ; ++j) {
		cost[1][j][a[i] - 1] =  (i - 1) - Query(0,j) - Query(1,a[i] - 1);
	    }
	    Insert(1,a[i]);
	}
