int apos[MAXN][2];
int dp[MAXN][MAXN][2];
Fenwick f[2];
int inv[MAXN];
int sum[MAXN][MAXN];

int calc(int pos, int num, int col) {
  int& res = dp[pos][num][col];
  if (res != -1) {
    return res;
  }
  res = 0;
  int otherNum = pos + 1 - num;
  if (pos == n) {
    return res;
  }
  if (otherNum > n / 2 || num > n / 2) {
    res = 1e9;
    return res;
  }
  int curPos = apos[num][col];
  res = inv[curPos];
  res += sum[curPos][otherNum + 1];
  res += min(calc(pos + 1, num + 1, col), calc(pos + 1, otherNum + 1, 1 - col));
  return res;
}

