int n;
vector<int> b, w;
vector<vector<int>> memo, dp, cntb, cntw;

int solve();

int main() {
  cin >> n;
  memo.assign(n, vector<int>(n, 0));
  cntb.assign(n, vector<int>(n + 1, 0));
  cntw.assign(n, vector<int>(n + 1, 0));
  for (int i = 0; i < 2 * n; ++i) {
    char c;
    int a;
    cin >> c >> a;
    --a;
    if (c == 'W') {
      w.push_back(a);
      for (auto p : b) memo[a][p] = 1;
    } else
      b.push_back(a);
  }
  cout << solve() << endl;
  return 0;
}

int solve() {
  auto bubble = [](vector<int> v) {
    int res = 0;
    for (int i = 0; i < n; ++i)
      for (int j = i + 1; j < n; ++j) res += v[i] > v[j];
    return res;
  };
  dp.assign(n + 1, vector<int>(n + 1, (int)1e8));
  dp[0][0] = 0;
  // w
  for (int i = 0; i < n; ++i)
    for (int j = n - 1; j >= 0; --j) {
      cntw[i][j] = memo[i][j];
      cntw[i][j] += cntw[i][j + 1];
    }
  // b
  for (int i = 0; i < n; ++i)
    for (int j = n - 1; j >= 0; --j) {
      cntb[i][j] = !memo[j][i];
      cntb[i][j] += cntb[i][j + 1];
    }
  for (int i = 0; i <= n; ++i)
    for (int j = 0; j <= n; ++j) {
      if (i != 0) dp[i][j] = min(dp[i][j], dp[i - 1][j] + cntw[i - 1][j]);
      if (j != 0) dp[i][j] = min(dp[i][j], dp[i][j - 1] + cntb[j - 1][i]);
    }
  return dp[n][n] + bubble(b) + bubble(w);
}

