	if (wid == N && bid == N) return 0;
	if (mem[wid][bid] != -1) return mem[wid][bid];
	int w = 1000000000;
	if (wid < N) {// use white
		int pos = WP[wid] + WWLR[wid][wid] + WBLR[wid][bid];
