template <typename T>
class Bit{
    private:
        V<T> data;
        T identity_ele;

    public:

        Bit(ll size, T identity_ele) {
            ll newsize = 1;
            while(newsize < size)  newsize = newsize << 1;
            this->identity_ele = identity_ele;
            data = V<T>(newsize + 1, identity_ele);
        }

        /*
         * 0-origin
         */
        T sum(ll pos) {
            T ret = identity_ele;
            pos++;
            while(pos > 0) {
                ret += data[pos];
                pos -= pos & -pos;
            }
            return ret;
        }

        /*
         * 0-origin
         */
        void add(ll pos, T delta) {
            pos++;
            while(pos <= data.size()) {
                data[pos] += delta;
                pos += pos & -pos;
            }
        }
};

