void Update(int ind, int val)
{
	for (int i = ind; i < Maxm; i += i & -i)
		BIT[i] += val;
}

int Get(int ind)
{
	int res = 0;
	for (int i = ind; i > 0; i -= i & -i)
		res += BIT[i];
	return res;
}

