#include <bits/stdc++.h>

using namespace std;

using int64 = long long;
const int64 INF = 1LL << 60;

template< class T >
struct BinaryIndexedTree {
  vector< T > data;

  BinaryIndexedTree(int sz) {
    data.assign(++sz, 0);
  }

  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  void add(int k, T x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }
};

int N;
int luz[2000], hiled[2000];
int64 dp[2001][2001];
BinaryIndexedTree< int > bit(4001);

int64 rec(int x, int y) {
  int z = x + y;
  if(z == 2 * N) return 0;
  if(~dp[x][y]) return dp[x][y];
  int64 ret = INF;
  if(x < N) {
    bit.add(luz[x], 1);
    ret = min(ret, rec(x + 1, y) + z - bit.sum(luz[x] - 1));
    bit.add(luz[x], -1);
  }
  if(y < N) {
    bit.add(hiled[y], 1);
    ret = min(ret, rec(x, y + 1) + z - bit.sum(hiled[y] - 1));
    bit.add(hiled[y], -1);
  }
  return dp[x][y] = ret;
}

