  cin >> N;
  for(int i = 0; i < 2 * N; i++) {
    char c;
    int a;
    cin >> c >> a;
    if(c == 'W') luz[--a] = i;
    else hiled[--a] = i;
  }
  memset(dp, -1, sizeof(dp));
  cout << rec(0, 0) << endl;
}

