const int MAX_N = 4400;

struct BIT {
    int bit[MAX_N + 1] = {}, n;

    void init(int n_) {
        n = n_;
    }

    int sum(int i) {
        int s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x) {
        while (i <= n) {
            bit[i] += x;
            i += i & -i;
        }
    }
};

BIT black, white;
int dp[2200][2200];

int DP(int b, int w) {
    if (b == 0 && w == 0) return 0;
    if (dp[b][w] != -1) return dp[b][w];
    int res = 1145141919;
    if (b != 0) {
        int cur = b + w - bAry[b] - bTable[b][w] - 1;
        cur += DP(b - 1, w);
        res = min(res, cur);
    }
    if (w != 0) {
        int cur = b + w - wAry[w] - wTable[w][b] - 1;
        cur += DP(b, w - 1);
        res = min(res, cur);
    }
    return dp[b][w] = res;
}

