using pii = pair<int, int>;

constexpr int inf = 1e9;

// 0-indexed
template <typename T>
class fenwick_tree {
public:
    fenwick_tree(int n) : n(n), dat(n, 0) {}

    void add(int i, T value) {
        for(; i<n; i |= i + 1) {
            dat[i] += value;
        }
    }

    T sum(int i) const {
        T res = 0;
        for(; i>=0; i = (i & (i+1)) - 1) {
            res += dat[i];
        }
        return res;
    }
    // [l, r)
    T sum(int l, int r) const {
        return sum(r-1) - sum(l-1);
    }

private:
    const int n;
    std::vector<T> dat;
};

int main() {
    int n;
    cin >> n;
    n = 2 * n;
    vector<char> c(n);
    vector<int> a(n);
    vector<pii> b, w;
    for(int i = 0; i < n; ++i) {
        cin >> c[i] >> a[i];
        if(c[i] == 'B') {
            b.emplace_back(a[i], i);
        } else {
            w.emplace_back(a[i], i);
        }
    }
    sort(begin(b), end(b));
    sort(begin(w), end(w));

    const int wn = w.size();
    const int bn = b.size();

    vector<vector<int>> cnt_w(wn + 1, vector<int>(bn + 1)), cnt_b(bn + 1, vector<int>(wn + 1));
    for(int i = 0; i < wn; ++i) {
        int cnt = 0;
        for(int j = 0; j < i; ++j) {
            if(w[i].second < w[j].second) {
                cnt += 1;
            }
        }
        fenwick_tree<int> bit(n + 1);
        for(int j = 0; j <= bn; ++j) {
            cnt_w[i][j] = cnt + bit.sum(0, w[i].second);
            bit.add(0, 1);
            bit.add(b[j].second, -1);
        }
    }
    for(int i = 0; i < bn; ++i) {
        int cnt = 0;
        for(int j = 0; j < i; ++j) {
            if(b[i].second < b[j].second) {
                cnt += 1;
            }
        }
        fenwick_tree<int> bit(n + 1);
        for(int j = 0; j <= wn; ++j) {
            cnt_b[i][j] = cnt + bit.sum(0, b[i].second);
            bit.add(0, 1);
            bit.add(w[j].second, -1);
        }
    }

    vector<vector<int>> dp(n + 1, vector<int>(bn + 1, inf));
    dp[0][0] = 0;
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j <= bn; ++j) {
            if(i - j < 0) continue;
            if(dp[i][j] == inf) continue;
            if(j + 1 <= bn) {
                int bp = b[j].second + cnt_b[j][i - j];
                dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + max(0, bp - i));
            }
            if(i - j < (int)w.size()) {
                int wp = w[i - j].second + cnt_w[i - j][j];
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + max(0, wp - i));
            }
        }
    }
    //for(int i = 0; i <= n; ++i) {
    //    for(int j = 0; j <= bn; ++j) {
    //        cout << dp[i][j] << ' ';
    //    }
    //    cout << endl;
    //}

    cout << dp[n][bn] << endl;
}

