	if(b == 0 && w == 0) {
		return 0;
	}
	if(dp[b][w] != -1) return dp[b][w];
	vector<pair<int,int> > v;
	for(int i = 0;i < 2*n;i++) {
		if(a[i].second == 1) {
			if(a[i].first > n-b) {
				v.push_back(a[i]);
			}
