		for(auto it : v) {

			if(it.second == 1 && it.first == n-b+1) {
				break;
			}
			cnt++;
		}
		ans = min(ans,rec(b-1,w) + cnt);
	}
	if(w > 0) {
		int cnt = 0;
		for(auto it : v) {
			if(it.second == 2 && it.first == n-w+1) {
				break;
			}
			cnt++;
		}
		ans = min(ans,rec(b,w-1) + cnt);
	}
	// cout << b << " " << w << " " << ans << endl;
	return dp[b][w] = ans;
}
