int main() {
    scanf("%d", &n);
    for (int i = 1; i <= 2 * n; i++) {
        scanf("%s %d", s[i], &a[i]);
        if (s[i][0] == 'W') pos1[a[i]] = i;
        else pos2[a[i]] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (pos1[j] > pos1[i]) c1[i][0]++;
        }
        for (int j = 1; j <= n; j++) {
            c1[i][j] = c1[i][j - 1] + (pos2[j] > pos1[i]);
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (pos2[j] > pos2[i]) c2[0][i]++;
        }
        for (int j = 1; j <= n; j++) {
            c2[j][i] = c2[j - 1][i] + (pos1[j] > pos2[i]);
        }
    }
    for (int i = 0; i <= n; i++) {
