//Be careful 1-indexed
template<typename T>
struct BinaryIndexedTree{
    private:
    vector<T> dat;
    public:
    BinaryIndexedTree(int sz){
        dat.assign(++sz,0);
    }
    void add(int k,T x){
        for (;k<=dat.size();k+=k&-k) dat[k]+=x;
    }
    T sum(int k){
        T ret=0;
        for (;k>0;k-=k&-k) ret+=dat[k];
        return ret;
    }
    int lower_bound(T x){
        if (x<=0) return 0;
        int lb=0,r=1;
        while(r<dat.size()) r<<=1;
        for (;r>0;r>>=1){
            if (lb+r<dat.size()&&dat[lb+r]<x){
                x-=dat[lb+r];
                lb+=r;
            }
        }
        return lb+1;
    }
    T query(int l,int r){ //[l,r)
        return sum(r-1)-sum(l-1);
    }
};

