			if(i>0) dp[i][j]=min(dp[i][j],dp[i-1][j]+cnt[i][j]);
			else dp[i][j]=min(dp[i][j],cnt[i][j]);
		}
	}
	ll tmp=INF*INF;
	REP(i,n+1) tmp=min(tmp,dp[n-1][i]);
	cout<<ans+tmp<<endl;
}

