  // dp[i][j] = (黒のi,白のjまで置いたときの転倒数のmin)
  // dp[i][j] = min(dp[i-1][j]+黒のiについてのコスト,dp[i][j-1]+白のjについてのコスト)
  // 黒のiをi+j+1番目に置くときにかかるコストがO(1)で知りたいので前計算しておく
  // cost_b[i][j] = 初期状態で黒のiより右にある 黒のi未満 or 白のj以下 の個数
  // cost_w[i][j] = 初期状態で白のjより右にある 黒のi以下 or 白のj未満 の個数

  ll n;
  cin >> n;
  vector<char> c(2*n);
  vector<ll> a(2*n);
  REP(i, 2*n) cin >> c[i] >> a[i], a[i];

  // cout << c << endl << a << endl;

  auto cost_b = make_v<ll>(n+1, n+1);
  auto cost_w = make_v<ll>(n+1, n+1);
  BIT<ll> black(n+1), white(n+1);
  for(ll i=2*n-1; i>=0; --i) {
    if(c[i]=='B') {
      REP(j, n+1) {
        cost_b[a[i]][j] = black.query(a[i]-1) + white.query(j);
      }
      black.update(a[i], 1);
    } else {
      REP(j, n+1) {
        cost_w[j][a[i]] = black.query(j) + white.query(a[i]-1);
      }
      white.update(a[i], 1);
    }
    // REP(j, n+1) cout << black.query(j) << " ";
    // cout << endl;
    // REP(j, n+1) cout << white.query(j) << " ";
