  // cout << endl;

  auto dp = make_v<ll>(n+1, n+1);
  fill_v(dp, INF);
  dp[0][0] = 0;
  REP(i, n+1) REP(j, n+1) {
    if(i) chmin(dp[i][j], dp[i-1][j] + cost_b[i][j]);
    if(j) chmin(dp[i][j], dp[i][j-1] + cost_w[i][j]);
  }
  cout << dp[n][n] << endl;

  return 0;
}

