const int INF = 1 << 30;

int main() {
    int N; cin >> N;
    vector<pair<char, int>> A(2 * N);
    vector<int> idx_b(N), idx_w(N);
    for(int i = 0; i < 2 * N; ++i) {
        char c; int a; cin >> c >> a;
        A[i] = make_pair(c, a);
        if(c == 'B') idx_b[a] = i;
        else idx_w[a] = i;
    }

    vector<vector<int>> sum_b(N + 1, vector<int>(2 * N + 1));
    vector<vector<int>> sum_w(N + 1, vector<int>(2 * N + 1));
    for(int x = 0; x <= N; ++x) {
        for(int i = 0; i < 2 * N; ++i) {
            if(A[i].first == 'B') sum_b[x][i] += (A[i].second > x);
            else sum_w[x][i] += (A[i].second > x);
            sum_b[x][i + 1] = sum_b[x][i];
            sum_w[x][i + 1] = sum_w[x][i];
        }
    }

    vector<vector<int>> dp(N + 1, vector<int>(N + 1, INF));
    dp[0][0] = 0;

    auto f = [&](auto &&f, int b, int w) -> int {
        if(dp[b][w] != INF) return dp[b][w];
        if(b) dp[b][w] = min(dp[b][w], f(f, b - 1, w) + sum_b[b][idx_b[b]] + sum_w[w][idx_b[b]]);
        if(w) dp[b][w] = min(dp[b][w], f(f, b, w - 1) + sum_b[b][idx_w[w]] + sum_w[w][idx_w[w]]);
        return dp[b][w];
    };
    cout << f(f, N, N) << '\n';
    return 0;
}

