inline void update(int pos, int val) {
    for(int i = pos; i <= 2 * n; i += lsb(i))
        aib[i] += val;
}

inline int query(int pos) {
    int ans = 0;
    for(int i = pos; i > 0; i -= lsb(i))
        ans += aib[i];
    return ans;
}

