    rep(j,4005){
      dp[j][i] = INF;

      cW += baseW[j];
      cB += baseB[j];
      cntW[i][j] = cW;
      cntB[i][j] = cB;
    }
    int pW = posW[i+1]-1;
    if(pW >= 0) baseW[pW] = 1;
