struct Ball {
        char color;
        int num;

        Ball(char color, int num) {
                this->color = color;
                this->num = num;
        }

        Ball operator=(const Ball &rhs) {
                this->color = rhs.color;
                this->num = rhs.num;
                return *this;
        }
};

int white_costs[2005][2005];  // (white, black)
int black_costs[2005][2005];  // (black, white)
int dp[2005][2005];  // (white, black)

void f(int white, int black)
{
        if (dp[white][black] >= 0) return;
        if (white == 0 && black == 0) {
                dp[0][0] = 0;
                return;
        }

        int ret1 = 3000;
        int ret2 = 3000;

        if (white > 0) {
                f(white-1, black);
                ret1 = dp[white-1][black] + white_costs[white-1][black];
        }
        if (black > 0) {
                f(white, black-1);
                ret2 = dp[white][black-1] + black_costs[black-1][white];
        }

        dp[white][black] = min(ret1, ret2);
}

int _main()
{
        ll n;
        llin(n);

        V<Ball> balls;
        rep (i, 2 * n) {
                char c; int a;
                CIN(c); CIN(a);
                balls.pb(Ball(c, a));
        }

        bool white_found[n+1];
        bool black_found[n+1];
        memset(white_found, 0, sizeof(white_found));
        memset(black_found, 0, sizeof(black_found));
        memset(white_costs, 0, sizeof(white_costs));
        memset(black_costs, 0, sizeof(black_costs));

        rep (i, 2 * n) {
                char color = balls[i].color;
                int num = balls[i].num;

                int cost = 0;
                srep (j, num, n+1) {
                        if (color == 'W' && white_found[j]) cost++;
                        if (color == 'B' && black_found[j]) cost++;
                }
                rrep (j, n+1) {
                        if (color == 'W') {
                                white_costs[num-1][j] = cost;
                                if (black_found[j]) cost++;
                        }
                        if (color == 'B') {
                                black_costs[num-1][j] = cost;
                                if (white_found[j]) cost++;
                        }
                }

                if (color == 'W') white_found[num] = true;
                if (color == 'B') black_found[num] = true;
        }

        rep (i, 2005) rep (j, 2005) dp[i][j] = -1;
        f(n, n);
        cout << dp[n][n];

        return 0;
}

