using namespace std;

const int INF = (1 << 30);

typedef long long ll;
typedef unsigned long long ull;
typedef pair <int, int> pii;

bool solve() {
  int n;
  if (scanf("%d", &n) != 1) { return false; }
  vector <int> pos1(n + 1), pos2(n + 1);
  for (int i = 0; i < 2 * n; ++i) {
    char ch;
    int x;
    scanf(" %c%d", &ch, &x);
    if (ch == 'B') {
      pos1[x] = i;
    } else {
      pos2[x] = i;
    }
  }
  int res = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = i + 1; j <= n; ++j) {
      if (pos1[i] > pos1[j]) {
        res++;
      }
      if (pos2[i] > pos2[j]) {
        res++;
      }
    }
  } 

  vector <vector<int>> inv1(n + 1, vector<int>(n + 1, 0));
  vector <vector<int>> inv2(n + 1, vector<int>(n + 1, 0));
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      inv1[i][j] = inv1[i - 1][j];
      inv2[i][j] = inv2[i][j - 1];
      if (pos1[i] > pos2[j]) {
        inv1[i][j] += 1;
      }
      if (pos2[j] > pos1[i]) {
        inv2[i][j] += 1;
      }
    }
  }

  vector <vector<int>> dp(n + 1, vector <int>(n + 1, INF));
  dp[0][0] = 0;
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= n; ++j) {
      if (i) {
        dp[i][j] = min(dp[i][j], dp[i - 1][j] + inv2[i][j]);
      }
      if (j) {
        dp[i][j] = min(dp[i][j], dp[i][j - 1] + inv1[i][j]);
      }
    }
  }
  printf("%d\n", res + dp[n][n]);
  return true;
}

int main() {
  while (solve());
  return 0;
}

