int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    V<int> a(2 * n);
    V<char> bw(2 * n);
    for (int i = 0; i < 2 * n; i++) cin >> bw[i] >> a[i];

    V< V<int> > black(n + 1, V<int>(n + 1, 0)), white(n + 1, V<int>(n + 1, 0));
    V<int> bcnt(n + 2, 0), wcnt(n + 2, 0);
    for (int i = 0; i < 2 * n; i++) {
        // bacc[j], wacc[j]: 各色の今までに出てきた j 以上の数
        V<int> bacc = bcnt, wacc = wcnt;
        for (int j = n - 1; j >= 0; j--) {
            bacc[j] += bacc[j + 1];
            wacc[j] += wacc[j + 1];
        }

        if (bw[i] == 'B') {
            for (int j = 0; j <= n; j++) {
                black[a[i]][j] = bacc[a[i]] + wacc[j + 1];
            }
        } else {
            for (int j = 0; j <= n; j++) {
                white[j][a[i]] = wacc[a[i]] + bacc[j + 1];
            }
        }
        (bw[i] == 'B' ? bcnt : wcnt)[a[i]]++;
    }

    // dp[i][j]: 黒を i 個、白を j 個詰めるための回数
    V< V<int> > dp(n + 1, V<int>(n + 1, INF));
    dp[0][0] = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i == 0 && j == 0) continue;
            if (i > 0) chmin(dp[i][j], dp[i - 1][j] + black[i][j]);
            if (j > 0) chmin(dp[i][j], dp[i][j - 1] + white[i][j]);
        }
    }
    cout << dp[n][n] << '\n';
    return 0;
}

