template<typename T>
struct BIT {
  vector<T> bit;
  const int sz;

  BIT(int n) : bit(n+1, 0), sz(n) {}

// [1, i] 1-indexed
  T sum(int i) {
    T s = 0;
    while (i > 0) { s += bit[i]; i -= i & -i; }
    return s;
  }

// [l, r] 1-indexed
  T sum(int l, int r) {
    return sum[r] - sum[l-1];
  }

  void add(int i, T x) {
    while (i <= sz) { bit[i] += x; i += i & -i; }
  }
};

void solve() {
  int n; cin >> n;
  Graph<int> g(2, vi(n+1));
  rep(i,2*n) {
    char c; int a; cin >> c >> a;
    g[c=='B'][a] = i;
  }

  Spacial<int> cost(2, Graph<int>(n+1, vi(n+1)));
  rep(c,2) {
    BIT<int> bit(2*n);
    rep1eq(i,n) {
      cost[c][i][0] = g[c][i] - bit.sum(g[c][i]);
      bit.add(g[c][i]+1, 1);
      rep1eq(j,n) {
        cost[c][i][j] = cost[c][i][j-1] - (g[1-c][j] < g[c][i]);
      }
    }
  }

  Graph<int> dp(n+1, vi(n+1, 1e8));
  dp[0][0] = 0;
  repeq(i,n) {
    repeq(j,n) {
      if (i) chmin(dp[i][j], dp[i-1][j] + cost[0][i][j]);
      if (j) chmin(dp[i][j], dp[i][j-1] + cost[1][j][i]);
    }
  }

  cout << dp[n][n] << endl;
}


