            if(w < n) dp[w + 1][b] = min(dp[w + 1][b], dp[w][b] + ww[w + 1] + wb[w + 1][b]);
            if(b < n) dp[w][b + 1] = min(dp[w][b + 1], dp[w][b] + bb[b + 1] + bw[b + 1][w]);
        }
    }
    cout << dp[n][n] << endl;
}

