template <class Integral = std::size_t> class irange {
	const Integral f, l;

public:
	using value_type = Integral;
	using reference = value_type;
	class irangeitr {
		friend irange;
		value_type i;
		irangeitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { ++i; }
		reference operator*() const noexcept { return i; }
		bool operator!=(const irangeitr &x) const noexcept { return i != x.i; }
	};
	irange(value_type first, value_type last) noexcept : f(first), l(last) {}
	irangeitr begin() const noexcept { return irangeitr(f); }
	irangeitr end() const noexcept { return irangeitr(l); }
};
template <class Integral = std::size_t> class Rirange {
	const Integral f, l;

public:
	using value_type = Integral;
	using reference = value_type;
	class Rirangeitr {
		friend Rirange;
		value_type i;
		Rirangeitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { --i; }
		reference operator*() const noexcept { return i - 1; }
		bool operator!=(const Rirangeitr &x) const noexcept { return i != x.i; }
	};
	Rirange(value_type first, value_type last) noexcept : f(first), l(last) {}
	Rirangeitr begin() const noexcept { return Rirangeitr(l); }
	Rirangeitr end() const noexcept { return Rirangeitr(f); }
};
