int main() {
	const auto n = IO.input<uint32>();
	SegmentTree<uint32> T(n<<1);
	std::vector<uint32> b(n), w(n);
	for (const auto i : irange<>(0, n << 1)) {
		char c;
		uint32 a;
		IO >> c >> a;
		--a;
		if (c == 'W')
			w[a] = i;
		else
			b[a] = i;
	}
	for (const auto i : irange<>(0, n<<1)) {
		T.update(i, 1);
	}
	uint64 ans = 0;
	uint32 bit = 0, wit = 0;
	while (bit < n||wit < n) {
		if (bit == n) {
			ans += T.range(0, w[wit]);
			T.update(w[wit], 0);
			++wit;
		}
		else if (wit == n) {
			ans += T.range(0, b[bit]);
			T.update(b[bit], 0);
			++bit;
		}
		else if (b[bit] < w[wit]) {
			ans += T.range(0, b[bit]);
			T.update(b[bit], 0);
			++bit;
		}
		else {
			ans += T.range(0, w[wit]);
			T.update(w[wit], 0);
			++wit;
		}
	}
	IO << ans;
	IO.endl();
	return 0;
}

