const int INF = 1e18+1;
const int MOD = 1e9+7;
const double PI = 3.14159265358979323846264338;

int raise(int a,int n,int m = MOD){
  if(n == 0)return 1;
  if(n == 1)return a;
  int x = 1;
    x *= raise(a,n/2,m);
    x %= m;
    x *= x;
    x %= m;
    if(n%2)x*= a;
    x %= m;
    return x;
}

int floor1(int n,int k){
    if(n%k == 0 || n >= 0)return n/k;
    return (n/k)-1;
}

int ceil1(int n,int k){
    return floor1(n+k-1,k);
}

const int N = 2001;
int dp[N][N];
int a[2*N];
int pos[2][N];
int hehe[2*N];
int color[2*N];
int before[2*N][N];
int n;

int whatif(int color,int keepwhere,int placed){
	//cout << color << " " << keepwhere << " " << placed << endl;
	int ind = pos[color][keepwhere];
	int samecolor = hehe[ind];
	int deserve = before[ind][placed];
	//cout << ind << " " << samecolor << " " << deserve << endl;
	return ind-samecolor-deserve-1;
}

void solve(){
  	cin >> n;
  	RE(i,2*n){
  		char o;int x;cin >> o >> x;
  		//cout << (bool)(o == 'B') << " " << x << endl;
  		pos[o == 'B'][x] = i;
  		a[i] = x;
  		color[i] = (o == 'B');
  	}
  //	cout << pos[1][1] << endl;
  	int inv = 0;
  	RE(i,2*n){
  		RE(j,i-1){
  			if(color[j] == color[i]){
  				inv += a[i]<a[j];
  				hehe[i]++;
  				continue;
  			}
  			before[i][a[j]] = 1;
  		}
  		RE(j,n){
  			before[i][j] += before[i][j-1];
  		}
  	}
  	dp[0][0] = 0;
  	//dp[1][0] = whatif(0,1,0);
  	//dp[0][1] = whatif(1,1,0);
  	REP(i,n+1){
  		REP(j,n+1){
  			if(i+j == 0)continue;
  			int case1 = INF;
  			int case2 = INF;
  			if(i)case1 = dp[i-1][j]+whatif(0,i,j);
  			if(j)case2 = dp[i][j-1]+whatif(1,j,i);
  			dp[i][j] = min(case1,case2);
  		}
  	}
  	RE(i,n){
  		RE(j,n){
  	//		cout << i << " " << j << " " << dp[i][j] << endl;
  		}
  	}
  	cout << dp[n][n]+inv;
}

