using namespace std;

struct tacka
{
    int b, x;
};
tacka niz[4010];
int seg[2][40010];
int br[2][4010][4010];
int inv[2][4010];
int dp[4010][4010];

void update(int boja, int t, int start, int end, int ind, int val)
{
    if(start == end)
    {
        seg[boja][t] += val;
        return;
    }
    int mid = (start + end) / 2;
    if(ind <= mid) update(boja, 2*t, start, mid, ind, val);
    else update(boja, 2*t+1, mid+1, end, ind, val);
    seg[boja][t] = seg[boja][2*t] + seg[boja][2*t + 1];
}

int query(int boja, int t, int start, int end, int l, int r)
{
    //if(start == end) return seg[boja][t];
    if(start > r || end < l) return 0;
    if(start >= l && end <= r) return seg[boja][t];
    int mid = (start + end) / 2;
    int x1 = query(boja, 2*t, start, mid, l, r);
    int x2 = query(boja, 2*t+1, mid+1, end, l, r);
    return x1 + x2;
}


int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    for(int i = 1; i <= 2*n; i++)
    {
        tacka t;
        char c;
        cin >> c;
        cin >> t.x;
        if(c == 'W') t.b = 0;
        else t.b = 1;
        niz[i] = t;
    }

    for(int i = 1; i <= 2*n; i++)
    {
        inv[niz[i].b][niz[i].x] = query(niz[i].b, 1, 1, n, niz[i].x + 1, n);
        for(int k = 0; k < n; k++)
            br[niz[i].b][niz[i].x][k] = query((niz[i].b + 1)%2, 1, 1, n, k + 1, n);
        update(niz[i].b, 1, 1, n, niz[i].x, 1);
    }

    dp[0][0] = 0;
    for(int i = 1; i <= n; i++) dp[0][i] = dp[0][i-1] + inv[1][i] + br[1][i][0];
    for(int i = 1; i <= n; i++) dp[i][0] = dp[i-1][0] + inv[0][i] + br[0][i][0];

    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= n; j++)
            dp[i][j] = min(dp[i-1][j] + br[0][i][j] + inv[0][i], dp[i][j-1] + br[1][j][i] + inv[1][j]);
    cout << dp[n][n];

    return 0;
}

