		for (int h = 0; h <= i; h++) {
			if (color[i] == 'W') cnt_w[h][a[i]]++;
			else cnt_b[h][a[i]]++;
		}
	}
	REP(i, n * 2) {
		for (int j = 1; j<(n * 2); j++) {
			cnt_w[i][j] += cnt_w[i][j - 1];
			cnt_b[i][j] += cnt_b[i][j - 1];
		}
