			if (i - 1 >= 0) cost_w += cnt_w[pos_w[i]][i - 1];
			if (j - 1 >= 0) cost_w += cnt_b[pos_w[i]][j - 1];
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + cost_w);
