		if (j<n) {
			int cost_b = 0;
			if (j - 1 >= 0) cost_b += cnt_b[pos_b[j]][j - 1];
			if (i - 1 >= 0) cost_b += cnt_w[pos_b[j]][i - 1];
			dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + cost_b);
		}
	}
	cout << dp[n][n] << endl;
}

