		for(int j=0;j<=n;j++) {
			black_lt[i][j] = black_lt[i-1][j];
			if(black[i-1] && a[i-1] < j) black_lt[i][j]++;
			white_lt[i][j] = white_lt[i-1][j];
			if(!black[i-1] && a[i-1] < j) white_lt[i][j]++;
		}
	}
	for(int i=0;i<2*n;i++) {
		if(black[i]) {
			for(int j=0;j<=n;j++) {
				costb[a[i]][j] = a[i] + j - black_lt[i][a[i]] - white_lt[i][j];
			}
		} else {
			for(int j=0;j<=n;j++) {
				costw[j][a[i]] = j + a[i] - black_lt[i][j] - white_lt[i][a[i]];
			}
		}
	}
	dp[0][0] = 0;
	for(int i=1;i<=n;i++) {
		dp[i][0] = dp[i-1][0] + costb[i-1][0];
		dp[0][i] = dp[0][i-1] + costw[0][i-1];
	}
	for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) {
		int t1 = dp[i-1][j] + costb[i-1][j];
		int t2 = dp[i][j-1] + costw[i][j-1];
		dp[i][j] = t1 < t2 ? t1 : t2;
	}
	cout << dp[n][n] << endl;
	return 0;
}

