class FenWickTree{
public:
	static const int MAXN = 2000 + 7;
	int L[MAXN];

	void update(int x, int val) {
//		for (int t = x; t < MAXN; t += t & -t) L[t] += val;
		for (int t = x; t > 0; t -= t & -t) L[t] += val;
	}

	int get(int x) {
		int res = 0;
//		for (int t = x; t > 0; t -= t & -t) {
//			res += L[t];
//		}
		for (int t = x; t < MAXN; t += t & -t) res += L[t];
		return res;
	}
} fenwickTree[2];

