void solve() {
	cin >> n;
	rep(i, 1, 2 * n + 1) {
		string s; cin >> s;
		int c = (s[0] == 'B'), a = 0;
		scanf("%d", &a);

		f[c][a] = fenwickTree[c].get(a);
		for (int j = 0; j <= n; ++j)
			g[c][a][j] = fenwickTree[1 - c].get(j + 1) + f[c][a];
		fenwickTree[c].update(a, 1);
	}

	rep(i, 0, n + 1) rep(j, 0, n + 1) dp[i][j] = linf;
	dp[0][0] = 0;

	for (int i = 0; i <= n; ++i) {
		for (int j = 0; j <= n; ++j) {
			if (i == 0 && j == 0) dp[i][j] = 0;
			else {
				if (i == 0) {
					dp[i][j] = dp[i][j - 1] + g[1][j][0];
				} else if (j == 0) {
					dp[i][j] = dp[i - 1][j] + g[0][i][0];
				} else {
					dp[i][j] = min(dp[i - 1][j] + g[0][i][j], dp[i][j - 1] + g[1][j][i]);
				}
			}
		}
	}

	cout << dp[n][n] << '\n';
}

