const int maxn = 2000 + 10;
int n,c[maxn << 1],a[maxn << 1],pos0[maxn],pos1[maxn];
int dp[maxn][maxn],cost0[maxn << 1][maxn],cost1[maxn << 1][maxn];
int main(){
    //File();
    scanf("%d",&n);
    REP(i,1,n * 2){
        char s[5];
        scanf("%s%d",s,&a[i]);
        c[i]= s[0] == 'W' ? 0 : 1;
        if(c[i] == 0)pos0[a[i]] = i;
        else pos1[a[i]] = i;
    }
    REP(i,1,n * 2)
        REP(j,0,n){
            cost0[i][j] = cost0[i - 1][j] + (a[i - 1] > j && c[i - 1] == 0);
            cost1[i][j] = cost1[i - 1][j] + (a[i - 1] > j && c[i - 1] == 1);
        }
    REP(i,0,n)
        REP(j,0,n){
            if(i == 0 && j == 0)continue;
            int p0 = pos0[i],p1 = pos1[j];
            dp[i][j] = inf;
            if(i)dp[i][j] = min(dp[i][j],dp[i - 1][j] + cost0[p0][i - 1] + cost1[p0][j]);
            if(j)dp[i][j] = min(dp[i][j],dp[i][j - 1] + cost1[p1][j - 1] + cost0[p1][i]);
        }
