// i:b, j:w
inline li calc(li pos, li i, li j) {
    return (cnt_b[pos][n] - cnt_b[pos][i]) + (cnt_w[pos][n] - cnt_w[pos][j]);
}

int main() {
    cin >> n;
    rep(i, 2 * n) {
        string s;
        li a;
        cin >> s >> a;
        if (s == "W") {
            w[a] = i;
            rep(j, n + 1) {
                cnt_w[i + 1][j] = cnt_w[i][j] + (j >= a ? 1 : 0);
            }
            rep(j, n + 1) {
                cnt_b[i + 1][j] = cnt_b[i][j];
            }
        } else {
            b[a] = i;
            rep(j, n + 1) {
                cnt_w[i + 1][j] = cnt_w[i][j];
            }
            rep(j, n + 1) {
                cnt_b[i + 1][j] = cnt_b[i][j] + (j >= a ? 1 : 0);
            }
        }
    }

    dp[0][0] = 0;
    rep(i, n) {
        dp[0][i + 1] = dp[0][i] + calc(w[i + 1], 0, i + 1);
    }
    repp(i, 1, n + 1) {
        dp[i][0] = dp[i - 1][0] + calc(b[i], i, 0);
        repp(j, 1, n + 1) {
            dp[i][j] = min(dp[i - 1][j] + calc(b[i], i, j),
                           dp[i][j - 1] + calc(w[j], i, j));
        }
    }

    cout << dp[n][n] << endl;
