int rec(int a, int b){
    if(a == N && b == N){
        return 0;
    }

    if(dp[a][b] != -1){
        return dp[a][b];
    }

    int res = 2001001001;

    if(a < N){
        int p = us[a + 1];
        res = min(res, p - memoW[p][a] - memoB[p][b] + rec(a + 1, b));
    }

    if(b < N){
        int p = vs[b + 1];
        res = min(res, p - memoW[p][a] - memoB[p][b] + rec(a, b + 1));     
    }

    return dp[a][b] = res;
}

