void f_revcnts(ll revcnts[], const ll numidx[], ll n)
{
    SegmentTree<ll> tree(4005, 0, sumll);
    rrep (a, n) {
        revcnts[a] = tree.query(0, numidx[a]);
        tree.update(numidx[a], 1);
    }
}

void f_rem(ll rem[2005][2005], ll numidx_from[], ll numidx_to[], ll n)
{
    rep (fromval, n) {
        SegmentTree<ll> tree(4005, 0, sumll);
        ll fromidx = numidx_from[fromval];
        rem[fromval][n] = 0;
        rrep (toval, n) {
            tree.update(numidx_to[toval], 1);
            rem[fromval][toval] = tree.query(0, fromidx);
        }
    }
}

