inline constexpr uint32_t get_min2pow(uint32_t value, uint32_t work = 1) {
	return ((value <= work) ? (work) : (get_min2pow(value, work * 2)));
}
template<typename T, size_t N_input>
class BIT
{
private:
	static constexpr size_t N = get_min2pow(N_input);
	// [1, n]
	T bit[N + 1];
public:
	//1-indexed [1,i]
	T sum(int i) {
		T s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	//1-indexed [i,j]
	T sum(int i, int j) {
		return sum(j) - sum(i - 1);
	}
	//1-indexed
	void add(int i, int x) {
		while (i <= N) {
			bit[i] += x;
			i += i & -i;
		}
	}
};
BIT<int32_t, 4000> bit;
int32_t N;
char T[4000];
int32_t A[4000];
bool unused[4000];
int main()
{
	using std::endl;
	in.sync_with_stdio(false);
	out.sync_with_stdio(false);
	in.tie(nullptr);
	out.tie(nullptr);

	in >> N;
	for (int32_t i = 0; i < 2*N; i++)
	{
		in >> T[i] >> A[i];
		if (T[i] == 'B') {
			T[i] = 1;
		}
		else {
			T[i] = 0;
		}
	}

	int32_t count = 0;
	int32_t max[2] = {0,0};
	std::vector<std::pair<char, int>> stac;
	for (int32_t i = 0; i < 2*N; i++)
	{
		if (stac.empty()) {
			if (A[i] == max[T[i]] + 1) {
				max[T[i]] = A[i];
				continue;
			}
			stac.emplace_back(T[i], A[i]);
			continue;
		}

		if (A[i] > max[T[i]] + 1) {
			stac.emplace_back(T[i], A[i]);
			continue;
		}
		count += stac.size() - bit.sum(2*N);
		max[T[i]] = A[i];
		bool updated = true;
		while (updated)
		{
			updated = false;
			for (int32_t j = 0; j < stac.size(); j++)
			{
				if (unused[j]) { continue; }
				if (stac[j].second == max[stac[j].first] + 1) {
					count += j - bit.sum(j+1);
					max[stac[j].first] = stac[j].second;
					unused[j] = true;
					bit.add(j + 1, 1);
					updated = true;
					break;
				}
			}
		}
	}
	out << count << endl;
	return 0;
}
