#define MAXN 2001

int n;
int a[MAXN*2], c[MAXN*2];
int dp[MAXN][MAXN];
int cost[2][MAXN][MAXN];

int input() {
	if (scanf("%d", &n) < 0) return 0;
	for (int i=0; i<2*n; i++) {
		char x;
		scanf(" %c %d", &x, &a[i]);
		a[i]--;
		c[i] = (x=='B');
	}
	return 1;
}

void init() {
}

long solve() {
	memset(cost, 0, sizeof(cost));
	for (int p=0; p<2*n; p++) {
		int i = a[p];
		int k = c[p];
		int d = 0;
		for (int q=0; q<p; q++) {
			int j = a[q];
			if (c[q] == k) d += j>i;
			else cost[k][i][j]++;
		}
		cost[k][i][n] = d;
		for (int j=n-1; j>=0; j--)
			cost[k][i][j] += cost[k][i][j+1];
	}
	//for (int k=0; k<2; k++) printg((int*)cost[k], n+1, n+1, MAXN);
	dp[0][0] = 0;
	for (int i=0; i<=n; i++) {
		for (int j=0; j<=n; j++) if (i||j) {
			int cc = INT_MAX;
			if (i) cc = min(cc, dp[i-1][j] + cost[0][i-1][j]);
			if (j) cc = min(cc, dp[i][j-1] + cost[1][j-1][i]);
			dp[i][j] = cc;
		}
	}
	//printg((int*)dp, n+1, n+1, MAXN);
	return dp[n][n];
}

void output(long ans) {
	printf("%ld\n", ans);
}

void cleanup() {
}

int main() {
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

