				int cnt1 = bsum[pos+1][n-i];
				int cnt2 = wsum[pos+1][i-1];
				dp[n][i] = min(dp[n][i], dp[n-1][i-1] + pos - n + cnt1 + cnt2 );
			}
			// bring black n-i to n
			if( n-i >= 1 ){
				int pos = bpos[n-i];
				int cnt1 = bsum[pos+1][n-i-1];
				int cnt2 = wsum[pos+1][i];
				dp[n][i] = min(dp[n][i], dp[n-1][i] + pos - n + cnt1 + cnt2 );		
			}
		}
	}
	cout << dp[2*N][N] << endl;
}

