template<class T> struct STree{
    int n;
    T e;
    vector<T> dat;

    inline T f(T x,T y){
        return x+y;
    }

    STree(int n_,T e_){
        n=1;e=e_;
        while(n<n_) n<<=1;
        dat.resize((n<<1),e);
    }

    STree(vector<T> v,T e_){
        int n_=v.size();
        n=1;e=e_;
        while(n<n_) n<<=1;
        dat.resize((n<<1),e);
        for(int i=0;i<n_;++i) dat[i+n]=v[i];
        for(int i=n-1;i>0;--i) dat[i]=f(dat[(i<<1)],dat[(i<<1)^1]);
    }

    void ud(int k,T c){
        k+=n;
        dat[k]+=c;
        while(k){
            if(k&1) dat[k>>1]=f(dat[k^1],dat[k]);
            else dat[k>>1]=f(dat[k],dat[k^1]);
            k>>=1;
        }
    }

    T gt(int l,int r){
        l+=n;r+=n;
        T s=e;
        while(l<r){
            if(r&1){
                --r;
                s=f(dat[r],s);
            }
            if(l&1){
                s=f(s,dat[l]);
                ++l;
            }
            l>>=1,r>>=1;
        }
        return s;
    }

    T operator[](int i){return dat[i+n];}
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n,a;
    cin>>n;
    char c;
    vector<int> v(2*n);
    fr(i,2*n){
        cin>>c>>a;
        v[a-1+n*(c=='B')]=i;
    }
    vector<vector<int>> dp(2*n+1,vector<int>(n+1,INT_MAX));
    dp[0][0]=0;
    Fr(i,2*n){
        STree<int> b(2*n,0),w(2*n,0);
        fr(j,max(0,i-n)) w.ud(v[j],1);
        fr(j,min(n,i)) b.ud(v[j+n],1);
        for(int j=max(0,i-n);j<=min(n,i);++j){
            int k=i-j;
            if(j){
                w.ud(v[j-1],-1);
                dp[i][j]=min(dp[i][j],dp[i-1][j-1]+v[j-1]
                        -w.gt(0,v[j-1])
                        -b.gt(0,v[j-1]));
                w.ud(v[j-1],1);
            }
            if(k){
                b.ud(v[k+n-1],-1);
                dp[i][j]=min(dp[i][j],dp[i-1][j]+v[k+n-1]
                        -w.gt(0,v[k+n-1])
                        -b.gt(0,v[k+n-1]));
                b.ud(v[k+n-1],1);
            }
            if(j<n) w.ud(v[j],1);
            if(k) b.ud(v[k+n-1],-1);
        }
    }
    cout<<dp[2*n][n]<<endl;
}

