#define MAXN 3005
#define INF 100000000

int bit[2*MAXN];

void add(int x, int val) {
  x += 1;
  while(x < 2*MAXN) {
    bit[x] += val;
    x += x&(-x);
  }
}

int sum(int x) {
  x += 1;
  int ret = 0;
  while(x > 0) {
    ret += bit[x];
    x -= x&(-x);
  }
  return ret;
}

int main() {
