    int cur = c == 'W' ? 0 : 1;
    pos[cur][x-1] = i;
  }

  std::vector<std::vector<int> > dp(n+1, std::vector<int>(n+1, INF));

  dp[0][0] = 0;
  for(int i = 0; i <= n; i++) {
    if(i) add(pos[0][i-1], 1);

    for(int j = 0; j <= n; j++) {
      if(j) add(pos[1][j-1], 1);
      if(i < n) dp[i+1][j] = std::min(dp[i+1][j], dp[i][j] + pos[0][i] - sum(pos[0][i]));
      if(j < n) dp[i][j+1] = std::min(dp[i][j+1], dp[i][j] + pos[1][j] - sum(pos[1][j]));
    }

    for(int j = 0; j < n; j++)
      add(pos[1][j], -1);
  }

