inline int read()
{
	int x=0,f=1; char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1; ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0'; ch=getchar();}
	return x*f;
}
int n,ps[2][N],F[N][N],tree[N<<2];
int S1[N][N],S2[N][N];
inline void Add(int x)
{
	for(;x<=2*n;x+=x&-x)
		tree[x]++;
}
inline int Ask(int x)
{
	if(!x) return 0;
	int ret=0; for(;x;x-=x&-x)
		ret+=tree[x]; return ret;
}
int main()
{
	n=read();
	for(int i=1;i<=2*n;i++)
	{
		char s[3]; scanf("%s",s);
		int x=read();
		if(s[0]=='B') ps[0][x]=i;
		else ps[1][x]=i;
	}
	memset(tree,0,sizeof tree);
	for(int i=1;i<=n;i++)
	{
		Add(ps[0][i]);
		for(int j=1;j<=2*n;j++)
			S1[i][j]=Ask(j-1);
	}
	memset(tree,0,sizeof tree);
	for(int i=1;i<=n;i++)
	{
		Add(ps[1][i]);
		for(int j=1;j<=2*n;j++)
			S2[i][j]=Ask(j-1);
	}
	memset(F,0x3f,sizeof F); F[0][0]=0;
	for(int i=0;i<=n;i++) for(int j=0;j<=n;j++)
	{
		if(i<n)
		{
			int xm=ps[0][i+1];
			F[i+1][j]=min(F[i+1][j],F[i][j]+(xm-1-S1[i][xm]-S2[j][xm]));
		}
		if(j<n)
		{
			int xm=ps[1][j+1];
			F[i][j+1]=min(F[i][j+1],F[i][j]+(xm-1-S1[i][xm]-S2[j][xm]));
		}
	}
	cout << F[n][n] << endl;
	return 0;
}

