int bcost[1024][1024];

int main(int argc, const char* argv[]) {
	scanf("%d\n", &N);

	balls.resize(2 * N);
	whites.resize(N);
	blacks.resize(N);
	{
		int i = 0;
		foreach (b, balls) {
			scanf("%c %d\n", &b.first, &b.second);
			b.second--;
			if (b.first == 'W')
				whites[b.second] = i;
			else
