			i++;
		}
	}

	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++)
			if (whites[j] < whites[i])
				wmore[j]++;
	}

	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++)
			if (blacks[j] < blacks[i])
				bmore[j]++;
	}

	{
		VI wpos(whites);
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j < N; j++) {
				int mypos = wpos[j] + wmore[j];
				int needpos = i + j;
				wcost[i][j] = mypos - needpos;
			}
			if (i < N) {
				int bb = blacks[i];
				for (int j = 0; j < N; j++)
					if (whites[j] < bb) {
						wpos[j]++;
					}
			}
		}
	}

	{
		VI bpos(blacks);
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j < N; j++) {
				int mypos = bpos[j] + bmore[j];
				int needpos = i + j;
				bcost[i][j] = mypos - needpos;
			}
			if (i < N) {
				int ww = whites[i];
				for (int j = 0; j < N; j++)
					if (blacks[j] < ww) {
						bpos[j]++;
					}
			}
		}
	}

	mem[0][0] = 0;
	for (int i = 1; i <= N; i++) {
		mem[i][0] = mem[i-1][0] + wcost[0][i-1];
	}

	for (int i = 1; i <= N; i++) {
		mem[0][i] = mem[0][i-1] + bcost[0][i-1];
	}

	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			mem[i][j] = min(mem[i-1][j] + wcost[j][i-1], mem[i][j-1] + bcost[i][j-1]);
		}
	}

	printf("%d\n", mem[N][N]);

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define LSOne(S) (S&(-S))

char c[4005];
int a[4005];

int f[4005];
int ft[4005];

int N;

int nextWhite[2005][2005];
int nextBlack[2005][2005];
int indxWhite[2005];
int indxBlack[2005];

void init(){
    memset(ft, 0, sizeof(ft));
    for(int i = 1; i <= 2*N; i ++){
        ft[i] += f[i];
        if(i + LSOne(i) <= 2*N){
            ft[i+LSOne(i)] += ft[i];
        }
    }
}

int rsq(int b){
    int sum = 0;
    for(; b; b -= LSOne(b)){
        sum += ft[b];
    }
    return sum;
}

void adjust(int k, int v){
    for(; k <= 2*N; k += LSOne(k)){
        ft[k] += v;
    }
}

void init2(){
    for(int i = 1; i <= 2*N; i ++){
        if(c[i] == 'B'){
            indxBlack[a[i]] = i;
        }else if(c[i] == 'W'){
            indxWhite[a[i]] = i;
            //printf("indxWhite[%d]=%d\n", a[i], i);
        }
    }
    for(int numWhite = 0; numWhite <= N; numWhite ++){
        for(int i = 1; i <= 2*N; i ++){
            if((c[i] == 'B') || (a[i] > numWhite)){
                f[i] = 1;
                //printf("f[%d]=%d\n", i, 1);
            }else{
                f[i] = 0;
            }
        }
        init();
        for(int numBlack = 0; numBlack <= N; numBlack ++){
            nextWhite[numWhite][numBlack] = rsq(indxWhite[numWhite+1]);
            nextBlack[numWhite][numBlack] = rsq(indxBlack[numBlack+1]);
            //printf("nextWhite[%d][%d]=%d\n", numWhite, numBlack, nextWhite[numWhite][numBlack]);
            if(numBlack == N){break;}
            adjust(indxBlack[numBlack+1], -1);
        }
    }
}

int memo[2005][2005];

int dp(int i, int j){
    if(i == N && j == N){
        return 0;
    }else if(memo[i][j] != -1){
        return memo[i][j];
    }else{
        memo[i][j] = 1023456789;
        if(i < N){
            memo[i][j] = min(memo[i][j], nextWhite[i][j]-1+dp(i+1, j));
        }
        if(j < N){
            memo[i][j] = min(memo[i][j], nextBlack[i][j]-1+dp(i, j+1));
        }
        return memo[i][j];
    }
}

