	FOR(b,0,N+1){
		FOR(i,1,N+1)bit.add(W[i],1);
		if(b!=0)bit.add(B[b],-1);
		FOR(w,0,N+1){
			if(w!=0)bit.add(W[w],-1);
			if(b<N)dp[b+1][w] = min( dp[b+1][w] , dp[b][w] + bit.sum(B[b+1]) - 1 );
			if(w<N)dp[b][w+1] = min( dp[b][w+1] , dp[b][w] + bit.sum(W[w+1]) - 1 );
		}
	}
	cout << dp[N][N] << "\n";
}

