using namespace std;
typedef pair<int,int> ii;

static vector<int> white[2005];
static vector<int> black[2005];
static int whitePos[2005];
static int blackPos[2005];
static ii arr[4005];

static int memo[2005][2005];

int dp(int w, int b){ ///first a white and first b black sorted
	if(w == 0 && b == 0) return 0;
	if(memo[w][b] != -1) return memo[w][b];

	int ans = 1023456789;
	if(b != 0){
		int bb = b - 1;
		int oPos = blackPos[bb];
		int bRight = bb - (lower_bound(black[bb].begin(),black[bb].end(),oPos) - black[bb].begin());
		int wRight = w - (lower_bound(white[w].begin(),white[w].end(),oPos) - white[w].begin());
		if(w == 0) wRight = 0;

		oPos += bRight;
		oPos += wRight;
		ans = min(ans, dp(w,bb) + oPos - w - bb);
	}
	if(w != 0){
		int ww = w - 1;
		int oPos = whitePos[ww];
		int bRight = b - (lower_bound(black[b].begin(),black[b].end(),oPos) - black[b].begin());
		int wRight = ww - (lower_bound(white[ww].begin(),white[ww].end(),oPos) - white[ww].begin());
		if(b == 0) bRight = 0;

		oPos += bRight;
		oPos += wRight;
		ans = min(ans, dp(ww,b) + oPos - ww - b);
	}
	//cout << w << " " << b << " " << ans << "\n";
	memo[w][b] = ans;
	return ans;
}

