class CumulativeSum {
    vector<ll> numbers;
    vector<ll> sums;

public:
    CumulativeSum(int n) {
        numbers.resize(n);
        sums.resize(n);
    }

    void set(int i, ll value) {
        numbers[i] = value;
    }

    ll getSum(int i) {
        if (i == -1) return 0;
        if (i == sums.size()) return sums.back();
        return sums[i];
    }

    ll getSectionSum(int start, int end) {
        return getSum(end) - getSum(start - 1);
    }

    void calculate() {
        for (int i = 0; i < numbers.size(); i++) {
            sums[i] = getSum(i - 1) + numbers[i];
        }
    }

};

int main() {
    int n;
    cin >> n;

    vector<Ball> balls(2 * n);
    rep(i, 2 * n) cin >> balls[i].c >> balls[i].v;

    vector<vector<ll>> dp(n + 1, vector<ll>(n + 1, INF));

    map<int, int> bi, wi;
    rep(i, 2 * n) if (balls[i].c == 'B') bi[balls[i].v] = i; else wi[balls[i].v] = i;

    dp[0][0] = 0;


    auto get_index = [&](char c, int v) {
        if (c == 'B') return bi[v];
        else return wi[v];
    };


    vector<CumulativeSum> bcs(n + 1, CumulativeSum(2 * n)), wcs(n + 1, CumulativeSum(2 * n));

    // 黒
    rep(i, n + 1) {
        rep(j, n + 1) {
            if (j <= i) continue;
            bcs[i].set(bi[j], 1);
        }
    }
    rep(i, n + 1) bcs[i].calculate();
    // 白
    rep(i, n + 1) {
        rep(j, n + 1) {
            if (j <= i) continue;
            wcs[i].set(wi[j], 1);
        }
    }
    rep(i, n + 1) wcs[i].calculate();

    auto get_lager = [&](int r, char c, int v) -> ll {

        if (c == 'B')return bcs[v].getSum(r - 1);
        return wcs[v].getSum(r - 1);

    };

    auto set = [&](int b, int w, ll value) {
        cmin(dp[b][w], value);
    };

    for (ll b = 0; b <= n; b++) {
        for (ll w = 0; w <= n; w++) {

            ll prev = dp[b][w];
            {

                // 黒を足す
                ll nb = b + 1;
                ll nw = w;

                if (nb <= n) {

                    ll i = get_index('B', nb);
                    ll lb = get_lager(i, 'B', nb);
                    ll lw = get_lager(i, 'W', nw);


                    ll now = prev + lb + lw;
                    set(nb, nw, now);
