                // 白を足す
                ll nw = w + 1;
                ll nb = b;

                if (nw <= n) {
                    ll i = get_index('W', nw);
                    ll lw = get_lager(i, 'W', nw);
                    ll lb = get_lager(i, 'B', nb);
                    ll now = prev + lb + lw;
                    set(nb, nw, now);
                }
            }

        }
    }

