struct BIT {
private:
	vector<ll>Bit;
	ll N;
public:
	void init(ll n) {
		N = n;
		Bit.resize(n);
	}
	void add(ll a, ll w) {
		for (int x = a; x < N; x += x & -x) Bit[x] += w;
	}
	int SUM(ll a) {
		ll ret = 0;
		for (int x = a; x > 0; x -= x & -x) ret += Bit[x];
		return ret;
	}
};


