class Bit{
public:
	vector<int>bit;
	Bit(){}
	Bit(int n){
		bit=vector<int>(n+10);
	}
	void add(int k,int x){
		k++;
		while(k<(int)bit.size()){
			bit[k]+=x;
			k+=k&-k;
		}
	}
	int sum(int k){
		k++;
		int res=0;
		while(k){
			res+=bit[k];
			k-=k&-k;
		}
		return res;
	}
};

template<class T>
class Rangetree{
	vector<vector<T>>dat;
	vector<T>v;
	void init(int k,int l,int r){
		if(r-l==1){
			if(l<(int)v.size())dat[k].push_back(v[l]);
			return;
		}
		int lb=k*2+1,rb=k*2+2;
		init(lb,l,(l+r)/2);
		init(rb,(l+r)/2,r);
		dat[k].resize(r-l);
		merge(dat[lb].begin(),dat[lb].end(),dat[rb].begin(),dat[rb].end(),dat[k].begin());
	}
public:
	Rangetree(){}
	Rangetree(int n,T*a){
		v.resize(n);
		for(int i=0;i<n;i++)v[i]=a[i];
		dat.resize(4*v.size());
		init(0,0,v.size());
	}
	Rangetree(vector<T>&a){
		v=a;
		dat.resize(4*v.size());
		init(0,0,v.size());
	}
	int query(int a,int b,int c,int d,int k,int l,int r){
		if(b<=l||r<=a)return 0;
		if(a<=l&&r<=b){
			int u=lower_bound(dat[k].begin(),dat[k].end(),d)-dat[k].begin();
			int v=lower_bound(dat[k].begin(),dat[k].end(),c)-dat[k].begin();
			return u-v;
		}
		int lb=query(a,b,c,d,k*2+1,l,(l+r)/2);
		int rb=query(a,b,c,d,k*2+2,(l+r)/2,r);
		return lb+rb;
	}
	int query(int a,int b,int c,int d){
		return query(a,b,c,d,0,0,v.size());
	}
};

