			bit[1].add(a[i],1);
		}
	}
	vector<Rangetree<int>>tree{
		Rangetree<int>(n,p[0]),
		Rangetree<int>(n,p[1])
	};
	memset(dp,0x3f,sizeof(dp));
	dp[0][0]=0;
	rep(i,n+1)rep(j,n+1){
		if(i<n){
			dp[i+1][j]=min(dp[i+1][j],dp[i][j]+tree[1].query(0,j,p[0][i],2*n+1));
		}
		if(j<n){
			dp[i][j+1]=min(dp[i][j+1],dp[i][j]+tree[0].query(0,i,p[1][j],2*n+1));
		}
	}
	cout<<dp[n][n]+ans<<endl;
}

