			if(j < n){
				const int p = inv[1][j];
				dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + p - table[0][p][i] - table[1][p][j]);
			}
		}
	}
	cout << dp[n][n] << endl;
	return 0;
}

