template<class T>
class BinaryIndexedTree{
    int n;
    std::vector<T> node;

public:
    BinaryIndexedTree(int n_ = 0, T x = 0){
        init(n_, x);
    }

    BinaryIndexedTree(std::vector<T>& dat){
        build(dat);
    }

    void init(int n_ = 0, T x = 0){
        n = n_;
        node.assign(n + 1, x);

        return;
    }

    void build(std::vector<T>& dat){
        n = (int)dat.size();

        init(n);

        for(int i = 0 ; i < n ; ++i){
            add(i, dat[i]);
        }

        return;
    }

    void add(int i, T x){
        ++i;

        while(i <= n){
            node[i] += x;
            i += i & -i;
        }

        return;
    }

    void update(int i, T x){
        add(i, x - sum(i, i + 1));
    }

    T sum(int r){
        T res = 0;

        while(0 < r){
            res += node[r];
            r -= r & -r;
        }

        return res;
    }

    T sum(int l, int r){
        return sum(r) - sum(l);
    }
};

