int used[N][N],mem[N][N];
int dfs(int i,int j, RSAQ &A){
  //pr(i, j);
  if(i == n && j == n) return 0;
  if(used[i][j]++) return mem[i][j];
  int a = INF, b = INF;

    if(i != n) {
      int idx = W[i].second;
      int cost = A.get(0, idx);
      A.add(idx, idx+1, -1);
      a = cost + dfs(i+1,j, A);
      A.add(idx, idx+1, 1);
    }

    if(j != n){
      int idx = B[j].second;
      int cost = A.get(0, idx);
      A.add(idx, idx+1, -1);
      b = cost + dfs(i, j+1, A);
      A.add(idx, idx+1, 1);
    }
    int res = min(a, b);
    return mem[i][j] = res;
}

