int n;

void add(int idx) {
	for (; idx < 3 * maxn; idx += (idx & -idx)) {
		fen[idx]++;
	}
	return;
}

int get(int idx) {
	int ret = 0;
	for (; idx > 0; idx -= (idx & -idx)) {
		ret += fen[idx];
	}
	return ret;
}

void antiadd(int idx) {
	for(; idx < 3 * maxn; idx += (idx & -idx)) {
		fen[idx]--;
	}
	return;
}

