#include <bits/stdc++.h>
using namespace std;

#define MAXN 2010
typedef long long LL;

int a[MAXN << 1], b[MAXN << 1], p0[MAXN], p1[MAXN];
int dp[MAXN][MAXN], big0[MAXN << 1][MAXN], big1[MAXN << 1][MAXN];
const int INF = 1e9;


int main()
{
	//freopen("in.txt", "r", stdin);

	int n;
	scanf("%d", &n);
	for (int i = 1; i <= 2 * n; ++i)
	{
		char c;
		scanf(" %c", &c);
		if (c == 'B') a[i] = 1;
		else a[i] = 0;
		scanf("%d", &b[i]);
	}
	vector<pair<int, int> > v;
 	for (int i = 1; i <= 2 * n; ++i)
	{
		if (a[i] == 0)
		{
			v.push_back(make_pair(b[i], i));
		}
	}
	sort(v.begin(), v.end());
	for (int i = 0; i < v.size(); ++i)
	{
		b[v[i].second] = i + 1;
		p0[i + 1] = v[i].second;
	}
	v.clear();
 	for (int i = 1; i <= 2 * n; ++i)
	{
		if (a[i] == 1)
		{
			v.push_back(make_pair(b[i], i));
		}
	}
	sort(v.begin(), v.end());
	for (int i = 0; i < v.size(); ++i)
	{
		b[v[i].second] = i + 1;
		p1[i + 1] = v[i].second;
	}
	v.clear();

	for (int i = 1; i <= 2 * n; ++i)
	{
		for (int j = 1; j <= n; ++j)
		{
			big0[i][j] = big0[i - 1][j];
			big1[i][j] = big1[i - 1][j];
			if (a[i] == 0 && b[i] >= j) ++big0[i][j];
			if (a[i] == 1 && b[i] >= j) ++big1[i][j];
		}
	}

	for (int i = 0; i <= n; ++i)
		for (int j = 0; j <= n; ++j)
			dp[i][j] = INF;

	//for (int i = 1; i <= n; ++i)
	//	cout << p0[i] << " " << p1[i] <<endl;
	dp[0][0] = 0;
	for (int len = 0; len < 2 * n; ++len)
	{
		for (int i = 0; i <= len; ++i)
		{
			int j = len - i;
			if (i > n || j > n) continue;
			if (dp[i][j] == INF) continue;
			//cout << i << " " << j << " " << dp[i][j] << endl;
			if (i < n)
			{
				int pos = p0[i + 1];
				dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + big0[pos - 1][i + 1] + big1[pos - 1][j + 1]);
			}
			if (j < n)
			{
				int pos = p1[j + 1];
				dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + big1[pos - 1][j + 1] + big0[pos - 1][i + 1]);
			}
		}
	}
	cout << dp[n][n] << endl;
	return 0;
}

