	ll N;
	cin >> N;

	vector<ll> white_pos(N + 1);
	vector<ll> black_pos(N + 1);
	string color;
	ll number;
	for (ll i = 0; i < N * 2; ++i)
	{
		cin >> color >> number;
		if (color == "W")
		{
			white_pos[number] = i;
		}
		else if (color == "B")
		{
			black_pos[number] = i;
		}
	}

	vector<vector<ll>> white_swap(N, vector<ll>(N + 1, 0));
	for (ll i = 0; i < N; ++i)
	{
		for (ll j = i + 2; j < N + 1; ++j)
		{
			if (white_pos[j] < white_pos[i + 1])
			{
				white_swap[i][N]++;
			}
		}
		for (ll j = N; j > 0; --j)
		{
			white_swap[i][j - 1] = white_swap[i][j];
			if (black_pos[j] < white_pos[i + 1])
			{
				white_swap[i][j - 1]++;
			}
		}
	}

	vector<vector<ll>> black_swap(N + 1, vector<ll>(N, 0));
	for (ll i = 0; i < N; ++i)
	{
		for (ll j = i + 2; j < N + 1; ++j)
		{
			if (black_pos[j] < black_pos[i + 1])
			{
				black_swap[N][i]++;
			}
		}
		for (ll j = N; j > 0; --j)
		{
			black_swap[j - 1][i] = black_swap[j][i];
			if (white_pos[j] < black_pos[i + 1])
			{
				black_swap[j - 1][i]++;
			}
		}
	}

	vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, 1LL << 32));
	dp[0][0] = 0;
	for (ll i = 0; i < N + 1; ++i)
	{
		for (ll j = 0; j < N + 1; ++j)
		{
			if (i > 0)
			{
				dp[i][j] = min(dp[i][j], dp[i - 1][j] + white_swap[i - 1][j]);
			}
			if (j > 0)
			{
				dp[i][j] = min(dp[i][j], dp[i][j - 1] + black_swap[i][j - 1]);
			}
		}
	}

	cout << dp[N][N] << endl; 

	return 0;
}

