        vec[i].second--;
    }

    int white[n][n+1]; // 白iより前に、i+1以上の白とj以上の黒がいくつあるか
    int black[n][n+1]; // 黒iより前に、i+1以上の黒とj以上の白がいくつあるか

    vector <int> white_count(n, 0);
    vector <int> black_count(n, 0);

    for (int i = 0; i < 2 * n; i++) {
        char color = vec[i].first;
        int idx = vec[i].second;

        // 累積和
        vector <int> white_sum(n + 1, 0); // j以上の白がいくつあるか
        vector <int> black_sum(n + 1, 0); // j以上の黒がいくつあるか
        for (int j = n-1; j >= 0; j--) {
            white_sum[j] = white_count[j] + white_sum[j+1];
            black_sum[j] = black_count[j] + black_sum[j+1];
        }

        for (int j = 0; j <= n; j++) {
            if (color == 'W') white[idx][j] = black_sum[j] + white_sum[idx+1];
            if (color == 'B') black[idx][j] = white_sum[j] + black_sum[idx+1];
        }

        if (color == 'W') white_count[idx]++;
        if (color == 'B') black_count[idx]++;
    }

    int dp[n+1][n+1]; // 白をi個、黒をj個置いた時の転倒数の最小値
    fill(dp[0], dp[n+1], (1<<30));
    dp[0][0] = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i < n) dp[i+1][j] = min(dp[i+1][j], dp[i][j] + white[i][j]);
            if (j < n) dp[i][j+1] = min(dp[i][j+1], dp[i][j] + black[j][i]);
        }
    }

    cout << dp[n][n] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define modulo 1000000007
#define mod(mod_x) ((((long long)mod_x+modulo))%modulo)
#define Inf 1000000000

template <typename T>
struct BIT{
	vector<T> v;
	int n;

	const T init_value = 0;

	BIT(int sz){
		n=sz+1;
		v.resize(n,init_value);
	}

	BIT(vector<T> &x){
		n=x.size()+1;
		v.resize(n,init_value);

		for(int i=0;i<x.size();i++){
			add(i,x[i]);
		}

	}

	void add(int x,T val){
		x++;
		while(x < n){
			v[x] = func(v[x],val);
			x += x & (-x);
		}
	}

	//区間[0,r)におけるクエリ処理
	T query(int r){
		T ret = init_value;

		while(r>0){
			ret = func(v[r],ret);
			r -= r & (-r);
		}

		return ret;
	}

	T query(int l,int r){
		return query(r) - query(l);
	}

	T func(T a,T b){
		return a+b;
	}

};

vector<pair<int,int>> calc(vector<int> &Bind,vector<int> &Wind,int c){
	BIT<int> B(2*Bind.size());
	for(int i=0;i<2*Bind.size();i++)B.add(i,1);
	for(int i=0;i<c;i++){
		B.add(Bind[i],-1);
	}

	vector<pair<int,int>> ret;
	for(int i=0;i<=Wind.size();i++){
		pair<int,int> t(-1,-1);
		if(c!=Bind.size()){
			t.first = B.query(0,Bind[c]);
		}
		if(i!=Wind.size()){
			t.second = B.query(0,Wind[i]);
		}
		ret.push_back(t);
		if(i!=Wind.size()){
			B.add(Wind[i],-1);
		}
	}
	return ret;
}


