struct BinaryIndexedTree {
    int sz;
    vector<ll> data;

    BinaryIndexedTree(int sz):sz(sz){
        data.assign(sz,0);
    }

    void add(int x,int val){
        while(x<sz)data[x]+=val,x|=x+1;
    }

    ll sum(int to){
        to=min(to,sz-1);
        ll ret=0;
        while(to>=0)ret+=data[to],to=(to&(to+1))-1;
        return ret;
    }

    ll sum(int from,int to){
        if(from>to)return 0;
        return sum(to)-sum(from-1);
    }
};

vvl g(vp &x,vp &y){
    vvl ret(N+1,vl(N));
    BinaryIndexedTree bit(2*N);
    rrep(i,N){
        bit.add(y[i].second,1);
        rep(j,N)ret[i][j]=bit.sum(x[j].second);
    }
    return ret;
}
ll f(vp &x){
    ll ret=0;
    BinaryIndexedTree bit(N);
    rep(i,N){
        ret+=bit.sum(x[i].first,N-1);
        bit.add(x[i].first,1);
    }
    return ret;
}

