int main(){
    int N; cin >> N;
    P A[4020];
    for(int i=0; i<2*N; i++){
        char c; int a; cin >> c >> a;
        A[i]=P(a,c);
    }
    int maxb=N+1, maxw=N+1; //揃ってるやつら 
    //0-originでmaxb+maxw-3を次決めたい
    int ans=0;
    while(maxb>1 || maxw>1){
        //全部見る
        int nextb=-1, nextw=-1;
        for(int i=0; i<maxb+maxw-2; i++){
            if(A[i]==P(maxb-1,'B') ) nextb=i;
            if(A[i]==P(maxw-1,'W') ) nextw=i;
        }
        int next=max(nextb,nextw);
        for(int i=next; i<maxb+maxw-3; i++){
            swap(A[i],A[i+1]); ans++;
        }
        if(next==nextb) maxb--;
        else maxw--;
    }
    cout << ans << endl;
}

