const int maxN = (int)2e3 + 10;

//标号为x的白、黑色球在wp[x]、bp[x]的位置上
int wp[maxN], bp[maxN];
char C[maxN * 2];
int V[maxN * 2];
int N;

void input()
{
    scanf("%d", &N);
    for (int i = 1; i <= N + N; i++)
    {
        scanf(" %c%d", C + i, V + i);
        if (C[i] == 'W')
            wp[V[i]] = i;
        else
            bp[V[i]] = i;
    }
}

struct Seg
{
    struct Node
    {
        int cnt;
        int ch[2];
    };
    Node node[maxN * 16];
    int root[maxN * 2];
    int cnt = 0;

    inline int newNode() { return cnt++; }
    int _init0(int l, int r) {
        if (l + 1 == r)
            return newNode();
        int res = newNode();
        int m = (l + r) >> 1;
        node[res].ch[0] = _init0(l, m);
        node[res].ch[1] = _init0(m, r);
        return res;
    }
    int insert(int key, int prev, int delta = 1)
    {
        int l = 1, r = N + N + 1; //2N!!!!!!!!
        int res = newNode();
        int cur = res;
        while (1)
        {
            node[cur] = node[prev];
            node[cur].cnt += delta;
            if (l + 1 == r)
                break;
            int m = (l + r) >> 1;
            int dir = (key < m ? 0 : 1);
            key < m ? r = m : l = m;
            cur = node[cur].ch[dir] = newNode();
            prev = node[prev].ch[dir];
        }
        return res;
    }
    int _l, _r;
    int _query(int nl, int nr, int cur)
    {
        if (_l <= nl && _r >= nr)
            return node[cur].cnt;
        if (_r <= nl || _l >= nr)
            return 0;
        int mid = (nl + nr) >> 1;
        return _query(nl, mid, node[cur].ch[0]) + _query(mid, nr, node[cur].ch[1]);
    }
    int query(int l, int r, int v) {
        _l = l;
        _r = r + 1;
        return _query(1, N + N + 1, root[v]); //2N!!!!!!!!!!
    }
};

Seg segW, segB;

void initSeg()
{
    segW.root[0] = segW._init0(1, N + N + 1);
    segB.root[0] = segB._init0(1, N + N + 1);
    for (int i = 1; i <= N; i++)
        segW.root[i] = segW.insert(wp[i], segW.root[i - 1]);
    for (int i = 1; i <= N; i++)
        segB.root[i] = segB.insert(bp[i], segB.root[i - 1]);
}

using LL = long long;

LL dp[maxN][maxN];

LL solve()
{
    initSeg();
    memset(dp, 0x3f, sizeof(dp));
    dp[0][0] = 0;
    for (int x = 0; x <= N; x++)
        for (int y = 0; y <= N; y++)
        {
            if (x == 0 && y == 0)
                continue;
            if (x > 0)
            {
                int d = wp[x] +
                        segW.query(wp[x] + 1, N + N, x - 1) +
                        segB.query(wp[x] + 1, N + N, y) -
                        (x + y);
                dp[x][y] = std::min(dp[x][y], d + dp[x - 1][y]);
            }
            if (y > 0)
            {
                int d = bp[y] +
                        segW.query(bp[y] + 1, N + N, x) +
                        segB.query(bp[y] + 1, N + N, y - 1) -
                        (x + y);
                dp[x][y] = std::min(dp[x][y], d + dp[x][y - 1]);
            }
        }
    return dp[N][N];
}

int main()
{
    input();
    printf("%lld\n", solve());
    return 0;
}

