void solve() {
    int n;
    cin >> n;
    vec<char> c(2 * n);
    vec<int> a(2 * n);

    vvec<int> b(2 * n, vec<int>(n, 0)), w(2 * n, vec<int>(n, 0));
    vec<int> posb(n, 0), posw(n, 0);
    REP(i, 2 * n) {
        cin >> c[i] >> a[i];
        if(c[i] == 'B') {
            b[i][a[i] - 1]++;
            posb[a[i] - 1] = i;
        } else {
            w[i][a[i] - 1]++;
            posw[a[i] - 1] = i;
        }
    }

    vvec<int> sumb(2 * n + 1, vec<int>(n + 1, 0)), sumw(2 * n + 1, vec<int>(n + 1, 0));
    REP(i, 2 * n) {
        REP(j, n) {
            sumb[i + 1][j + 1] = sumb[i + 1][j] + sumb[i][j + 1] - sumb[i][j] + b[i][j];
            sumw[i + 1][j + 1] = sumw[i + 1][j] + sumw[i][j + 1] - sumw[i][j] + w[i][j];
        }
    }

    vvec<int> dp(n + 1, vec<int>(n + 1, INF_INT));
    dp[0][0] = 0;

    REP(i, n + 1) {
        REP(j, n + 1) {
            if(i < n) {
                int cost = 0;
                {
                    ll rx = posb[i];
                    ll lx = 0;
                    ll ry = n;
                    ll ly = i;
                    cost += sumb[rx][ry] - sumb[rx][ly] - sumb[lx][ry] + sumb[lx][ly];
                }
                {
                    ll rx = posb[i];
                    ll lx = 0;
                    ll ry = n;
                    ll ly = j;
                    cost += sumw[rx][ry] - sumw[rx][ly] - sumw[lx][ry] + sumw[lx][ly];
                }
                chmin(dp[i + 1][j], dp[i][j] + cost);
            }
            if(j < n) {
                int cost = 0;
                {
                    ll rx = posw[j];
                    ll lx = 0;
                    ll ry = n;
                    ll ly = i;
                    cost += sumb[rx][ry] - sumb[rx][ly] - sumb[lx][ry] + sumb[lx][ly];
                }
                {
                    ll rx = posw[j];
                    ll lx = 0;
                    ll ry = n;
                    ll ly = j;
                    cost += sumw[rx][ry] - sumw[rx][ly] - sumw[lx][ry] + sumw[lx][ly];
                }
                chmin(dp[i][j + 1], dp[i][j] + cost);
            }
        }
    }

    cout << dp[n][n] << en;
}

