	REP(i, n) {
		BIT bit(m);
		rep(j, i) {
			bit.add(posB[j + 1], 1);
		}
		srep(j, i, m) {
			costW[j][i] = (posW[j - i + 1] - j) + (j - bit.get(posW[j - i + 1]));
			costB[j][i] = (posB[i + 1] - j) + (j - bit.get(posB[i + 1]));
			bit.add(posW[j - i + 1], 1);
		}
	}
	REP(i, m)	REP(j, n)	dp[i][j] = inf;
	dp[0][0] = 0;
	rep(i, m) {
		REP(j, min(i, n)) {
			if (dp[i][j] == inf)	continue;
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + costW[i][j]);
			dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + costB[i][j]);
		}
	}
	cout << dp[m][n] << endl;
	return 0;
}

