const int mxN = 2010;
const int inf = 10000010;
int BIT[mxN];
void upd(int ind, int val) {
	while (ind < mxN) {
		BIT[ind] += val;
		ind |= ind + 1;
	}
}

int get(int ind) {
	int res = 0;
	while (ind >= 0) {
		res += BIT[ind];
		ind = (ind & (ind + 1)) - 1;
	}
	return res;
}

