		}
		else if(tmp[i] % 2 == 1 && tmp[i] > maxodd) {
			maxodd = tmp[i];
		}
		else if(tmp[i] % 2 == 1 && tmp[i] < maxodd) {
			int pos = -1;
			for(int j = 0; j < i; j++) {
				if(tmp[j] % 2 == 1 && tmp[j] > tmp[i]) {
					pos = j;
					cnt += i - pos;
					break;
				}
			}
			if(pos != -1) {
				for(int j = i; j > pos; j--) {
					swap(tmp[j], tmp[j-1]);
				}
			}
		}
	}
	int cnt_min = 0;
	maxeven = 99999;
	maxodd = 99999;
	for(int i = 2 * n - 1; i >= 0; i--) {
		if(tmp2[i] % 2 == 0 && tmp2[i] > maxeven)  {
			int pos = -1;
			for(int j = 2 * n - 1; j > i; j--) {
				if(tmp2[j] % 2 == 0 && tmp2[j] < tmp2[i]) {
					pos = j;
					cnt_min += pos - i;
					break;
				}
			}
			if(pos != -1) {
				for(int j = i; j < pos; j++) {
					swap(tmp2[j], tmp2[j+1]);
				}
			}
		}
		else if(tmp2[i] % 2 == 0 && tmp2[i] < maxeven) {
			maxeven = tmp2[i];
		}
		else if(tmp2[i] % 2 == 1 && tmp2[i] < maxodd) {
			maxodd = tmp2[i];
		}
		else if(tmp2[i] % 2 == 1 && tmp2[i] > maxodd) {
			int pos = -1;
			for(int j = 2 * n - 1; j > i; j--) {
				if(tmp2[j] % 2 == 1 && tmp2[j] < tmp2[i]) {
					pos = j;
					cnt_min += pos - i;
					break;
				}
			}
			if(pos != -1) {
				for(int j = i; j < pos; j++) {
					swap(tmp2[j], tmp2[j+1]);
				}
			}
		}
	}
	//cout << endl;
	//cout <<cnt << endl;
	//cout << cnt_min << endl;
	cout << min(cnt, cnt_min) << endl;
	return 0;
