template<typename T = int> class BIT {
public:
    int n;
    vector<T> dat;
    BIT(int n) : n(n) { dat.assign(n, 0); }
    // [0, k)
    inline T sum(int k) {
        if (k >= n) k = n - 1;
        T ret = 0;
        for (int x = k - 1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += dat[x];
        }
        return ret;
    }
    // [l, r)
    inline T sum(int l, int r) { return sum(r) - sum(l); }
    inline T get(int l, int r) { return sum(r) - sum(l); }
    inline T get(int k) { return sum(k); }
    inline T operator[](int k) {
        assert(0 <= k && k < n);
        return sum(k + 1) - sum(k);
    }
    inline T operator()(int k) { return sum(k); }
    inline T operator()(int l, int r) { return sum(l, r); }
    //0 index
    inline void add(int k, T val = 1) { for (int x = k; x < n; x |= x + 1)dat[x] += val; }
    inline void update(int k, T val = 0) { add(k, -operator[](k) + val); }
    inline void del(int k) { update(k, 0); }
    inline void clear() { fill(dat, 0); }
    inline void debu() {
#ifdef _DEBUG
        vi res;
        rep(i, min(10, n)) {
            res.pb(operator[](i));
        }
        deb(res);
#endif
        ;
    }
    //合計がw以上となる最小のxを返す
    inline int lower_bound(int w) {
        if (w <= 0) return -1;
        int x = 0;
        int k = 1;
        while (k * 2 <= n) k *= 2;
        for (; k > 0; k /= 2) {
            if (x + k <= n && dat[x + k - 1] < w) {
                w -= dat[x + k - 1];
                x += k;
            }
        }
        return x;
    }
};
