class Bit {
  ll n, bit[10000];
public:
  void init(ll _n) {
    n = 1;
    while (n <= _n) n *= 2;
  }
  void add(ll a, ll w) {
    for (ll x = a; x <= n; x += x & -x) bit[x] += w;
  }
  ll sum(ll a) {
    ll ans = 0;
    for (ll x = a; x > 0; x -= x & -x) ans += bit[x];
    return ans;
  }
};

ll n, a[4000], w[2000], b[2000], dp[2001][2001];
