// [i][j]: 位置iより左側にある、jより小さいボールの数
int white_table[4010][2010];
int black_table[4010][2010];

// ボールiのある位置
int white_pos[2010];
int black_pos[2010];

// ボールiにとって、自分より左にある、自分より小さいボールの数
int white_left[2010];
int black_left[2010];

int main(void)
{
    cin.sync_with_stdio(false);
    int N; cin >> N;

    REP(n, 2*N) {
        char c; int a;
        cin >> c >> a; --a;
        if (c == 'B') {
            black_pos[a] = n;
            FOR(m, n + 1, 2 * N) {
                black_table[a][m] = 1;
            }
        }
        else {
            white_pos[a] = n;
            FOR(m, n + 1, 2 * N) {
                white_table[a][m] = 1;
            }
        }
    }

    FOR(a, 1, N) {
        REP(n, 2 * N) {
            black_table[a][n] += black_table[a - 1][n];
            white_table[a][n] += white_table[a - 1][n];
        }
    }

    vector<int> blacks;
    REP(n, N) {
        auto pos = black_pos[n];
        auto it = lower_bound(ALL(blacks), pos);
        auto dist = distance(blacks.begin(), it);
        black_left[n] = abs(dist);
        blacks.insert(it, pos);
    }
    vector<int> whites;
    REP(n, N) {
        auto pos = white_pos[n];
        auto it = lower_bound(ALL(whites), pos);
        auto dist = distance(whites.begin(), it);
        white_left[n] = abs(dist);
        whites.insert(it, pos);
    }



    // dp[black][white]
    FOR(sum, 1, N*2+1) {
        REP(black, sum + 1) {
            if (black > N) break;
            auto white = sum - black;
            if (white > N) continue;

            // dp[1][1] <- dp[1][0]
            dp[black][white] = INF;

            if (white > 0) {
                white--;
                dp[black][white] =
                    min(dp[black][white],
                        // 白 white を先頭にもってくる。
                        // 要素数は、もともとのwhiteの位置から

                        dp[black][white - 1]
                        + white_pos[white]
                        - white_table[white - 1][white_pos[white]]
                        - black_table[black][white_pos[white]]
                    );
            }
            if (black > 0) {
                black--;
                dp[white][black] =
                    min(dp[white][black],
                        dp[white][black - 1]
                        + black_pos[black]
                        - black_table[black - 1][black_pos[black]]
                        - white_table[white][black_pos[black]]
                    );
            }
        }
    }
    cout << dp[N][N] << endl;
    return 0;
}

