int n;
char color[4400];
int a[4400], pos_w[4400], pos_b[4400];
int dp[2200][2200], 
cnt_w[2200][2200],// [i, n*2)にあるj以下の数の個数（白色の） 
cnt_b[2200][2200];// [i, n*2)にあるj以下の数の個数（黒色の）

void solve()
{
	memset(pos_w, -1, sizeof pos_w); 
	memset(pos_b, -1, sizeof pos_b);

	cin >> n;
	REP(i, n * 2) {
		cin >> color[i] >> a[i]; a[i]--;
		if (color[i] == 'W') pos_w[a[i]] = i;
		else pos_b[a[i]] = i;
	}

	for (int i = n * 2 - 1; i >= 0; i--) {
		for (int h = 0; h <= i; h++) {
			if (color[i] == 'W') cnt_w[h][a[i]]++;
			else cnt_b[h][a[i]]++;
		}
	}
	REP(i, n * 2) {
		for (int j = 1; j<(n * 2); j++) {
			cnt_w[i][j] += cnt_w[i][j - 1];
			cnt_b[i][j] += cnt_b[i][j - 1];
		}
	}

	REP(i, 2200) REP(j, 2200) dp[i][j] = INF;
	dp[0][0] = 0;
	for (int i = 0; i <= n; i++)for (int j = 0; j <= n; j++) { // 白:0, 1, ..., i-1まで置いた；次置くのはi
		if (i<n) {
			int cost_w = 0;
			if (i - 1 >= 0) cost_w += cnt_w[pos_w[i]][i - 1];
			if (j - 1 >= 0) cost_w += cnt_b[pos_w[i]][j - 1];
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + cost_w);
		}
		if (j<n) {
			int cost_b = 0;
			if (j - 1 >= 0) cost_b += cnt_b[pos_b[j]][j - 1];
			if (i - 1 >= 0) cost_b += cnt_w[pos_b[j]][i - 1];
			dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + cost_b);
		}
	}
	cout << dp[n][n] << endl;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout << fixed << setprecision(13);
	solve();
	return 0;
}

