/*
白を i 個、黒を ｊ 個解決するための最小手数を DP です。
この状態で白を解決するためには、その位置が x とすると、
x より左で未解決なものの個数です。
そこで、解決しているものをセグツリーで管理です。
ループの内側で n 回セグツリーを作ります。
*/

#include "bits/stdc++.h"

using namespace std;

typedef long long ll;
constexpr int INF = numeric_limits<int>::max() / 2;

// BIT
// initialize : FenwickTree(n)
// add(pos, n): data[pos] += n;
// sum(l, r)  : sum [l, r)
template <typename T>
class FenwickTree
{
  const int n;
  vector<T> data;

public:
  FenwickTree(int count) : n(count), data(count, 0) { ; }

  void add(int pos, const T &value)
  {
    assert(0 <= pos && pos < n);
    for (int i = pos; i < n; i |= i + 1)
      data[i] += value;
  }

  T sum(int pos) const
  {
    assert(0 <= pos && pos <= n);
    T res = 0;
    for (int i = pos - 1; i >= 0; i = (i & (i + 1)) - 1)
    {
      res += data[i];
    }
    return res;
  }

  T sum(int l, int r) const
  {
    assert(0 <= l && l <= r && r <= n);
    return sum(r) + (-sum(l));
  }
  using value_type = T;
  using update_type = T;
};

