	rep(i,2*N){
		if(c[i]=="W"){
			W[i]=a[i];
			mW[a[i]]=i;
		}else{
			B[i]=a[i];
			mB[a[i]]=i;
		}
	}

	constexpr ll bitlength = 1 + log2(2000);
	WaveletMatrix<ll,bitlength,0LL> wmW(W.begin(), W.end());
	WaveletMatrix<ll,bitlength,0LL> wmB(B.begin(), B.end());

	vector<vector<ll>> dp(N+1,vector<ll>(N+1,INF));
	dp[0][0]=0;
	rep(i,N+1)rep(j,N+1){
		if(i<N){
			ll windex=mW[i+1];
			ll maisu1=wmW.rangefreq(0, windex, i+2, N+1);
			ll maisu2=wmB.rangefreq(0, windex, j+1, N+1);
			chmin(dp[i+1][j],dp[i][j]+maisu1+maisu2);
