			ll bindex=mB[j+1];
			ll maisu3=wmW.rangefreq(0, bindex, i+1, N+1);
			ll maisu4=wmB.rangefreq(0, bindex, j+2, N+1);
			chmin(dp[i][j+1],dp[i][j]+maisu3+maisu4);
		}
	}

	p(dp[N][N]);
}

