#include <bits/stdc++.h>
using namespace std;


int N;
vector<int> a;

const int NMAX = 2000;

int dp[NMAX+1][NMAX+1];

int main()
{
    scanf("%d\n", &N);
    a.resize(N * 2);

    for (int i=0; i<2*N; i++)
    {
        char str;
        scanf("%s", &str);
        scanf("%d", &a[i]);
        if (str == 'W') a[i] *= -1;
    }

    vector<vector<int> > memo(2*N);
    //各石（黒1~N、」白1~N）の手前にある石を全部調べてソートしておく(N^2logN)
    for (int j=1; j<=N; j++) // 黒j
    {
        for (int i=0; i<2*N; i++)
        {
            if (a[i] == j) break;
            memo[j-1].push_back(a[i]);
        }
    }
    for (int j=1; j<=N; j++) // 白j
    {
        for (int i=0; i<2*N; i++)
        {
            if (a[i] == -j) break;
            memo[N + j - 1].push_back(a[i]);
        }
    }

    for (int i=0; i<2*N; i++) sort(memo[i].begin(), memo[i].end());

    // dp[i][j] : 先頭から黒i個白j個が正しい順に並ぶまでの最小操作回数

    dp[0][0] = 0;

    for (int i=1; i<=N; i++)
    {
        int aa = 0;
        for (int k=0; k<2*N; k++)
        {
            if (a[k] == i) break;
            if (a[k] > i || a[k] < 0) aa++;
        }
        int bb = 0;
        for (int k=0; k<2*N; k++)
        {
            if (a[k] == -i) break;
            if (a[k] < -i || a[k] > 0) bb++;
        }

        dp[i][0] = dp[i-1][0] + aa;
        dp[0][i] = dp[0][i-1] + bb;
    }

    for (int i=1; i<=N; i++)
    {
        for (int j=1; j<=N; j++)
        {
            /* iroiro */
            // 数字iが書かれた黒を手前に持ってくるまでの総回数
            int aa = 
            distance(lower_bound(memo[i-1].begin(), memo[i-1].end(), i), memo[i-1].end())
            + distance(memo[i-1].begin(), lower_bound(memo[i-1].begin(), memo[i-1].end(), -j));
            int bb =
            distance(upper_bound(memo[j-1+N].begin(), memo[j-1+N].end(), i), memo[j-1+N].end())
            + distance(memo[j-1+N].begin(), lower_bound(memo[j-1+N].begin(), memo[j-1+N].end(), -j));

            dp[i][j] = min(dp[i-1][j] + aa, dp[i][j-1] + bb);
        }
    }

    printf("%d\n", dp[N][N]);
    return 0;
}

