template<int D,class point> struct kd_tree{
    point p;
    int axis;
    kd_tree<D,point>* left,*right;
    kd_tree(int axis_=-1):left(NULL),right(NULL),axis(axis_){};
    kd_tree(vector<point> points,int axis_=0):left(NULL),right(NULL),axis(axis_){ assert(points.size()); build(points,0,points.size()); }
    ~kd_tree(){ delete left; delete right; }
    kd_tree<D,point>* build(vector<point> &points,int l,int r){
        int m=(l+r)/2;
        nth_element(points.begin()+l,points.begin()+m,points.begin()+r,[&](const point& p,const point& q){ return p[axis]<q[axis]; });
        p=points[m];
        if(l<m){
            left=new kd_tree<D,point>((axis+1)%D);
            left->build(points,l,m);
        }
        if(m+1<r){
            right=new kd_tree<D,point>((axis+1)%D);
            right->build(points,m+1,r);
        }
        return this;
    }
    //例えば,同じ点が大量にinsertされると右の子ばかり増えてしまう.そのようなときは適当なタイミングで全体をリビルドしたほうがよいかも.
    kd_tree<D,point>* insert(const point& q){
        if(axis==-1){
            axis=0;
            p=q;
            return this;
        }
        if(q[axis]<p[axis]){
            if(left==NULL){
                left=new kd_tree<D,point>({q},(axis+1)%D);
                return left;
            }else return left->insert(q);
        }else{
            if(right==NULL){
                right=new kd_tree<D,point>({q},(axis+1)%D);
                return right;
            }else return right->insert(q);
        }
    }
    //未検証.多分遅い(O(n))のでerasedタグを付けて置いて,erasedが一定以上増えたら全体をbuildするようにした方が良いかも.
    void erase(const point& q){
        kd_tree<D,point>* tree=nearest_neighbor(q);
        vector<point> points=tree->collect();
        points.erase(points.rbegin());
        delete tree->left;
        delete tree->right;
        tree->build(points,0,points.size());
    }
    //未検証
    vector<point> collect()const{
        vector<point> points;
        if(left!=NULL){
            vector<point> left_points=left->collect();
            points.insert(points.end(),left_points.begin(),left_points.end());
        }
        if(right!=NULL){
            vector<point> right_points=right->collect();
            points.insert(points.end(),right_points.begin(),right_points.end());
        }
        points.push_back(p);
        return points;
    };
    const kd_tree<D,point>* nearest_neighbor(const point& q)const{ //const外した方が良いかも
        const kd_tree<D,point>* res=this;
        long double mind=1e130;
        auto dist=[&](const point& p,const point& q){
            long double d=0;
            for(int i=0; i<D; ++i) d+=(p[i]-q[i])*(p[i]-q[i]);
            return d;
        };
        function<void(const kd_tree<D,point>*)> rec=[&](const kd_tree<D,point>* tree){
            auto d=dist(tree->p,q);
            if(d<mind){
                mind=d;
                res=tree;
            }
            if(q[tree->axis]<tree->p[tree->axis]){
                if(tree->left!=NULL) rec(tree->left);
                if(tree->right!=NULL and tree->p[tree->axis]-q[tree->axis]<=mind) rec(tree->right);
            }else{
                if(tree->right!=NULL) rec(tree->right);
                if(tree->left!=NULL and q[tree->axis]-tree->p[tree->axis]<=mind) rec(tree->left);
            }
        };
        rec(this);
        return res;
    }
    i64 range_search(const point& lb,const point& ub)const{
        i64 res;
        function<void(const kd_tree<D,point>*)> rec=[&](const kd_tree<D,point>* tree){
            bool in_range=true;
            for(int i=0; i<D; ++i) if(tree->p[i]<lb[i] or ub[i]<tree->p[i]){
                in_range=false;
                break;
            }
            if(in_range) ++res;
            if(tree->left!=NULL and lb[tree->axis]<=tree->p[tree->axis]) rec(tree->left);
            if(tree->right!=NULL and ub[tree->axis]>=tree->p[tree->axis]) rec(tree->right);
        };
        rec(this);
        return res;
    }
};

void solve(){
    int N;
    cin >> N;
    vector<char> c(2*N);
    vector<int> a(2*N);
    rep(i,0,2*N){
        cin >> c[i] >> a[i];
        --a[i];
    }

    i64 ans=0;
    rep(i,0,N){
        int ma=N-i-1;
        {
            int p;
            rep(j,0,2*N) if(c[j]=='W' and a[j]==ma){
                p=j;
                break;
            }
            rep(j,p+1,2*N) if(c[j]=='W' and a[j]<ma) ++ans;
        }
         {
            int p;
            rep(j,0,2*N) if(c[j]=='B' and a[j]==ma){
                p=j;
                break;
            }
            rep(j,p+1,2*N) if(c[j]=='B' and a[j]<ma) ++ans;
        }
    }

    vector<i64> s(N),t(N);
    rep(i,0,2*N){
        if(c[i]=='W') s[a[i]]=i;
        else t[a[i]]=i;
    }

    kd_tree<2,vector<double>> wb,bw;
    rep(i,0,N){
        {
            vector<double> tmp({(double)i,(double)s[i]});
            wb.insert(tmp);
        }
        {
            vector<double> tmp({(double)i,(double)t[i]});
            bw.insert(tmp);
        }

    }

    function<i64(int,int)> f=[&](int i,int j){
        vector<double> lb({0,s[i]+0.5}),ub({j+0.5,inf});
        return (i64)bw.range_search(lb,ub);
    };

    function<i64(int,int)> g=[&](int i,int j){
        vector<double> lb({0,t[i]+0.5}),ub({j+0.5,inf});
        return (i64)wb.range_search(lb,ub);
    };

    static i64 dp[2048][2048];
    fill_n((i64*)dp,2048*2048,inf64);

    rep(i,0,N+1) dp[i][0]=dp[0][i]=0;

    rep(i,1,N+1) rep(j,1,N+1){
        dp[i][j]=min(dp[i][j],dp[i-1][j]+f(i-1,j-1));
        dp[i][j]=min(dp[i][j],dp[i][j-1]+g(j-1,i-1));
    }

    cout << ans+dp[N][N] << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

