const int inf = 1e9;

int main(){
	int n;
	cin >> n;
	vector<int> c(2*n, 0),a(2*n);
	REP(i, 2*n){
		char ch;
		cin >> ch >> a[i];
		if(ch == 'B') c[i] = 1;
	}

	int ans = 0;
	int step = 0;
	while(1){
		bool changed = false;
		set<int> dicfront[2];
		set<int> dicrear[2];
		REP(i, 2*n) dicrear[c[i]].insert(-a[i]);

		REP(i, 2*n-1){
			dicrear[c[i]].erase(-a[i]);
			if(c[i] == c[i+1]){
				if(a[i] > a[i+1]){
					swap(a[i], a[i+1]);
					swap(c[i], c[i+1]);
					ans++;
					changed = true;
				}
			}else{
				bool con[2] = {dicrear[c[i]].upper_bound(-a[i])!=dicrear[c[i]].end(),
					dicfront[c[i+1]].upper_bound(a[i+1])!=dicfront[c[i+1]].end()};
				if((con[0] && con[1]) || (step==1 &&(con[0] || con[1]))){
					swap(a[i], a[i+1]);
					swap(c[i], c[i+1]);
					ans++;
					changed = true;
				}
			}
			dicfront[c[i]].insert(a[i]);
		}
		if(!changed){
			if(step==1) break;
			else step=1;
		}
	}
	cout << ans << endl;
	return 0;
}

