class SegTree {
public:
	int n, height;
	vector<ll> dat;

	ll def = 0;
	ll operation(int a, int b) {
		return a + b;
	}

	// 初期化（_nは必要な要素数）
	SegTree(int _n) {
		n = 1;
		height = 1;
		while (n < _n) {
			n *= 2;
			height++;
		}
		dat = vector<ll>(2 * n - 1, def);
	}

	// 場所i(0-indexed)にxを足す
	void add(int i, ll x) {
		i += n - 1;
		dat[i] += x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] += x;
		}
	}

	// 場所i(0-indexed)の値をxに更新
	void change(int i, ll x) {
		i += n - 1;
		dat[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = operation(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	// 区間[a,b)の総和。ノードk=[l,r)に着目している。
	ll _query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return def;  // 交差しない
		if (a <= l && r <= b)return dat[k];   // a,l,r,bの順で完全に含まれる
		else {
			ll c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2);    // 左の子
			ll c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r);    // 右の子
			return operation(c1, c2);
		}
	}

	// 内部クエリ_query()を呼び出す
	ll query(int a, int b) {
		return _query(a, b, 0, 0, n);
	}
};

int main() {
	int N;
	cin >> N;
	vc c(2 * N);
	vi a(2 * N);
	vi bpos(N), wpos(N);
	rep(i, 2 * N) {
		cin >> c[i] >> a[i];
		a[i]--;
		if (c[i] == 'B') {
			bpos[a[i]] = i;
		}
		else {
			wpos[a[i]] = i;
		}
	}

	vvi bb(N, vi(N)), bw(N, vi(N)), wb(N, vi(N)), ww(N, vi(N));
	// cd[i][j] = c色のiの右にあるd色のj以下の個数
	SegTree sgb(2 * N), sgw(2 * N);
	rep(i, N) {
		// それぞれのセグ木で数iの位置を加算
		sgb.change(bpos[i], 1);
		sgw.change(wpos[i], 1);

		rep(j, N) {
			bb[j][i] = sgb.query(bpos[j] + 1, 2 * N);
			bw[j][i] = sgw.query(bpos[j], 2 * N);
			wb[j][i] = sgb.query(wpos[j], 2 * N);
			ww[j][i] = sgw.query(wpos[j] + 1, 2 * N);
		}
	}


	// dp[i][j] = 黒がi-1まで、白がj-1まである状態のswap数
	vvi dp(N + 1, vi(N + 1, 0));

	repr(i, 2, N + 1) {
		dp[0][i] = dp[0][i-1] + ww[i - 1][i - 2];
	}
	repr(i, 2, N + 1) {
		dp[i][0] = dp[i-1][0] + bb[i - 1][i - 2];
	}

	rep(i, N) {
		rep(j, N) {
			dp[i + 1][j + 1] = min(	dp[i][j + 1] + (i==0?0:bb[i][i - 1]) + bw[i][j],
									dp[i + 1][j] + wb[j][i] + (j==0?0:ww[j][j - 1]));
		}
	}

	cout << dp[N][N] << endl;

	return 0;
}

