const int N=4005;

int n,a[N],ans=INT_MAX,cur,BIT[N];
char c[N];

void update(int pos){
	for (int i=pos;i;i-=(i&-i)){
		BIT[i]++;
	}
}

int query(int pos){
	int ret=0;
	for (int i=pos;i<N;i+=(i&-i)){
		ret+=BIT[i];
	}
	return ret;
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> n;
	for (int i=1;i<=n*2;i++){
		cin >> c[i] >> a[i];
	}
	for (int i=1;i<=n+1;i++){
		memset(BIT,0,sizeof(BIT));
		int now=0;
		for (int j=1;j<=n*2;j++){
			if (c[j]=='B'){
				cur=i+a[j]-1;
			}else{
				if (a[j]<i){
					cur=a[j];
				}else{
					cur=i+n-1+a[j]-(i-1);
				}
			}
			now+=query(cur+1);
			update(cur);
		}
		ans=min(ans,now);
		memset(BIT,0,sizeof(BIT));
		now=0;
		for (int j=1;j<=n*2;j++){
