	F(i,1,2*n) {
		scanf("%s%d", str, &p[i]);
		c[i] = str[0] == 'B';
		pos[c[i]][p[i]] = i;
	}
	F(i,1,2*n) {
		int tot = 0;
		F(j,1,i) if(c[j] != c[i]) pre[i][p[j]] ++; else if(p[j] <= p[i]) tot ++;
		F(j,1,n) pre[i][j] += pre[i][j-1];
		F(j,0,n) pre[i][j] += tot;
	}
	F(i,0,n) {
		F(j,0,n) {
			int p0 = pos[0][i], p1 = pos[1][j];
