	for (int i=n*2;i>=1;i--){
		for (int j=1;j<=n*2+1;j++)
			tot[i][j]=tot[i+1][j];
		if (a[i]<=n)
			for (int j=a[i];j<=n;j++)
				tot[i][j]++;
		else
			for (int j=a[i];j<=n*2;j++)
				tot[i][j+1]++;
	}
	memset(dp,63,sizeof dp);
	dp[0][0]=0;
	for (int i=1;i<=n*2;i++)
