				continue;
			if (w>0)
				dp[i][j]=min(dp[i][j],dp[i-1][j-1]+p[w]-i+tot[p[w]][w-1]+tot[p[w]][b+1]);
			if (b>n)
				dp[i][j]=min(dp[i][j],dp[i-1][j]+p[b]-i+tot[p[b]][b-1+1]+tot[p[b]][w]);
		}
