#define int ll

void solve() {
	int N; cin >> N;
	vector<pair<bool, int> > field; // isWhite, number
	map<pair<bool, int>, int> pos;

	for (int i = 0; i < 2 * N; ++i) {
		char c; int a; cin >> c >> a;
		field.emplace_back(c == 'W', a);
		pos[make_pair(c == 'W', a)] = i;
	}

	vector<vector<int> > blackCnt(N + 1, vector<int>(field.size()+2));
	vector<vector<int> > whiteCnt(N + 1, vector<int>(field.size()+2));


	for (int i = 1; i < N + 1; ++i) {
		blackCnt[i][field.size()-1] = (not field[field.size()-1].first and field[field.size()-1].second <= i ? 1 : 0);
		whiteCnt[i][field.size()-1] = (field[field.size()-1].first and field[field.size()-1].second <= i ? 1 : 0);
		for (int j = field.size()-2; j >= 0; --j) {
			blackCnt[i][j] = blackCnt[i][j + 1];
			whiteCnt[i][j] = whiteCnt[i][j + 1];
			if (not field[j].first and field[j].second <= i) blackCnt[i][j]++;
			if (field[j].first and field[j].second <= i) whiteCnt[i][j]++;
		}
	}


	vector<vector<int> > dp(N+1, vector<int>(N+1, inf));
	dp[0][0] = 0;
	for (int i = 1; i < N+1; ++i) {
		int p = pos[make_pair(false, i)];
		dp[0][i] = dp[0][i - 1] + blackCnt[i - 1][p+1];
	}
	for (int i = 1; i < N+1; ++i) {
		int p = pos[make_pair(true, i)];
		dp[i][0] = dp[i-1][0] + whiteCnt[i - 1][p+1];
	}

	for (int w = 1; w <= N; ++w) {
		for (int b = 1; b <= N; ++b) {
			int blackPos = pos[make_pair(false, b)];
			int whitePos = pos[make_pair(true, w)];
			dp[w][b] = min(dp[w - 1][b] + blackCnt[b][whitePos + 1] + whiteCnt[w - 1][whitePos + 1], dp[w][b - 1] + blackCnt[b - 1][blackPos + 1] + whiteCnt[w][blackPos + 1]);
		}
	}
	cout << dp[N][N] << endl;
}

