int update(int k, int i) {
    for(i; i <= 2*n; i += i & (-i)) t[k][i]++;
}

int get(int k, int i) {
    int res = 0;
    for(i; i; i -= i & (-i)) res += t[k][i];
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
