int dfs(int n, int sa, int flg) {
  if ( n == N*2 ) return 0;
  if ( dp[n][sa][flg] >= 0 ) return dp[n][sa][flg];

  int ret = INF;
  if ( n == 0 ) {
    ret = min(ret, dfs(n+1, 1, 1) + bp[0]);
    ret = min(ret, dfs(n+1, 1, 0) + wp[0]);    
  } else {
    int x = (n+sa)/2;
    int y = n-x;
    if ( flg && x > y ) swap(x, y);
    if ( !flg && x < y ) swap(x, y);
    if ( x < N ) {
      int add;
      int tmp = wp[x];
      if ( x >= 1 ) tmp += wt[x-1][n+1];
      if ( y >= 1 ) tmp += bt[y-1][n+1];
      if ( tmp <= n ) add = 0;
      else add = tmp-n;
      //cout << n << " " << sa << " " << flg << " " << add << endl;
      ret = min(ret, dfs(n+1, abs((x+1)-y), y>x) + add);
    }
    if ( y < N ) {
      int add;
      int tmp = bp[y];
      if ( x >= 1 ) tmp += wt[x-1][n+1];
      if ( y >= 1 ) tmp += bt[y-1][n+1];
      if ( tmp <= n ) add = 0;
      else add = tmp-n;
      //cout << n << " " << sa << " " << flg << " " << add << endl;
      ret = min(ret, dfs(n+1, abs(x-(y+1)), y>x) + add);
    }
  }

  return dp[n][sa][flg] = ret;

}

