        else { posB[A[i]] = i; }
    }

    ZERO(dp);
    ZERO(costB);
    ZERO(costW);

    REP(i, 2 * N) {
        bit_Bs[i] = new BITree<int>(N);
        bit_Ws[i] = new BITree<int>(N);
        for(int ind = 0; ind < i; ++ind) {
            if(C[ind] == 'B') { bit_Bs[i]->Add(A[ind], 1); }
            else { bit_Ws[i]->Add(A[ind], 1); }
        }
    }

    for(int i = 0; i <= N; ++i) {
        for(int j = 0; j <= N; ++j) {
            costB[i][j] += bit_Bs[posB[i+1]]->Sum(i+2, N);
            costB[i][j] += bit_Ws[posB[i+1]]->Sum(j+1, N);
            costW[i][j] += bit_Bs[posW[j+1]]->Sum(i+1, N);
            costW[i][j] += bit_Ws[posW[j+1]]->Sum(j+2, N);
        }
    }

    dp[0][0] = 0;
    for(int i = 0; i <= N; ++i) {
