            if(j > 0) { cand2 = dp[i][j-1] + costW[i][j-1]; }
            dp[i][j] = min(cand1, cand2);
        }
    }

    REP(i, 2 * N) {
        delete bit_Bs[i];
        delete bit_Ws[i];
    }

    printf("%d\n", dp[N][N]);
    return 0;
}

