// one-based numbering
template<class T> struct Fenwick {
    vector<T> bit; int N;
    Fenwick(int n) {
        N = n;
        bit.resize(n+1, 0);
    }
    void add(int a, T w) {
        for (int x = a; x <= N; x += x & -x) bit[x] += w;
    }
    T sum(int a) {
        T ret = 0;
        for (int x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }
};

int main() {
    int n; cin >> n;
    int b[n+1][n+1]; int w[n+1][n+1];
    Fenwick<int> fb(n+1), fw(n+1);
    int bcount = 0; int wcount = 0;
    for (int i = 1; i <= 2*n; i++) {
        char c; int t; cin >> c >> t;
        if (c == 'B') {
            int tmp = (t-1) - fb.sum(t);
            b[t][0] = tmp + wcount;
            for (int j = 1; j <= n; j++) {
                b[t][j] = tmp + wcount - fw.sum(j);
            }
            fb.add(t, 1);
            bcount++;
        } else {
            int tmp = (t-1) - fw.sum(t);
            w[0][t] = tmp + bcount;
            for (int j = 1; j <= n; j++) {
                w[j][t] = tmp + bcount - fb.sum(j);
            }
            fw.add(t, 1);
            wcount++;
        }
    }
    vector<vector<int>> dp(n+1, vector<int>(n+1, 1e9));
    dp[0][0] = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            if (i != 0) dp[i][j] = min(dp[i][j], dp[i-1][j] + b[i][j]);
            if (j != 0) dp[i][j] = min(dp[i][j], dp[i][j-1] + w[i][j]);
        }
    }
    cout << dp[n][n] << endl;
    return 0;
}

