class BIT {
public:
	vll dat;
	int n;
	BIT(int _n) {
		n = 1;
		while (n <= _n)	n <<= 1;
		dat.assign(n + 1, 0);
	}

	void add(int k, ll v) {
		k++;
		while (k <= n) {
			dat[k] += v;
			k += -k & k;
		}
	}

	ll get(int k) {
		k++;
		ll ret = 0;
		while (k > 0) {
			ret += dat[k];
			k -= -k & k;
		}
		return ret;
	}
};

int main() {
