			posB[a] = i;
		}
	}
	// number of bk
	REP(i, n) {
		BIT bit(m);
		rep(j, i) {
			bit.add(posB[j + 1], 1);
		}
		srep(j, i, m) {
			costW[j][i] = (posW[j - i + 1] - j) + (j - bit.get(posW[j - i + 1]));
			costB[j][i] = (posB[i + 1] - j) + (j - bit.get(posB[i + 1]));
			bit.add(posW[j - i + 1], 1);
		}
	}
	REP(i, m)	REP(j, n)	dp[i][j] = inf;
	dp[0][0] = 0;
	rep(i, m) {
		REP(j, min(i + 1, n)) {
			if (dp[i][j] == inf)	continue;
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + costW[i][j]);
			dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + costB[i][j]);
		}
	}
	cout << dp[m][n] << endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
int bit[40000];
int u;
void bitinit(int n){
  int now=1;
  for(int i=0;;i++){
    if(now>=n){
      u=now;
      break;
    }
    now*=2;
  }
  fill(bit,bit+u+1,0);
}
void add(int n,int x){
  int i=n;
  while(i<=u){
    bit[i]+=x;
    i+=i&-i;
  }
}
int sum(int n){
  int ret=0;
  int i=n;
  while(i>0){
    ret+=bit[i];
    i-=i&-i;
  }
}
int main(){
  int n;cin>>n;
  int bla[n+1];
  int whi[n+1];
  int a[2*n+1];
  char b[2*n+1];
  bitinit(n);
  for(int i=0;i<2*n;i++){
    char c;cin>>c;
    int m;cin>>m;
    if(c=='B')bla[m]=i+1;
    else whi[m]=i+1;
    add(i+1,1);
    a[i+1]=m;
    b[i+1]=c;
  }
  int ans=0;
  bool used[2*n+1];
  fill(used,used+2*n+1,false);
  int bl=0;
  int wh=0;
  for(int i=1;i<=2*n;i++){
    if(used[i])continue;
    if(b[i]=='B'){
      if(bl+1==a[i]){
        bl++;
        used[i]=true;
        continue;
      }
      else{
        int y=bla[bl+1];
        ans+=sum(y)-sum(i);
        add(y,-1);
        used[y]=true;
        bl++;
      }
    }
    if(b[i]=='W'){
      if(wh+1==a[i]){
        wh++;
        used[i]=true;
        continue;
      }
      else{
        int y=whi[wh+1];
        ans+=sum(y)-sum(i);
        add(y,-1);
        used[y]=true;
        wh++;
      }
    }
  }
  cout<<ans<<endl;
}

