int N,a[MAXN * 2];
char c[MAXN * 2][5];
int tr[2][MAXN],cost[2][MAXN][MAXN],dp[MAXN][MAXN];
int lowbit(int x) {return x & (-x);}
void Insert(int id,int x) {
    while(x <= N) {
	tr[id][x]++;
	x += lowbit(x);
    }
}
int Query(int id,int x) {
    int res = 0;
    while(x > 0) {
	res += tr[id][x];
	x -= lowbit(x);
    }
    return res;
}
void Solve() {
    scanf("%d",&N);
    for(int i = 1 ; i <= 2 * N ; ++i) {
	scanf("%s%d",c[i] + 1,&a[i]);
    }
    for(int i = 1 ; i <= 2 * N ; ++i) {
	if(c[i][1] == 'W') {
	    for(int j = 0 ; j <= N ; ++j) {
		cost[0][a[i] - 1][j] = (i - 1) - Query(0,a[i] - 1) - Query(1,j);
	    }
	    Insert(0,a[i]);
	}
	else {
	    for(int j = 0 ; j <= N ; ++j) {
		cost[1][j][a[i] - 1] =  (i - 1) - Query(0,j) - Query(1,a[i] - 1);
	    }
	    Insert(1,a[i]);
	}
    }
    for(int i = 0 ; i <= N ; ++i) {
	for(int j = 0 ; j <= N ; ++j) {
	    if(i == 0 && j == 0) continue;
	    dp[i][j] = 0x7fffffff;
	    if(i != 0) {
		dp[i][j] = min(dp[i][j],dp[i - 1][j] + cost[0][i - 1][j]);
	    }
	    if(j != 0) {
		dp[i][j] = min(dp[i][j],dp[i][j - 1] + cost[1][i][j - 1]);
	    }
	}
    }
    printf("%d\n",dp[N][N]);
}
