int n;
int w[4005],b[4005];
int aa[4005][4005],bb[4005][4005],dp[4005][4005];

int main(){
	cin>>n;
	for(int i=1;i<=2*n;i++){
		int d;
		char c;
		cin>>c>>d;
		if(c=='W') w[d]=i;
		else b[d]=i;
	}
	for(int i=1;i<=n;i++){
		for(int j=1;j<=n;j++){
			aa[i][j]=aa[i][j-1]+(w[j]>b[i]);
			bb[i][j]=bb[i][j-1]+(b[j]>w[i]);
		}
	}
	for(int i=0;i<=n;i++) for(int j=0;j<=n;j++) dp[i][j]=1e9+7;
	dp[0][0]=0;
	for(int i=0;i<=n;i++){
		for(int j=0;j<=n;j++){
			if(i<n) dp[i+1][j]=min(dp[i+1][j],dp[i][j]+aa[i+1][j]);
			if(j<n) dp[i][j+1]=min(dp[i][j+1],dp[i][j]+bb[j+1][i]);
		}
	}
	for(int i=1;i<=n;i++){
		for(int j=1;j<i;j++) dp[n][n]+=(w[i]<w[j])+(b[i]<b[j]);
	}
	cout<<dp[n][n]<<endl;
	return 0;
