// 2000. 현재 상태에 따라서. 모든 스왑수가 정해지지 않나?
// 어떤 점에서 반대 색깔이 몇까지 열렸을 떄 원하는 자리로 가는 데에 필요한 연산수.
// 뒤에 자신보다 순서가 앞선 점의 개수만큼 자신 위치를 더해준다.
// 2000 * 2000 쌍에 대한 순서..

int dp[2001][2001];
int ww[2000], bb[2000];
int wg[2000][2001], bg[2000][2001];
int n;
int tree[4001];
int tmp[4001];

void update(int i, int val) {
	for (; i <= 2 * n; i += i & -i)
		tree[i] += val;
}

int find(int i) {
	int sum = 0;
	for (; i; i -= i & -i)
		sum += tree[i];
	return sum;
}

int go(int o, int oo) {
	if (o == n && oo == n) return 0;
	if (dp[o][oo] != -1) return dp[o][oo];

	int miv = 1e9;
	if(o != n) miv = min(miv, go(o + 1, oo) + ww[o] + wg[o][oo] - (o + oo + 1)); // 현재 위치. o + oo + 1에 맞춰져야 함.
	if(oo != n) miv = min(miv, go(o, oo + 1) + bb[oo] + bg[oo][o] - (o + oo + 1));

	// printf("%d %d : %d %d // %d %d // %d\n", o, oo, ww[o], wg[o][oo], bb[o], bg[o][oo], miv);
	return dp[o][oo] = miv;
}

int main() {
	memset(dp, -1, sizeof(dp));
	scanf("%d", &n);

	char a;
	int b, l = 0, r = 0;
	for (int i = 0; i < 2 * n; i++) {
		scanf(" %c %d", &a, &b);
		b--;

		if (a == 'W') ww[b] = i + 1;
		else bb[b] = i + 1;
	}

	for (int i = 0; i < n; i++) {
		memcpy(tmp, tree, sizeof(tmp));

		wg[i][0] = find(2 * n) - find(ww[i]);
		for (int j = 0; j < n; j++) {
			update(bb[j], 1);
			wg[i][j + 1] = find(2 * n) - find(ww[i]);
		}

		memcpy(tree, tmp, sizeof(tmp));
		update(ww[i], 1);
	}

	memset(tree, 0, sizeof(tree));
	for (int i = 0; i < n; i++) {
		memcpy(tmp, tree, sizeof(tmp));

		bg[i][0] = find(2 * n) - find(bb[i]);
		for (int j = 0; j < n; j++) {
			update(ww[j], 1);
			bg[i][j + 1] = find(2 * n) - find(bb[i]);
		}

		memcpy(tree, tmp, sizeof(tmp));
		update(bb[i], 1);
	}

	printf("%d", go(0, 0));
}

