void init(int k) {
	bmemo = -1; wmemo = -1;
	for (int i = 0; i < 2 * n; i++) {
		if (x[i] / n == 0) {
			b[x[i]] = i;
			if (i == 0) {
				wmax[0] = -1;
				bmax[0] = x[0];
			}
			else {
				bmax[i] = max(bmax[i - 1], x[i]);
				wmax[i] = wmax[i - 1];
			}
		}
		else {
			w[x[i] - n] = i;
			if (i == 0) {
				wmax[0] = x[0] - n;
				bmax[0] = -1;
			}
			else {
				wmax[i] = max(wmax[i - 1], x[i] - n);
				bmax[i] = bmax[i - 1];
			}
		}
		if (bmemo==-1&&x[i]/n==0&&x[i]>k)bmemo = i;
		if (wmemo==-1&&x[i] / n == 1&&x[i]-n>k)wmemo = i;
	}
}
