#include <bits/stdc++.h>

using namespace std;

const int N = 2222;
int n;
string c[N * 2];
int a[N * 2], p[N][2];
int f[2][N][2];

void upd(int &x, int y) {
  if (x == -1) x = y;
  else x = min(x, y);
}

int g[2][N * 2][N];

// sign:[1, ed), > val
int cnt(int sign, int ed, int val) {
  return g[sign][ed - 1][val + 1];
}


int main() {

  cin >> n;

  memset(g, 0x00, sizeof(g));

  for (int i = 1; i <= n * 2; ++i) {
    cin >> c[i] >> a[i];
    int sign = (c[i] == "W" ? 0: 1);
    p[a[i]][sign] = i;
    for (int j = i; j <= n * 2; ++j) {
      g[sign][j][a[i]]++;
    }
  }

  for (int sign = 0; sign < 2; ++sign) {
    for (int ed = 1; ed <= n * 2; ++ed) {
      for (int val = n - 1; val >= 1; --val) {
        g[sign][ed][val] += g[sign][ed][val + 1];
      }
    }
  }

  int x = 0, y = 1;

  memset(f[x], 0xff, sizeof(f[x]));

  f[x][1][0] = cnt(0, p[1][0], 1) + cnt(1, p[1][0], 0);
  f[x][1][1] = cnt(0, p[1][1], 0) + cnt(1, p[1][1], 1);

  for (int i = 2; i <= n * 2; ++i, swap(x, y)) {

    memset(f[y], 0xff, sizeof(f[y]));

    for (int j = 1; j <= n; ++j) {
      for (int k = 0; k < 2; ++k) {

        if (f[x][j][k] == -1) continue;

        int _j = (i - 1) - j;

        if (j + 1 <= n) upd(f[y][j + 1][k], f[x][j][k] + cnt(k, p[j + 1][k], j + 1) + cnt(k ^ 1, p[j + 1][k], _j));        

        if (_j + 1 <= n) upd(f[y][_j + 1][k ^ 1], f[x][j][k] + cnt(k, p[_j + 1][k ^ 1], j) + cnt(k ^ 1, p[_j + 1][k ^ 1], _j + 1));        



      }
    }

  }

  cout << min(f[x][n][0], f[x][n][1]) << endl;

  return 0;
}

