        per(j, n) {
            bsum[j] = bsum[j+1] + bnum[j];
            wsum[j] = wsum[j+1] + wnum[j];
        } //後ろからみる
        per(j, n+1) {
            if(col == 'B') black[num][j] = bsum[num+1] + wsum[j];
            if(col == 'W') white[num][j] = wsum[num+1] + bsum[j];
        }
        if(col == 'B') {
            bnum[num] ++;
        } else {
            wnum[num] ++;
        }
    }

    rep(i, 2020) {
        rep(j, 2020) {
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;
    rep(i, n) {
        rep(j, n) {
            if(i < n) dp[i+1][j] = min(dp[i+1][j], dp[i][j] + black[i][j]);
            if(j < n) dp[i][j+1] = min(dp[i][j+1], dp[i][j] + white[i][j]);
        }
    }
    cout << dp[n][n] << endl;
	return 0;
}

