int wi[2010], bi[2010];
int seg[2048];
Ti G[2010][2010][2];
ll arr[2010][2010];

int rsq(int s, int t, int k = 1, int l = 0, int r = 1023) {
	if (t < l || r < s) {
		return 0;
	}
	if (s <= l && r <= t) {
		return seg[k];
	}

	int lv = rsq(s, t, k * 2, l, (l + r) / 2);
	int rv = rsq(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

void upd(int x) {
	x += 1024;
	seg[x]++;
	while (x) {
		x /= 2;
		seg[x] = seg[x * 2] + seg[x * 2 + 1];
	}
}

int main() {
	for (int i = 0;i < 2048;i++)seg[i] = 0;
	int N, a;
	char c;
	cin >> N;

	for (int i = 0;i < 2 * N;i++) {
		cin >> c >> a;
		if (c == 'W') {
			wi[a] = i;
		}
		else {
			bi[a] = i;
		}
	}

	for (int i = 0;i <= N;i++) {
		for (int j = 0;j < 2048;j++)seg[j] = 0;
		for (int j = 1;j <= i;j++) {
			upd(wi[j]);
		}
		for (int j = 0;j <= N;j++) {
			if (j)
				upd(bi[j]);

			if (i < N)G[i][j][0] = Ti(rsq(wi[i + 1], 2047), i + 1, j);
			else G[i][j][0] = Ti(-1, -1, -1);
			if (j < N)G[i][j][1] = Ti(rsq(bi[j + 1], 2047), i, j + 1);
			else G[i][j][1] = Ti(-1, -1, -1);

			arr[i][j] = -1;
		}
	}

	priority_queue<Ti> Q;
	Q.push(Ti(0, 0, 0));
	ll x, y, z;
	ll x0, y0, z0;
	ll x1, y1, z1;
	while (!Q.empty()) {
		tie(x, y, z) = Q.top();
		Q.pop();
		if (y == N && z == N) {
			cout << -x << endl;
			return 0;
		}
		if (arr[y][z] > 0)continue;
		arr[y][z] = -x;
		tie(x0, y0, z0) = G[y][z][0];
		tie(x1, y1, z1) = G[y][z][1];
		if (x0 >= 0) {
			Q.push(Ti(x - x0, y0, z0));
		}
		if (x1 >= 0) {
			Q.push(Ti(x - x1, y1, z1));
		}
	}
}

