ll mergeCount(vector<int>& A, int l, int c, int r)
{
    ll count = 0;
    vector<int> B(r - l + 1);
    int j = 0;
    int i1 = l;
    int i2 = c + 1;
    while (i1 <= c || i2 <= r){
        if (r < i2 || (i1 <= c && A[i1] <= A[i2])){
            B[j] = A[i1];
            ++i1;
        }else{ // i2 <= r && (c < i1 || A[i2] < A[i1])
            count += c - i1 + 1;
            B[j] = A[i2];
            ++i2;
        }
        ++j;
    }
    for (int j = 0; j < B.size(); ++j){
        A[l + j] = B[j];
    }
    return count;
}

ll mcount(vector<int>& A, int l, int r)
{
    if (r <= l) return 0;
    const int c = l + (r - l) / 2;
    return mcount(A, l, c) + mcount(A, c + 1, r) + mergeCount(A, l, c, r);
}

