constexpr int INF = 1 << 28;

struct BIT {
    int N;
    vector<int> bit;

    void init(int _n){
        N = _n;
        bit.resize(_n+1, 0);
    }
    int getSum(int i) {  // i番目までの要素の和を求める(1-index)
        int sum = 0;
        while (i > 0) {
            sum += bit[i];
            i -= i & -i;
        }
        return sum;
    }
    void add(int i, int x) {  // i番目の要素にxを加算
        while (i <= N) {
            bit[i] += x;
            i += i & -i;
        }
    }
};

int n;
int idx[2][2005];
vector<vector<int> > dp;

int rec(int i, int j, BIT &bit){
    if(i==n && j==n) return 0;
    if(dp[i][j] < INF) return dp[i][j];
    int res = INF, cost;
    if(i<n){
        bit.add(idx[0][i],-1);
        cost = bit.getSum(idx[0][i]);
        res = min(res, rec(i+1,j,bit)+cost);
        bit.add(idx[0][i],1);
    }
    if(j<n){
        bit.add(idx[1][j],-1);
        cost = bit.getSum(idx[1][j]);
        res = min(res, rec(i,j+1,bit)+cost);
        bit.add(idx[1][j],1);
    }
    return dp[i][j] = res;
}

