        if (rk[i] < a[i] && rk[i + 1] == a[i + 1]) {
            sw(i, i + 1);
            return true;
        }

        if (rk[i] == a[i] && rk[i + 1] > a[i + 1]) {
            sw(i, i + 1);
            return true;
        }
    }
    return false;
}

