            int i = u+v+1;
            if (u < n) {
                int p = pos[0][u+1];
                p += get(0, 2*n) - get(0, pos[0][u+1]);
                p += get(1, 2*n) - get(1, pos[0][u+1]);
                f[u+1][v] = min(f[u+1][v], f[u][v] + p - i);
            }
            if (v < n) {
                int p = pos[1][v+1];
                p += get(0, 2*n) - get(0, pos[1][v+1]);
                p += get(1, 2*n) - get(1, pos[1][v+1]);
                f[u][v+1] = min(f[u][v+1], f[u][v] + p - i);
            }
            if (v < n) update(1, pos[1][v+1]);
        }
        if (u < n) update(0, pos[0][u+1]);
    }
    cout << f[n][n];
}

