      if (w[i] < b[j]) count_w++;
      cb[i][j + 1] = count_b;
      cw[i][j + 1] = count_w;
    }
  }

  dp[0][0] = 0;
  for (int i = 1; i <= n; i++) {
    dp[i][0] = dp[i - 1][0] + cb[i - 1][0];
    dp[0][i] = dp[0][i - 1] + cw[i - 1][0];
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      dp[i][j] = min(dp[i - 1][j] + cb[i - 1][j], dp[i][j - 1] + cw[j - 1][i]);
    }
  }
  cout << dp[n][n];
}

