        cin >> C[i] >> A[i];
        if (C[i] == 'W') {
            P[A[i]] = i;
            W[i][A[i]] = 1;
        } else {
            P[A[i]+N+1] = i;
            B[i][A[i]] = 1;
        }
    }
    for (int i = 0; i < 2*N; i++) {
        for (int j = N-1; j >= 0; j--) {
            W[i][j] += W[i][j+1];
            B[i][j] += B[i][j+1];
        }
    }
    for (int i = 0; i < 2*N-1; i++) {
        for (int j = 0; j <= N; j++) {
            W[i+1][j] += W[i][j];
            B[i+1][j] += B[i][j];
        }
    }
    vector<vector<int>> dp(N+1, vector<int>(N+1, 1e9));
    dp[0][0] = 0;
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            if (i + 1 <= N) {
                int pos = P[i+1];
                int cnt = W[pos][i+1+1] + B[pos][j+1];
                dp[i+1][j] = min(dp[i+1][j], dp[i][j] + cnt);
            }
            if (j + 1 <= N) {
                int pos = P[j+1+N+1];
                int cnt = W[pos][i+1] + B[pos][j+1+1];
                dp[i][j+1] = min(dp[i][j+1], dp[i][j] + cnt);
            }
        }
    }
    cout << dp[N][N] << endl;
    return 0;
}

