    for(int i = 1; i <= N; i++){
        int w_pos = w[i];
        for(int j = 1; j <= N; j++){
            if(w_pos > b[j]){
                b_offset[i][j] = b_offset[i-1][j] + 1;
            }
            else{
                b_offset[i][j] = b_offset[i-1][j];
            }
        }
    }

