inline int calc(const vector<int>& A, const vector<string>& C, int j, int k, int p){
  if(p<0 || 4005<=p || j<0 || k<0 || 2005<=j || 2005<=k) return 0;
  return cntW[j][p] + cntB[k][p];
}

int main(){
  int N;
  cin >> N;
  vector<string> C;
  vector<int> A;
  map<pair<string,int>,int> pos;
  rep(i,2*N){
    string c;
    int a;
    cin >> c >> a;
    C.push_back(c);
    A.push_back(a);
    pos[make_pair(c,a)] = i+1;

    if(c=="W"){
      cntW[a][i] = 1;
    }else{
      cntB[a][i] = 1;
    }
  }

  rep(i,2005){
    int cW = 0;
    int cB = 0;
    rep(j,4005){
      dp[j][i] = INF;

      cW += baseW[j];
      cB += baseB[j];
      cntW[i][j] = cW;
      cntB[i][j] = cB;
    }
    int pW = pos[make_pair("W",i+1)]-1;
    if(pW >= 0) baseW[pW] = 1;
    int pB = pos[make_pair("B",i+1)]-1;
    if(pB >= 0) baseB[pB] = 1;
  }

