const int INF = 1 << 25;

void sum2d(vec<int, 2>& sum) {
  int H = sum.size(), W = sum[0].size();
  for (int i = 1; i < H; i++) {
    for (int j = 1; j < W; j++) {
      sum[i][j] += sum[i - 1][j] + sum[i][j - 1] - sum[i - 1][j - 1];
    }
  }
}

int main() {
  int N;
  while (cin >> N) {
    vector<int> bQ(N, -1), wQ(N, -1);
    vec<int, 2> sumB = make_v(2 * N + 1, N + 1, 0);
    vec<int, 2> sumW = make_v(2 * N + 1, N + 1, 0);
    for (int i = 0; i < 2 * N; i++) {
      char c;
      int x;
      cin >> c >> x;
      --x;
      if (c == 'B') {
        bQ[x] = i;
        ++sumB[i + 1][x + 1];
      } else {
        wQ[x] = i;
        ++sumW[i + 1][x + 1];
      }
    }
    sum2d(sumB);
    sum2d(sumW);
    vec<int, 2> dp = make_v(N + 1, N + 1, INF);
    dp[0][0] = 0;
    for (int i = 0; i < 2 * N; i++) {
      for (int b = 0; b <= N && b <= i; b++) {
        int w = i - b;
        if (w > N || dp[b][w] >= INF) continue;
        // black
        if (b + 1 <= N) {
          int q = bQ[b];
          int cost = q - sumW[q][w] - sumB[q][b];
          dp[b + 1][w] = min(dp[b + 1][w], dp[b][w] + cost);
        }
        // white
        if (w + 1 <= N) {
          int q = wQ[w];
          int cost = q - sumW[q][w] - sumB[q][b];
          dp[b][w + 1] = min(dp[b][w + 1], dp[b][w] + cost);
        }
      }
    }
    cout << dp[N][N] << endl;
  }
  return 0;
}

