// x-1とxをswap
void swap(int x, vector<P> &v, map<char,vector<int>> &pos){
    char c1 = v[x-1].second;
    char c2 = v[x].second;
    int a1 = v[x-1].first;
    int a2 = v[x].first;
    swap(v[x-1], v[x]);
    pos[c1][a1] = x;
    pos[c2][a2] = x-1;
}

int left_move(int n, vector<P> v, map<char,vector<int>> pos){
    int w=0,b=0,cnt=0;
    rep(i,n*2-1){
        P dw = {pos['W'][w]-i, 'W'};
        P db = {pos['B'][b]-i, 'B'};
        P close = min(dw,db);
        char c = close.second;
        cnt += close.first;
        for(int x = i+close.first; x > i; x--){
            swap(x,v,pos);
        }
        if(c == 'W') w++;
        else b++;
    }
    // cerr<<__func__<<cnt<<endl;
    return cnt;
}

int right_move(int n, vector<P> v, map<char,vector<int>> pos){
    int w=n-1,b=n-1,cnt=0;
    for(int i = 2*n-1; i>0; i--){
        P dw = {i-pos['W'][w], 'W'};
        P db = {i-pos['B'][b], 'B'};
        P close = min(dw,db);
        if(close.first < 0){
            close = max(dw,db);
        }
        char c = close.second;
        // if(close.first < 0){
        //     debug(i);
        //     debug(w);
        //     debug(b);
        // }
        // if(w<=0 && b<=0){
        //     debug(w);
        //     debug(b);
        //     printf("\ncnt = %d\n",cnt);
        //     printf("i = %d: c,dist = %c,%d \n",i,close.second,close.first);
        // }
        cnt += close.first;
        for(int x = i-close.first+1; x <= i; x++){
            swap(x,v,pos);
        }
        if(c == 'W') w--;
        else b--;
    }
    // cerr<<__func__<<cnt<<endl;
    return cnt;
}


int main(void){
    int n;
    cin>>n;
    vector<P> v(n*2);
    map<char,vector<int>> pos;
    pos['W'].resize(n+1);
    pos['B'].resize(n+1);
    pos['W'][n] = INF;
    pos['B'][n] = INF;
    rep(i,n*2){
        char c;
        int a;
        cin>>c>>a;
        a--;
        v[i] = {a,c};
        pos[c][a] = i;
    }
    int res1 = left_move(n,v,pos);
    int res2 = right_move(n,v,pos);
    cout<<min(res1,res2)<<endl;
    return 0;
}

