class BIT {
public:
	vector<LL> Bit;
	LL M;
	BIT(LL M) :
		Bit(vector<LL>(M + 1, 0)), M(M) {}
	void init() {
		rep(i, M + 1)Bit[i] = 0;
	}
	LL sum(LL i) {
		LL s = 0;
		while (i > 0) {
			s += Bit[i];
			i -= (i&(-i));
		}
		return s;
	}
	LL sum(LL i, LL j) {
		return sum(j) - sum(i - 1);
	}
	//1-index
	void add(LL i, LL x) {
		while (i <= M) {
			Bit[i] += x;
			i += (i&(-i));
		}
	}
	//初めてk以上になる、index
	int lower_bound(LL k) {
		int l = -1, r = n + 1, m;
		while (r - l > 1) {
			m = (l + r) / 2;
			if (sum(m) >= k)
				r = m;
			else l = m;
		}
		return (r == n + 1 ? -1 : r);
	}
	//初めてkより大きくなる、index
	int upper_bound(LL k) {
		int l = -1, r = M + 1, m;
		while (r - l > 1) {
			m = (l + r) / 2;
			if (sum(m) > k)
				r = m;
			else l = m;
		}
		return (r == M + 1 ? M + 1 : r);
	}
};
