            FOR(m, n + 1, 2 * N) {
                black_table[a][m] = 1;
            }
        }
        else {
            white_pos[a] = n;
            FOR(m, n + 1, 2 * N) {
                white_table[a][m] = 1;
            }
        }
    }

    FOR(a, 2, N + 1) {
        REP(n, 2 * N) {
            black_table[a][n] += black_table[a - 1][n];
            white_table[a][n] += white_table[a - 1][n];
