        cw[i][0]++;
      }
    }
    for (int j = 1; j <= n; j++) {
      cw[i][j] = cw[i][j - 1];
      if (w[i] < b[i]) {
        cw[i][j]++;
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j < i; j++) {
      if (b[i] < b[j]) {
        cb[0][i]++;
      }
    }
    for (int j = 1; j <= n; j++) {
      cb[j][i] = cb[j - 1][i];
      if (b[i] < w[j]) {
        cb[j][i]++;
      }
