// 1-indexed であることに注意
template<typename T>
class BITree {
    public:
        BITree(int n) : m_N(n + 1) { m_Tree.assign(m_N, 0); }
        // [1, i] の合計値を返す (log m_N)
        // 閉区間であることに注意
        T Sum(int i) {
            if(i < 1 || i >= m_N) { return 0; }
            T s = 0;
            while(i > 0) { s += m_Tree[i]; i -= i & -i; }
            return s;
        }
        // [i, j] の合計値を返す (log m_N)
        // i < j
        // 閉区間であることに注意
        T Sum(int i, int j) {
            if(i > j) { return 0; }
            return Sum(j) - Sum(i-1);
        }
        // i 番目の要素(1-indexed)に x を足して更新 O(log m_N)
        void Add(int i, T x){ while(i < m_N) { m_Tree[i] += x; i += i & -i; } }
    private:
        int m_N;            // 要素数
        vector<T> m_Tree;   // BIT 本体
};

int dp[MAX_N][MAX_N] = {};
int costB[MAX_N][MAX_N] = {};
int costW[MAX_N][MAX_N] = {};
int posB[MAX_2N] = {};      // B の i がある A のインデックス
int posW[MAX_2N] = {};      // W の i がある A のインデックス
BITree<int>* bit_Bs[MAX_2N] = {};
BITree<int>* bit_Ws[MAX_2N] = {};

signed main()
{
    cin >> N;
    REP(i, 2 * N) {
        cin >> C[i] >> A[i];
        if(C[i] == 'W') { posW[A[i]] = i; }
        else { posB[A[i]] = i; }
    }

    ZERO(dp);
    ZERO(costB);
    ZERO(costW);

    REP(i, 2 * N) {
        bit_Bs[i] = new BITree<int>(N);
        bit_Ws[i] = new BITree<int>(N);
        for(int ind = 0; ind < i; ++ind) {
            if(C[ind] == 'B') { bit_Bs[i]->Add(A[ind], 1); }
            else { bit_Ws[i]->Add(A[ind], 1); }
        }
    }

    for(int i = 0; i <= N; ++i) {
        for(int j = 0; j <= N; ++j) {
            costB[i][j] += bit_Bs[posB[i+1]]->Sum(i+2, N);
            costB[i][j] += bit_Ws[posB[i+1]]->Sum(j+1, N);
            costW[i][j] += bit_Bs[posW[j+1]]->Sum(i+1, N);
            costW[i][j] += bit_Ws[posW[j+1]]->Sum(j+2, N);
        }
    }

    dp[0][0] = 0;
    for(int i = 0; i <= N; ++i) {
        for(int j = 0; j <= N; ++j) {
            if(i == 0 && j == 0) { continue; }
            int cand1 = INF, cand2 = INF;
            if(i > 0) { cand1 = dp[i-1][j] + costB[i-1][j]; }
            if(j > 0) { cand2 = dp[i][j-1] + costW[i][j-1]; }
            dp[i][j] = min(cand1, cand2);
        }
    }

    REP(i, 2 * N) {
        delete bit_Bs[i];
        delete bit_Ws[i];
    }

    printf("%d\n", dp[N][N]);
    return 0;
}

