int main() {
	ll n;
	cin >> n;
	vector<pair<char, ll>> ca(2*n);
	REP(i, 2 * n) {
		cin >> ca[i].first >> ca[i].second;
		ca[i].second--;
	}
	Matrix cntb(2010, Array(2010));
	Matrix cntw(2010, Array(2010));
	SumSegTree seg1(n), seg2(n);
	REP(i,2* n) {
		if (ca[i].first == 'W') {
			seg1.add(ca[i].second, 1);
		}
		else {
			seg2.add(ca[i].second, 1);
		}
		REP(j, n+1) {
			ll temp = 0;
			if (ca[i].first == 'W') {
				temp += seg1.sum(0, ca[i].second);
				temp += seg2.sum(0, j);
				cntw[ca[i].second][j] = i - temp;
			}
			else {
				temp += seg2.sum(0, ca[i].second);
				temp += seg1.sum(0, j);
				cntb[ca[i].second][j] = i - temp;
			}
		}
	}
	REP(i, n + 1)REP(j, n + 1)dp[i][j] = INF;
	dp[0][0] = 0;
	REP(i, n+1) {
		REP(j, n+1) {
			if(i<n)chmin(dp[i + 1][j], dp[i][j] + cntw[i][j]);
			if(j<n)chmin(dp[i][j + 1], dp[i][j] + cntb[j][i]);
		}
	}
	cout << dp[n][n];

	return 0;
}

#include <cstdio>
#include <algorithm>

#define INF 1000000000

#define MAXN 2009

int alb[MAXN], negru[MAXN], aa[MAXN], nn[MAXN];
int an[MAXN][MAXN], na[MAXN][MAXN], dp[MAXN][MAXN];

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 1; i <= 2 * n; i++) {
        char ch;
        int x;
        scanf(" %c%d", &ch, &x);

        if (ch == 'W')
            alb[x] = i;
        if (ch == 'B')
            negru[x] = i;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = n; j >= 0; j--) {
            aa[i] += j > i && alb[j] < alb[i];
            nn[i] += j > i && negru[j] < negru[i];
            an[i][j] = an[i][j + 1] + (negru[j] < alb[i]);
            na[i][j] = na[i][j + 1] + (alb[j] < negru[i]);
        }
    }

    for (int i = 0; i <= n; i++) {
        for (int j = 1 - bool(i); j <= n; j++) {
            dp[i][j] = INF;
            if (i > 0)
                dp[i][j] = std::min(dp[i][j], dp[i - 1][j] + an[i][j + 1] + aa[i]);
            if (j > 0)
                dp[i][j] = std::min(dp[i][j], dp[i][j - 1] + na[j][i + 1] + nn[j]);
        }
    }

    printf("%d\n", dp[n][n]);

    return 0;
}

