void solve(){
    int N;
    cin >> N;
    vector<char> c(2*N);
    vector<int> a(2*N);
    rep(i,0,2*N){
        cin >> c[i] >> a[i];
        --a[i];
    }

    i64 ans=0;
    rep(i,0,N){
        int ma=N-i-1;
        {
            int p;
            rep(j,0,2*N) if(c[j]=='W' and a[j]==ma){
                p=j;
                break;
            }
            rep(j,p+1,2*N) if(c[j]=='W' and a[j]<ma) ++ans;
        }
         {
            int p;
            rep(j,0,2*N) if(c[j]=='B' and a[j]==ma){
                p=j;
                break;
            }
            rep(j,p+1,2*N) if(c[j]=='B' and a[j]<ma) ++ans;
        }
    }

    vector<i64> s(N),t(N);
    rep(i,0,2*N){
        if(c[i]=='W') s[a[i]]=i;
        else t[a[i]]=i;
    }

    vector<vector<i64>> w(2*N+1),b(2*N+1);
    for(int i=2*N-1; i>=0; --i){
        w[i]=w[i+1];
        b[i]=b[i+1];
        if(c[i]=='W') w[i].push_back(a[i]);
        else b[i].push_back(a[i]);
        sort(begin(w[i]),end(w[i]));
        sort(begin(b[i]),end(b[i]));
    }

    function<i64(int,int)> f=[&](int i,int j){
        return upper_bound(begin(b[s[i]+1]),end(b[s[i]+1]),j)-begin(b[s[i]+1]);
    };

    function<i64(int,int)> g=[&](int i,int j){
        return upper_bound(begin(w[t[i]+1]),end(w[t[i]+1]),j)-begin(w[t[i]+1]);
    };

    static i64 dp[2048][2048];
    fill_n((i64*)dp,2048*2048,inf64);

    rep(i,0,N+1) dp[i][0]=dp[0][i]=0;

    rep(i,1,N+1) rep(j,1,N+1){
        dp[i][j]=min(dp[i][j],dp[i-1][j]+f(i-1,j-1));
        dp[i][j]=min(dp[i][j],dp[i][j-1]+g(j-1,i-1));
    }

    cout << ans+dp[N][N] << endl;
}

