        a[i].first  = (input<char>() == 'W');
        a[i].second = input<int>();
    }

    auto a_copy = a;
    int64_t best_ans = TYPEMAX(int64_t);
    for (int iter = 0; iter != 4; ++iter) {
        a = a_copy;

        if (iter % 2 == 1) {
            std::reverse(ALL(a));
            for (auto& elem: a)
                elem.second = n + 1 - elem.second;
        }


        int64_t ans = 0;
        while (true) {
            int cnt0 = 0, cnt1 = 0;

            pair<bool, int> target = {false, -1};
            int go_to = -1;
            for (int i = 0; i != 2 * n; ++i)
                if (a[i].first == 0) {
                    ++cnt0;

                    if (a[i].second != cnt0) {
                        target = {0, cnt0};
                        go_to = i;
                        break;
                    }
                } else {
                    ++cnt1;

                    if (a[i].second != cnt1) {
                        target = {1, cnt1};
                        go_to = i;
                        break;
                    }
                }

            if (go_to == -1)
                break;

            if (iter / 2 == 0) {
                int index = std::find(ALL(a), target) - a.begin();
                ans += index - go_to;
                a.erase(a.begin() + index);
                a.insert(a.begin() + go_to, target);
            } else {
                int index = std::find(ALL(a), target) - a.begin();
                ans += index - go_to;
                a.insert(a.begin() + index + 1, a[go_to]);
                a.erase(a.begin() + go_to);
            }
        }

        cerr << ans << "\n";
        best_ans = min(best_ans, ans);
    }
