  rep(i,2*N) {
    if (w!=N&&bp[b]>wp[w]) { mv[wp[w]] = i; w++; }
    else { mv[bp[b]] = i; b++; }
  }
  // debug(mv,mv+2*N);

  SegTree tree(2*N);
  ll result = 0;
  rep(i,2*N) {
    result += tree.query(mv[i],2*N);
    tree.update(mv[i],1);
  }
  cout << result << endl;
  return 0;
}

