        char c;
        int a;
        cin >> c >> a;
        if(c=='B')bpos[a] = i;
        else wpos[a] = i;
        bit.add(i, 1);
    }
    ll ans = 0;
    int w = 1, b = 1;
    while(b<=N || w<=N){
        int bcost = 10000, wcost = 10000;
        if(b<=N)bcost = bit.sum(bpos[b] - 1);
        if(w<=N)wcost = bit.sum(wpos[w] - 1);
        if(bcost<wcost){
            ans += bcost;
            bit.add(bpos[b], -1);
            b++;
        }
        else{
            ans += wcost;
            bit.add(wpos[w], -1);
            w++;
        }
    }
    cout << ans << endl;

    return 0;
}

