const int BIT_SIZE = 2000;

struct BIT {
  int n;
  int bit[BIT_SIZE + 1];

  BIT() {}
  BIT(int _n) {
    n = _n;
  }

  int sum(int i) {
    int s = 0;
    while(i > 0) {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, int x) {
    while (i <= n) {
      bit[i] += x;
      i += i & -i;
    }
  }
};

