void solve()
{
    int n;
    cin >> n;
    akari<int> bs(n), ws(n);
    akari<int> accb(n + 1), accw(n + 1);
    yukari<int> accb2(n, akari<int>(n + 1)), accw2(accb2);
    akari<BIT<int>> bit(2, BIT<int>(2020));
    for (int i = 0; i < 2 * n; i++)
    {
        char c;
        int a;
        cin >> c >> a;
        a--;
        if (c == 'B')
        {
            bs[a] = i;
            accb[a + 1] = a - bit[0].sum(a + 1);
            bit[0].add(a + 1, 1);
            for (int j = 0; j < n; j++)
            {
                accb2[a][j + 1] = j + 1 - bit[1].sum(j + 1);
            }
        }
        else
        {
            ws[a] = i;
            accw[a + 1] = a - bit[1].sum(a + 1);
            bit[1].add(a + 1, 1);
            for (int j = 0; j < n; j++)
            {
                accw2[a][j + 1] = j + 1 - bit[0].sum(j + 1);
            }
        }
    }
    yukari<int> dp(n + 1, akari<int>(n + 1, 1e9));
    dp[0][0] = 0;
    for (int i = 0; i <= n; i++)
        for (int j = 0; j <= n; j++)
        {
            if (i < n)
            {
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + max(0, bs[i] - (i + j) + accb[i + 1] + accb2[i][j]));
            }
            if (j < n)
            {
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + max(0, ws[j] - (i + j) + accw[j + 1] + accw2[j][i]));
            }
        }
    cout << dp[n][n] << endl;
}

