int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
    int n; cin >> n;
    char c[4040]; int a[4040];
    int dp[2020][2020]; //左から(B,0),..,(B,i-1), (W,0),..(W,j-1)を目標順にするための最小swap数
    rep(i, 2 * n) {
        cin >> c[i] >> a[i];
        --a[i];
    }

    vector<vector<int>> black(n, vector<int>(n + 1, 0));
    //(B, i)の前に(B, iより大),(W, j以上)が何個あるか
    vector<vector<int>> white(n, vector<int>(n + 1, 0));
    //(W, i)の前に(W, iより大),(B, j以上)が何個あるか

    vector<int> bnum(n, 0);
    vector<int> wnum(n, 0);
    rep(i, 2 * n) {
        int num = a[i];
        char col = c[i];
        vector<int> bsum(n+1, 0), wsum(n+1, 0); //前にあるi以上の個数
        per(j, n) {
            bsum[j] = bsum[j+1] + bnum[j];
            wsum[j] = wsum[j+1] + wnum[j];
        } //後ろからみる
        per(j, n+1) {
            if(col == 'B') black[num][j] = bsum[num+1] + wsum[j];
            if(col == 'W') white[num][j] = wsum[num+1] + bsum[j];
        }
        if(col == 'B') {
            bnum[num] ++;
        } else {
            wnum[num] ++;
        }
    }

    rep(i, 2020) {
        rep(j, 2020) {
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;
    rep(i, n) {
        rep(j, n) {
            if(i < n) dp[i+1][j] = min(dp[i+1][j], dp[i][j] + black[i][j]);
            if(j < n) dp[i][j+1] = min(dp[i][j+1], dp[i][j] + white[i][j]);
        }
    }
    cout << dp[n][n] << endl;
	return 0;
}

