	{
		if (i) for (int j=0;j<=n;j++)
		{
			small[i][j][0]=small[i-1][j][0];
			small[i][j][1]=small[i-1][j][1];
			biger[i][j][0]=biger[i-1][j][0];
			biger[i][j][1]=biger[i-1][j][1];
		}
		for (int j=0;j<a[i];j++) small[i][j][tp[i]]++;
		for (int j=a[i];j<=n;j++) biger[i][j][tp[i]]++;
	}
