        for (int j = 0;j < i;++j) BITw.add(b[j],1);
        for (int j = 0;j < n;++j) {
            invb[i][j+1] = i+j-BITb.sum(b[j]);
            invw[j+1][i] = i+j-BITw.sum(w[j]);
            BITb.add(b[j],1);
            BITw.add(w[j],1);
        }
    }
    dp[0][0] = 0;
    for (int i = 0;i < n+1;++i) {
        for (int j = 0;j < n+1;++j) {
            if (i > 0) dp[i][j] = dp[i-1][j]+invw[i][j];
            if (j > 0) dp[i][j] = min(dp[i][j],dp[i][j-1]+invb[i][j]);
        }
    }
    cout << dp[n][n] << endl;
    return 0;
}

