using namespace std;

inline int getInt(){ int s; scanf("%d", &s); return s; }
inline char getChar() { char s[8]; scanf("%s", s); return s[0]; }

class BIT{
  vector<int> bit;
public:
  BIT(int n) : bit(n + 1) {}
  void add(int idx, int val){
    idx++;
    while(idx < (int)bit.size()){
      bit[idx] += val;
      idx += idx & -idx;
    }
  }
  int sum(int i) const{
    int s = 0;
    i++;
    while(i > 0){
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }
};

int dp[2048][2048];

int main(){
  const int n = getInt();
  vector<pair<char, int> > v(n + n);
  vector<int> w(n);
  vector<int> b(n);

  REP(i,n+n){
    v[i].first = getChar();
    v[i].second = getInt() - 1;

    if(v[i].first == 'W'){
      w[v[i].second] = i;
    }else{
      b[v[i].second] = i;
    }
  }

  const int inf = 1 << 30;
  REP(i,n+1) REP(j,n+1) dp[i][j] = inf;
  dp[0][0] = 0;

  vector<BIT> bits(n + 1, BIT(n + n));

  for(int i = 1; i <= n; i++){
    for(int j = 0; j < i; j++)
      bits[i].add(w[j], 1);
  }

  REP(i,n+1){
    BIT &bit = bits[i];
    REP(j,n+1){
      const int tot = i + j;

      if(i != n){
	// white
	const int idx = w[i];
	const int pre = bit.sum(idx);
	dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + tot - pre);
      }
      if(j != n){
	// black
	const int idx = b[j];
	const int pre = bit.sum(idx);
	dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + tot - pre);
	bit.add(b[j], 1);
      }
    }
  }

  printf("%d\n", dp[n][n]);

  return 0;
}

