using namespace std;

template<typename T>
struct BIT {
  vector<T> data;
  BIT() {}
  BIT(int n) : data(n+1, 0) {}
  void init(int n) { data.assign(n+1, 0); }
  T sum(int ed) const {
    for(T res(0); ; ed &= ed-1) if(ed) res += data[ed]; else return res;
  }
  void add(int i, const T& x) {
    for(++i; i < (int)data.size(); i += i&-i) data[i] += x;
  }
};



struct K {
  char c;
  int v;
};

int n;
K vs[4010];

int toPos[2][2010];

int memo[2010][2010];
BIT<int> bit(4010);
int solve(int i1, int i2) {
  int& res = memo[i1][i2];
  if(res < 0) {
    if(i1 == n && i2 == n) {
      res = 0;
    } else {
      res = 1e9;
      if(i1 < n) {
        int pos = toPos[0][i1];
        int cost = pos-bit.sum(pos)+(i1+i2) - (i1+i2); // 現在の位置→所定の位置
        bit.add(pos, 1);
        res = min(res, solve(i1+1, i2) + cost);
        bit.add(pos, -1);
      }
      if(i2 < n) {
        int pos = toPos[1][i2];
        int cost = pos-bit.sum(pos)+(i1+i2) - (i1+i2); // 現在の位置→所定の位置
        bit.add(pos, 1);
        res = min(res, solve(i1, i2+1) + cost);
        bit.add(pos, -1);
      }
    }
  }
  return res;
}


int main(void) {
  scanf("%d", &n);
  REP(i, 2*n) {
    scanf(" %c %d", &vs[i].c, &vs[i].v);
    toPos[vs[i].c == 'B'][--vs[i].v] = i;
  }
  memset(memo, -1, sizeof memo);
  int res = solve(0, 0);
  printf("%d\n", res);
  return 0;
}

