ll calcdp(ll w, ll b) {
    if(w == N && b == N) return 0;
    if(dp[w][b] != -1) return dp[w][b];
    ll &res = dp[w][b] = LINF;
    if(w < N) res = min(res, calcdp(w + 1, b) + wsum[w][b]);
    if(b < N) res = min(res, calcdp(w, b + 1) + bsum[b][w]);
    return res;
