		for (j = 1; j <= 2 * n; j++) {
			cntB[i][j] += cntB[i][j - 1];
			cntW[i][j] += cntW[i][j - 1];
		}
	}

	for (j = 1; j <= 2 * n; j++) {
		for (i = 1; i <= n; i++) {
