    int n;
    scanf("%d", &n);
    vector< pair<int, int> > complete_array(2*n);
    vector< vector<int> > pos(2, vector<int>(n));
    for(int i=0; i<2*n; i++)
    {
        char ch;
        int num;
        scanf(" %c %d", &ch, &num);
        num--;
        int id=0;
        if(ch=='B') id=1;
        complete_array[i]=make_pair(id, num);
        pos[id][num]=i;
    }
    int needed=0;
    int curr_pos=0;
    int curr_zero=0;
    int curr_one=0;
    while(curr_pos != 2*n)
    {
        int winner_pos=-1;
        int winner_id=-1;
        if(curr_zero==n)
        {
            winner_pos=pos[1][curr_one];
            winner_id=1;
        }
        else if(curr_one==n)
        {
            winner_pos=pos[0][curr_zero];
            winner_id=0;
        }
        else
        {
            if(pos[0][curr_zero]<pos[1][curr_one])
            {
                winner_pos=pos[0][curr_zero];
                winner_id=0;
            }
            else
            {
                winner_pos=pos[1][curr_one];
                winner_id=1;
            }
        }
        while(winner_pos != curr_pos)
        {
            swap(complete_array[winner_pos], complete_array[winner_pos-1]);
            needed++;
            winner_pos--;
            pos[complete_array[winner_pos].first][complete_array[winner_pos].second]--;
            pos[complete_array[winner_pos+1].first][complete_array[winner_pos+1].second]++;
        }
        curr_pos++;
        if(winner_id==0) curr_zero++;
        else curr_one++;
    }
    printf("%d\n", needed);
    return 0;
}

