using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;

int main(void) {
  ll N;
  cin >> N;
  vector<pll> P(N * 2);
  REP(i, 0, N * 2) {
    char c;
    ll a;
    cin >> c >> a;
    a--;
    P[i] = pll(a, c == 'B' ? 0 : 1);
  }

  ll bpos[N], wpos[N];
  REP(i, 0, N * 2) {
    if(P[i].second == 0) bpos[P[i].first] = i;
    if(P[i].second == 1) wpos[P[i].first] = i;
  }

  ll black[N + 1][N * 2], white[N + 1][N * 2];
  REP(i, 0, N + 1) {
    ll bcnt = 0, wcnt = 0;
    REP(j, 0, N * 2) {
      black[i][j] = bcnt;
      white[i][j] = wcnt;
      if(P[j].second == 0 && P[j].first < i) bcnt++;
      if(P[j].second == 1 && P[j].first < i) wcnt++;
    }
  }

  const ll INF = 1LL << 60;
  ll dp[N + 1][N + 1];
  REP(i, 0, N + 1) REP(j, 0, N + 1) dp[i][j] = INF;
  REP(i, 0, N + 1) REP(j, 0, N + 1) {
    if(i == 0 && j == 0) dp[i][j] = 0;
    else {
      if(i - 1 >= 0) dp[i][j] = min(dp[i][j], dp[i - 1][j] + (black[N][bpos[i - 1]] - black[i][bpos[i - 1]]) + (white[N][bpos[i - 1]] - white[j][bpos[i - 1]]));
      if(j - 1 >= 0) dp[i][j] = min(dp[i][j], dp[i][j - 1] + (white[N][wpos[j - 1]] - white[j][wpos[j - 1]]) + (black[N][wpos[j - 1]] - black[i][wpos[j - 1]]));
    }
  }

  cout << dp[N][N] << endl;
}

