// NOTE: one-indexed
template <typename T> struct bit {
    const int n;
    vector<T> t;
    bit(int n) : n(n), t(n + 1) {}
    void add(int i, T value) {
        for(int j = i; j <= n; j += j & -j) {
            t[j] += value;
        }
    }
    T sum(int i) {
        T res = 0;
        for(int j = i; j > 0; j -= j & -j) {
            res += t[j];
        }
        return res;
    }
    T sum(int L, int R) {
        return sum(R) - sum(L - 1);
    }
};
void solve(long long N, std::vector<char> c, std::vector<long long> a) {
    vector<vector<int>> pos_black_ignore_white_le(N + 1, vector<int>(N + 1));
    vector<vector<int>> pos_white_ignore_black_le(N + 1, vector<int>(N + 1));
    for(int white = 0; white <= N; white++) {
        bit<int> b(N);
        for(int i = 0, whites_seen = 0; i < 2 * N; i++) {
            if(c[i] == 'B') {
                pos_black_ignore_white_le[white][a[i]] = whites_seen + b.sum(a[i] + 1, N);
                b.add(a[i], 1);
            }
            whites_seen += c[i] == 'W' and a[i] > white;
        }
    }
    for(int black = 0; black <= N; black++) {
        bit<int> b(N);
        for(int i = 0, blacks_seen = 0; i < 2 * N; i++) {
            if(c[i] == 'W') {
                pos_white_ignore_black_le[black][a[i]] = blacks_seen + b.sum(a[i] + 1, N);
                b.add(a[i], 1);
            }
            blacks_seen += c[i] == 'B' and a[i] > black;
        }
    }
    vector<vector<int>> opt(N + 1, vector<int>(N + 1));
    for(int black = N; black >= 0; black--) {
        for(int white = N; white >= 0; white--) {
            int& ans = opt[black][white];
            if(black == N and white == N) {
                ans = 0;
            } else if(black == N) {
                ans = pos_white_ignore_black_le[black][white + 1] + opt[black][white + 1];
            } else if(white == N) {
                ans = pos_black_ignore_white_le[white][black + 1] + opt[black + 1][white];
            } else {
                ans = min({
                    pos_white_ignore_black_le[black][white + 1] + opt[black][white + 1],
                    pos_black_ignore_white_le[white][black + 1] + opt[black + 1][white]
                });
            }
        }
    }
    cout << opt[0][0] << endl;
}

