struct BinaryIndexTree {
    BinaryIndexTree(int n): tree(n) {
        for (int i = 0; i < n; i++)
            tree[i] = i & -i;
    }
    void add(int i, int v) {
        for (; i < (int)tree.size(); i += i & -i)
            tree[i] += v;
    }
    int prefix(int i) {
        int result = 0;
        for (; i != 0; i -= i & -i)
            result += tree[i];
        return result;
    }
