    for (int i = 1; i <= n + n; i++) {
        char color;
        int value;
        std::cin >> color >> value;
        (color == 'W' ? white : black)[value] = i;
    }
    BinaryIndexTree tree(n + n + 1);
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 1));
    for (int i = 0; i <= n; i++) {
        if (i != 0) tree.add(white[i], -1);
        for (int j = 0; j <= n; j++) {
            if (j != 0) tree.add(black[j], -1);
            if (i == 0 && j == 0) continue;
            dp[i][j] = INT_MAX;
            if (i != 0) dp[i][j] = std::min(dp[i][j], dp[i - 1][j] + tree.prefix(white[i]));
            if (j != 0) dp[i][j] = std::min(dp[i][j], dp[i][j - 1] + tree.prefix(black[j]));
        }
        for (int j = 1; j <= n; j++)
            tree.add(black[j], 1);
    }
    std::cout << dp[n][n] << "\n";
    return 0;
}

