LL dp(LL i, LL j)
{
	if (i == N && j == N) return 0;
	if (memo[i][j] != -1) return memo[i][j];
	LL res1 = inf, res2 = inf;
	if (i < N) res1 = cost[i][j][0] + dp(i + 1, j);
	if (j < N) res2 = cost[i][j][1] + dp(i, j + 1);
	return memo[i][j] = std::min(res1, res2);
}

