	for (LL i = 0; i <= 2 * N; ++i) for (LL j = 1; j <= N; ++j) rep(k, 2) cntR[i][j][k] += cntR[i][j - 1][k];

	cost.resize(N + 1, std::vector<std::vector<LL>>(N + 1, std::vector<LL>(2)));
	for (LL i = 0; i <= N; ++i)
	{
		for (LL j = 0; j <= N; ++j)
		{
			if (i == N && j == N) continue;
			LL pos = std::min(border[i][0], border[j][1]);
			if (i < N)
			{
				LL wantW = i + 1, wantW_pos = originalPos[wantW][0];
				LL cntR_sumW1 = cntR[pos][i][0] + cntR[pos][j][1];
