	for (int i = 0; i < n; i++) {
		int pos = pos_w[i];
		int cnt = 0;
		b_before_w[i][0] = 0;
		for (int j = 0; j < n; j++) {
			if (pos_b[j] < pos) cnt++;
			b_before_w[i][j + 1] = cnt;
		}
