	int w_before_b[n][n + 1]; // [i][j] : w >= j after i-th b
	for (int i = 0; i < n; i++) {
		int pos = pos_b[i];
		int cnt = 0;
		w_before_b[i][0] = 0;
		for (int j = 0; j < n; j++) {
