void c_fac(int x=pow(10,6)+10) { fac.resize(x,true); rep(i,x) fac[i] = i ? (fac[i-1]*i)%MOD : 1; }
ll inv(ll a, ll m=MOD) { ll b = m, x = 1, y = 0; while (b!=0) { int d = a/b; a -= b*d; swap(a,b); x -= y*d; swap(x,y); } return (x+m)%m; }
ll nck(ll n, ll k) { return fac[n]*inv(fac[k]*fac[n-k]%MOD)%MOD; }
ll gcd(ll a, ll b) { if (a<b) swap(a,b); return b==0 ? a : gcd(b, a%b); }
ll lcm(ll a, ll b) { return a/gcd(a,b)*b; }

struct SegTree {
  int size;
  vector<ll> pos;
  SegTree(ll N) { size = 1; while(size<N) size<<=1; pos.resize(2*size,0); }
  ll operator[](const ll &x) const { return pos[x+size]; }

  void build() { per(i,size) operate(i); }
  void set(ll x, const ll v) { pos[x+size] = v; }
  void update(ll x, const ll v) { set(x,v); x+=size; while (x>>=1) operate(x); }
  ll query(ll a, ll b) {
    ll L = 0, R = 0;
    for (a+=size, b+=size; a<b; a>>=1, b>>=1) {
      if (a&1) { L = q(L,pos[a]); a++; }
      if (b&1) { b--; R = q(R,pos[b]); }
    }
    return q(L,R);
  }
  void operate(ll i) { pos[i] = pos[i*2] + pos[i*2+1]; }
  ll q(ll x, ll y) { return x + y; }
};

int main() {
  int N; cin >> N;

  int bp[N] = {}, wp[N] = {};
  SegTree(2*N);
  rep(i,2*N) {
    char c; int a; cin >> c >> a; a--;
    if (c=='B') bp[a] = i;
    else wp[a] = i;
  }

  int b = 0, w = 0;
  int mv[2*N] = {};
  rep(i,2*N) {
    if (w!=N&&bp[b]>wp[w]) { mv[wp[w]] = i; w++; }
    else { mv[bp[b]] = i; b++; }
  }
  // debug(mv,mv+2*N);

  SegTree tree(2*N);
  ll result = 0;
  rep(i,2*N) {
    result += tree.query(mv[i],2*N);
    tree.update(mv[i],1);
  }
  cout << result << endl;
  return 0;
}

