  }
  BIT<int> b(3000,0),w(3000,0);
  for(int i=2*N-1;i>=0;i--){
    if(v[i].c=='B'){
      int res=b.sum(v[i].a);
      for(int j=0;j<=N;j++){
        int tmp=w.sum(j);
        costb[j][v[i].a]=res+tmp;
      }
      b.add(v[i].a,1);
    }
    else{
      int res=w.sum(v[i].a);
      for(int j=0;j<=N;j++){
        int tmp=b.sum(j);
        costw[v[i].a][j]=res+tmp;
      }
      w.add(v[i].a,1);
    }
  }
  for(int i=0;i<=N;i++){
    for(int j=0;j<=N;j++){
      if(!i&&!j)continue;
      if(!i)dp[i][j]=dp[i][j-1]+costb[i][j];
      if(!j)dp[i][j]=dp[i-1][j]+costw[i][j];
      if(i&&j)dp[i][j]=min(dp[i][j-1]+costb[i][j],dp[i-1][j]+costw[i][j]);
    }
  }
  cout<<dp[N][N]<<endl;
}

