int B[MAXN][MAXN];
int W[MAXN][MAXN];
int dp[MAXN][MAXN];
int N;

int tree[2][MAXN];

void Update(int pos, int val, int flag) {
    for(int i = pos; i <= N; i += i & -i) {
        tree[flag][i] += val;
    }
}

int Sum(int pos, int flag) {
    int sum = 0;
    for(int i = pos; i; i -= i & -i) {
        sum += tree[flag][i];
    }
    return sum;
}

int main() {
