	for(int k=0;k<2;k++){
		for(int j=n;j>=1;j--){
			for(int i=1;i<=n*2;i++){
				preSum[k][j][i]=preSum[k][j+1][i];
				if(i>=p[k][j])
					preSum[k][j][i]++;
			}
		}
	}
