	void init(int len)
	{
		sz=len;
		memset(dt,0,sizeof(int)*(len+7));
	}
	void add(int pos,int num)
	{
		while(pos<=sz)
		{
			dt[pos]+=num;
			pos+=pos&-pos;
		}
	}
	int sum(int pos)
	{
		int s=0;
		while(pos)
		{
			s+=dt[pos];
			pos&=pos-1;
