const int maxn = 2020;
const int inf = 1e7;


int n;
int a[maxn*2][2];
int mp[2][maxn];
int dp[maxn][maxn];

int cntW[maxn][maxn];
int cntB[maxn][maxn];

int solve(int w, int b) {
    if (w==0 && b==0) return 0;

    int &res = dp[w][b];
    if (~res) return res;

    res = inf;
    int idx = w+b;


    if (w>0) {
	int at = mp[0][w];
	int dist = at-idx;


	// Elems to left of `at` that have already moved to their positions
	// will move our actual index to the left.

	dist -= cntW[at-1][w+1];
	dist -= cntB[at-1][b+1];

	dist = abs(dist);
	res = min(res, solve(w-1,b) + dist);
    }


    if (b>0) {
	int at = mp[1][b];
	int dist = at-idx;

	dist -= cntW[at-1][w+1];
	dist -= cntB[at-1][b+1];


	dist = abs(dist);
	res = min(res, solve(w,b-1) + dist);
    }


    return res;
}


