  //cout<<w<<" "<<b<<" | "<<case1[w][b]<<" "<<case2[w][b]<<endl;
  return memo[w][b]=min(dp(w-1,b)+case1[w][b],dp(w,b-1)+case2[w][b]);
}

int bin_search(vector<int> &v, int val){
  int ans=0;
  int l=-1; int r=v.size();
  while(r-l>1){
    int mid=(l+r)/2;
    if (v[mid]<=val) l=mid;
    else r=mid;
  }
  return max(0,l+1);
}



