void solve_c() {
  int n;
  cin >> n;
  vi ra(n), rb(n);
  forn(i, n*2) {
    char c; cin >> c;
    int x; cin >> x;
    --x;
    (c == 'W' ? ra : rb)[x] = i;
  }
  vvi d(n + 1, vi(n + 1, inf));
  vvi p(n + 1, vi(n + 1, 0));
  d[0][0] = 0;
  vvi da(n + 1, vi(2 * n + 1, 0));
  vvi db(n + 1, vi(2 * n + 1, 0));
  forn(i, n) {
    forn(j, 2 * n + 1) {
      da[i + 1][j] = da[i][j] + (ra[i] > j ? 1 : 0);
      db[i + 1][j] = db[i][j] + (rb[i] > j ? 1 : 0);
    }
  }
  auto cost = [&] (vi& a, vi& b, vvi& da, vvi& db, int i, int j) {
    return da[i][a[i]] + db[j][a[i]];
    int s = 0;
    forn(t, j) if (b[t] > a[i]) s += 1;
    forn(t, i) if (a[t] > a[i]) s += 1;
    assert(s == da[i][a[i]] + db[j][a[i]]);
    return s;
  };
  forn(i, n + 1) {
    forn(j, n + 1) {
      if (d[i][j] == inf) continue;
      if (i + 1 <= n) uin(d[i + 1][j], d[i][j] + cost(ra, rb, da, db, i, j));
      if (j + 1 <= n) if (uin(d[i][j + 1], d[i][j] + cost(rb, ra, db, da, j, i))) p[i][j+1] = 1;
    }
  }
  if (0) {
    int i = n, j = n;
    while (i+j) {
      if (j && p[i][j]) { cout << '1'; --j; }
      else { cout << '0'; --i; }
    }
    cout << endl;
  }
  int ans = d[n][n];
  cout << ans << endl;
}

void solve_b() {
