  cin >> n >> m;
  vi p(n);
  forn(i, n) { cin >> p[i]; --p[i]; }
  vvi g(n);
  forn(i, m) {
    int v, u; cin >> v >> u;
    --v; --u;
    g[v].pb(u); g[u].pb(v);
  }
  int ans = 0;
  vi used(n, 0);
  queue<int> Q; vi comp;
  forn(i, n) if (!used[i]) {
    Q.push(i); used[i] = 1; comp.pb(i);
    while (!Q.empty()){ 
      int v = Q.front(); Q.pop();
      for(int u: g[v]) if (!used[u]) {
        used[u] = 1; Q.push(u); comp.pb(u);
      }
    }
    sort(all(comp));
    for (int j: comp) ans += binary_search(all(comp), p[j]);
    comp.clear();
  }
  cout << ans << endl;
}

