        for(int j=0; j<=N; j++) {
            int target = i + j;
            if(i != N) {
                int inv1 = seg.query(pos[1][i], 2*N);
                chmin(dp[i+1][j], dp[i][j] + (pos[1][i] + inv1 - target));
