template <typename T>
class Bit{
    private:
        V<T> data;
        T identity_ele;

    public:

        Bit(ll size, T identity_ele) {
            ll newsize = 1;
            while(newsize < size)  newsize = newsize << 1;
            this->identity_ele = identity_ele;
            data = V<T>(newsize + 1, identity_ele);
        }

        /*
         * 0-origin
         */
        T sum(ll pos) {
            T ret = identity_ele;
            pos++;
            while(pos > 0) {
                ret += data[pos];
                pos -= pos & -pos;
            }
            return ret;
        }

        /*
         * 0-origin
         */
        void add(ll pos, T delta) {
            pos++;
            while(pos <= data.size()) {
                data[pos] += delta;
                pos += pos & -pos;
            }
        }
};

struct Ball {
    ll a, c;
};

const ll INF = 5e15;
VV<ll> dp(2010, V<ll>(2010, INF));
V<Ball> VB;
ll N;
V<ll> winv(2010), binv(2010);
VV<ll> lbcnt(2010, V<ll>(2010)), lwcnt(2010, V<ll>(2010));

void calc() {
    Bit<ll> BB(N + 20, 0), WB(N + 20, 0);
    for(const Ball &e : VB) {
        ll a = e.a, c = e.c;
        auto &B = (c == 0 ? WB : BB);
        auto &Bi = (c == 0 ? BB : WB);
        auto &cnt = (c == 0 ? lbcnt : lwcnt);
        auto &inv = (c == 0 ? winv : binv);
        B.add(a, 1);
        inv[a] = B.sum(N + 10) - B.sum(a);
        for(ll i = 0; i <= N; i++) cnt[a][i] = Bi.sum(i);
    }
}

int main() {
    cin >> N;
    V<Ball> v;
    V<ll> wv, bv;
    dp[0][0] = 0;
    for(ll i = 0; i < 2 * N; i++) {
        char c;
        ll a;
        cin >> c >> a;
        VB.push_back(Ball{a, c == 'B'});
        (c == 'W' ? wv : bv).push_back(a);
    }
    calc();
    for(ll i = 1; i <= 2 * N; i++) {
        for(ll w = 0; w <= N; w++) {
            ll b = i - w;
            if(!(0 <= w && w <= N &&
                 0 <= b && b <= N)) continue;
            ll val = dp[w][b];
            if(0 < w && w <= N) {
                ll tmp = dp[w - 1][b];
                tmp += winv[w];
                tmp += b - lbcnt[w][b];
                val = min(val, tmp);
            }
            if(0 < b && b <= N) {
                ll tmp = dp[w][b - 1];
                tmp += binv[b];
                tmp += w - lwcnt[b][w];
                val = min(val, tmp);
            }
            dp[w][b] = val;
        }
    }
    //for(ll i = 0; i <= N; i++) for(ll j = 0; j <= N; j++) cout << "dp[" << i << "][" << j << "] = " << dp[i][j] << endl;
    cout << dp[N][N] << endl;
    return 0;
}

