// ボールiのある位置
int white_pos[2010];
int black_pos[2010];

// [i][j]: 位置iより左側にある、j以下の小さいボールの数
int white_table[4010][4010];
int black_table[4010][4010];

int main(void)
{
    cin.sync_with_stdio(false);
    int N; cin >> N;

    REP(n, 2*N) {
        char c; int a;   // a は 1-based   座標 は 0-based
        cin >> c >> a;
        if (c == 'B') {
            black_pos[a] = n;
            FOR(m, n + 1, 2 * N) {
                black_table[a][m] = 1;
            }
        }
        else {
            white_pos[a] = n;
            FOR(m, n + 1, 2 * N) {
                white_table[a][m] = 1;
            }
        }
    }

    FOR(a, 2, N + 1) {
        REP(n, 2 * N) {
            black_table[a][n] += black_table[a - 1][n];
            white_table[a][n] += white_table[a - 1][n];
        }
    }

    // dp[black][white]
    FOR(sum, 1, N*2+1) {
        REP(black, sum + 1) {
            if (black > N) break;
            auto white = sum - black;
            if (white > N) continue;

            // dp[1][1] <- dp[1][0]
            dp[black][white] = INF;

            if (white > 0) {
                dp[black][white] =
                    min(dp[black][white],
                        // 白 white を先頭にもってくる。
                        dp[black][white - 1]
                        + white_pos[white]
                        - white_table[white - 1][white_pos[white]]
                        - black_table[black][white_pos[white]]
                    );
                if (dp[black][white] < 0) {
                    cerr << "white > 0   dp[][] = " << dp[black][white] << endl;
                    cerr << dp[black][white - 1]
                        << " + " << white_pos[white]
                        << " - " << white_table[white - 1][white_pos[white]]
                        << " - " << black_table[black][white_pos[white]]
                         << endl;
                    exit(0);

                }


            }
            if (black > 0) {
                dp[black][white] =
                    min(dp[black][white],
                        // 黒 black を先頭にもってくる。
                        dp[black - 1][white]
                        + black_pos[black]
                        - black_table[black - 1][black_pos[black]]
                        - white_table[white][black_pos[black]]
                    );

                if (dp[black][white] < 0) {
                    cerr << "black > 0   dp[][] = ";
                    cerr <<
                        dp[black - 1][white]
                        << " + " << black_pos[black]
                        << " - " << black_table[black - 1][black_pos[black]]
                         << " - " << white_table[white][black_pos[black]]
                         << endl;

                    //     dp[black][white - 1]
                    //     << " + " << white_pos[white]
                    //     << " - " << white_table[white - 1][white_pos[white]]
                    //     << " - " << black_table[black][white_pos[white]]
                    //      << endl;
                    // exit(0);

                }

            }
        }
    }
    cout << dp[N][N] << endl;
    return 0;
}

