class Binary_Indexed_Tree {
private:
	vll bits;
	int n;
public:
	Binary_Indexed_Tree(vll a) {
		n = a.size();
		bits = vll(n, 0);
		Loop(i, a.size()) add(i, a[i]);
	}
	void add(int k, ll x) {
		++k;
		for (int index = k; index <= n; index += index & -index) {
			bits[index - 1] += x;
		}
	}
	// note: sum of [s, t)
	ll sum(int s, int t) {
		ll ret = 0;
		for (int index = t; index > 0; index -= index & -index) {
			ret += bits[index - 1];
		}
		for (int index = s; index > 0; index -= index & -index) {
			ret -= bits[index - 1];
		}
		return ret;
	}
};

