        cin >> c >> x;
        pos[c == 'B'][x] = i;
        for (int j = 0; j <= n; ++j) {
            pref[0][i][j] = pref[0][i - 1][j];
            pref[1][i][j] = pref[1][i - 1][j];
        }
        for (int j = x; j <= n; ++j) {
            ++pref[c == 'B'][i][j];
        }
        v.pb({c == 'B', x});
