int main() {
	long long N;
	vector<pair<long long, long long> > V;
	cin >> N;
	vector<vector<long long> > NOW(2, vector<long long>(N, 0));
	vector<vector<vector<vector<long long> > > > COUNT(2, vector<vector<vector<long long> > >(N, vector<vector<long long> >(2)));
	V.resize(N * 2);
	for (int i = 0; i < N * 2; i++) {
		char C;
		cin >> C >> V[i].first;
		V[i].first--;
		if (C == 'B') V[i].second = 0;
		else V[i].second = 1;
	}
	for (int i = 0; i < N * 2; i++) {
		COUNT[V[i].second][V[i].first][0] = NOW[0];
		COUNT[V[i].second][V[i].first][1] = NOW[1];
		NOW[V[i].second][V[i].first]++;
	}
	for (int i = 0; i < 2; i++) {
		for (int j = 0; j < N; j++) {
			for (int k = 0; k < 2; k++) {
				for (int l = N - 2; l >= 0; l--) {
					COUNT[i][j][k][l] += COUNT[i][j][k][l + 1];
				}
			}
		}
	}
	long long INF = 1000000000000;
	vector<vector<long long> > DP(N * 2 + 1, vector<long long>(N + 1, INF));
	DP[0][0] = 0;
	for (int i = 0; i < N * 2; i++) {
		for (int j = 0; j <= N; j++) {
			long long NOWB = j, NOWW = i - j;
			if (0 <= NOWB && NOWB < N && 0 <= NOWW && NOWW <= N) {
				long long PB, PW;
				PB = COUNT[0][NOWB][0][NOWB];
				if (NOWW >= N) PW = 0;
				else PW = COUNT[0][NOWB][1][NOWW];
				DP[i + 1][j + 1] = min(DP[i + 1][j + 1], DP[i][j] + PB + PW);
			}
			if (0 <= NOWB && NOWB <= N && 0 <= NOWW && NOWW < N) {
				long long PB, PW;
				PW = COUNT[1][NOWW][1][NOWW];
				if (NOWB >= N) PB = 0;
				else PB = COUNT[1][NOWW][0][NOWB];
				DP[i + 1][j] = min(DP[i + 1][j], DP[i][j] + PB + PW);
			}
		}
	}
	cout << DP[N * 2][N] << endl;
}

