int bit[4100];
#define mxidx 4096
int gett(int x){
    int ret = 0;
    while(x){
        ret += bit[x];
        x = x & (x-1);
    }
    return ret;
}

void sett(int x){
    while(x^mxidx){
        bit[x]++;
        x += x & (-x);
    }
}

