// 0-origin BIT
template <typename T>
class BIT {
public:
	vector<T> data;
	int n;
	BIT() {}
	BIT(int n_) {
		n = n_;
		data.assign(n, T(0));
	}
	// v[a] += w
	void add(int a, T w) {
		for (int x = a; x < n; x |= x + 1) data[x] += w;
	}
	// sum of v[i] for i in [0, a)
	T sum(int a) {
		T ret = 0;
		for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
			ret += data[x];
		}
		return ret;
	}
};


