  BIT(int n) : data(n+1, 0) {}
  void init(int n) { data.assign(n+1, 0); }
  T sum(int ed) const {
    for(T res(0); ; ed &= ed-1) if(ed) res += data[ed]; else return res;
  }
  void add(int i, const T& x) {
    for(++i; i < (int)data.size(); i += i&-i) data[i] += x;
  }
};

struct K {
  char c;
  int v;
};

int n;
K vs[4010];
int toPos[2][2010];


BIT<int> bit;
int memo[2010][2010];
int solve(int nb, int nw) {
  int& res = memo[nb][nw];
  if(res < 0) {
    if(nb + nw == 2*n) {
      res = 0;
    } else {
      res = 1000000000;
      if(nb < n) { // ここに黒を持ってくる
        int pos = toPos[0][nb];
        int cost = pos-bit.sum(pos);
        bit.add(pos, 1);
        res = min(res, cost + solve(nb+1, nw));
        bit.add(pos, -1);
      }
      if(nw < n) { // ここに白を持ってくる
        int pos = toPos[1][nw];
        int cost = pos-bit.sum(pos);
        bit.add(pos, 1);
        res = min(res, cost + solve(nb, nw+1));
        bit.add(pos, -1);
      }
    }
  }
  return res;
}


