class RMQ{
public : 
  typedef long long ll;
  ll INF = 1LL<<55;
  struct data{
    bool type; //0 - empty   , 1 - update
    ll value;
  };
  ll n,n_;
  vector<ll> dat;
  vector<data> td;
  int toMax; //0 -> RangeMin 1->RangeMax;

  RMQ(){n=-1;}
  RMQ(int n_,int toMax = 0):n_(n_),toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1,(data){0,0});
    dat.resize(2*n-1,INF);
  }

  //[a,b)の値をxに変更　update(a,b,x)
  ll update(int a,int b,ll x,bool flg=true,int k=0,int l=0,int r=-1){
    if(r == -1) {
      r = n;
      assert(a <= b), assert(a <= n && b <= n), assert(a >= 0 && b >= 0);
      if(toMax) x *= -1;
    }

    if(r<=a||b<=l)return flg? dat[k]:INF;
    if(a<=l&&r<=b){
      if(flg==true){
        td[k]=(data){1,x};
        dat[k]=x;
      }
      return dat[k];
    }

    if(td[k].type){
      td[k].type=0;
      dat[k*2+1] = dat[k*2+2] = td[k].value;
      td[k*2+1] = td[k*2+2] = (data){1,td[k].value};
    }

    ll vl=update(a,b,x,flg,k*2+1,l,(l+r)/2);
    ll vr=update(a,b,x,flg,k*2+2,(l+r)/2,r);
    if(flg==true)dat[k]=min(vl,vr);
    return min(vl,vr);
  }

  //[a,b)の最小値を得る　find(a,b);
  ll find(int a,int b){return (toMax? -1:1) * update(a,b,0,false);};
};

class RSAQ{
public:
  typedef long long ll;
  ll n;
  vector<ll> dat,td;

  RSAQ(){n = -1;}
  RSAQ(int n_){
    n=1;
    while(n<n_)n*=2; //要素数nを2のべき乗に
    dat.resize(2*n-1,0),td.resize(2*n-1,0);
  }

  //[a,b)の区間にxを加算する,query(a,b,x);

  ll query(int a,int b,ll x){
    assert(a <= n && b <= n);    
    function <ll(int,int,int)> add = [&](int k,int l,int r){
      if(r<=a||b<=l)return 0LL;
      if(a<=l&&r<=b){
	dat[k]+=(r-l)*x; 
	td[k]+=x;
	return dat[k];
      }

      dat[k]+=(min(r,b)-max(l,a))*x;
      ll kl=k*2+1,kr=k*2+2,t=td[k]*(r-l)/2;
      dat[kl]+=t, dat[kr]+=t;
      td[kl]+=td[k], td[kr]+=td[k];
      td[k]=0;

      ll vl=add(k*2+1,l,(l+r)/2);
      ll vr=add(k*2+2,(l+r)/2,r);
      return vl+vr;
    };
    return add(0, 0, n);
  }

  ll add(int a,int b,int x){return query(a, b, x);}
  //[a,b)の総和を得る
  ll sum(int a,int b){return query(a,b,0);}
};


const int N = 2001;
int n;
vector<P> W,B;
int used[N][N],mem[N][N];
int dfs(int i,int j, RSAQ &A){
  //pr(i, j);
  if(i == n && j == n) return 0;
  if(used[i][j]++) return mem[i][j];
  int a = INF, b = INF;

    if(i != n) {
      int idx = W[i].second;
      int cost = A.sum(0, idx);
      A.add(idx, idx+1, -1);
      a = cost + dfs(i+1,j, A);
      A.add(idx, idx+1, 1);
    }

    if(j != n){
      int idx = B[j].second;
      int cost = A.sum(0, idx);
      A.add(idx, idx+1, -1);
      b = cost + dfs(i, j+1, A);
      A.add(idx, idx+1, 1);
    }
    int res = min(a, b);
    return mem[i][j] = res;
}

