typedef long long llint;

const int inf = 1e9;

int main(void) {
  int N;
  scanf("%d", &N);
  vector<bool> c(2*N);
  vector<int> a(2*N);
  REP(i, 2*N) {
    static char buff[5];
    scanf("%s %d", buff, &a[i]);
    --a[i];
    c[i] = buff[0] == 'W';
  }

  vector<int> pos_0(N), pos_1(N);
  REP(i, 2*N) {
    if (c[i]) {
      pos_1[a[i]] = i;
    } else {
      pos_0[a[i]] = i;
    }
  }

  vector<int> right_00(N), right_11(N);
  vector<vector<int>> right_01(N, vector<int>(N+1)), right_10(N, vector<int>(N+1));

  REP(i, 2*N) {
    FOR(j, i+1, 2*N) {
      if (c[i] == 0) {
        if (c[j] == 0) {
          if (a[j] < a[i]) right_00[a[i]]++;
        } else {
          right_01[a[i]][a[j]+1]++;
        }
      } else {
        if (c[j] == 1) {
          if (a[j] < a[i]) right_11[a[i]]++;
        } else {
          right_10[a[i]][a[j]+1]++;
        }
      }
    }
  }

  REP(i, N) {
    FOR(j, 1, N+1) {
      right_01[i][j] += right_01[i][j-1];
      right_10[i][j] += right_10[i][j-1];
    }
  }

  vector<vector<int>> f(N+1, vector<int>(N+1, inf));
  f[0][0] = 0;

  REP(i, N+1) REP(j, N+1) {
    if (i < N) {
      int npos = pos_0[i] + right_00[i] + right_01[i][j];
      assert(npos >= i + j);
      f[i+1][j] = min(f[i+1][j], npos - (i + j) + f[i][j]);
    }
    if (j < N) {
      int npos = pos_1[j] + right_11[j] + right_10[j][i];
      assert(npos >= i + j);
      f[i][j+1] = min(f[i][j+1], npos - (i + j) + f[i][j]);
    }
  }

  printf("%d\n", f[N][N]);
  return 0;
}

