		for(int j=0;j<2*n;j++){
			if(i)
				gre[i][j]=gre[i-1][j], gere[i][j]=gere[i-1][j];

			if(j<n){
				gre[i][j]+=(a[i]<n)&&(a[i]>j);
				gere[i][j]+=(a[i]<n)&&(a[i]>=j);
			}
			else{
				gre[i][j]+=(a[i]>j);
				gere[i][j]+=(a[i]>=j);
			}
		} 
	}

	memset(dp,0x3f,sizeof(dp));
	dp[0][0]=0;

	for(int i=0;i<2*n;i++){
		for(int j=0;j<=n;j++){
