			int lw=j, lb=i-j;

			if(lw<n){
				int indw = mp[lw];

				dp[i+1][j+1]=min(dp[i+1][j+1], dp[i][j]+gre[indw][lw]+((lb>0)?gre[indw][lb+n-1]:gere[indw][n]));
			}
			if(lb<n){
				int indb = mp[lb+n];

				dp[i+1][j]=min(dp[i+1][j], dp[i][j]+gre[indb][lb+n]+((lw>0)?gre[indb][lw-1]:gere[indb][0]));
			}

		}
	}

	cout << dp[2*n][n] << endl;
	return 0;
}

