int n;

int calc(int num0, int num1)
{
    if(dp[num0][num1] != -1) return dp[num0][num1];
    if(num0==n && num1==n) return dp[num0][num1]=0;
    int targ_pos=num0+num1;
    int ans=0;
    if(num0==n)
    {
        int his_pos=pos[1][num1]+rechts_kleiner_zelfde_soort[pos[1][num1]]+rechts_kleiner_andere_soort[pos[1][num1]][num0];
        return dp[num0][num1]=his_pos-targ_pos+calc(num0, num1+1);
    }
    else if(num1==n)
    {
        int his_pos=pos[0][num0]+rechts_kleiner_zelfde_soort[pos[0][num0]]+rechts_kleiner_andere_soort[pos[0][num0]][num1];
        return dp[num0][num1]=his_pos-targ_pos+calc(num0+1, num1);
    }
    else
    {
        int his_pos=pos[1][num1]+rechts_kleiner_zelfde_soort[pos[1][num1]]+rechts_kleiner_andere_soort[pos[1][num1]][num0];
        ans=his_pos-targ_pos+calc(num0, num1+1);
        his_pos=pos[0][num0]+rechts_kleiner_zelfde_soort[pos[0][num0]]+rechts_kleiner_andere_soort[pos[0][num0]][num1];
        ans=min(ans, his_pos-targ_pos+calc(num0+1, num1));
        return dp[num0][num1]=ans;
    }
}

