int posw[MAX];
int posb[MAX];

int d[MAX][MAX];

int sufw[MAX][MAX];
int sufb[MAX][MAX];

void init() {
	fi(0, MAX - 1) {
		fj(0, MAX - 1) {
			d[i][j] = INF;
		}
	}
	fi(1, n * 2) {
		if (col[i] == 'B') {
			posb[val[i]] = i;
		} else {
			posw[val[i]] = i;
		}
	}
	fdi(n * 2, 1) {
		memcpy(sufw[i], sufw[i + 1], sizeof(sufw[i]));
		memcpy(sufb[i], sufb[i + 1], sizeof(sufb[i]));
		fj(val[i], n) {
			if (col[i] == 'B') {
				sufb[i][j]++;
			} else {
				sufw[i][j]++;
			}
		}
	}	
}

void solve() {
	init();
	d[0][0] = 0;
	fi(0, n * 2 - 1) {
		fj(0, n) {
			if (d[i][j] == INF) continue;
			int w = j;
			int b = i - w;
			int nw = w + 1;
			int nb = b + 1;
			if (nw <= n) {
				int p = posw[nw];
				int np = p;
				np += sufw[p][nw - 1];
				np += sufb[p][nb - 1];
				int dist = np - i - 1;
				assert(dist >= 0);
				d[i	+ 1][j + 1] = min(d[i + 1][j + 1], d[i][j] + dist);
			}	
			if (nb <= n) {
				int p = posb[nb];
				int np = p;
				np += sufb[p][nb - 1];
				np += sufw[p][nw - 1];
				int dist = np - i - 1;
//				err("i = %d j = %d nw = %d nb = %d dist = %d\n", i, j, nw, nb, dist);
				assert(dist >= 0);
				d[i + 1][j] = min(d[i + 1][j], d[i][j] + dist);
			}
		}
	}
	printf("%d\n", d[n * 2][n]);
}

