	int mn = 2e9, t;
	if (p == 0 && q == 0) return 0;
	if (u[p][q] != -1) return u[p][q];
	if (p > 0) {
		t = vw[p] - g(vw[p]);
		h(vw[p], 1);
		mn = min(mn, f(p - 1, q) + (p + q - t));
		h(vw[p], -1);
	}
	if (q > 0) {
		t = vb[q] - g(vb[q]);
		h(vb[q], 1);
		mn = min(mn, f(p, q - 1) + (p + q - t));
		h(vb[q], -1);
	}
	return u[p][q] = mn;
}
