const long long INF = 1LL<<60;

int N;
vector<char> c;
vector<int> a;

long long solve() {
    vector<vector<long long>> dp(N+2, vector<long long>(N+2, INF));
    dp[0][0] = 0;
    for (int b = 0; b <= N; ++b) {
        for (int w = 0; w <= N; ++w) {
            int inb = b+w; // (B, b) が何番目にあるか
            for (int i = 0; i < N*2; ++i) {
                if (c[i] == 'B' && a[i] == b) break;
                if (c[i] == 'B' && a[i] > b) ++inb;
                else if (c[i] == 'W' && a[i] >= w) ++inb;
            }
            int inw = b+w;
            for (int i = 0; i < N*2; ++i) {
                if (c[i] == 'W' && a[i] == w) break;
                if (c[i] == 'W' && a[i] > w) ++inw;
                else if (c[i] == 'B' && a[i] >= b) ++inw;
            }

            //cout << b << ", " << w << ": " << inb << ", " << inw << ";; " << dp[b][w] << endl;

            chmin(dp[b+1][w], dp[b][w] + abs(inb - (b+w)));
            chmin(dp[b][w+1], dp[b][w] + abs(inw - (b+w)));
        }
    }
    return dp[N][N];
}

