	template<class T, class F>struct seg_tree_base
	{
	private:
		std::vector<T> vec;
		std::size_t depth;
		F func;
	public:
		seg_tree_base(std::size_t depth_, F func_ = F()):vec((1 << (depth_ + 1)) - 1), depth(depth_), func(func_) {}

		T get(std::size_t first, std::size_t last)const//[first, last)の範囲
		{
			if (last <= first)
			{
				return T();
			}
			return get(first, last - first, 0);
		}

		void change(T const& val, std::size_t index)
		{
			change(val, index, 0);
		}
	private:
		T get(std::size_t first, std::size_t length, std::size_t dep)const
		{
			if (length == 1)
			{
				return vec[(std::size_t(1) << depth) + first - 1];
			}
			auto x = std::size_t(1) << dep;
			auto y = std::size_t(1) << (depth - dep);
			if (first % y == 0)
			{
				if (length == y)
				{
					return vec[x + first / y - 1];
				}
				else if (length > y)
				{
					return func(vec[x + first / y - 1], get(first + y, length - y, dep + 1));
				}
				else
				{
					return get(first, length, dep + 1);
				}
			}
			else
			{
				auto next = first / y + 1;
				if (next*y < first + length)
				{
					return func(
						get(first, next*y - first, dep + 1),
						get(next*y, length - (next*y - first), dep + 1));
				}
				else
				{
					get(first, length, dep + 1);
				}
			}
		}

		void change(T const& val, std::size_t index, std::size_t dep)
		{
			auto x = 1 << dep;
			auto y = 1 << (depth - dep);
			if (dep == depth)
			{
				vec[x + index - 1] = val;
			}
			else
			{
				change(val, index, dep + 1);
				auto ind = index / y;
				vec[x + ind - 1] = func(vec[(x << 1) + 2 * ind - 1], vec[(x << 1) + 2 * ind]);
			}
		}
	};
	template<class T>using basic_seg_tree = seg_tree_base<T, std::plus<>>;

	template<class T, class F>class calc_tree
	{
		int size;
		const int count = 32;
		boost::multi_array<boost::optional<std::pair<int, T>>, 2> inside;
		std::vector<int> depth;
		F func;
		union_find_light uf;

		void init(int now, int prev, int dep, std::vector<std::map<int, T>>const& edge)
		{
			depth[now] = dep;
			FOREACH_STRUCT2(index, value, edge[now])
			{
				if (index == prev)
				{
					continue;
				}
				inside[index][0] = std::make_pair(now, value);
				init(index, now, dep + 1, edge);
			}
		}

		std::tuple<T, int> get(int now, int dep)
		{
			T ret{};
			for (auto sft : boost::irange(0, count))
			{
				if (dep&(1 << sft))
				{
					DEFINE_STRUCT2(next, val, *inside[now][sft]);
					now = next;
					ret = func(ret, val);
				}
			}
			return std::make_tuple(ret, now);
		}
	public:
		template<class Range>calc_tree(int size_, F func_, Range const& rng):
			size(size_),
			inside(boost::extents[size][count]),
			depth(size),
			func(func_),
			uf(size)
		{
			std::vector<std::map<int, T>> edge(size);
			FOREACH_STRUCT3(a, b, val, rng)
			{
				if (uf.is_same_group(a, b))
				{
					throw std::invalid_argument("this is not tree");
				}
				uf.merge(a, b);
				edge[a].emplace(b, val);
				edge[b].emplace(a, val);
			}
			for (auto i : uf.tops())
			{
				init(i, -1, 0, edge);
			}
			for (auto k : boost::irange(1, count))
			{
				for (auto j : boost::irange(0, size))
				{
					if (inside[j][k - 1])
					{
						DEFINE_STRUCT2(next1, val1, *inside[j][k - 1]);
						if (inside[next1][k - 1])
						{
							DEFINE_STRUCT2(next2, val2, *inside[next1][k - 1]);
							inside[j][k] = std::make_pair(next2, func(val1, val2));
						}
					}
				}
			}
		}

		boost::optional<T> get_value(int x, int y)
		{
			if (!uf.is_same_group(x, y))
			{
				return boost::none;
			}
			if (depth[y] < depth[x])
			{
				std::swap(x, y);
			}
			T ret{};
			std::tie(ret, y) = get(y, depth[y] - depth[x]);
			if (x == y)
			{
				return ret;
			}
			for (auto sft = count - 1; sft >= 0; --sft)
			{
				if (inside[x][sft])
				{
					DEFINE_STRUCT2(next1, val1, *inside[x][sft]);
					DEFINE_STRUCT2(next2, val2, *inside[y][sft]);
					if (next1 != next2)
					{
						x = next1;
						y = next2;
						ret = func(func(val1, val2), ret);
					}
				}
			}
			return func(func(inside[x][0]->second, inside[y][0]->second), ret);
		}
	};
	template<class T, class Func, class Range>auto make_calc_tree(std::size_t size, Func func, Range const& rng)
	{
		return calc_tree<T, Func>(size, func, rng);
	}

	auto maxf = [](auto a, auto b) {return std::max(a, b); };
	auto minf = [](auto a, auto b) {return std::min(a, b); };
}

namespace out
{
	namespace detail
	{
		template<class>struct void_out
		{
			typedef void type;
		};
		template<class T>auto write(std::ostream& ost, T const& val)
			->typename void_out<decltype(ost << val)>::type
		{
			ost << val;
		}
		template<class T, class... Ts>void write(std::ostream& ost, T const& val, Ts const&... nexts)
		{
			write(ost, val);
			ost << " ";
			write(ost, nexts...);
		}
		template<class T, std::size_t... Is>void write_tuple(std::ostream& ost, T const& tuple, std::index_sequence<Is...>)
		{
			write(ost, std::get<Is>(tuple)...);
		}
		template<class... Ts>void write(std::ostream& ost, std::tuple<Ts...>const& tuple)
		{
			write_tuple(ost, tuple, std::make_index_sequence<sizeof...(Ts)>());
		}
		template<class T0, class T1>void write(std::ostream& ost, std::pair<T0, T1>const& pair)
		{
			write(ost, pair.first);
			ost << " ";
			write(ost, pair.second);
		}
		template<class T>void write(std::ostream& ost, std::vector<T>const& vec)
		{
			auto size = vec.size();
			if (size == 0)
			{
				return;
			}
			write(ost, vec[0]);
			for (auto i : boost::irange<std::size_t>(1, size))
			{
				ost << " ";
				write(ost, vec[i]);
			}
		}
		template<class T>void write(std::ostream& ost, boost::multi_array<T, 2>const& ar)
		{
			write(ost, ar[0][0]);
			for (auto const& v : lib::make_range(std::next(ar[0].begin()), ar[0].end()))
			{
				ost << " ";
				write(ost, v);
			}
			for (auto ite = std::next(ar.begin()); ite != ar.end(); ++ite)
			{
				ost << std::endl;
				write(ost, *ite->begin());
				for (auto const& v : lib::make_range(std::next(ite->begin()), ite->end()))
				{
					ost << " ";
					write(ost, v);
				}
			}
		}
		template<std::uint64_t Mod>void write(std::ostream& ost, lib::modnum<Mod>const& val)
		{
			ost << val.val;
		}
	}
	void write_line()
	{
		std::cout << std::endl;
	}
	template<class...Ts>void write_line(Ts const&... args)
	{
		detail::write(std::cout, args...);
		std::cout << std::endl;
	}
	void debug()
	{
		std::cerr << std::endl;
	}
	template<class...Ts>void debug(Ts const&... args)
	{
		detail::write(std::cerr, args...);
		std::cerr << std::endl;
	}
	template<class Range>void write_range(Range const& rng)
	{
		for (auto const& v : rng)
		{
			write_line(v);
		}
	}
	template<class Range>void debug_range(Range const& rng)
	{
		for (auto const& v : rng)
		{
			debug(v);
		}
	}
