template<typename T> struct BinaryIndexedTree {
	vector<T> data;
	BinaryIndexedTree(int sz) { data.assign(++sz, 0); }
	BinaryIndexedTree(vector<T> data) : data(data) {}
	T sum(int k) {
		if (k < 0) return 0;
		T ret = 0;
		for (++k; k > 0; k -= k & -k) ret += data[k];
		return ret;
	}
	void add(int k, T x) {
		for (++k; k < data.size(); k += k & -k) data[k] += x;
	}
	void debug() {
		int sz = (int)data.size() - 1;
		for (int i = 0; i < sz; ++i) {
			cerr << sum(i) - sum(i - 1) << " \n"[i == sz - 1];
		}
	}
};

int N;
vector<int> black, white;

// idx[i][j] := 白がi個, 黒がj個(後ろから)残っているとき, 各色の最小値を一番前に持ってくるための操作回数
vector<vector<int>> black_idx, white_idx;

// dp[i][j] :=	前からi番目までがソート済みで, 内j個が黒いボールのとき,
//				残りをソート済みにするために必要な操作回数の最小値
vector<vector<int>> dp;
int rec(int p, int q) {
	if (dp[p][q] != -1) return dp[p][q];
	int ret = INF;
	if (q < N)		ret = min(ret, black_idx[N - (p - q)][N - q] + rec(p + 1, q + 1));	// 黒を動かす
	if (p - q < N)	ret = min(ret, white_idx[N - (p - q)][N - q] + rec(p + 1, q));		// 白を動かす
	return dp[p][q] = ret;
}

