struct BIT {
	int n;
	vector<T> d;
	BIT(ijt n = 0) :n(n), d(n + 1) {}
	void add(ijt i, T x = 1) {
		for (i++; i <= n; i += i & -i) {
			d[i] += x;
		}
	}
	T sum(ijt i) {
		T x = 0;
		for (i++; i; i -= i & -i) {
			x += d[i];
		}
		return x;
	}

	long long inversion(vector<int> a) {
		long long ans = 0;
		for (int j = 0; j < a.size(); j++) {
			ans += j - sum(a[j]);
			add(a[j], 1);
		}
		return ans;
	}
};

