  for(int i=0;i<(2*n);++i) {
    char c; int a; cin >> c >> a;
    a--;
    v.push_back({c, a});
  }
  vvi black(n, vi(n+1, 0)), white(n, vi(n+1, 0));
  vi bnum(n, 0), wnum(n, 0);
  for(int k=0;k<(2*n);++k) {
    char c = v[k].first;
    int num = v[k].second;
    vi wsum(n+1, 0), bsum(n+1, 0);
    for(int l=(int)(n);l>=(int)(1);--l) {
      bsum[l-1] = bsum[l] + bnum[l-1];
      wsum[l-1] = wsum[l] + wnum[l-1];
    }
    for(int l=(int)(n+1);l>=(int)(1);--l) {
      if(c == 'B') black[num][l-1] = wsum[l-1] + bsum[num+1];
      else white[num][l-1] = wsum[num+1] + bsum[l-1];
    }
    if(c == 'B') bnum[num]++;
    else wnum[num]++;
  }
  vvi dp(2*n+1, vi(n+1, INF));
  dp[0][0] = 0;
  for(int i=0;i<(2*n);++i) {
    for(int j=0;j<(min(n+1, i+1));++j) {
      if(dp[i][j] == INF) continue;
      int nxtw = j;
      int nxtb = i-j;
      if(nxtw < n) chmin(dp[i+1][j+1], dp[i][j] + black[nxtw][nxtb]);
      if(nxtb < n) chmin(dp[i+1][j], dp[i][j] + white[nxtb][nxtw]);
    }
  }
  cout << dp[2*n][n] << endl;
}

