int rsq(int s, int t, int k = 1, int l = 0, int r = 4095) {
	if (t < l || r < s) {
		return 0;
	}
	if (s <= l && r <= t) {
		return seg[k];
	}

	int lv = rsq(s, t, k * 2, l, (l + r) / 2);
	int rv = rsq(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

void upd(int x) {
	x += 4096;
	seg[x]++;
	while (x) {
		x /= 2;
		seg[x] = seg[x * 2] + seg[x * 2 + 1];
	}
}

void chmin(ll& x, ll y) {
	x = min(x, y);
