map<pair<char, int>, int> pos;

int cost(char cur, int pos, int k) {
	// trace(cur, pos, k);
	int &y = dp2[cur=='B'][pos][k];
	if(y!=-1) return y;
	if(k == 0) return y = 0;
	return y = (::pos[MP(cur, k)] > pos) + cost(cur, pos, k-1);
}

int calc(int pos, int b, int w) {
	int &y = dp[b][w];
	if(y!=-1) return y;
	if(pos == 0) return y = 0;
	y = INT_MAX;
	if(b) {
		y = min(y, cost('B', ::pos[MP('B', b)], b-1) + cost('W', ::pos[MP('B', b)], w) + calc(pos-1, b-1, w));
	}
	if(w) {
		y = min(y, cost('B', ::pos[MP('W', w)], b) + cost('W', ::pos[MP('W', w)], w-1) + calc(pos-1, b, w-1));
	}
	return y;
}

