			y[i][j] = s.sum(t);
			s.add(t, 1);
		}
	}

	vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, 0));
	rep(i, N+1)rep(j, N+1) {
		if (i > 0) { dp[i][j] = max(dp[i][j], dp[i - 1][j] + y[i][j]); }
		if (j > 0) { dp[i][j] = max(dp[i][j], dp[i][j - 1] + x[i][j]); }
	}

	ll ans = N * (2 * N - 1) - dp[N][N];
	cout << ans << endl;


	system("PAUSE");
}

