struct st{
	vector<int> t;

	st(){
		t.resize(2 * MAXN);
	}

	void build(){
		for(int i = MAXN - 1 ; i > 0 ; --i){
			t[i] = t[2 * i] + t[2 * i + 1];
		}
	}

	void modify(int p , int val){
		for(t[p += MAXN] = val ; p > 1 ; p /= 2){
			t[p / 2] = t[p] + t[p ^ 1];
		}
	}

	int sum(int l , int r){//[l , r)
		int res = 0;
		for(l += MAXN , r += MAXN ; l < r ; l /= 2 , r /= 2){
			if(l % 2){
				res += t[l];
				++l;
			}
			if(r % 2){
				--r;
				res += t[r];
			}
		}
		return res;
	}
};

