{
    const auto n = read<int>();
    std::vector<bool> c(2 * n);
    std::vector<usize> a(2 * n);
    std::vector<usize> bs, ws;
    usize w = 0, b = 0;
    for (usize i = 0; i < 2 * n; i++) {
