    ll n = in1;
    vector<pair<char, ll>> ca(n*2);
    REP(i, n*2) {
        char c; ll a; cin >> c >> a;
        a--; // 0-indexed
        ca[i] = make_pair(c, a);
    }

    vector<ll> pw(n), pb(n);
    REP(i, n*2) {
        char c; ll a; tie(c, a) = ca[i];
        (c=='W' ? pw : pb)[a] = i;
    }

    // (iw|ib)[i][j] := (w|b)_i以降, (b|w)_j以降が残ってるときに(w|b)_iの左に残っている項の数
    vector<vector<ll>> iw(n, vector<ll>(n+1, INF));
    vector<vector<ll>> ib(n, vector<ll>(n+1, INF));
    DSRNG(i, n-1, 0) {
        ll ws = 0;
        DSRNG(j, pw[i]-1, 0) {
            if (ca[j].first == 'W') {
                if (i < ca[j].second) {
                    ws++;
                }
            }
        }
        iw[i][n] = ws;
        DSRNG(j, n-1, 0) {
            iw[i][j] = iw[i][j+1] + (pw[i] > pb[j]);
        }
    }
    DSRNG(i, n-1, 0) {
        ll bs = 0;
        DSRNG(j, pb[i]-1, 0) {
            if (ca[j].first == 'B') {
                if (i < ca[j].second) {
                    bs++;
                }
            }
        }
        ib[i][n] = bs;
        DSRNG(j, n-1, 0) {
            ib[i][j] = ib[i][j+1] + (pb[i] > pw[j]);
        }
    }

    vector<vector<ll>> dp(n+1, vector<ll>(n+1, INF));
    dp[0][0] = 0;
    REP(i, n+1) REP(j, n+1) {
        if (i+1 <= n) {
            chmin(dp[i+1][j], dp[i][j] + iw[i][j]);
        }
        if (j+1 <= n) {
            chmin(dp[i][j+1], dp[i][j] + ib[j][i]);
        }
    }
    say(dp[n][n]);


}

