#define mod 1000000007

class RMQ
{
private:
	int n;
	vector<int> v;

public:
	RMQ(int k)
	{
		n = k;
		v = vector<int>(2 * n, 0);
	}

	void add(int x, int val)
	{
		x += n - 1;
		v[x] += val;
		while(x > 0){
			x = (x - 1) / 2;
			v[x] = v[2 * x + 1] + v[2 * x + 2];
		}
	}

	int getsum(int tl, int tr, int nl, int nr, int index)
	{
		// cout << tl << " " << tr << " " << nl << " " << nr << " " << index << endl;
		if(nr <= tl || tr <= nl) return 0;
		if(tl <= nl && nr <= tr) return v[index];
		return getsum(tl, tr, nl, (nl + nr) / 2, 2 * index + 1) + getsum(tl, tr, (nl + nr) / 2, nr, 2 * index + 2);
	}

	void print()
	{
		for(int i = 0; i < 2 * n; i++){
			cout << v[i] << " ";
		}
		cout << endl;
	}
};



