		if(c == 'W'){
			qu[0].push(make_pair(-a, i));
		} else {
			qu[1].push(make_pair(-a, i));
		}
	}
	int ans = 0;
	int popcnt = 0;
	while(!qu[0].empty() || !qu[1].empty()){
		int p0 = mod;
		int p1 = mod;
		if(!qu[0].empty()) p0 = (qu[0].top()).second;
		if(!qu[1].empty()) p1 = (qu[1].top()).second;
		// cout << p0 << " " << p1  << endl;
		if(p0 < p1){
			ans += p0 + rmq.getsum(p0, tmp, 0, tmp, 0) - popcnt;
			rmq.add(p0, 1);
			qu[0].pop();
		} else {
			ans += p1 + rmq.getsum(p1, tmp, 0, tmp, 0) - popcnt;
			rmq.add(p1, 1);
			qu[1].pop();
		}
		popcnt++;
		// rmq.print();
