                cw[i][0]++; 
            }
        }
        for (int j = 1; j <= n; j++) {
            cw[i][j] = cw[i][j - 1]; 
            if (pw[i] < pb[j]) {
                cw[i][j]++; 
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j < i; j++) {
            if (pb[i] < pb[j]) {
                cb[0][i]++;
            }
        }
        for (int j = 1; j <= n; j++) {
            cb[j][i] = cb[j - 1][i]; 
            if (pb[i] < pw[j]) {
                cb[j][i]++; 
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        dp[i][0] = dp[i - 1][0] + cw[i][0]; 
        dp[0][i] = dp[0][i - 1] + cb[0][i]; 
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dp[i][j] = min(dp[i - 1][j] + cw[i][j], dp[i][j - 1] + cb[i][j]); 
        }
    }
    printf("%d\n", dp[n][n]); 
    return 0; 
}

