ll sumW[2200][2200];
vl idxB(2200),idxW(2200);
ll dp[2200][2200];
ll f(ll b,ll w){
    if(b==n&&w==n)return 0;
    if(0<=dp[b][w])return dp[b][w];
    ll res=INF;
    if(b!=n){
        ll cnt=0;
        if(0<=idxB[b+1]-1) cnt+=sumB[b+1][idxB[b+1]-1];
        if(0<=idxB[b+1]-1) cnt+=sumW[w+1][idxB[b+1]-1];
        chmin(res,f(b+1,w)+cnt);
    }
    if(w!=n){
        ll cnt=0;
        if(0<=idxW[w+1]-1) cnt+=sumB[b+1][idxW[w+1]-1];
        if(0<=idxW[w+1]-1) cnt+=sumW[w+1][idxW[w+1]-1];
        chmin(res,f(b,w+1)+cnt);
    }
    return dp[b][w]=res;
}
