// 1 base
template<typename T, int max_n>
class BIT {
private:
    T bit[max_n + 1];
    int n;
public:
    BIT(int _n = max_n) {
        n = _n;
        memset(bit, 0, sizeof(bit));
    }
    // [1, i]
    T sum(int i) {
        T s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }
    // [a, b]
    T sum(int a, int b) {
        return sum(b) - sum(a-1);
    }

    void add(int i, T x) {
        while (i <= n) {
            bit[i] += x;
            i += i & -i;
        }
    }

    int lower_bound(T x) {
        int lb = 0, ub = n;
        while (ub - lb > 1) {
            int mid = (ub + lb) / 2;
            T v = sum(mid);
            if (v < x) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return ub;
    }

    int upper_bound(T x) {
        int lb = 1, ub = n+1;
        while (ub - lb > 1) {
            int mid = (ub + lb) / 2;
            T v = sum(mid);
            if (v <= x) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return ub;
    }
};

BIT<int, 4010> bit;

int calc(int u, int v) {
    if (u == n && v == n) return 0;
    if (dp[u][v] < 0) {
        int uc = inf, vc = inf;
        if (u < n) {
            int up = pos[make_pair('W', u+1)];
            uc = up - bit.sum(up) - 1;
            bit.add(up, 1);
            uc += calc(u+1, v);
            bit.add(up, -1);
        }
        if (v < n) {
            int vp = pos[make_pair('B', v+1)];
            vc = vp - bit.sum(vp) - 1;
            bit.add(vp, 1);
            vc += calc(u, v+1);
            bit.add(vp, -1);
        }
        dp[u][v] = min(uc, vc);
    }
    return dp[u][v];
}

