            }
        }
        for (int j = 1; j <= N; j++)
        {
            int pos = indices_b[j];
            cost_b[i][j - 1] = pos - bit.sum(0, pos) - 1;
            // cerr << "i = " << i << " j = " << j - 1 << " pos = " << pos << " " << bit.sum(0, pos) << " " << cost_w[i - 1][j] << endl;
            bit.add(pos, 1);
        }

    }
    cout << memo(0, 0) << endl;
    return 0;
}

