  for (int pos = 0; pos < 2 * n; pos++) {
    char c; int i;
    cin >> c >> i;
    i--;
    (c == 'B' ? b : w).at(i) = pos;
  }
  constexpr int inf = 1 << 30;
  vector<vector<int>> dp(n + 1, vector<int> (n + 1, inf));
  dp[0][0] = 0;
  binary_indexed_tree<int> bit(2 * n, plus<int>(), minus<int>(), 0);
  for (int i = 0; i <= n; i++) {
    binary_indexed_tree<int> wit(2 * n, plus<int>(), minus<int>(), 0);
    for (int j = 0; j <= n; j++) {
      auto cal = [&] (int k) {
        return k - bit.cum(k) - wit.cum(k);
      };
      if (i < n) cmn(dp[i + 1][j], dp[i][j] + cal(b[i]));
      if (j < n) cmn(dp[i][j + 1], dp[i][j] + cal(w[j]));
      if (j < n) wit.add(w[j], 1);
    }
    if (i < n) bit.add(b[i], 1);
  }
