// 0-origin BIT
template <typename T>
class BIT {
public:
	vector<T> data;
	int n;
	BIT() {}
	BIT(int n_) {
		n = n_;
		data.assign(n, T(0));
	}
	// v[a] += w
	void add(int a, T w) {
		for (int x = a; x < n; x |= x + 1) data[x] += w;
	}
	// sum of v[i] for i in [0, a)
	T sum(int a) {
		T ret = 0;
		for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
			ret += data[x];
		}
		return ret;
	}
};

int N;
int cost[2002][2002][2];
ll memo[2002][2002];

ll dfs(int nb, int nw) {
	if(nb == N && nw == N) {
		return 0;
	}
	if (memo[nb][nw] != -1) return memo[nb][nw];
	ll ret = 1LL << 60;
	if (nb < N) {
		ret = min(ret, dfs(nb + 1, nw) + cost[nb][nw][0]);
	}
	if (nw < N) {
		ret = min(ret, dfs(nb, nw + 1) + cost[nb][nw][1]);
	}
	memo[nb][nw] = ret;
	return ret;
}


int main() {
	cin >> N;

	vector<int> pos_b(N), pos_w(N);
	for(int i=0;i<2*N;i++) {
		char c;
		int a;
		cin >> c >> a;
		if(c == 'W') {
			pos_w[a - 1] = i;
		}else {
			pos_b[a - 1] = i;
		}
	}

	{
		BIT<int> bit_b(2 * N);
		for (int nb = 0; nb <= N; nb++) {
			BIT<int> bit_w(2 * N);
			for (int nw = 0; nw <= N; nw++) {
				if(nb < N) cost[nb][nw][0] = pos_b[nb] - (bit_b.sum(pos_b[nb]) + bit_w.sum(pos_b[nb]));
				if(nw < N) cost[nb][nw][1] = pos_w[nw] - (bit_b.sum(pos_w[nw]) + bit_w.sum(pos_w[nw]));
				if(nw < N) bit_w.add(pos_w[nw], 1);
			}
			if(nb < N) bit_b.add(pos_b[nb], 1);
		}
	}

	memset(memo, -1, sizeof(memo));
	cout << dfs(0, 0) << endl;

	return 0;
}

