int main()
{
	int N;

	cin >> N;

	Black[2001];
	White[2001];

	int ans = 0;

	for (int i = 0; i < 2 * N; ++i)
	{
		char c; int a;
		cin >> c >> a;

		if (c == 'B') { Black[a] = i; }
		else if (c == 'W') { White[a] = i; }
	}
	for (int i = 1; i < N; ++i)
	{
		if (Black[i] < Black[i + 1])continue;
		ans += Black[i] - Black[i + 1];	
		moveBall(Black[i + 1], Black[i],N);
		//cout << ">B " << i << ":" <<Black[i] <<" "<< i+1 << ":" << Black[i+1] << endl;
	}
	for (int i = 1; i < N; ++i)
	{
		if (White[i] < White[i + 1])continue;
		ans += White[i] - White[i + 1];
		moveBall(White[i + 1], White[i],N);
		//cout << ">W " << i << ":" << White[i] << " " << i + 1 << ":" << White[i + 1] << endl;
	}

	cout << ans << endl;

	return 0;
}

void moveBall(int x, int y, int n)
{
	for (int i = 1; i <= n; ++i)
	{
		if (x < Black[i] && Black[i] <= y) { Black[i] -= 1; }
		else if (x == Black[i]) { Black[i] = y; }

		if (x < White[i] && White[i] <= y) { White[i] -= 1;  }
		else if (x == White[i]) { White[i] = y; }
	}
}

