        //~ cerr << "gwt " << x << endl;
        int ans = 0;
        for(; x > 0; x -= x & -x) ans += v[x];
        //~ cerr << " -> " << ans << endl;
        return ans;
    }
    void upd(int x){
        //~ cerr << "upd " << x << endl;
        for(; x <= n; x += x & -x) v[x]++;
    }
};

