struct BIT {
    vector<int> data;
    int size;
    BIT(int n): size(n + 1), data(n + 1, 0) {}
    void add(int i, int x) {
        i++;
        while (i <= size) {
            data[i] += x;
            i += i & -i;
        }
    }
    int sum(int i) {
        i++;
        int ret = 0;
        while (i > 0) {
            ret += data[i];
            i -= i & -i;
        }
        return ret;
    }
};

