    for (int i = 0; i <= n; i++) {
        memset(tree, 0, sizeof(tree));
        for (int j = 1; j <= 2*n; j++) {
            add(nums[j]);
            if (nums[j] <= 2000) {
                costw[nums[j]][i] = query(nums[j]+1, 2000);
                costw[nums[j]][i] += query(2000+i+1, 2000+n);
            }
        }
    }
