int getw(int p)
{
	int ans=0;
	while(p>0)
	{
		ans+=bitw[p];
		p-=(p&(-p));
	}
	return ans;
}

int getb(int p)
{
	int ans=0;
	while(p>0)
	{
		ans+=bitb[p];
		p-=(p&(-p));
	}
	return ans;
}

