{
	while(p<=2*n)
	{
		bitw[p]++;
		p+=(p&(-p));
	}
	return;
}

void updateb(int p)
{
	while(p<=2*n)
	{
		bitb[p]++;
		p+=(p&(-p));
	}
	return;
}

