using namespace std;

const int N = 4e3 + 4, inf = 1e9 + 7;
struct BIT {
  int n;
  int bit[N][N];
  BIT() : n(N-2) {
    memset(bit, 0, sizeof bit);
  }
  int get(int x, int y) {
    ++x, ++y;
    int yy = y, ret = 0;
    for (; x; x -= x&-x)
      for (y = yy; y <= n; y += y&-y)
        ret += bit[x][y];
    return ret;
  }
  void upd(int x, int y, int v) {
    ++x, ++y;
    int yy = y;
    for (; x <= n; x += x&-x)
      for (y = yy; y; y -= y&-y)
        bit[x][y] += v;    
  }
};

