using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int, int> ii;

const int MAX = 4000 + 5;
const int INF = (int) 1e9;
int pref[2][MAX][MAX];
int memo[MAX][MAX];
int el_idx[2][MAX], vals[MAX], colors[MAX];
int n;

int roll(int idx, int w_idx) {
	if(idx == 2 * n + 1) {
		return 0;
	}

	int &ans = memo[idx][w_idx];
	if(~ans) {
		return ans;
	}

	int b_idx = idx - w_idx + 1;

	ans = INF;
	if(w_idx <= n) {
		int ball_idx = el_idx[0][w_idx] - (pref[0][w_idx - 1][el_idx[0][w_idx]] + pref[1][b_idx - 1][el_idx[0][w_idx]]);
		int price = ball_idx - 1;
		ans = min(ans, roll(idx + 1, w_idx + 1) + price);
	}

	if(b_idx <= n) {
		int ball_idx = el_idx[1][b_idx] - (pref[0][w_idx - 1][el_idx[1][b_idx]] + pref[1][b_idx - 1][el_idx[1][b_idx]]);
		int price = ball_idx - 1;
		ans = min(ans, roll(idx + 1, w_idx) + price);
	}

	return ans;
}

int main() {
	scanf("%d%*c", &n);

	fori(i, 1, 2 * n + 1) {
		char color;
		int val;
		scanf("%c %d%*c", &color, &val);
		int mask = color == 'B';

		el_idx[mask][val] = i;
		vals[i] = val;
		colors[i] = mask;
	}

	fori(i, 0, 2) {
		fori(j, 1, n + 1) {
			int total = 0;
			fori(k, 1, 2 * n + 1) {
				if(colors[k] == i && vals[k] <= j) {
					total++;
				}
				pref[i][j][k] = total;
			}
		}
	}

	memset(memo, -1, sizeof memo);
	printf("%d\n", roll(1, 1));

	return 0;
}

