using namespace std;

const int N = 2005;
const int INF = 1e9;

int n, a[N * 2], pos[N * 2];
char c[N * 2];
int dp[N * 2][N];

struct Fenwick {
    int t[N];

    void upd(int x) {
        for(;x < N; x += x&(-x)) t[x] ++;
    }

    int get(int x) {
        int ret = 0;
        for (;x > 0;x -= x&(-x)) ret += t[x];
        return ret;
    }
} bitB[N * 2], bitW[N * 2];

int main() {
    //freopen("in.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;
    for (int i = 1; i <= n + n; ++i) {
        cin >> c[i] >> a[i];
        if (c[i] == 'B') pos[a[i]] = i;
        else pos[a[i] + n] = i;
    }

    for (int i = n + n; i >= 1;i --) {
        bitB[i] = bitB[i + 1];
        bitW[i] = bitW[i + 1];
        if (c[i] == 'W') {
            bitW[i].upd(a[i]);
        } else {
            bitB[i].upd(a[i]);
        }
    }

    for (int i = 0; i <= n + n; ++i) {
        for (int j = 0; j <= n; ++j) {
            dp[i][j] = INF; // reset
        }
    }

    dp[0][0] = 0;
    for (int i = 0; i < n + n; ++i) {
        for (int b = 0; b <= i && b <= n; ++b) { // B
            if (dp[i][b] == INF) continue;
            int w = i - b; // W
            if (w < n) {
                int p = pos[w + 1 + n];
                dp[i + 1][b] = min(dp[i + 1][b], dp[i][b] + bitW[p + 1].get(w) + bitB[p + 1].get(b));
            }
            if (b < n) {
                int p = pos[b + 1];
                dp[i + 1][b + 1] = min(dp[i + 1][b + 1], dp[i][b] + bitW[p + 1].get(w) + bitB[p + 1].get(b));
            }
        }
    }

    cout << dp[n + n][n] << endl;
}

