            if(ball[i - 1][1] > j) ball[i - 1][0] == 0 ? costw[i][j]++ : costb[i][j]++;
        }
    }
    SET_INF(dp);
    dp[0][0] = 0;
    for(int i = 0; i <= N / 2; i++){
        for(int j = 0; j <= N / 2; j++){
            int u = pos[0][i + 1],v = pos[1][j + 1];
            dp[i + 1][j] = min(dp[i + 1][j],dp[i][j] + costw[u][i + 1] + costb[u][j]);
            dp[i][j + 1] = min(dp[i][j + 1],dp[i][j] + costw[v][i] + costb[v][j + 1]);
        }
    }
    cout<<dp[N / 2][N / 2]<<endl;
    return 0;
}

