long long int solve(vector<pair<char, long long int>>ca){
	long long int w = 1, b = 1;
	long long int ans = 0;
	for( int i = 0; i < 2 * N; i++ ){
		if( ca[i].first == 'B'&&ca[i].second >= b ){
			long long int j = i;
			long long int w_ = w;
			while( !( ca[j].first == 'B'&&ca[j].second == b ) ){
				j++;
				if( ca[j].first == 'W'&&ca[j].second < w_ ){
					continue;
				}
				if( ca[j].first == 'W'&&ca[j].second == w_ ){
					w_++;
				}
				if( ca[j].first == 'B'&&ca[j].second < b ){
					continue;
				}
				ans += 1;
			}
			b++;
			if( j - i ){
				i--;
			}
			continue;
		}
		if( ca[i].first == 'W'&&ca[i].second >= w ){
			long long int j = i;
			long long int b_ = b;
			while( !( ca[j].first == 'W'&&ca[j].second == w ) ){
				j++;
				if( ca[j].first == 'W'&&ca[j].second < w ){
					continue;
				}
				if( ca[j].first == 'B'&&ca[j].second < b_ ){
					continue;
				}
				if( ca[j].first == 'B'&&ca[j].second == b_ ){
					b_++;
				}
				ans += 1;
			}
			w++;
			if( j - i ){
				i--;
			}
			continue;
		}
	}
	return ans;
}


