            loc_white[a[i]] = i;
        } else {
            loc_black[a[i]] = i;
        }
    }

    BIT processed_white = BIT(MAX_N*2);
    for (int i = 0; i <= N; i++) {
        BIT processed_black = BIT(MAX_N*2);
        for (int j = 0; j <= N; j++) {
            if (i != N) {
                cost_white[i][j] = loc_white[i+1] - 1 - processed_white.sum(loc_white[i+1] - 1) - processed_black.sum(loc_white[i+1] - 1);
            }
            if (j != N) {
                cost_black[i][j] = loc_black[j+1] - 1 - processed_white.sum(loc_black[j+1] - 1) - processed_black.sum(loc_black[j+1] - 1);
            }
            if (j != N) { processed_black.add(loc_black[j+1], 1); }
