        }
        if (i != N) { processed_white.add(loc_white[i+1], 1); }   
    }

    dp[0][0] = 0;
    for (int i = 1 ; i <= N; i++) {
        dp[i][0] = dp[i-1][0] + cost_white[i-1][0];
        dp[0][i] = dp[0][i-1] + cost_black[0][i-1];
    }

    for (int i = 1 ; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            dp[i][j] = std::min(dp[i-1][j] + cost_white[i-1][j], dp[i][j-1] + cost_black[i][j-1]);
        }
    }

    std::cout << dp[N][N] << std::endl;

    return 0;
}

