  bool operator<(const tup tt) const {
    if (c != tt.x) return c < tt.c;
    else if (x != tt.y) return x < tt.x;
    else return y < tt.y;
  }
  bool operator>(const tup tt) const {
    if (c != tt.x) return c > tt.c;
    else if (x != tt.y) return x > tt.x;
    else return y > tt.y;
  }
