    char ch; int a;
    cin>>ch>>a; a--;
    if (ch=='W') p[i]={0,a};
    else p[i]={1,a};
  }
  int r[2][n];
  for(int i=0;i<2*n;i++) {
    r[p[i].first][p[i].second]=i;
  }
  priority_queue<tup, vector<tup>, greater<tup>> que;
  for(int i=0;i<2;i++) {
    for(int j=1;j<n;j++) {
      if (r[i][j-1] < r[i][j]) continue;
      que.push({i,j-1,r[i][j-1]-r[i][j]});
    }
  }
  int an=0;
  while(!que.empty()) {
    tup t = que.top(); que.pop();
    int color = t.x, number = t.y;
