    auto get_lager = [&](int r, char c, int v) -> ll {
        ll ans = 0;
        rep(i, r) {
            Ball ball = balls[i];
            if (ball.c != c) continue;
            if (ball.v > v) ans++;
        }
        return ans;
    };

    auto set = [&](int b, int w, ll value) {
        if(b == n && w == n) cout << value << endl;
        P index(b, w);
        if (m.find(index) == m.end()) m[index] = value;
        else
            cmin(m[index], value);
    };

    for (ll b = 0; b <= n; b++) {
        for (ll w = 0; w <= n; w++) {

            assert(m.find(P(b, w)) != m.end());
            ll prev = m[P(b, w)];
            {

                // 黒を足す
                ll nb = b + 1;
                ll nw = w;

                if (nb <= n) {

                    ll i = get_index('B', nb);
                    ll lb = get_lager(i, 'B', nb);
                    ll lw = get_lager(i, 'W', nw);


                    ll now = prev + lb + lw;
                    set(nb, nw, now);
                }
            }
            {
                // 白を足す
                ll nw = w + 1;
                ll nb = b;

                if (nw <= n) {
                    ll i = get_index('W', nw);
                    ll lw = get_lager(i, 'W', nw);
                    ll lb = get_lager(i, 'B', nb);
                    ll now = prev + lb + lw;
                    set(nb, nw, now);
                }
            }

        }
    }
    cout << m[P(n, n)] << endl;

}

