int solve(int N, vector<char>& c, vector<int>& a) {
    vector<int> wloc(N), bloc(N), wg(N), bg(N);
    vector<int> wor, bor;
    wor.reserve(N), bor.reserve(N);
    int iw=0, ib=0;
    rep(i,N*2){
        --a[i];
        if (c[i]=='B') {
            bloc[a[i]] = ib++;
            bg[a[i]] = i;
            bor.pb(a[i]);
        }
        else if (c[i]=='W') {
            wloc[a[i]] = iw++;
            wg[a[i]] = i;
            wor.pb(a[i]);
        }
    }
#ifdef DEBUG
    cerr << wor << wloc << wg << endl;
    cerr << bor << bloc << bg << endl;
#endif

