    for (int var=N-1; var>=0; --var) {
//    rep(at,N){
//        int var = wor[at]; // at番目の数
        int at = wloc[var];
        if (at == var) continue;

        int oldloc = wg[ var ]; // いまここ
        int newloc = wg[ wor[var] ]; // 行き先
//        printf("%d : %d -> %d\n", var, oldloc, newloc);
        // [oldloc+1 .. newloc]
        for (int i=at; i<var; ++i) {
            wor[i] = wor[i+1];
            --wloc[ wor[i] ]; ++ans;
            --wg[ wor[i] ];
        }
        wor[var] = var;
        wloc[var] = var;
        wg[var] = newloc;

        rep(i,N) {
            if (oldloc < bg[i] && bg[i] <= newloc) {
                --bg[i]; ++ans;
            }
        }
        //cerr << wor << wloc << endl;
    }
#ifdef DEBUG
    cerr << wor << wloc << wg << endl;
    cerr << bor << bloc << bg << endl;
#endif
    // b
    for (int var=N-1; var>=0; --var) {
//    rep(at,N){
//        int var = wor[at]; // at番目の数
        int at = bloc[var];
        if (at == var) continue;

        int oldloc = bg[ var ]; // いまここ
        int newloc = bg[ bor[var] ]; // 行き先
//        printf("%d : %d -> %d\n", var, oldloc, newloc);
        // [oldloc+1 .. newloc]
        for (int i=at; i<var; ++i) {
            bor[i] = bor[i+1];
            --bloc[ bor[i] ]; ++ans;
            --bg[ bor[i] ];
        }
        bor[var] = var;
        bloc[var] = var;
        bg[var] = newloc;

        rep(i,N) {
            if (oldloc < wg[i] && wg[i] <= newloc) {
                --wg[i]; ++ans;
            }
        }
        //cerr << wor << wloc << endl;
    }
#ifdef DEBUG
    cerr << wor << wloc << endl;
    cerr << bor << bloc << endl;
#endif

    return ans;
}

