int max_certifice_white = 0, max_certifice_black = 0; 
void fill_new_index(char color, int color_index, int place, vector<pair<char, int>> &table, vector<int> &new_index, int &count){
	int actions = 0;
	for(int i = place + 1; i < table.size(); ++i){
		if(new_index.at(i) > 0) continue;
		if(table.at(i).first == color && table.at(i).second < color_index){
			if(color == 'W') new_index.at(i) = count + table.at(i).second - max_certifice_white - 1;
			else new_index.at(i) = count + table.at(i).second - max_certifice_black - 1;
			++actions;
		}
	}
	count += actions;
}

