    }
    for(int i=1;i<=n;i++){
        for(int j=i-1;j>0;j--){
            dp[j]=min(dp[j]+l[i-j]-1-b[j].ask(l[i-j]),dp[j-1]+r[j]-1-b[j-1].ask(r[j]));
            b[j].add(1,l[i-j]);
        }
        dp[0]+=l[i]-1-b[0].ask(l[i]);
        b[0].add(1,l[i]);
        for(int j=i;j<=n;j++){
            dp[j]+=r[i]-1-b[j].ask(r[i]);
            b[j].add(1,r[i]);
        }
    }
    for(int i=n+1;i<=tot;i++){
        for(int j=n;j>=i-n;j--){
            dp[j]=min(dp[j]+l[i-j]-1-b[j].ask(l[i-j]),dp[j-1]+r[j]-1-b[j-1].ask(r[j]));
