int calc(const vector<int>& A, const vector<string>& C, int j, int k, int p){
  if(p<0 || 4005<=p || j<0 || k<0 || 2005<=j || 2005<=k) return 0;
  return cntW[j][p] + cntB[k][p];
}

int main(){
  int N;
  cin >> N;
  vector<string> C;
  vector<int> A;
  map<pair<string,int>,int> pos;
  rep(i,2*N){
    string c;
    int a;
    cin >> c >> a;
    C.push_back(c);
    A.push_back(a);
    pos[make_pair(c,a)] = i+1;

    if(c=="W"){
      cntW[a][i] = 1;
    }else{
      cntB[a][i] = 1;
    }
  }

  rep(i,4005){
    int cW = 0;
    int cB = 0;
    rep(j,2005){
      dp[i][j] = INF;
      if(cntW[j][i] == 1) cW++;
      if(cntB[j][i] == 1) cB++;
      cntW[j][i] = cW;
      cntB[j][i] = cB;
    }
  }

  rep(i,2005){
    int cW = 0;
    int cB = 0;
    rep(j,4005){
      if(cntW[i][j] > 0) cW++;
      if(cntB[i][j] > 0) cB++;
      cntW[i][j] = cW;
      cntB[i][j] = cB;
    }
  }

  dp[0][0] = 0;
  rep(i,2*N){
    rep(j,i+1){
      if(dp[i][j] == INF) continue;
      int k = i-j;
      if(k < 0 || k > N) continue;

      {
        int p = pos[make_pair("W",j+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + p-add-1);
      }
      {
        int p = pos[make_pair("B",k+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j] = min(dp[i+1][j], dp[i][j] + p-add-1);
      }
    }
  }

  cout << dp[2*N][N] << endl;

  return 0;
}

