#define rep(i,i0,n) for (int (i) = (i0); (i) < (n); ++(i))

using namespace std;
using ll = long long;

const int MAX_N = 4000;

class Bit {
public:
    Bit(int n);
    int sum(int i);
    void add(int i, int x);
private:
    int dat[MAX_N];
    int size;
};

Bit::Bit(int n) {
    size = n;
}

int Bit::sum(int i) {
    int s = 0;
    --i;
    while (0 <= i) {
        s += dat[i];
        i = (i & (i + 1)) - 1;
    }
    return s;
}

void Bit::add(int i, int x) {
    while (i < size) {
        dat[i] += x;
        i |= i + 1;
    }
}

unsigned short length_h[2020*2020];
unsigned short length_v[2020*2020];
int dist[2020*2020];
int w[2020];
int b[2020];

int solve(int n, int *w, int *b, Bit &bit_w, Bit &bit_b) {
    fill(length_h, length_h + 2020*2020, 0);
    fill(length_v, length_v + 2020*2020, 0);

    rep (y, 0, n) {
        rep (x, 0, n) {
            length_h[y*(n+1) + x] = bit_b.sum(w[x]);
        }
        bit_b.add(b[y], -1);
    }

    rep (x, 0, n) {
        rep (y, 0, n) {
            length_v[y*(n+1) + x] = bit_w.sum(b[y]);
        }
        bit_w.add(w[x], -1);
    }

    priority_queue< tuple<int, int, int> > pq;
    int d, x, y, alt;

    fill(dist, dist + 2020*2020, INT_MAX);
    dist[0] = 0;
    pq.push(make_tuple(0, 0, 0));

    while (!pq.empty()) {
        tie(d, x, y) = pq.top();
        pq.pop();
        d = -d;
        if (x < n) {
            alt = dist[y*(n+1) + x] + length_h[y*(n+1) + x];
            if (alt < dist[y*(n+1) + x + 1]) {
                dist[y*(n+1) + x + 1] = alt;
                pq.push(make_tuple(-alt, x + 1, y));
            }
        }
        if (y < n) {
            alt = dist[y*(n+1) + x] + length_v[y*(n+1) + x];
            if (alt < dist[(y + 1)*(n+1) + x]) {
                dist[(y + 1)*(n+1) + x] = alt;
                pq.push(make_tuple(-alt, x, y + 1));
            }
        }
    }

    int ans = dist[n*(n+1) + n];

    rep (i, 0, n) {
        rep (j, i + 1, n) {
            if (w[j] < w[i]) {
                ++ans;
            }
            if (b[j] < b[i]) {
                ++ans;
            }
        }
    }

    return ans;
}


int main(int argc, const char * argv[]) {
    Bit bit_w(4000), bit_b(4000);
    int n;
    string c;
    int a;

    cin >> n;
    rep (i, 0, 2 * n) {
        cin >> c >> a;
        --a;
        if (c[0] == 'W') {
            w[a] = i;
            bit_w.add(i, 1);
        } else {
            b[a] = i;
            bit_b.add(i, 1);
        }
    }

    cout << (solve(n, w, b, bit_w, bit_b)) << endl;

    return 0;
}

