// 1 base
template<typename T, int max_n>
class BIT {
private:
    T bit[max_n + 1];
    int n;
public:
    BIT(int _n = max_n) {
        n = _n;
        memset(bit, 0, sizeof(bit));
    }
    // [1, i]
    T sum(int i) {
        T s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }
    // [a, b]
    T sum(int a, int b) {
        return sum(b) - sum(a-1);
    }

    void add(int i, T x) {
        while (i <= n) {
            bit[i] += x;
            i += i & -i;
        }
    }

    int lower_bound(T x) {
        int lb = 0, ub = n;
        while (ub - lb > 1) {
            int mid = (ub + lb) / 2;
            T v = sum(mid);
            if (v < x) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return ub;
    }

    int upper_bound(T x) {
        int lb = 1, ub = n+1;
        while (ub - lb > 1) {
            int mid = (ub + lb) / 2;
            T v = sum(mid);
            if (v <= x) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return ub;
    }
};

int solve() {
    BIT<int, 4010> bit(2*n+10);
    int s0 = 1, s1 = 1;
    int p[2][n+1];
    for (int i = 0; i < 2*n; i++) {
        if (c[i] == 'B') {
            p[0][a[i]] = i+1;
        } else {
            p[1][a[i]] = i+1;
        }
    }

    int res = 0;
    while (s0 <= n || s1 <= n) {
        int v0 = (s0 <= n ? p[0][s0]-bit.sum(p[0][s0])-1 : inf);
        int v1 = (s1 <= n ? p[1][s1]-bit.sum(p[1][s1])-1 : inf);
        if (v0 < v1) {
            res += v0;
            bit.add(p[0][s0], 1);
            s0++;
        } else {
            res += v1;
            bit.add(p[1][s1], 1);
            s1++;
        }
    }
    return res;
}

