  int n;
  cin>>n;
  vector<int>a(2*n);
  string s;
  adj.resize(n+1);
  adj2.resize(n+1);
  for(int i=0;i<2*n;i++){
    char z;
    cin>>z;
    s+=z;
    cin>>a[i];
    if(z=='B'){
      adj[a[i]]=i;
    }
    else{
      adj2[a[i]]=i;
    }
  }
  debug("A");
  for(int j=0;j<=n;j++){
    st[j].t.resize(8*n);
    dp[0][j]=dp[1][j]=1e9;
    for(int i=0;i<2*n;i++){
      st[j].update(1,0,2*n-1,i,1); 
    }
    for(int i=1;i<=j;i++){
      st[j].update(1,0,2*n-1,adj[i],0);
    }
    debug(j);
  }
  debug("B");
  dp[0][0]=0;
  for(int i=0;i<2*n;i++){
    debug(i);
    for(int j=0;j<=min(n-1,i);j++){
      int gt=st[j].query(1,0,2*n-1,0,adj[j+1]);
      dp[1][j+1]=min(dp[1][j+1],dp[0][j]+gt-1);
    }
    for(int j=0;j<=n;j++){
      if(i-j<0){
	break;
      }
      if(i-j>=n){
	continue;
      }
      int gt=st[j].query(1,0,2*n-1,0,adj2[i-j+1]);
      dp[1][j]=min(dp[1][j],dp[0][j]+gt-1);
    }
    for(int j=0;j<=n;j++){
      dp[0][j]=dp[1][j];
      dp[1][j]=1e9;
    }
    for(int j=0;j<=min(n,i+1);j++){
      if(i-j+1<=n&&i-j+1>0){
	st[j].update(1,0,2*n-1,adj2[i-j+1],0);
      }
    }
  }
  cout<<dp[0][n];
}

