struct BIT {
    int N;
    vector<int> bit;
    BIT(int n) : N(n) , bit(N + 1, 0) {}

    void add(int a, int w) {
        for(int x = a; x <= N; x += x & -x) bit[x] += w;
    }
    int sum(int a) {
        int ret = 0;
        for(int x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }
};
int getTentou(vector<int> &A) {
    BIT bit(A.size());
    int ret = 0;
    for (int i = 0; i < A.size(); i++) {
        ret += i - bit.sum(A[i]);
        bit.add(A[i], 1);
    }
    return ret;
}

