template<class T> struct SegmentTree{
	using F = function<T(T, T)>;
	vector<T> dat; //第i要素 dat[i+n-1]
	ll n; //要素数以上の最小の 2のべき乗
	F f;
	T ti;
	SegmentTree(){}
	SegmentTree(vector<T> &v, F f, T ti){ Init(v, f, ti); }
	void Init(vector<T> &v, F f, T ti){
		this->f=f; this->ti=ti;
		for (n = 1; n < (ll)v.size(); n *= 2);
		dat.resize(2*n-1, ti);
		REP(i, (ll)v.size()) { dat[i+n-1] = v[i]; }//初期化
		DEP(i, n-1) { dat[i] = f(dat[2*i+1], dat[2*i+2]); }//構築
	}
	void Set(ll i, T x){ //第i要素にxをセット
		i += n-1;  dat[i] = x;
		while (i>0) { i=(i-1)/2; dat[i]=f(dat[2*i+1], dat[2*i+2]); }
	}
	T Range(ll a, ll b) { return range(a, b, 0, 0, n); }
	T operator [] (ll i) { return dat[i+n-1]; }
	void Dump(ll w=5){
		REP(i, n) for (ll k=i+n-1, m=1, p=1; k>=0; p=m, m*=k%2, k=(k==0)?-1:(k-1)/2){
			if (m) cerr << ((k<n-1)?" ┬ ":"") << setw(w) << dat[k];
			else   cerr << ((p&~m) ?" ┘ ":"");
			if (k==0) cerr << '\n';
		} cerr << '\n';
	}
	T range(ll a, ll b, ll k, ll l, ll r){ //注目ノードk=[l,r)
		if (r<=a || b<=l) return ti; //完全に外
		if (a<=l && r<=b) return dat[k];//完全に含まれる
		return f(range(a, b, k*2+1, l, (l+r)/2), range(a, b, k*2+2, (l+r)/2, r));
	}
};


//自分より大きいものが既に何個出てきたか、を加算
ll tento(vll &vec){
	ll N = (ll)vec.size();
	vll ini(N);
	SegmentTree<ll> sgt(
		ini,
		[](ll x, ll y){return x+y; }, //データ同士の合成関数
		0 //単位元
	);

	ll sum=0;
	EACH(e, vec){
		sum += sgt.Range(e, N);
		sgt.Set(e, 1);
	}
	return sum;
}

void solve()
{
	ll N;  cin >> N;
	auto ca = cinv2<char,ll>(2*N);
	EACH(e, ca) e.second--;

	vll bpos(N);
	vll wpos(N);
	REP(i, 2*N){
		char c; ll a; tie(c, a) = ca[i];
		if (c=='B') bpos[a] = i;
		else        wpos[a] = i;
	}

	//黒/白の転倒数を求める
	vll blacks, whites;
	EACH(e, ca){
		if (e.first == 'B') blacks.push_back(e.second);
		else                whites.push_back(e.second);
	}
	ll bten = tento(blacks);
	ll wten = tento(whites);

	//白黒間転倒数を求める
	vvll dp(N+1, vll(N+1));
	vll bbits(2*N);
	REPS(b, 1, N){
		ll p = bpos[b-1];

		//全wに対し、b-1→bへの遷移の計算
		ll t=0;
		REPS(w, 1, N){
			ll pp = wpos[w-1];
			if (p < pp) t++;

			dp[b][w] = dp[b-1][w] + t;
		}
		//dp[b]に対し、w-1→wへの遷移の計算
		bbits[p] = 1;
		vll cum(2*N);
		cum[2*N-1] = bbits[2*N-1];
		DEPS(i, 0, 2*N-2){
			cum[i] = cum[i+1] + bbits[i];
		}

		REPS(w, 1, N){
			ll pp = wpos[w-1];
			chmin(dp[b][w], dp[b][w-1] + cum[pp]);
		}
	}
	ll ans = bten+wten+dp[N][N];
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

