#include <bits/stdc++.h>

using namespace std;

const int N = 4 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
int a[N], c[N];
int pos[2][N];
int cnt[N][2][N];
int dp[N][N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 1; i <= n + n; ++i) {
        char ch;
        cin >> ch >> a[i];
        c[i] = ch == 'W' ? 0 : 1;
    }

    return true;
}

void solve() {
    for (int i = 1; i <= n + n; ++i) {
        pos[c[i]][a[i]] = i;

        for (int j = 1; j < i; ++j)
            ++cnt[i][c[j]][a[j]];

        for (int j = n; j >= 0; --j)
            for (int k = 0; k < 2; ++k)
                cnt[i][k][j] += cnt[i][k][j + 1];
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= n; ++j)
            dp[i][j] = MOD;

    dp[0][0] = 0;

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= n; ++j) {
            if (i + 1 <= n) {
                auto k = pos[0][i + 1];
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + cnt[k][0][i + 1] + cnt[k][1][j + 1]);
            }

            if (j + 1 <= n) {
                auto k = pos[1][j + 1];
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + cnt[k][0][i + 1] + cnt[k][1][j + 1]);
            }
        }

    cout << dp[n][n] << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

