    rep(i,n+1){
        rep(j,n+1){
            if(i<n)s0[i][j]=seg.query(0,id[P(i,0)]);
            if(j<n)s1[i][j]=seg.query(0,id[P(j,1)]);
            if(j<n)seg.update(id[P(j,1)],0);
        }
