class Solve {
private:
	auto get_cost(const vector<pair<int, char>>& p, const vector<int>& ib) {
		const int n = (int)ib.size();
		vector<vector<int>> rst(n, vector<int>(n + 1, 0));

		const char c = p[ib.front()].second;
		for (int i = 0; i < n; i++) {
			auto& b = rst[i];
			int cntb = 0;
			unordered_set<int> sw;
			for (int j = 0; j < ib[i]; j++) {
				if (p[j].second != c) {
					sw.insert(p[j].first);
				}
				else if (p[j].first > i) {
					cntb++;
				}
			}

			for (int j = 0; j <= n; j++) {
				b[j] = cntb + sw.size();
				sw.erase(j);
			}
		}
		return rst;
	}

	void solve() {
		int n;
		cin >> n;

		vector<pair<int, char>> p(2 * n);
		vector<int> ib(n);
		vector<int> iw(n);

		for (int i = 0; i < n * 2; i++) {
			cin >> p[i].second >> p[i].first;
			p[i].first--;
			if (p[i].second == 'W') iw[p[i].first] = i;
			else ib[p[i].first] = i;
		}

		auto cb = get_cost(p, ib);
		auto cw = get_cost(p, iw);

		//dp[i][j]: i bs and j ws
		vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));

		dp[0][0] = 0;
		for (int j = 1; j <= n; j++) dp[0][j] = dp[0][j - 1] + cw[j - 1][0];
		for (int i = 1; i <= n; i++) {
			dp[i][0] = dp[i - 1][0] + cb[i - 1][0];
			for (int j = 1; j <= n; j++) {
				dp[i][j] = min(dp[i][j - 1] + cw[j - 1][i], dp[i - 1][j] + cb[i - 1][j]);
			}
		}

		int cnt = dp[n][n];

		cout << cnt << endl;
	}

public:
	Solve() { solve(); }
};

int main(int argc, char* argv[]) {
	unique_ptr<Solve> solve = make_unique<Solve>();
	return 0;
}

