int Cost(char c, int i, int j) {
  if (c == 'W') {
    int ni = h[make_pair(c,i)];
    if (i != 0) { i -= cntw[ni][i-1]; }
    if (j != 0) { j -= cntb[ni][j-1]; }
    return i+j;
  } else {
    int ni = h[make_pair(c,j)];
    if (i != 0) { i -= cntw[ni][i-1]; }
    if (j != 0) { j -= cntb[ni][j-1]; }
    return i+j;
  }
}

signed main() {
