    h[p] = i;
  }

  REP(j, N) {
    cntw[0][j] = 0;
    cntb[0][j] = 0;
  }
  REP(i, 2*N) {
    REP(j, N) {
      cntw[i+1][j] = cntw[i][j];
      if (ca[i].first == 'W' && ca[i].second <= j) { cntw[i+1][j]++; }
