      if (i == 0) {
        dp[i][j] = dp[i][j-1] + Cost('B', i, j-1);
      } else if (j == 0) {
        dp[i][j] = dp[i-1][j] + Cost('W', i-1, j);
      } else {
        dp[i][j] = MIN(
          dp[i][j-1] + Cost('B', i, j-1),
          dp[i-1][j] + Cost('W', i-1, j));
      }
    }
  }
  ans = dp[N][N];

  cout << ans << endl;
  return 0;
}

