ll dp[2005][2005]={0};
int bidx[2005]={0},widx[2005]={0};
int bsum[2005]={0},wsum[2005]={0};
int n;
ll dynamic(int bl,int wt){
  if(bl<0||wt<0) return inf;
  if(dp[bl][wt]<inf) return dp[bl][wt];
  if(bl==0&&wt==0) return 0;
  ll lb=dynamic(bl-1,wt);
  lb+=max(0,wsum[bidx[bl]]-wt);
  ll rb=dynamic(bl,wt-1);
  rb+=max(0,bsum[widx[wt]]-bl);
  return dp[bl][wt]=min(lb,rb);
}
int bubblesort(vector<int> v){
  int ret=0;
  for(int i=0;i<n;i++){
    for(int j=n-1;j>i;j--){
      if(v[j]<v[j-1]){
        int r=v[j];
        v[j]=v[j-1];
        v[j-1]=r;
        ret++;
      }
    }
  }
  return ret;
}
