		for (int j = 1; j < 2 * n; j++) {
			T2[i][j] = T2[i][j - 1] + A2[j];
		}
		A2[W[i]] = 1;
	}
	C2[0] = A2[0];
	for (int i = 1; i < 2 * n; i++)
		C2[i] = C2[i - 1] + A2[i];
	for (int i = 1; i <= n; i++) {
		dp[i][0] = dp[i - 1][0] + T1[i - 1][B[i - 1]] + C2[B[i - 1]];
	}
	for (int j = 1; j <= n; j++) {
		dp[0][j] = dp[0][j - 1] + T2[j - 1][W[j - 1]] + C1[W[j - 1]];
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			dp[i][j] = min(dp[i - 1][j] + T1[i - 1][B[i - 1]] + T2[j - 1][B[i - 1]], dp[i][j - 1] + T2[j - 1][W[j - 1]] + T1[i - 1][W[j - 1]]);
//			cout << i << ' ' << j << ' ' << dp[i][j] << endl;
		}
	}
	cout << dp[n][n];
}

