int costB[maxn][maxn];
int costW[maxn][maxn];
int N;

int v[maxn];

void init()
{
	int vsize = 0;
	for(int i=0; i<2*N; i++)
	{
		if(a[i].color=='B') {
			int j=0;
			int k=0;
			int cnt=0;
			for(int j=0; j<i; j++) if(a[j].color=='B' && a[j].id>a[i].id) cnt++;
			while(k<vsize) {
				while(v[k]>j)
				{
					costB[a[i].id][j]=vsize-k+cnt;
					j++;
				}
				k++;
			}
			while(j<=N)
			{
				costB[a[i].id][j] = cnt;
				j++;
			}
			cnt++;
		}
		else {
			// insert sort
			v[vsize++] = a[i].id;
			int j = vsize-1;
			while(j>0 && v[j-1]>v[j] )
			{
				swap(v[j-1], v[j]);
				j--;
			}
		}
	}

	// change to w
	vsize = 0;
	for(int i=0; i<2*N; i++)
	{
		if(a[i].color=='W') {
			int j=0;
			int k=0;
			int cnt=0;
			for(int j=0; j<i; j++) if(a[j].color=='W' && a[j].id>a[i].id) cnt++;
			while(k<vsize) {
				while(j<v[k]) {
					costW[j][a[i].id]=vsize-k+cnt;
					j++;
				}
				k++;
			}
			while(j<=N) {
				costW[j][a[i].id] = cnt;
				j++;
			}
			cnt++;
		}
		else {
			v[vsize++] = a[i].id;
			int j = vsize-1;
			while(j>0 && v[j-1]>v[j]) {
				swap(v[j], v[j-1]);
				j--;
			}
		}
	}
}

int main()
{
	cin>>N;
	for(int i=0; i<2*N; i++) cin>>a[i].color>>a[i].id;
	memset(costB,0,sizeof(costB));
	memset(costW,0,sizeof(costW));
	memset(F,0,sizeof(F));
	init();
	for(int i=1; i<=N; i++)
		F[i][0] = costB[i][0] + F[i-1][0];
	for(int i=1; i<=N; i++)
		F[0][i] = costW[0][i] + F[0][i-1];

	for(int i=1; i<=N; i++)
		for(int j=1; j<=N; j++)
		{
			F[i][j] = min(F[i-1][j]+costB[i][j], F[i][j-1]+costW[i][j]);
		}
	cout<<F[N][N]<<endl;
	return 0;
}

