	reps (j, n)
	{
		dp[j][0]=dp[j-1][0];
		reps(i, n) if(b[i]<w[j]) dp[j][0]++;
		wb[0][j]=dp[j][0]-dp[j-1][0];
	}

	reps(i, n) reps(j, n)
	{
		wb[i][j]=wb[i-1][j];
		if(b[i]<w[j]) wb[i][j]--;
	}

	reps(j, n)
	{
		dp[0][j]=dp[0][j-1];
		reps(i, n) if(w[i]<b[j]) dp[0][j]++;
		bw[0][j]=dp[0][j]-dp[0][j-1];
	}

	reps(i, n) reps(j, n)
	{
		bw[i][j]=bw[i-1][j];
		if(w[i]<b[j]) bw[i][j]--;
	}

	reps(i, n) reps(j, n)
	{
		dp[i][j]=min(dp[i-1][j]+wb[j][i], dp[i][j-1]+bw[i][j]);
		//cout << tw << tb << ' ' << dp[i][j] << ' ';
	}
