        rep(j,i+1){
            if(i-j<n)
            chmax(dp[i+1][j],dp[i][j]+bit[j].sum(w[i-j]));
            if(j<n)
            chmax(dp[i+1][j+1],dp[i][j]+bit[j].sum(b[j]));
        }
        rep(j,i+1){
            if(i-j<n)
            bit[j].add(w[i-j],1);
        }
        rep(j,i+1){
            if(j<n)
            bit[i+1].add(b[j],1);
        }
    }
    ll ans=n*(n*2-1);
    cout<<ans-dp[n*2][n]<<endl;
