const int INF = 1e9;
template <class T> T Next() { T buf; cin >> buf; return buf; }

int n;
PP p[4000];
int DP[2001][2001];
int s[4001][2001];
int t[4001][2001];
int inv[2][2000];

int main() {
  cin >> n;
  for (int i = 0; i < 2 * n; ++i) {
    int a = Next<char>() == 'B';
    int b = Next<int>() - 1;
    p[i] = PP(a, b);
    inv[a][b] = i;
  }

  for (int i = 0; i < 2 * n; ++i) {
    for (int j = 0; j <= n; ++j) {
      bool a = p[i].first == 0 && p[i].second >= j;
      bool b = p[i].first == 1 && p[i].second >= j;
      s[i + 1][j] = s[i][j] + a;
      t[i + 1][j] = t[i][j] + b;
    }
  }

  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= n; ++j) {
      DP[i][j] = INF;
    }
  }
  DP[0][0] = 0;

  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= n; ++j) {
      if (i < n) {
        int k = inv[0][i];
        DP[i + 1][j] = min(DP[i + 1][j], DP[i][j] + s[k][i] + t[k][j]);
      }

      if (j < n) {
        int l = inv[1][j];
        DP[i][j + 1] = min(DP[i][j + 1], DP[i][j] + s[l][i] + t[l][j]);
      }
    }
  }

  cout << DP[n][n] << endl;
  return 0;
}

