template<typename T> class Monoid{
public:
	virtual T e()=0,c(T,T)=0;
};

template<typename T> class MaxMonoid:public Monoid<T>{
public:
	T e(){return -INF<T>();}
	T c(T a,T b){return max(a,b);}
	static MaxMonoid<T>& i(){static MaxMonoid<T> i;return i;}
};

template<class T> class SparseTable{
public:
	vector<vector<T>> dbl;Monoid<T>& m;
	SparseTable(const vector<T>& as,Monoid<T>& m):dbl(msb(as.size())+1,vector<T>(as.size())),m(m){
		copy(ALL(as),dbl[0].begin());
		for(int l:range(1,dbl.size()))
			for(int i:range(dbl[l].size()))
				dbl[l][i]=m.c(dbl[l-1][i],dbl[l-1][i+(1<<(l-1))]);
	}
	inline T get(int v){return dbl[0][v];}
	T query(int a,int b){ //[a,b)
		if(a > b) assert(false);
		if(a == b) return m.e();
		int l=msb(b-a);
		return m.c(dbl[l][a],dbl[l][b-(1<<l)]);
	}
};

template <typename T,typename Func> T satisfy_mini(Func P,T l ,T r){//(l |sep| r)
	l -= EPS<T>();
	while(r-l>EPS<T>()){
		T m=(l+r)/2;
		(P(m)?r:l)=m;
	}
	return r;
}

template<typename T> struct Fenwick{
// public:
	int size;
	vector<T> dat;

	inline T e(){ return 0;}
	inline T c(T x,T y){return x+y;}
	inline T inv(T x){return -x;}
	Fenwick(int n):size(n){
		dat = vector<T>(n+1);
	}
	Fenwick():size(0){
		dat = vector<T>(1);

	}
	T query(int n){// [0,n)
		T s= e();
		while(n>0){
			s = c(s,dat[n]);
			n -= n&-n;//low
		}
		return s;
	}
	void add(int i,T x){//[0,...i...,n)
		i++;
		while(i<=size){
			dat[i] = c(dat[i],x);
			i += i&-i;//next
		}
	}
	T query(int a,int b){// [a,b)
		return c(query(b),inv(query(a)));
	}

	T lower_bound(T a){//minarg [0,n) <= a
		T sum = 0;
		int i = 0, b = msb(size + 1);
		while(b >= 0){
			if(i + (1 << b) < size + 1 && sum + dat[i + (1 << b)] < a){
				sum += dat[i + (1 << b)];
				i += 1 << b;
			}
			b--;
		}
		return i + 1;
	}
};


class Main{
	public:

	void run(){
		int N;cin >> N;
		vector<char> cs(2*N);
		vector<int> nums(2*N);
		vector<vector<int>> pos(2,vector<int>(N));
		for(int i:range(2*N)){
			cin >> cs[i] >> nums[i];nums[i]--;
			pos[cs[i]=='B'][nums[i]] = i;
		}

		// cerr << pos << endl;

		vector<vector<ll>> dp(N+1,vector<ll>(N+1,INF<ll>()));
		dp[0][0] = 0;

		Fenwick<int> fen(2*N);
		for(int bc:range(N+1)){
			if(IN(0,bc-1,N)) fen.add(pos[1][bc-1],1);
			for(int wc:range(N+1)){
				if(IN(0,wc-1,N)) fen.add(pos[0][wc-1],1);
				if(bc < N){
					dp[bc+1][wc] = min(dp[bc+1][wc], dp[bc][wc] + pos[1][bc] - fen.query(0,pos[1][bc]));
				}
				if(wc < N){
					dp[bc][wc+1] = min(dp[bc][wc+1], dp[bc][wc] + pos[0][wc] - fen.query(0,pos[0][wc]));
				}
			}
			for(int wc:range(N)) fen.add(pos[0][wc],-1);
		}

		cout << dp[N][N] << endl;
	}
};

int main(){
	cout <<fixed<<setprecision(20);
	cin.tie(0);
	ios::sync_with_stdio(false);
	Main().run();
	return 0;
}

