struct data {
	int type, val;
	data(int _type = 0, int _val = 0): type(_type), val(_val) {};
};

int n;
data a[N];
int where[2005][2];
int cntAft[4005][2005][2];
int dp[2005][2005];

int cal(int cnt0, int cnt1) {
	int &ret = dp[cnt0][cnt1];
	if (ret != -1) return ret;
	ret = 1e9;
	if (cnt0 == n && cnt1 == n) {
		ret = 0;
		return ret;
	}
	if (cnt0 != n) {
		int preP = where[cnt0 + 1][0];
		int nowP = preP + cntAft[preP][cnt0][0] + cntAft[preP][cnt1][1];
		ret = min(ret, cal(cnt0 + 1, cnt1) + nowP - preP);
	}
	if (cnt1 != n) {
		int preP = where[cnt1 + 1][1];
		int nowP = preP + cntAft[preP][cnt0][0] + cntAft[preP][cnt1][1];
		ret = min(ret, cal(cnt0, cnt1 + 1) + nowP - preP);
	}
	return ret;
}

void prep() {
