int maxw[2010], maxb[2010];

struct Ball {
	char color;
	int num;
	Ball(char color, int num) {
		this->color = color;
		this->num = num;
	}
};

int N;
int solve(vector<Ball> balls) {
	memset(maxw, 0, sizeof maxw);
	memset(maxb, 0, sizeof maxb);

	rep(i, 2 * N) {
		if (balls[i].color == 'W') {
			maxw[i] = balls[i].num;
		} else {
			maxb[i] = balls[i].num;
		}
		if (i > 0) {
			maxw[i] = max(maxw[i], maxw[i - 1]);
			maxb[i] = max(maxb[i], maxb[i - 1]);
		}
	}

	int ret = 0;
	rep(i, 2 * N) {
		Ball ball = balls[i];
		int pt = i;
		if (ball.color == 'W') {
			while (maxw[pt] > ball.num) {
				if (pt <= 0) throw "okashii!!";
				if (balls[pt - 1].color == 'W') {
					if (balls[pt - 1].num == maxw[pt - 1]) {
						if (pt > 1) maxw[pt - 1] = maxw[pt - 2];
						else maxw[pt - 1] = 0;
						maxw[pt - 1] = max(maxw[pt - 1], balls[pt].num);
					}
				} else {
					if (balls[pt - 1].num == maxb[pt - 1]) {
						if (pt > 1) maxb[pt - 1] = maxb[pt - 2];
						else maxb[pt - 1] = 0;
					}
				}

				swap(balls[pt], balls[pt - 1]);
				pt--;
				ret++;
			}
		} else {
			while (maxb[pt] > ball.num) {
				if (pt <= 0) throw "okashii!!";
				if (balls[pt - 1].color == 'W') {
					if (balls[pt - 1].num == maxw[pt - 1]) {
						if (pt > 1) maxw[pt - 1] = maxw[pt - 2];
						else maxw[pt - 1] = 0;
					}
				} else {
					if (balls[pt - 1].num == maxb[pt - 1]) {
						if (pt > 1) maxb[pt - 1] = maxb[pt - 2];
						else maxb[pt - 1] = 0;
						maxb[pt - 1] = max(maxb[pt - 1], balls[pt].num);
					}
				}

				swap(balls[pt], balls[pt - 1]);
				pt--;
				ret++;
			}
		}
	}

	return ret;
}

