typedef long long ll;

const int INF = 1<<29;

const int MAX_N = 5020;

int p[MAX_N];
int c[MAX_N];

int smallerOrEq[MAX_N][MAX_N][2];
int indexOf[MAX_N][2];

int dp[MAX_N][MAX_N];

int getIndex(int val, int c, int white, int black) {
    int idx = indexOf[val][c];
    int res = idx;
    res += smallerOrEq[idx][white][0];
    res += smallerOrEq[idx][black][1];
    return res;
}

int getRes(int white, int black, int n) {
    if(white + black == 2 * n) {
        return 0;
    }
    if(dp[white][black] != -1) {
        return dp[white][black];
    }

    int res = INF;

    //cout<<"State\tw: "<<white<<"\tb: "<<black<<endl;

    if(white < n) {
        int idx = getIndex(white+1, 0, white, black);
        int cost = idx - (white+black+1);
        //cout<<"w idx: "<<idx<<endl;
        res = min(res, getRes(white+1, black, n) + cost);
    }

    if(black < n) {
        int idx = getIndex(black+1, 1, white, black);
        int cost = idx - (white+black+1);
        //cout<<"b idx: "<<idx<<endl;
        res = min(res, getRes(white, black+1, n) + cost);
    }

    return dp[white][black] = res;
}

int main() {
    ios::sync_with_stdio(false);

    int n;
