        indexOf[p[i]][c[i]] = i;
    }

    for(int i = 2*n;i >= 1;--i) {
        for(int j = n;j>=1;--j) {
            for(int k = 0;k<2;++k) {
                smallerOrEq[i][j][k] = 0;

                if(i+1 <= 2*n) {
                    smallerOrEq[i][j][k] += smallerOrEq[i+1][j][k];

                    if(p[i+1] <= j && c[i+1] == k) {
                        smallerOrEq[i][j][k]++;
                    }
                }
            }
        }
    }

    for(int i = 0;i<MAX_N;++i) {
        for(int j = 0;j<MAX_N;++j) {
            dp[i][j] = -1;
        }
    }

    int res = getRes(0, 0, n);

    cout<<res<<endl;

    return 0;
}

