// 1-indexed であることに注意
template<typename T>
class BITree {
    public:
        BITree(int n) : m_N(n + 1) { m_Tree.assign(m_N, 0); }
        // [1, i] の合計値を返す (log m_N)
        // 閉区間であることに注意
        T Sum(int i) {
            if(i < 1 || i >= m_N) { return 0; }
            T s = 0;
            while(i > 0) { s += m_Tree[i]; i -= i & -i; }
            return s;
        }
        // [i, j] の合計値を返す (log m_N)
        // i < j
        // 閉区間であることに注意
        T Sum(int i, int j) {
            if(i > j) { return 0; }
            return Sum(j) - Sum(i-1);
        }
        // i 番目の要素(1-indexed)に x を足して更新 O(log m_N)
        void Add(int i, T x){ while(i < m_N) { m_Tree[i] += x; i += i & -i; } }
    private:
        int m_N;            // 要素数
        vector<T> m_Tree;   // BIT 本体
};

// 順列 p の転倒数を返す (転倒数：順番を維持したままペアをとったとき、左の数字の方が大きいペアの数)
// O (N log N) (N: 順列の最大値)
template<typename T>
T GetInversionCnt(const vector<T>& p) {
    T ret = 0;
    T max_val = 0;
    for(auto& val : p) { max_val = max(max_val, val); }
    BITree<T> bit(max_val);    // 以左に現れた数を BIT で管理
    for(int i = 0; i < p.size(); ++i) {
        ret += bit.Sum(p[i] + 1, max_val);  // 自分より大きいものを数える
        bit.Add(p[i], 1);   // 現れた数を更新
    }
    return ret;
}

// 2 つの順列の転倒距離を求める
// 転倒距離：同じサイズ N の順列 X と Y で順番が入れ替わっている数字のペアの数
// X か Y のどちらかが (1, 2, 3 .., N) なら、転倒距離はもう一方の転倒数
// O(N log N)
template<typename T>
T GetInversionDist(const vector<T>& v1, const vector<T>& v2) {
    assert(v1.size() == v2.size());
    vector<T> val_to_ind, comp;
    val_to_ind.assign(v1.size() + 1, 0);
    for(int i = 0; i < v1.size(); ++i) {
        val_to_ind[v1[i]] = i + 1;
    }
    for(int i = 0; i < v2.size(); ++i) {
        comp.push_back(val_to_ind[v2[i]]);
    }
    return GetInversionCnt(comp);
}

// b とかぶらない数にする
static inline ll change_w(ll w) { return w + N; }

enum CostType { CostB = 0, CostW };

// B を [1,i] , W を [1,j] 個既に置いているときに黒の i+1 を置いた時の転倒数
ll cost(ll i, ll j, ll type) {
    vector<ll> v1, v2;
    // [1,i], [1,j] の置き方は合わせる
    for(ll b = 1; b <= i; ++b) {
        v1.push_back(b);
        v2.push_back(b);
    }
    for(ll w = 1; w <= j; ++w) {
        v1.push_back(change_w(w));
        v2.push_back(change_w(w));
    }
    if(type == CostB) { v1.push_back(i+1); }
    else { v1.push_back(change_w(j+1)); }

    // 残りを置いていく
    REP(ind, 2 * N) {
        if(C[ind] == 'B') {
            if(type == CostB) {
                if(A[ind] == i + 1) { v2.push_back(A[ind]); }
                else if(A[ind] > i + 1) { v1.push_back(A[ind]); v2.push_back(A[ind]); }
            } else {
                if(A[ind] > i) { v1.push_back(A[ind]); v2.push_back(A[ind]); }
            }
        } else {
            if(type == CostB) {
                if(A[ind] > j) { v1.push_back(change_w(A[ind])); v2.push_back(change_w(A[ind])); }
            } else {
                if(A[ind] == j + 1) { v2.push_back(change_w(A[ind])); }
                else if(A[ind] > j + 1) { v1.push_back(change_w(A[ind])); v2.push_back(change_w(A[ind])); }
            }
        }
    }
    return GetInversionDist(v1, v2);
}

ll dp[MAX_N][MAX_N] = {};

// B を [1,i] 個, W を [1,j] 個置いた時の最小転倒数
ll dfs(ll i, ll j) {
    if(i <= 0 && j <= 0) {
        dp[0][0] = 0;
        return 0;
    }
    if(dp[i][j] != -1) { return dp[i][j]; }
    ll cand1 = INF, cand2 = INF;
    if(i > 0) { cand1 = dfs(i-1, j) + cost(i-1, j, CostB); }
    if(j > 0) { cand2 = dfs(i, j-1) + cost(i, j-1, CostW); }
    dp[i][j] = min(cand1, cand2);
    return dp[i][j];
}

