        costw[i][N] = costw[i][0];
        for (int j = N; j >= 1; j--) {
            if (pb[j] < pw[i + 1]) sum++;
            costw[i][j - 1] = costw[i][0] + sum;
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = i + 2; j <= N; j++)
            if (pb[j] < pb[i + 1]) costb[0][i]++;
        int sum = 0;
        costb[N][i] = costb[0][i];
        for (int j = N; j >= 1; j--) {
            if (pw[j] < pb[i + 1]) sum++;
            costb[j - 1][i] = costb[0][i] + sum;
        }
    }
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            if (!i && !j) continue;
            if (!i) dp[i][j] = dp[i][j - 1] + costb[0][j - 1];
            else if (!j) dp[i][j] = dp[i - 1][j] + costw[i - 1][0];
            else dp[i][j] = min(dp[i - 1][j] + costw[i - 1][j], dp[i][j - 1] + costb[i][j - 1]);
        }
    }
    printf("%d\n", dp[N][N]);
    return 0;
}

