int dp[2010][2010];

int choose(int white_back, int black_back){
    if(dp[white_back + 1][black_back + 1] != -1){
        return dp[white_back + 1][black_back + 1];
    }else if(white_back == N - 1 && black_back == N - 1){
        return dp[white_back + 1][black_back + 1] = 0;
    }else if(white_back == N - 1){
        return dp[white_back + 1][black_back + 1] = choose(white_back, black_back + 1) + nums_cumulative_sum_white[nums_position[black_back + N + 1]][white_back + 1] + nums_cumulative_sum_black[nums_position[black_back + N + 1]][black_back + 1];
    }else if(black_back == N - 1){
        return dp[white_back + 1][black_back + 1] = choose(white_back + 1, black_back) + nums_cumulative_sum_white[nums_position[white_back + 1]][white_back + 1] + nums_cumulative_sum_black[nums_position[white_back + 1]][black_back + 1];
    }else{
        return dp[white_back + 1][black_back + 1] = max(choose(white_back, black_back + 1) + nums_cumulative_sum_white[nums_position[black_back + N + 1]][white_back + 1] + nums_cumulative_sum_black[nums_position[black_back + N + 1]][black_back + 1],
                                                        choose(white_back + 1, black_back) + nums_cumulative_sum_white[nums_position[white_back + 1]][white_back + 1] + nums_cumulative_sum_black[nums_position[white_back + 1]][black_back + 1]);
    }
}

