using namespace std;
long long int N;

long long int solve(vector<pair<char, long long int>>ca){
	long long int w = 1, b = 1;
	long long int ans = 0;
	for( int i = 0; i < 2 * N; i++ ){
		if( ca[i].first == 'B'&&ca[i].second >= b ){
			long long int j = i;
			while( !( ca[j].first == 'B'&&ca[j].second == b ) ){
				j++;
				if( ca[j].first == 'W'&&ca[j].second < w ){
					continue;
				}
				if( ca[j].first == 'B'&&ca[j].second < b ){
					continue;
				}
				ans += 1;
			}
			b++;
			if( j - i ){
				i--;
				continue;
			}
		}
		if( ca[i].first == 'W'&&ca[i].second >= w ){
			long long int j = i;
			while( !( ca[j].first == 'W'&&ca[j].second == w ) ){
				j++;
				if( ca[j].first == 'W'&&ca[j].second < w ){
					continue;
				}
				if( ca[j].first == 'B'&&ca[j].second < b ){
					continue;
				}
				ans += 1;
			}
			w++;
			if( j - i ){
				i--;
				continue;
			}
		}
	}
	return ans;
}


int main(){
	cin >> N;
	vector<pair<char, long long int>>ca(2 * N);
	for( size_t i = 0; i < 2 * N; i++ ){
		cin >> ca[i].first >> ca[i].second;
	}
	long long int ans = solve(ca);
	reverse(ca.begin(), ca.end());
	for( size_t i = 0; i < 2 * N; i++ ){
		ca[i].second = N - ca[i].second + 1;
	}
	ans = min(ans, solve(ca));
	cout << ans << endl;
}

