//BIT<ijt> bit1(200020), bit2(200020);

ijt costb(ijt p, ijt q) {
	BIT<ijt> bit1(10000);
	for (int i = 1; i <= p; i++)
	{
		bit1.add(blue[i], 1);
	}
	for (int i = 1; i <= q; i++) {
		bit1.add(white[i], 1);
	}
	return p + q - bit1.sum(blue[p + 1]);
}
ijt costw(ijt p, ijt q) {
	BIT<ijt> bit2(10000);
	for (int i = 1; i <= p; i++)
	{
		bit2.add(blue[i], 1);
	}
	for (int i = 1; i <= q; i++)
	{
		bit2.add(white[i], 1);
	}
	return p + q - bit2.sum(white[q + 1]);
}
