using namespace std;

template<typename T>
struct BinaryIndexedTree {
    vector<T> data;

    BinaryIndexedTree(int sz) {
        data.assign(++sz, 0);
    }

    T sum(int k) {
        T ret = 0;
        for (++k; k > 0; k -= k & -k) ret += data[k];
        return (ret);
    }

    void add(int k, T x) {
        for (++k; k < data.size(); k += k & -k) data[k] += x;
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> white(n), black(n);
    for (int i = 0; i < 2 * n; i++) {
        char c;
        int a;
        cin >> c >> a;
        if (c == 'W')white[a - 1] = i;
        else black[a - 1] = i;
    }

    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 1145141919));
    dp[0][0] = 0;

    BinaryIndexedTree<int> onlyBlack(2 * n + 1);
    for (int alreadyBlack = 0; alreadyBlack <= n; alreadyBlack++) {
        BinaryIndexedTree<int> BIT = onlyBlack;
        for (int alreadyWhite = 0; alreadyWhite <= n; alreadyWhite++) {
            if (alreadyBlack < n) {
                int cost = dp[alreadyBlack][alreadyWhite] + (BIT.sum(2 * n) - BIT.sum(black[alreadyBlack]));
                dp[alreadyBlack + 1][alreadyWhite] = min(dp[alreadyBlack + 1][alreadyWhite], cost);
            }
            if (alreadyWhite < n) {
                int cost = dp[alreadyBlack][alreadyWhite] + (BIT.sum(2 * n) - BIT.sum(white[alreadyWhite]));
                dp[alreadyBlack][alreadyWhite + 1] = min(dp[alreadyBlack][alreadyWhite + 1], cost);
            }

            if (alreadyWhite < n)BIT.add(white[alreadyWhite], 1);
        }
        if (alreadyBlack < n)onlyBlack.add(black[alreadyBlack], 1);
    }

    cout << dp[n][n] << endl;
    return 0;
}

