int main(){
    cin >> N;
    for(i=0; i<2*N; i++){
        cin >> C[i] >> A[i];
        if(C[i] == 'B'){
            rev_b[A[i]] = i;
            before_b[i][A[i]] += 1;
        }else{
            rev_w[A[i]] = i;
            before_w[i][A[i]] += 1;
        }
    }
    for(i=0; i<2*N; i++){
        for(j=2; j<=N; j++){
            before_b[i][j] += before_b[i][j-1];
            before_w[i][j] += before_w[i][j-1];
        }
    }
    for(i=1; i<2*N; i++){
        for(j=1; j<=N; j++){
            before_b[i][j] += before_b[i-1][j];
            before_w[i][j] += before_w[i-1][j];
        }
    }
    int sum;
    for(sum=1; sum<=2*N; sum++){
        int lb = max(0, sum - N);
        int ub = min(sum, N);
        int b, w;
        for(b=lb; b<=ub; b++){
            w = sum - b;
            int cand = 1<<30;
            if(b>0){
                int pos = rev_b[b];
                int d = dp[b-1][w] + pos - before_b[pos][b-1] - before_w[pos][w];
                cand = min(cand, d);
            }
            if(w>0){
                int pos = rev_w[w];
                int d = dp[b][w-1] + pos - before_b[pos][b] - before_w[pos][w-1];
                cand = min(cand, d);
            }
            dp[b][w] = cand;
        }
    }
    cout << dp[N][N] << endl;
    return 0;
}

