    lint ww[n+1], wb[n+1][n+1], bw[n+1][n+1], bb[n+1];
    rep(i, n+1){
        rep(j, n+1) wb[i][j] = bw[i][j] = 0;
        ww[i] = bb[i] = 0;
    }
    rep(i, n*2){
