const int MAXN = 4e3 + 5;
char color[MAXN];
int val[MAXN];

int B[MAXN][MAXN];
int W[MAXN][MAXN];
int dp[MAXN][MAXN];
int N;

int tree[2][MAXN];

void Update(int pos, int val, int flag) {
    for(int i = pos; i <= N; i += i & -i) {
        tree[flag][i] += val;
    }
}

int Sum(int pos, int flag) {
    int sum = 0;
    for(int i = pos; i; i -= i & -i) {
        sum += tree[flag][i];
    }
    return sum;
}

int main() {
    while(~scanf("%d", &N)) {
        for(int i = 0; i < 2 * N; ++i) {
            char tmp[10];
            scanf("%s %d", tmp, &val[i]);
            color[i] = tmp[0];
        }

        for(int i = 0; i < 2 * N; ++i) {
            if(color[i] == 'B') {
                Update(val[i], 1, 0);
                for(int j = 0; j <= N; ++j) {
                    B[val[i]][j] = i + 1 - Sum(j, 1) - Sum(val[i], 0);
                }
            } else {
                Update(val[i], 1, 1);
                for(int j = 0; j <= N; ++j) {
                    W[j][val[i]] = i + 1 - Sum(j, 0) - Sum(val[i], 1);
                }
            }
        }

        memset(dp, INF, sizeof(dp));
        dp[0][0] = 0;

        for(int i = 0; i <= N; ++i) {
            for(int j = 0; j <= N; ++j) {
                if(i == 0 && j == 0) continue;

                if(i) dp[i][j] = min(dp[i][j], dp[i - 1][j] + B[i][j]);
                if(j) dp[i][j] = min(dp[i][j], dp[i][j - 1] + W[i][j]);
            }
        }

        printf("%d\n", dp[N][N]);
    }
    return 0;
}

