                dp[i][j] = min(dp[i][j], dp[i - 1][j] + i + j - get(ind[0][i] + 1));
            if(j != 0)
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + j + i - get(ind[1][j] + 1));
            if(dp[i][j] != 0){
                exit(0);
