int main()
{
    scanf("%d\n", &N);
    a.resize(N * 2);

    for (int i=0; i<2*N; i++)
    {
        char str;
        scanf("%s", &str);
        scanf("%d", &a[i]);
        if (str == 'W') a[i] *= -1;
    }

    // dp[i][j] : 先頭から黒i個白j個が正しい順に並ぶまでの最小操作回数

    dp[0][0] = 0;

    for (int i=1; i<=N; i++)
    {
        int aa = 0;
        for (int k=0; k<2*N; k++)
        {
            if (a[k] == i) break;
            if (a[k] > i || a[k] < 0) aa++;
        }
        int bb = 0;
        for (int k=0; k<2*N; k++)
        {
            if (a[k] == -i) break;
            if (a[k] < -i || a[k] > 0) bb++;
        }

        dp[i][0] = dp[i-1][0] + aa;
        dp[0][i] = dp[0][i-1] + bb;
    }

    for (int i=1; i<=N; i++)
    {
        for (int j=1; j<=N; j++)
        {
            /* iroiro */
            // 数字iが書かれた黒を手前に持ってくるまでの総回数
            int aa = 0;
            int bb = 0;
            for (int k=0; k<2*N; k++)
            {
                if (a[k] == i) break;
                if (a[k] > i || a[k] < -j) aa++;
            }

            for (int k=0; k<2*N; k++)
            {
                if (a[k] == -j) break;
                if (a[k] > i || a[k] < -j) bb++;
            }

            dp[i][j] = min(dp[i-1][j] + aa, dp[i][j-1] + bb);
        }
    }

    printf("%d\n", dp[N][N]);
    return 0;
}

