}

int query(vector<vector<int>> &st, int left, int right, int x, int y, int val, int pos)
{
	if((left>y)||(right<x))	return 0;
	if((x<=left)&&(right<=y))
	{
		return upper_bound(st[pos].begin(),st[pos].end(),val)-st[pos].begin();
	}
	int mid=(left+right)/2;
	return query(st,left,mid,x,y,val,pos*2+1)+query(st,mid+1,right,x,y,val,pos*2+2);
}
