            if(k <= i) dp[i+1][k] = dp[i][k] + white[i-k + 1][k+1];
            else dp[i+1][k] = INF;
            if(k >= 1){
                chmin(dp[i+1][k],dp[i][k-1] + black[k][i-k+2]);
