			pos[0][a[i]]=i;
		else
			pos[1][a[i]]=i;
	}
	dp[0][0]=0;
	for(int i=0;i<=n;i++)
	{
		for(int j=0;j<=n;j++)
		{
			if(i+j)
				dp[i][j]=1e9;
			// (i-1,j)
			if(i)
			{
				int z = pos[0][i];
				int x = (int)(upper_bound(all(vec[0][z]),i-1)-vec[0][z].begin());
				int	y = (int)(upper_bound(all(vec[1][z]),j)-vec[1][z].begin());
				int res = dp[i-1][j]+i-1-x+sz(vec[0][z])-x+j-y+sz(vec[1][z])-y;
				dp[i][j]=min(dp[i][j],res-1);
			}
			if(j)
			{
				int z = pos[1][j];
				int x = (int)(upper_bound(all(vec[0][z]),i)-vec[0][z].begin());
				int	y = (int)(upper_bound(all(vec[1][z]),j-1)-vec[1][z].begin());		
				int res = dp[i][j-1]+i-x+sz(vec[0][z])-x+j-1-y+sz(vec[1][z])-y;
				dp[i][j]=min(dp[i][j],res-1);
			}
		}
	}
	cout<<dp[n][n]/2<<"\n";
	return 0;
}

