{
	int l=0,r=0;
	while((l<ki.size())||(r<ka.size()))
	{
		if(l==ki.size())
		{
			hsl.push_back(ka[r]);
			r++;
			continue;
		}
		if(r==ka.size())
		{
			hsl.push_back(ki[l]);
			l++;
