// Segment tree {{{
// O(N) 構築
// O(log(N)) update, query
// verified AOJ DSL_2_A
template <typename T>
struct SGT {
    vector<T> v;
    int n;
    T init;
    function<T(T, T)> f;
    SGT(vector<T> a, T init, function<T(T, T)> f){
        int m = a.size();
        n = 1;
        while(n < m) n <<= 1;
        this->init = init;
        this->f = f;
        v.resize(2*n-1, init);
        for(int i=0;i<m;i++) v[n-1+i] = a[i];
        for(int i=n-2;i>=0;i--) v[i] = min(v[i*2+1], v[i*2+2]);
    }
    void update(int i, T x) {
        i += n-1;
        v[i] = x;
        while(i>0){
            i = (i-1)/2;
            v[i] = f(v[i*2+1], v[i*2+2]);
        }
    }
    T query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return init;
        if(a <= l && r <= b) return v[k];
        T vl = query(a, b, k*2+1, l, (l+r)/2);
        T vr = query(a, b, k*2+2, (l+r)/2, r);
        return f(vl, vr);
    }
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};
// }}}

int solve(int n, vector<int> c, vector<int> a) {
    int x[2] = {0, 0};
    int r[2][2000];

    inc(i, 0, n*2){
        r[c[i]][a[i]] = i;
    }

    vector<int> v(n*2);
    inc(i, 0, n*2) v[i] = 0;
    SGT<int> sgt(v, 0, [](int a, int b){return a+b;});

    int ans = 0;

    inc(i, 0, n*2){
        if(c[i] == -1) continue;
        if(x[c[i]] == a[i]){
            x[c[i]]++;
            continue;
        }
        //cout << "#" << i << endl;
        inc(j, x[c[i]], a[i]){
            int k = r[c[i]][j];
            int d = k - i - sgt.query(i+1, k+1);
            ans += d;
            //cout << k << " " << d << endl;
            sgt.update(k, 1);
            c[k] = -1;
        }
        //cout << i << " " << ans << endl;
        x[c[i]]=a[i]+1;
    }

    return ans;
}

