		f[a[i]][r_idx[i][0]] = 1;
		A[i] = {a[i], r_idx[i][0]};
	}
	sort(A.begin() + 1, A.end());
	B[0] = {N, N}; for (int i = n + 1; i <= n + 4; ++i) B[i] = {N, N};
	for (int i = 1; i <= n; ++i) {
		g[b[i]][r_idx[i][1]] = 1;
