		for (int j = 1; j <= 2 * n; ++j) {
			f[i][j] += f[i - 1][j] + f[i][j - 1] - f[i - 1][j - 1];
			g[i][j] += g[i - 1][j] + g[i][j - 1] - g[i - 1][j - 1];
