template <typename Base>
class BinaryIndexedTree
{
private:
    static constexpr int sz(const int n)
    {
        int ans = 1;
        for (; n > ans; ans <<= 1) {}
        return ans;
    }

public:
    using T = typename Base::T;
    using AbelGroup = Base;
    BinaryIndexedTree(const int n) : data_num(n), size(sz(n)), value(size + 1, AbelGroup::id()) { assert(n > 0); }
    template <typename InIt>
    BinaryIndexedTree(const InIt first, const InIt last) : data_num(distance(first, last)), size(sz(data_num)), value(size + 1, AbelGroup::id())
    {
        copy(first, last, value.begin() + 1);
        for (int x = 1; x < size; x++) { value[x + (x & -x)] = op(value[x + (x & -x)], value[x]); }
    }
    T accumulate(const int a) const  // [0,a]
    {
        assert(0 <= a and a < data_num);
        int ind = a + 1;
        T sum = AbelGroup::id();
        while (ind > 0) {
            sum = op(sum, value[ind]);
            ind &= ind - 1;
        }
        return sum;
    }
    T accumulate(const int l, const int r) const  // [l,r)
    {
        assert(0 <= l and l < r and r <= data_num);
        return op(accumulate(r - 1), AbelGroup::inv(l == 0 ? AbelGroup::id() : accumulate(l - 1)));
    }
    void add(const int a, const T& val)
    {
        assert(0 <= a and a < data_num);
        int ind = a + 1;
        while (ind <= size) {
            value[ind] = op(value[ind], val);
            ind += ind & (-ind);
        }
    }
    void set(const int a, const T& val) { add(a, op(val, AbelGroup::inv(get(a)))); }
    T get(const int a) const
    {
        assert(0 <= a and a < data_num);
        return accumulate(a, a + 1);
    }
    template <typename Predicate>                    // Predicate: T -> bool
    int partitionPoint(const Predicate& pred) const  // [0,x).accumulate.pred = true となるxの上限
    {
        if (not pred(AbelGroup::id())) {
            return 0;
        }
        int x = 0;
        T offset = AbelGroup::id();
        for (int k = ((size == data_num) ? size : size / 2); k > 0; k /= 2) {
            if (x + k <= size and pred(op(value[x + k], offset))) {
                offset = op(offset, value[x + k]);
                x += k;
            }
        }
        return min(x, data_num);
    }

    vector<T> data() const
    {
        vector<T> ans(data_num);
        for (int i = 0; i < data_num; i++) { ans[i] = get(i); }
        return ans;
    }

private:
    const int data_num;
    const int size;
    const AbelGroup op{};
    vector<T> value;
};

