using namespace std;

const int maxn = (2012);
int dp[maxn][maxn], fen[3 * maxn], pl[maxn][3];
int n;

void add(int idx) {
	for (; idx < 3 * maxn; idx += (idx & -idx)) {
		fen[idx]++;
	}
	return;
}

int get(int idx) {
	int ret = 0;
	for (; idx > 0; idx -= (idx & -idx)) {
		ret += fen[idx];
	}
	return ret;
}

void antiadd(int idx) {
	for(; idx < 3 * maxn; idx += (idx & -idx)) {
		fen[idx]--;
	}
	return;
}

int main() {
	cin >> n;
	for (int i = 1; i <= 2 * n; i++) {
		char c;
		int num;
		cin >> c >> num;
		if(c == 'B') pl[num][0] = i;
		else pl[num][1] = i;
	}
	for (int i = 1; i <= n; i++) {
		add(pl[i][0]);
		dp[0][i] = i - get(pl[i][0]) + dp[0][i - 1];
	}
	for (int i = 1; i <= n; i++) {
		antiadd(pl[i][0]);
	}
	for (int i = 1; i <= n; i++) {
  		add(pl[i][1]);
  		dp[i][0] = i - get(pl[i][1] - 1) + dp[i - 1][0];
		for (int j = 1; j <= n; j++) {
   			add(pl[j][0]);
			dp[i][j] = min(dp[i - 1][j] + get(2 * n) - get(pl[i][1]), dp[i][j - 1] + get(2 * n) - get(pl[j][0]));
		}
		for (int j = 1; j <= n; j++) {
			antiadd(pl[j][0]);
		}
	}
	cout << dp[n][n];
}

