using namespace std;

void chmin(int &a, int b) { a = min(a, b); }

int n;
char c[4000]; int a[4000];
int posW[2001];
int posB[2001];
int cntW[4001][2001];	//cntW[i][j] = 先頭i文字を取り除いたとき、j以下の白いボールはいくつあるか？
int cntB[4001][2001];
int dp[2001][2001];		//dp[白][黒] = 反転数の最小値
int INF = 1e+7;

int main() {
	int i, j;

	cin >> n;
	rep(i, 2 * n) {
		cin >> c[i] >> a[i];
		if (c[i] == 'W') { posW[a[i]] = i; cntW[i][a[i]]++; }
		if (c[i] == 'B') { posB[a[i]] = i; cntB[i][a[i]]++; }
	}

	rep(i, 2 * n + 1) {
		rep(j, n) cntW[i][j + 1] += cntW[i][j];
		rep(j, n) cntB[i][j + 1] += cntB[i][j];
	}

	rep(j, n + 1) {
		rrep(i, 2 * n) cntW[i][j] += cntW[i + 1][j];
		rrep(i, 2 * n) cntB[i][j] += cntB[i + 1][j];
	}

	rep(i, n + 1) rep(j, n + 1) dp[i][j] = INF;
	dp[0][0] = 0;

	rep(i, n + 1) {
		rep(j, n + 1) {
			if (i < n) {
				chmin(dp[i + 1][j], dp[i][j] + cntW[posW[i + 1] + 1][i] + cntB[posW[i + 1] + 1][j]);
			}
			if (j < n) {
				chmin(dp[i][j + 1], dp[i][j] + cntW[posB[j + 1] + 1][i] + cntB[posB[j + 1] + 1][j]);
			}
		}
	}
	cout << dp[n][n] << endl;
	return 0;
}

