int bc[SIZE][SIZE];//0
int wc[SIZE][SIZE];//1

int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<2*n;i++)
	{
		scanf("%s %d",&str,&A[i]);
		A[i]--;
		if(str[0]=='B') col[i]=0;
		else col[i]=1;
	}
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<2*n;j++)
		{
			if(col[j]==0&&A[j]==i) break;
			if(col[j]==1)
			{
				bc[i][A[j]]++;
			}
		}
		for(int j=n-2;j>=0;j--) bc[i][j]+=bc[i][j+1];
		for(int j=0;j<2*n;j++)
		{
			if(col[j]==1&&A[j]==i) break;
			if(col[j]==0)
			{
				wc[i][A[j]]++;
			}
		}
		for(int j=n-2;j>=0;j--) wc[i][j]+=wc[i][j+1];
	}
	for(int i=0;i<=n;i++)
	{
		for(int j=0;j<=n;j++)
		{
			dp[i][j]=INF;
		}
	}
	dp[0][0]=0;
	for(int i=0;i<=n;i++)
	{
		for(int j=0;j<=n;j++)
		{
			if(i<n)
			{
				dp[i+1][j]=min(dp[i+1][j],dp[i][j]+bc[i][j]);
			}
			if(j<n)
			{
				dp[i][j+1]=min(dp[i][j+1],dp[i][j]+wc[j][i]);
			}
			//printf("%d %d : %d\n",i,j,dp[i][j]);
		}
	}
	int ret=dp[n][n];
	for(int i=0;i<2*n;i++)
	{
		for(int j=i+1;j<2*n;j++)
		{
			if(A[i]>A[j]&&col[i]==col[j])
			{
				ret++;
			}
		}
	}
	printf("%d\n",ret);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int w[2001], b[2001];
int cw[2001][2001], cb[2001][2001], f[2001][2001];

int main(){
  memset(cw, 0, sizeof(cw));
  memset(cb, 0, sizeof(cb));
  memset(f, 0, sizeof(f));

  int N;cin>>N;
  for (int i=1;i<=2*N;++i){
    char c;cin>>c;int a;cin>>a;
    if(c=='W') w[a]=i;else b[a]=i;
  }

  for (int i=1;i<=N;++i){
    for (int j=1;j<i;++j){
      cw[i][0]+=(w[j]>w[i]);
    }

    for (int j=1;j<=N;++j){
      cw[i][j]=cw[i][j-1]+(w[i]<b[j]);
    }
  }

  for (int i=1;i<=N;++i){
    for (int j=1;j<i;++j){
      cb[0][i]=(b[j]>b[i]);
    }

    for (int j=1;j<=N;++j){
      cb[j][i]=cb[j-1][i]+(b[i]<w[j]);
    }
  }

  for (int i=1;i<=N;++i){
    f[i][0]=f[i-1][0]+cw[i][0];
  }
  for (int i=1;i<=N;++i){
    f[0][i]=f[0][i-1]+cb[0][i];
  }

  for (int i=1;i<=N;++i){
    for (int j=1;j<=N;++j){
      f[i][j]=min(f[i-1][j]+cw[i][j], f[i][j-1]+cb[i][j]);
    }
  }

  cout << f[N][N] << endl;
  return 0;
}

