#define N 5000

int n;
map<int, int> mb, mw;
int data[N*2];

void add(int k, int x) {
  while(k <= 2*n) {
    data[k] += x;
    k += k & -k;
  }
}
int get(int k) {
  int s = 0;
  while(k > 0) {
    s += data[k];
    k -= k & -k;
  }
  return s;
}

vector<int> aw, ab;
int cb[N][N], cw[N][N], dp[N][N];

int main() {
  cin >> n;
  rep(i, n*2) {
    char c; int a;
    cin >> c >> a;
    if(c == 'W') {
      mw[a] = i;
      aw.push_back(a);
    } else {
      mb[a] = i;
      ab.push_back(a);
    }
  }
  sort(ALL(aw));
  sort(ALL(ab));

  rep(i, 2*n) {
    add(i+1, 1);
  }

  rep(i, n+1) {
    rep(j, n+1) {
      if(i < n) {
        cw[i][j] = get(mw[aw[i]]+1)-1;
      }
      if(j < n) {
        cb[i][j] = get(mb[ab[j]]+1)-1;
        add(mb[ab[j]]+1, -1);
      }
      //cout << i SP j SP cw[i][j] SP cb[i][j] << endl;
    }
    rep(j, n) {
      add(mb[ab[j]]+1, 1);
    }
    if(i < n) {
      add(mw[aw[i]]+1, -1);
    }
  }

  rep(i, n+1) rep(j, n+1) dp[i][j] = INF;
  dp[0][0] = 0;
  rep(i, n+1) {
    rep(j, n+1) {
      int v = dp[i][j];
      if(i > 0) {
        v = mind(v, dp[i-1][j] + cw[i-1][j]);
      }
      if(j > 0) {
        v = mind(v, dp[i][j-1] + cb[i][j-1]);
      }
      dp[i][j] = v;
    }
  }
  cout << dp[n][n] << endl;
  return 0;
}

