int main() {
	int N;
	cin >> N;
	for (int i = 0; i < 2 * N; i++) {
		string c;
		int a;
		cin >> c >> a;
		if (c == "W") w[a - 1] = i;
		else b[a - 1] = i;
	}
	SegTree W, B;
	W.init(0, 0, N, w);
	B.init(0, 0, N, b);
	fill((LL*)dp, (LL*)(dp + 2 * N + 1), 1LL << 60);
	dp[0][0] = 0;
	for (int i = 0; i < 2 * N; i++) {
		for (int j = 0; j <= min(i, N); j++) {
			if (dp[i][j] == 1LL << 60) continue;
			if (j + 1 <= N) {
				LL add = j - B.query(0, j, b[j], 0, 0, N);
				add += (i - j) - W.query(0, i - j, b[j], 0, 0, N);
				dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + add);
			}
			if (i - j + 1 <= N) {
				LL add = (i - j) - W.query(0, i - j, w[i - j], 0, 0, N);
				add += j - B.query(0, j, w[i - j], 0, 0, N);
				dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + add);
			}
		}
	}
	cout << dp[2 * N][N] << endl;
}

