int get(int ind)
{
	if (!ind)
		return 0;

	int cnt = 0;
	for (int i = ind; i; i -= i &-i)
		cnt += t[i];

	return cnt;
}


int get(int l, int r)
{
	return get(r) - get(l - 1);
}


