struct ball{
    char color;
    int number;
    bool valid;
};

int main(){
    int N;
    cin >> N;
    vector<ball> b(2*N);
    REP(i,2*N){
        char color; int num;
        cin >> color >> num;
        b[i] = {color,num,true};
    }

    ll ans = 0;
    int numb = 1;
    int numw = 1;

    int i = 0;
    while(i<2*N){
        if (b[i].valid == false){
            i++;
            continue;
        }

        if (b[i].color == 'W' and b[i].number == numw){
            ++i;
            numw++;
            continue;
        }

        if (b[i].color == 'B' and b[i].number == numb){
            ++i;
            numb++;
            continue;
        }

        int count = 0;
        FORq(j,i+1,2*N-1){
            if (b[j].valid == false) continue;
            count++;
            if (b[j].color == 'W' and b[j].number == numw){
                ans += count;
                numw++;
                b[j].valid = false;
                break;
            }

            if (b[j].color == 'B' and b[j].number == numb){
                ans += count;
                numb++;
                b[j].valid = false;
                break;
            }
        }

    }

    cout << ans << endl;


}

