class Bit {
  ll n, bit[20000];
public:
  void init(ll _n) {
    n = _n;
  }
  void add(ll a, ll w) {
    for (ll x = a; x <= n; x += x & -x) bit[x] += w;
  }
  ll sum(ll a) {
    ll ans = 0;
    for (ll x = a; x > 0; x -= x & -x) ans += bit[x];
    return ans;
  }
};

