Bit w_s, b_s;

ll sum(ll a, ll b) { return a + b; }

ll search(ll x, ll y) {
  if (dp[x][y] != -1) return dp[x][y];
  ll ans = INF, num;
  if (x > 0) {
    num = w[x-1]+1;
    w_s.add(num, 1);
    ans = min(ans, search(x-1, y) + w_s.sum(num-1) + b_s.sum(num-1));
    w_s.add(num, -1);
  }
  if (y > 0) {
    num = b[y-1]+1;
    b_s.add(num, 1);
    ans = min(ans, search(x, y-1) + w_s.sum(num-1) + b_s.sum(num-1));
    b_s.add(num, -1);
  }
  return dp[x][y] = ans;
}

