    dp[0][0] = 0;
    go(i, 1, 2 * n) {
        go(j, max(0, i - n), min(i, n)) {
            // all 'B'
            if (j == 0) {
                int originPos = pos[0][i];
                int smallB = foo[0][originPos - 1][i - 1];
                dp[i][0] = dp[i - 1][0] + originPos - smallB - 1;
            } else if (j == i) {// all 'W'
                int originPos = pos[1][i];
                int smallW = foo[1][originPos - 1][i - 1];
                dp[i][i] = dp[i - 1][i - 1] + originPos - smallW - 1;
            } else {// j 'W' and i - j 'B'
                int originW = pos[1][j];
                int originB = pos[0][i - j];
                int smallW = foo[0][originW - 1][i - j] + foo[1][originW - 1][j - 1];
                int smallB = foo[0][originB - 1][i - j - 1] + foo[1][originB - 1][j];
                dp[i][j] = min(dp[i - 1][j - 1] + originW - smallW - 1,
                                  dp[i - 1][j] + originB - smallB - 1);
            }
        }
    }

    cout << dp[2 * n][n];

#ifdef ZYC_LOCAL
    cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif
    return 0;
}

