	if(type == 0){
		return 1LL * abs(cp - pos) + min(rec(pos + 1 , 0 , last_w + 1 , last_w + 1 , last_b , tree),
			rec(pos + 1 , 1 , last_b , last_w + 1  , last_b , tree));	
	}else{
