struct Problem {

	UL LW[2000][2001] = {};
	UL LB[2000][2001] = {};
	UL dp[2001][2001];

	void Solve() {
		UL N; cin >> N;
		vector<UL> Black(N), White(N);
		rep(i, N * 2) {
			char c; cin >> c;
			UL a; cin >> a;
			((c == 'B') ? Black : White)[a - 1] = i;
		}
		rep(i, N) {
			for (UL j = 0; j < i; j++) {
				if (White[j] < White[i]) LW[i][0]++;
				if (Black[j] < Black[i]) LB[i][0]++;
			}
			for (UL j = 1; j <= N; j++) {
				if (Black[j - 1] < White[i]) LW[i][j]++;
				if (White[j - 1] < Black[i]) LB[i][j]++;
				LW[i][j] += LW[i][j - 1];
				LB[i][j] += LB[i][j - 1];
			}
		}
		rep(i, N) {
			rep(j, N + 1) {
				LW[i][j] = White[i] - LW[i][j];
				LB[i][j] = Black[i] - LB[i][j];
			}
		}
		rep(i, N + 1) rep(j, N + 1) dp[i][j] = 1000000000;
		dp[0][0] = 0;
		rep(i, N + 1) {
			rep(j, N + 1) {
				auto &p = dp[i][j];
				if (i != 0) p = min(p, dp[i - 1][j] + LW[i - 1][j]);
				if (j != 0) p = min(p, dp[i][j - 1] + LB[j - 1][i]);
				dp[i][j] = p;
				//cout << dp[i][j] << " ";
			} //cout << endl;
		}
		cout << dp[N][N] << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
