    for (int i=2*n;i>=1;i--){
        if (type[i]=='W'){
            for (int j=0;j<=n;j++){
                add[i][j] = nrW[val[i]] + nrB[j];
            }
            for (int j=val[i];j<=n;j++) nrW[j]++;
        }
        else{
            for (int j=0;j<=n;j++){
                add[i][j] = nrB[val[i]] + nrW[j];
            }
            for (int j=val[i];j<=n;j++) nrB[j]++;
