    for (int i=1;i<=2*n;i++){
        for (int j=max(i-n,0);j<=min(i,n);j++){
            int A = (j==0 ? 1e8 : DP[i-1][j-1] + (posW[j] + add[posW[j]][i-j] - i));
            int B = (j>i-1 ? 1e8 : DP[i-1][j] + (posB[i-j] + add[posB[i-j]][j] - i));
