int solve(int N, vector<pair<char, int> > ca) {


    int wcor = 0, bcor = 0;
    int ans = 0;

    for (int i = 0; i < 2 * N; i++) {
        int wdist = INF;
        int bdist = INF;
        for (int j = i; j < 2 * N; j++) {
            if (ca[j].first == 'B') {
                if (ca[j].second == bcor + 1) {
                    bdist = j - i;
                }
            } else {
                if (ca[j].second == wcor + 1) {
                    wdist = j - i;
                }
            }
        }

        if (wdist < bdist) {
            wcor++;
            //白のwcorをiのいちに持ってくる
            for (int j = i + wdist; j > i; j--) {
                swap(ca[j], ca[j - 1]);
                ans++;
            }
        } else {
            bcor++;
            for (int j = i + bdist; j > i; j--) {
                swap(ca[j], ca[j - 1]);
                ans++;
            }
        }
    }
    return ans;
}

