template <class Monoid> struct SegmentTree{
    using Func = function<Monoid(Monoid, Monoid)>;

    int size;
    vector<Monoid> seg;
    const Func merge;
    const Monoid def;

    SegmentTree(int n, Monoid d, const Func f): merge(f), def(d){
        for(size = 1; size <= n; size <<= 1);
        seg.assign(size*2, def);
    }

    Monoid& operator[] (int i) { return seg[i+size]; };
    void build(){ for(int i = size-1;i >= 0;i--) seg[i] = merge(seg[i*2], seg[i*2+1]); }

    void update(int i, Monoid val){
        seg[i += size] = val;
        while(i >>= 1) seg[i] = merge(seg[i*2], seg[i*2+1]);
    }

    void add(int i, Monoid val){ update(i, val+seg[i+size]); }

    Monoid get(int a, int b){
        Monoid l = def, r = def;
        for(a += size, b += size; a < b; a >>= 1, b >>= 1){
            if(a & 1) l = merge(l, seg[a++]);
            if(b & 1) r = merge(r, seg[--b]);
        }
        return merge(l, r);
    }
};

int n;
pair<char, int> p[4010];

int b[2010];
int w[2010];
int memo[2010][2010];

SegmentTree<int> seg(4010, 0, [](int a, int b){ return (a + b);});

int dp(int i, int j){
    if(i == n/2 && j == n/2){
        return 0;
    }

    if(memo[i][j] != -1) return memo[i][j];

    int ans = LLONG_MAX;
    if(i < n/2){
        seg.update(b[i], 0);
        ans = min(ans, dp(i+1, j) + seg.get(0, b[i]));
        seg.update(b[i], 1);
    }

    if(j < n/2){
        seg.update(w[j], 0);
        ans = min(ans, dp(i, j+1) + seg.get(0, w[j]));
        seg.update(w[j], 1);
    }

    return memo[i][j] = ans;
}

