template<typename T, size_t N_input>
class BIT
{
private:
	static constexpr size_t N = get_min2pow(N_input);
	// [1, n]
	T bit[N + 1];
public:
	//1-indexed [1,i]
	T sum(int i) {
		T s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	//1-indexed [i,j]
	T sum(int i, int j) {
		return sum(j) - sum(i - 1);
	}
	//1-indexed
	void add(int i, int x) {
		while (i <= N) {
			bit[i] += x;
			i += i & -i;
		}
	}
};
