    auto f = [&](char col, auto& cost) {
        for (int k = 0; k <= n; ++k) {
            Fenwick<int> fen(n + 1);
            int count = 0;
            for (int i = 0; i < 2 * n; ++i) {
                if (c[i] == col) {
                    cost[a[i]][k] = count + fen.sum(n) - fen.sum(a[i]);
                    fen.add(a[i], 1);
                } else {
                    count += a[i] > k;
                }
            }
        }
    };
    f('B', cost_b);
    f('W', cost_w);
    int dp[2001][2001] = {};
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (i != 0 || j != 0) {
