const int N = 2005;
const int INF = (int)1e+9;

int n;
int dp[N][N];
int BIT[N][2];
int posBlack[N], posWhite[N];

void update(int id, int k, int v) {
	for (; k <= 2*n; k += k & -k) {
		BIT[k][id] += v;
	}
}

int query(int id, int k) {
	int ret = 0;
	for (; k > 0; k -= k & -k) {
		ret += BIT[k][id];
	}
	return ret;
}

int query(int id, int x, int y) {
	return query(id, y) - query(id, x-1);
}

int DP(int white, int black) {
	if (white == n && black == n) {
		return 0;
	}
	int& ret = dp[white][black];
	if (ret != -1) return ret;
	ret = INF;
	int total = white + black;
	int pos;
	if (white < n) {
		pos = posWhite[white + 1] + query(0, posWhite[white + 1], 2*n) + query(1, posWhite[white + 1], 2*n);
		//printf("white -> %d %d %d\n", white, black, pos);
		update(0, posWhite[white + 1], 1);
		ret = min(ret, abs(pos - (total + 1)) + DP(white + 1, black));
		update(0, posWhite[white + 1], -1);
	}
	if (black < n) {
		pos = posBlack[black + 1] + query(0, posBlack[black + 1], 2*n) + query(1, posBlack[black + 1], 2*n);
		//printf("black -> %d %d %d\n", white, black, pos);
		update(1, posBlack[black + 1], 1);
		ret = min(ret, abs(pos - (total + 1)) + DP(white, black + 1));
		update(1, posBlack[black + 1], -1);
	}
	return ret;
}

