            if(a[i] > lw){
                rightw[a[i]] = a[i] - lw - 1;
                lw = a[i];
            }
        }
    }
    int ans = 0;
    for(int i = 0; i < n * 2; i++){
        if((c[i] == 'B' && c[i + 1] == 'W' && rightb[a[i]] > rightw[a[i + 1]] + 1) ||
           (c[i] == 'W' && c[i + 1] == 'B' && rightw[a[i]] > rightb[a[i + 1]] + 1)){
            swap(a[i], a[i + 1]);
            swap(c[i], c[i + 1]);
            ans++;
        }
        for(int j = i + 1; j < n * 2; j++){
            if(c[j] == c[i] && a[j] < a[i]){
                int t = a[j];
                int k = j;
                for(; k > i; k--){
                    c[k] = c[k - 1];
                    a[k] = a[k - 1];
                }
                while(k > 0 && c[k - 1] == c[i] && t < a[k - 1]){
                    a[k] = a[k - 1];
                    k--;
                }
                a[k] = t;
                ans += j - k;
                i++;
            }
        }
    }
    cout << ans << endl;
}

