int c[3][maxn*2];
int f[maxn][maxn];

void update(int o, int i, int v)
{
  for (; i <= 2 * n; i += (i & -i)) c[o][i] += v;
}

int query(int o, int i)
{
  int ret = 0;
  for (; i; i -= (i & -i)) ret += c[o][i];
  return ret;
}

int main(int argc, char *argv[])
{
