        }
    }

    int res = 0;
    while (s0 <= n || s1 <= n) {
        int v0 = (s0 <= n ? p[0][s0]-bit.sum(p[0][s0])-1 : inf);
        int v1 = (s1 <= n ? p[1][s1]-bit.sum(p[1][s1])-1 : inf);
        if (v0 < v1) {
            res += v0;
            bit.add(p[0][s0], 1);
            s0++;
        } else {
            res += v1;
            bit.add(p[1][s1], 1);
            s1++;
        }
    }
    return res;
}

