int dp[2][N];

void solve(){
  int n;
  cin>>n;
  vector<int>a(2*n);
  string s;
  adj.resize(n+1);
  adj2.resize(n+1);
  for(int i=0;i<2*n;i++){
    char z;
    cin>>z;
    s+=z;
    cin>>a[i];
    if(z=='B'){
      adj[a[i]]=i;
    }
    else{
      adj2[a[i]]=i;
    }
  }
  for(int j=0;j<=n;j++){
    dp[0][j]=dp[1][j]=1e9;
    for(int i=0;i<2*n;i++){
      st[j].insert(i); 
    }
    for(int i=1;i<=j;i++){
      st[j].erase(adj[i]);
    }
  }
  dp[0][0]=0;
  for(int i=0;i<2*n;i++){
    for(int j=0;j<=min(n,i);j++){
      int gt=st[j].order_of_key(adj[j+1]);
      dp[1][j+1]=min(dp[1][j+1],dp[0][j]+gt);
    }
    for(int j=0;j<=n;j++){
      if(i-j<0){
	break;
      }
      if(i-j>n){
	continue;
      }
      int gt=st[j].order_of_key(adj2[i-j+1]);
      dp[1][j]=min(dp[1][j],dp[0][j]+gt);
    }
    for(int j=0;j<=n;j++){
      dp[0][j]=dp[1][j];
      dp[1][j]=1e9;
    }
    for(int j=0;j<=min(n,i+1);j++){
      if(i-j+1<=n&&i-j+1>0){
	st[j].erase(adj2[i-j+1]);
      }
    }
  }
  cout<<dp[0][n];
}

