#include <bits/stdc++.h>

using namespace std;

const int N = 2001;

int f[N * 2][N], bl[N], wt[N], bit[N * 2], n, p;
char x;

void upd (int x, int v)
{
    if (!x)
        return;
    for (; x < N; x += x & -x)
        bit[x] += v;
}

int get (int x)
{
    int rep = 0;
    for (; x; x -= x & -x)
        rep += bit[x];
    return rep;
}

int main ()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cin >> n;
    for (int i = 0; i < (N * 2); ++i)
        for (int j = 0; j < N; ++j)
            f[i][j] = 1e9;
    f[0][0] = 0;
    for (int i = 1; i <= (n * 2); ++i)
    {
        cin >> x >> p;
        if (x == 'B')
            bl[p] = i;
        else
            wt[p] = i;
    }
    for (int i = 1; i <= (n * 2); ++i)
    {
        memset(bit, 0, sizeof bit);
        for (int j = 1; j <= (n * 2); ++j)
            upd(j, 1);
        int k = min(i, n);
        for (int j = 1; j <= k; ++j)
            upd(wt[j], -1);
        for (int j = 1; j <= (i - k); ++j)
            upd(bl[j], -1);
        for (int j = max(0, i - n); j <= min(i, n); )
        {
            if (i > j)
                f[i][j] = min(f[i][j], f[i - 1][j] + get(wt[k]));
            if (j)
                f[i][j] = min(f[i][j], f[i - 1][j - 1] + get(bl[j]));
            upd(wt[k--], 1);
            upd(bl[++j], -1);
        }
    }
    cout << f[n * 2][n];
    return 0;
}

