int u;
void bitinit(int n){
  int now=1;
  for(int i=0;;i++){
    if(now>=n){
      u=now;
      break;
    }
    now*=2;
  }
  fill(bit,bit+u+1,0);
}
void add(int n,int x){
  int i=n;
  while(i<=u){
    bit[i]+=x;
    i+=i&-i;
  }
}
int sum(int n){
  int ret=0;
  int i=n;
  while(i>0){
    ret+=bit[i];
    i-=i&-i;
  }
}
int main(){
  int n;cin>>n;
  int bla[n+1];
  int whi[n+1];
  int a[2*n+1];
  char b[2*n+1];
  bitinit(n);
  for(int i=0;i<2*n;i++){
    char c;cin>>c;
    int m;cin>>m;
    if(c=='B')bla[m]=i+1;
    else whi[m]=i+1;
    add(i+1,1);
    a[i+1]=m;
    b[i+1]=c;
  }
  int ans=0;
  bool used[2*n+1];
  fill(used,used+2*n+1,false);
  int bl=0;
  int wh=0;
  for(int i=1;i<=2*n;i++){
    if(used[i])continue;
    if(b[i]=='B'){
      if(bl+1==a[i]){
        bl++;
        used[i]=true;
        continue;
      }
      else{
        int y=bla[bl+1];
        ans+=bit(y)-bit(i);
