struct Ball {
  char color;
  int number;
};

Ball ball[4005];
int sumw[4005][4005], sumb[4005][4005], posw[4005], posb[4005];
int dp[4005][4005];

int n;

int solve(int w, int b){ //w = white balls placed so far, b = black balls
  if(w > n && b > n) return 0;
  if(dp[w][b] != -1) return dp[w][b];

  int res = 1e9;
  if(w <= n){
    int whiteBalls = sumw[2*n][w-1] - sumw[posw[w]][w-1]; //number of white balls in the left
    int blackBalls = sumb[2*n][b-1] - sumb[posw[w]][b-1]; //number of black balls in the right
    int cost = abs(posw[w] + whiteBalls + blackBalls - (w+b-1));
    res = min(res, solve(w+1, b) + cost);
  }

  if(b <= n){
    int whiteBalls = sumw[2*n][w-1] - sumw[posb[b]][w-1];
    int blackBalls = sumb[2*n][b-1] - sumb[posb[b]][b-1];
    int cost = abs(posb[b] + whiteBalls + blackBalls - (w+b-1));
    res = min(res, solve(w, b+1) + cost);
  }

  return dp[w][b] = res;
}

int main(){

