      sumw[i][num] += sumw[i-1][num] + sumw[i][num-1] - sumw[i-1][num-1];
      sumb[i][num] += sumb[i-1][num] + sumb[i][num-1] - sumb[i-1][num-1];
    }
  }

  cout << solve(1,1) << endl;

  return 0;
}

