// Binary Indexed Tree (1 indexed)
struct BIT {
  vector<int> data;
  BIT(){}
  void init(int n) {
    data.resize(n+1, 0);
  }
  int sum(int k) {
    int ret = 0;
    while(k > 0) {
      ret += data[k];
      k -= k & -k;
    }
    return ret;
  }
  void add(int k, int x) {
    while(k < (int)data.size()) {
      data[k] += x;
      k += k & -k;
    }
  }
};

int n;
vint w, b;
BIT bit;
int dp[2002][2002];

int solve(int i, int j) {
  if(i == n && j == n) return 0;
  int& res = dp[i][j];
  if(~res) return res;
  res = inf;
  if(i < n) {
    bit.add(w[i]+1, -1);
    chmin(res, solve(i+1, j)+bit.sum(w[i]+1));
    bit.add(w[i]+1, 1);
  }
  if(j < n) {
    bit.add(b[j]+1, -1);
    chmin(res, solve(i, j+1)+bit.sum(b[j]+1));
    bit.add(b[j]+1, 1);
  }
  return res;
}

