constexpr int MAXN = 2048;

int n;
struct Item{ bool color; int index; };
Item a[MAXN*2];

int poses[2][MAXN];
int cnt[2][MAXN][MAXN*2];
// cnt[c][i][j] 表示有多少个颜色为 c 的 item
// 其编号 <= i 并且位置 >= j
void InitCnt(){
	For(i,n+n) poses[a[i].color][a[i].index] = i;
	For0(col,2){
		auto cnt = ::cnt[col];
		For(i,n+n)
			if( a[i].color == col )
				++cnt[a[i].index][i];
		For(i,n)
			For(j,n+n)
				cnt[i][j] += cnt[i-1][j];
		For(i,n)
			fOR(j,n+n){
				cnt[i][j] += cnt[i][j+1];

				// int t = 0;
				// For(k,n+n)
				// 	if( a[k].color == col and k >= j and a[k].index <= i )
				// 		++t;
				// assert( cnt[i][j] == t );
			}
	}
}

int dp[MAXN][MAXN];
#define NOW dp[use0][use1]
#define KNOW ~NOW
int Dfs( int use0 , int use1 ){
	int totUse = use0 + use1;
	if( totUse == n+n ) return 0;
	if(KNOW) return NOW;
	int ans = INF;
	For0(vCol,2){
		int vColUse = vCol ? use1 : use0;
		if( vColUse == n ) continue;
		int vPos = totUse + 1;
		int initVPos = poses[vCol][vColUse+1];
		int nowVPos = initVPos + cnt[0][use0][initVPos+1] + cnt[1][use1][initVPos+1];
		assert( nowVPos >= vPos );
		int tans = Dfs(use0+(1-vCol),use1+vCol) + nowVPos - vPos;
		MyMin(ans,tans);
	}
	return NOW = ans;
}

