int a[4010],pb[2010],pw[2010],cb[2010][2010],cw[2010][2010],f[2010][2010];
char c[4010];

int main(){
	int n,i,j,s;
 	scanf("%d",&n);
	for(i=1;i<=n<<1;i++){
		scanf("%s%d",c+i,a+i);
		(c[i]=='B'?pb:pw)[a[i]]=i;
	}
	for(i=1;i<=n;i++){
		s=0;
		for(j=pb[i]+1;j<=n<<1;j++){
			if(c[j]=='B'&&a[j]<i)s++;
		}
		for(j=0;j<=n;j++){
			if(pw[j]>pb[i])s++;
			cb[i-1][j]=s;
		}
		s=0;
		for(j=pw[i]+1;j<=n<<1;j++){
			if(c[j]=='W'&&a[j]<i)s++;
		}
		for(j=0;j<=n;j++){
			if(pb[j]>pw[i])s++;
			cw[j][i-1]=s;
		}
	}
	for(i=1;i<=n;i++){
		f[i][0]=f[i-1][0]+cb[i-1][0];
		f[0][i]=f[0][i-1]+cw[0][i-1];
	}
	for(i=1;i<=n;i++){
		for(j=1;j<=n;j++)f[i][j]=min(f[i-1][j]+cb[i-1][j],f[i][j-1]+cw[i][j-1]);
	}
	printf("%d",f[n][n]);
	return 0;
}

