#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct BIT
{
    vector<ll> bit;
    ll MAX_N;

    BIT(ll n) : bit(n), MAX_N(n)
    {
        for(int i = 0; i < MAX_N; i++)
        {
            bit[i] = 0;
        }
    }

    int sum(int i)
    {
        int s = 0;
        while(i > 0)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }
    void add(int i, int x)
    {
        while(i <= MAX_N)
        {
            bit[i] += x;
            i += i & -i;
        }
    }
};

int main()
{
    int n;
    cin >> n;
    vector<char> c(2*n);
    vector<int> a(2*n);
    for(int i = 0; i < 2*n; i++)
    {
        cin >> c[i] >> a[i];
    }
    reverse(c.begin(), c.end());
    reverse(a.begin(), a.end());
    BIT bitb(n+1);
    BIT bitw(n+1);

    vector<vector<int>> dp(n+1, vector<int>(n+1));
    vector<vector<int>> costb(n+1, vector<int>(n+1));
    vector<vector<int>> costw(n+1, vector<int>(n+1));
    for(int i = 0; i < 2*n; i++)
    {
        int pos = a[i];
        if(c[i] == 'B')
        {
            bitb.add(a[i], 1);
            for(int j = 0; j <= n; j++)
            {
                costb[pos][j] = bitb.sum(pos-1) + bitw.sum(j);
            }
        }
        else
        {
            bitw.add(a[i], 1);
            for(int j = 0; j <= n; j++)
            {
                costw[j][pos] = bitb.sum(j) + bitw.sum(pos-1);
            }
        }
    }
    for(int i = 0; i <= n; i++)
    {
        for(int j = 0; j <= n; j++)
        {
            dp[i][j] = 1e9;
            if(i == 0 && j == 0) dp[i][j] = 0;
            if(i > 0)
            {
                dp[i][j] = min(dp[i][j], dp[i-1][j] + costb[i][j]);
            }
            if(j > 0)
            {
                dp[i][j] = min(dp[i][j], dp[i][j-1] + costw[i][j]);
            }
        }
    }

    cout << dp[n][n] << endl;
}

