// x-1とxをswap
void swap(int x, vector<P> &v, map<char,vector<int>> &pos){
    char c1 = v[x-1].second;
    char c2 = v[x].second;
    int a1 = v[x-1].first;
    int a2 = v[x].first;
    swap(v[x-1], v[x]);
    pos[c1][a1] = x;
    pos[c2][a2] = x-1;
}

int solve(int n, vector<P> v, map<char,vector<int>> pos){
    int w=0,b=0,cnt=0;
    pos['W'].push_back(INF);
    pos['B'].push_back(INF);
    rep(i,n*2-1){
        P dw = {pos['W'][w]-i, 'W'};
        P db = {pos['B'][b]-i, 'B'};
        P close = min(dw,db);
        char c = close.second;
        assert(w<=n && b<=n);
        assert(close.first >= 0);
        cnt += close.first;
        for(int x = i+close.first; x > i; x--){
            swap(x,v,pos);
        }
        if(c == 'W') w++;
        else b++;
    }
    cerr<<__func__<<cnt<<endl;
    return cnt;
}

