class BIT {
public:
    BIT(int n);
    int query(int i);
    void modify(int i, int v);

private:
    int size() { return m_size; }
    int m_size;
    vector<int> m_data;
};

BIT::BIT(int n) : m_size(n)
{
    int len = 1;
    while(len < n+1)
        len *= 2;
    m_data = vector<int>(len);
}

// 0-index
int BIT::query(int i)
{
    i = i + 1;
    assert(1 <= i && i <= m_size);
    int ret = 0;
    while (i > 0) {
        ret += m_data[i];
        // 一番下の立っている bit を削除
        i -= i & -i;
    }
    return ret;
}

// 0-index
void BIT::modify(int i, int v)
{
    i = i + 1;
    assert(1 <= i && i <= m_size);
    while (i <= m_size) {
        m_data[i] += v;
        i += i & -i;
    }
}

