template <typename T> struct BinaryIndexedTree0 {
	const int N;
	vector<T> val;

	BinaryIndexedTree0(int N) : N(N), val(N) {}

	T sum(int i) const {
		T s = 0;
		--i;
		if (i >= N) i = N - 1;
		for (; i >= 0; i = (i & (i + 1)) - 1) s += val[i];
		return s;
	}

	T sum(int l, int r) const {
		return sum(r) - sum(l);
	}

	void add(int i, T x) {
		for (; i < N; i |= i + 1) val[i] += x;
	}

	void set(int i, T x) {
		T c = sum(i, i + 1);
		add(i, x - c);
	}

	int lower_bound(T w) const {
		int x = 0;

		for (int k = (1 << (31 - __builtin_clz(N))) - 1; ; k >>= 1) {
			if (x + k < N && val[x + k] < w) {
				w -= val[x + k];
				x += k + 1;
			}
			if (k == 0) break;
		}
		return x;
	}
};
template<class V> ostream& operator<<(ostream& os, const BinaryIndexedTree0<V>& ft) {
	vector<V> vec;
	for (int i = 0; i < ft.N; i++) {
		vec.emplace_back(ft.sum(i, i+1));
	}
	os << vec;
	return os;
}


