const int inf = 1e9;

template <class T> vector<int> compress(const vector<T> &orig) {
	vector<int> ret(orig.size());
	vector<T> a(orig);
	sort(a.begin(), a.end()); a.erase(unique(a.begin(), a.end()), a.end());
	for (size_t i = 0; i < orig.size(); i++) {
		ret[i] = distance(a.begin(), lower_bound(a.begin(), a.end(), orig[i]));
	}
	return ret;
}

ll countInv(vi A) {
	int n = sz(A);
	A = compress(A);
	BinaryIndexedTree0<int> ft(n);
	ll ret = 0;
	rep(i, n) {
		ret += ft.sum(A[i], n);
		ft.add(A[i], 1);
	}
	return ret;
}

ll solve() {
	int n = ri();

	string C;
	vi B(n), W(n);
	rep(i, n * 2) {
		char c = rs()[0];
		int x = ri()-1;
		if (c == 'B') B[x] = i;
		else W[x] = i;
		C += c;
	}

	ll invW = countInv(W), invB = countInv(B);
	out(invW, invB);

	vi RB(2*n+1), RW(2*n+1);
	rep(i, 2*n) {
		RB[i+1] = RB[i];
		RW[i+1] = RW[i];
		if (C[i] == 'B') {
			RB[i+1]++;
		}
		else {
			RW[i+1]++;
		}
	}
	out(C, RB, RW);
	out(B, W);

	vvi dp(n+1, vi(n+1, inf));
	dp[0][0] = 0;

	BinaryIndexedTree0<int> ftB(n*2+2);
	rep(i, n) {
		BinaryIndexedTree0<int> ftW(n*2+2);
		rep(j, n) {
			out(i,j,dp[i][j], ftB, ftW);
			{
				int pos = B[i];
				int nuku = RW[pos+1] - ftW.sum(pos+1);
				amin(dp[i+1][j], dp[i][j] + nuku);
				out(i,j,pos,nuku, dp[i+1][j]);
			}
			{
				int pos = W[j];
				int nuku = RB[pos+1] - ftB.sum(pos+1);
				amin(dp[i][j+1], dp[i][j] + nuku);
				out(i,j,pos,nuku, dp[i][j+1]);
			}
			out(i,j,dp[i][j], dp[i+1][j], dp[i][j+1]);
			ftW.add(W[j], 1);
		}
		ftB.add(B[i], 1);
	}

	out(dp);

	ll ans = inf;
	rep(i, n) {
		amin(ans, dp[i][n]);
		amin(ans, dp[n][i]);
	}
	out(ans);

	return ans + invW + invB;

}

void Main() {
	cout << solve() << endl;
}
