      B.pb(A[y++]);
    }else if(y == r){
      res += bs - x + l;
      B.pb(A[x++]);
    }else{
      //A[x] <= A[y] でイコールを含める転倒数
      if(A[x] < A[y]){
        res += bs - x + l;
        B.pb(A[x++]);
      }else{
        B.pb(A[y++]);
      }
    }
  }
  for(ll i = l; i < r; i++) A[i] = B[i-l];
  return res;
}


void solve(){
  ll N;
  cin >> N;
  vector<ll> A(2 * N);
  rep(i, 2 * N){
    char c;
    cin >> c >> A[i];
    if(c == 'W') A[i] *= -1;
  }
  map<ll, ll> mp;
  rep(i, 2 * N){
    mp[A[i]] = i;
  }
  ll b = 0, w = 0;
  vector<ll> B;
  while(b != N || w != N){
    if(b == N){
      B.pb(-(w+1));
      w++;
    }else if(w == N){
      B.pb(b+1);
      b++;
    }else if(mp[(b+1)] < mp[-(w+1)]){
      B.pb(b+1);
      b++;
    }else{
      B.pb(-(w+1));
      w++;
    }
  }

  vector<ll> C(2 * N);
  rep(i, 2 * N){
    C[mp[B[i]]] = i;
  }

  ll ans = tnt(0, 2 * N, C);
  cout << ans << endl;
}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

