        } else {
            p[1][a[i]] = i+1;
        }
    }

    int res = 0;
    while (s0 <= n || s1 <= n) {
        int u0 = p[0][s0], u1 = p[1][s1];
        int v0 = (s0 <= n ? u0-bit.sum(u0)-1 : inf);
        int v1 = (s1 <= n ? u1-bit.sum(u1)-1 : inf);
        if (v0 < v1) {
            res += v0;
            bit.add(u0, 1);
            s0++;
        } else {
            res += v1;
            bit.add(u1, 1);
            s1++;
        }
    }
    return res;
}

