int bfreq[2010][2010]; // bfreq[i][j] -> 白をj個置いた状態で、i個目の黒を置いた時の、転置数

int rec(int w, int b){
    if(dp[w][b] >= 0) return dp[w][b];
    int res = 1<<29;
    if(w == 0 && b == 0){
        res = 0;
    }
    else{
        if(w > 0){
            res = min(res, rec(w - 1, b) + wfreq[w][b]);
        }
        if(b > 0){
            res = min(res, rec(w, b - 1) + bfreq[b][w]);
        }
    }

    return dp[w][b] = res;
}

