  //i番目の要素にx加算(0 オリジン)
  void add(ll i,ll x){
    assert( i >= 0 && i <= n );
    i+=2;

    while(i <= n){
      bit[i] = (bit[i] + x);
      i += i & -i;
    }
  }

  ll sum(int l,int r){ //[l, r)
    assert(l <= r);
    assert( 0 <= l && l <= n);
    assert( 0 <= r && r <= n);
    return sum(r) - sum(l);
  }
};


const int N = 2001;
int n;
vector<P> W,B;
int used[N][N],mem[N][N];

int dfs(int i,int j, BIT &A){
  if(i == n && j == n) return 0;
  if(used[i][j]++) return mem[i][j];
  int a = INF, b = INF;

    if(i != n) {
      int idx = W[i].second;
      int cost = A.sum(0, idx);
      A.add(idx, -1);
      a = cost + dfs(i+1,j, A);
      A.add(idx, 1);
    }

    if(j != n){
      int idx = B[j].second;
      int cost = A.sum(0, idx);
      A.add(idx, -1);
      b = cost + dfs(i, j+1, A);
      A.add(idx, 1);
    }
    int res = min(a, b);
    return mem[i][j] = res;
}

