long long solve() {
    // iB[j] = (B, j) が何番目か
    // iW[j] = (W, j) が何番目か
    // nB[i][j] = [0, i) の範囲に、(B, j 以上) が何個あるか
    // nW[i][j] = [0, i) の範囲に、(W, j 以上) が何個あるか
    vector<int> iB(N+1, 0), iW(N+1, 0);
    vector<vector<int>> nB(N*2+1, vector<int>(N+1, 0));
    vector<vector<int>> nW(N*2+1, vector<int>(N+1, 0));
    for (int i = 0; i < N*2; ++i) {
        if (c[i] == 'B') iB[a[i]] = i;
        else iW[a[i]] = i;
    }
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N*2; ++i) {
            int nbadd = 0, nwadd = 0;
            if (c[i] == 'B' && a[i] >= j) ++nbadd;
            if (c[i] == 'W' && a[i] >= j) ++nwadd;
            nB[i+1][j] = nB[i][j] + nbadd;
            nW[i+1][j] = nW[i][j] + nwadd;
        }
    }

    // DP
    vector<vector<long long>> dp(N+2, vector<long long>(N+2, INF));
    dp[0][0] = 0;
    for (int b = 0; b <= N; ++b) {
        for (int w = 0; w <= N; ++w) {
            int inb = b+w + nB[iB[b]][b] + nW[iB[b]][w]; // (B, b) が何番目にあるか
            int inw = b+w + nW[iW[w]][w] + nB[iW[w]][b]; // (W, w) が何番目にあるか

            //cout << b << ", " << w << ": " << inb << ", " << inw << ";; " << dp[b][w] << endl;

            chmin(dp[b+1][w], dp[b][w] + abs(inb - (b+w)));
            chmin(dp[b][w+1], dp[b][w] + abs(inw - (b+w)));
        }
    }
    return dp[N][N];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (cin >> N) {
        c.resize(N*2); a.resize(N*2);
        for (int i = 0; i < N*2; ++i) cin >> c[i] >> a[i], --a[i];
        cout << solve() << endl;
    }
}

