const int N = 2e3 + 7;
int n, pos[2][N];
struct Fenwick {
	static const int N = ::N << 1;
	int a[N], n;
	void ini(int _n) { fill_n(a + 1, n = _n, 0); }
	void add(int p, int v) { for (; p <= n; p += p & -p) a[p] += v; }
	int qry(int p) { int r = 0; for (; p; p -= p & -p) r += a[p]; assert(r >= 0); return r; }
}	fen;
int dp[N << 1][N];
int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(0);
	cin >> n;
	rep(i, 1, n << 1 | 1) {
		char ch; int id; cin >> ch >> id;
		pos[ch == 'B'][id] = i;
	}
	dp[0][0] = 0;
	fen.ini(n << 1);
	rep(i, 1, n << 1 | 1) fen.add(i, 1);
	rep(i, 1, n << 1 | 1) {
		rep(j, 1, min(n, i) + 1) fen.add(pos[0][j], -1);
		rep(j, 0, min(n, i) + 1) { // j black balls
			if (j > 0) fen.add(pos[1][j], -1);
			if (i - j <= n) {
				int &d = dp[i][j]; d = INT_MAX;
				if (j - 1 >= 0) d = min(d, dp[i - 1][j - 1] + fen.qry(pos[1][j]));
				if (i - 1 >= j) d = min(d, dp[i - 1][j] + fen.qry(pos[0][i - j]));
			}
			if (i - j > 0 && i - j <= n) fen.add(pos[0][i - j], 1);
		}
		rep(j, min(n, i) + 1, i) fen.add(pos[0][i - j], 1);
		rep(j, 1, min(n, i) + 1) fen.add(pos[1][j], 1);
	}
	cout << dp[n << 1][n];
	return 0;
}

