const int MAXN = 2005;
const int INF = 1e9;
template <typename T> void chkmax(T &x, T y) {x = max(x, y); }
template <typename T> void chkmin(T &x, T y) {x = min(x, y); } 
template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
template <typename T> void write(T x) {
	if (x < 0) x = -x, putchar('-');
	if (x > 9) write(x / 10);
	putchar(x % 10 + '0');
}
template <typename T> void writeln(T x) {
	write(x);
	puts("");
}
int n, a[MAXN * 2];
int fb[MAXN][MAXN], fw[MAXN][MAXN], dp[MAXN][MAXN];
char type[MAXN * 2];
int main() {
	read(n);
	int tans = 0;
	for (int i = 1; i <= 2 * n; i++) {
		char opt = getchar();
		while (opt != 'B' && opt != 'W') opt = getchar();
		type[i] = opt; read(a[i]);
		for (int j = 1; j <= i - 1; j++)
			tans += type[i] == type[j] && a[i] < a[j];
	}
	static bool eb[MAXN], ew[MAXN];
	for (int i = 2 * n; i >= 1; i--) {
		if (type[i] == 'B') {
			for (int j = 1; j <= n; j++)
				fb[a[i]][j] = fb[a[i]][j - 1] + ew[j];
		} else {
			for (int j = 1; j <= n; j++)
				fw[a[i]][j] = fw[a[i]][j - 1] + eb[j];
		}
		if (type[i] == 'B') eb[a[i]] = true;
		else ew[a[i]] = true;
	}
	for (int i = 0; i <= n; i++)
	for (int j = 0; j <= n; j++) {
		if (i == 0 && j == 0) dp[i][j] = 0;
		else dp[i][j] = INF;
		if (i != 0) chkmin(dp[i][j], dp[i - 1][j] + fb[i][j]);
		if (j != 0) chkmin(dp[i][j], dp[i][j - 1] + fw[j][i]);
	}
	writeln(dp[n][n] + tans);
	return 0;
}

