        cntw[i][N] = w[N];
        for(int j = N-1; j >= 0; j--){
            cntb[i][j] = cntb[i][j+1] + b[j];
            cntw[i][j] = cntw[i][j+1] + w[j];
        }
    }

    for(int i = 0; i <= N; i++){
        for(int j = 0; j <= N; j++){
            if(i == 0 && j == 0) dp[i][j] = 0;
            else if(i == 0){
                dp[i][j] = dp[i][j-1]+cntb[B[j]][j+1]+cntw[B[j]][i+1];
            }else if(j == 0){
                dp[i][j] = dp[i-1][j]+cntb[W[i]][j+1]+cntw[W[i]][i+1];
            }else{
                dp[i][j] = min(dp[i-1][j]+cntb[W[i]][j+1]+cntw[W[i]][i+1], dp[i][j-1]+cntb[B[j]][j+1]+cntw[B[j]][i+1]);
            }
        }
    }
    cout << dp[N][N] << endl;
}

