	using RET = int;
	constexpr int BUF = 1123456;
	int ptr = 0;
	RET t[BUF];
	inline RET* get(const int size) {
		ptr += size;
		return t + ptr - size;
	}
	inline void reset() {
		ptr = 0;
	}
}
//[1,n],0は扱えない!
struct BIT {
	using T = BIT_::RET;
	T* bit;
	int sz;
	BIT(int n) :bit(BIT_::get(n + 10)), sz(n) {
		fill(bit, bit + n + 10, 0);
	}
	T sum(int i) {
		T s = 0;
		while (i>0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	T sum(int lb, int ub) {
		return sum(ub) - sum(lb - 1);
	}
	void add(int i, T x) {
		while (i <= sz) {
			bit[i] += x; i += i & -i;
		}
	}
};

