template<typename T>
struct Segtree{
    int n;
    T op;
    vector<T> elm;
    function<T(T, T)> f;

    Segtree(int n, T init, function<T(T, T)> f, T op = T()) :
        n(n),
        op(op),
        elm(2 * n, init),
        f(f)
    {
    }

    void set(int x, T val){
        x += n;
        elm[x] = val;
        while(x >>= 1)
            elm[x] = f(elm[2 * x], elm[2 * x + 1]);
    }

    void update(int x, T val){
        x += n;
        elm[x] = f(val, elm[x]);
        while(x >>= 1)
            elm[x] = f(elm[2 * x], elm[2 * x + 1]);
    }

    T get(int x, int y) const{
        T val = op;
        for(x += n, y += n - 1; x <= y; x >>= 1, y >>= 1){
            if(x & 1)
                val = f(val, elm[x++]);
            if(!(y & 1))
                val = f(val, elm[y--]);
        }
        return val;
    }
};


signed main(){
    int n;
    cin >> n;
    vector<pair<int,int>> a;
    vector<vector<int>> t(2, vector<int>(n));
    for(int i = 0; i < 2 * n; ++i){
        string s;
        int x;
        cin >> s >> x;
        a.emplace_back(s == "B", --x);
        t[s == "B"][x] = i;
    }
    // v[i][j]: dp[i][j]で遷移に必要な値
    vector<vector<vector<int>>> v(n + 1, vector<vector<int>>(n + 1, vector<int>(2, MOD)));
    for(int i = 0; i <= n; ++i){
        Segtree<int> seg(2 * n, 0, [](int x, int y){return x + y;});
        for(int j = 0; j < i; ++j)
            seg.set(t[0][j], 1);
        for(int j = 0; j <= n; ++j){

            int pos_i = t[0][i];
            int pos_j = t[1][j];
            v[i][j][0] = pos_i - seg.get(0, pos_i);
            v[i][j][1] = pos_j - seg.get(0, pos_j);

            if(j != n)
                seg.set(t[1][j], 1);
        }
    }


    vector<vector<int>> dp(n + 1, vector<int>(n + 1, MOD));
    dp[0][0] = 0;

    for(int i = 0; i <= n; ++i){
        for(int j = 0; j <= n; ++j){
            if(i != n)
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + v[i][j][0]);
            if(j != n)
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + v[i][j][1]);
        }
    }

    cout << dp[n][n] << endl;
}

