int main() {
  aim_cpo; // インタラクティブのときは消すように.
#ifdef LOCAL_DEFINE
  LOCAL_INPUT; // インタラクティブのときは消すように.
//  LOCAL_OUTPUT; // ファイルに出力したいときのみ
  show(MOD);
#endif
  // テキトー考察
  //
  // まずはじめに、転倒数のお勉強から.
  // 転倒数は長さnのある数列Aが与えられたとき、0 <= i < j <= n - 1 && A[i] > A[j] となる(i, j)のペアの個数のこと
  // これは有名で、この転倒数の意味を少し一般的に見てみると、
  // 長さnのある数列Aが与えられたときの数列の状態を初期状態とし、最終的になるべき形になった数列の状態を最終状態とする.
  // 0 <= i < nとなるiを決めて、初期状態でA[i]より左にあって、かつ最終状態でA[i]より右にあるものの個数をF[i]とすると、
  // 転倒数は \sum^{n - 1}_{i = 0} F[i] となる.
  // 要は、最初自分より左にあって、最後には自分より右にあるようなものの個数をすべての要素に対して求めたものの合計の個数を転倒数という.
  // 何が言いたいかというと、数列の初期状態と最終状態さえわかってしまえば転倒数は求めることができる.
  // 今回の問題は初期状態が与えられているけど、最終状態がわからないので難しい.
  // 最終状態になれるような数列の並びのパターン数が多すぎるので、最小の転倒数を求めれない.
  // dpを使って求めていく.
  // dp[i][j] := 白をi個、黒をj個並べるときの最小コストとする.
  // 遷移は...
  // dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + costW[j][i]);
  // dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + costB[i][j]);
  // 求める値はdp[n][n]
  // costBは初期状態で黒がj個、白がi個'既に'並べられている、
  // 最終状態で黒がj個、白がi個並べられているすぐ右に黒のj + 1番目を並べる この場合でのF[j + 1].
  // 自分の左にいる黒(n - 1~j + 1)と白(n - 1~i)の合計の数が求まれば、costB[i][j]は求まる. BITを使って求めてね.O(n^2logn)
  // costWも全く同じ方法で求まる.
  // 
  // 最終状態がわかれば、転倒数はもとまる.
  // でも、最終状態がわからないので、dpで次に来るのが白なのか、黒なのかを探索する.
  // 次に来る要素が決まれば、それがその場所に来るまでにどれだけスワップしなければいけないかを求めなくてはいけないので
  // 事前に転倒数の部分解的なやつを求めておく.
  // 今回の問題はこんな感じの流れ.
  cin >> n;
  v.resize(2 * n);
  rep(i, 0, 2 * n) {
    cin >> v[i].fi >> v[i].se;
    v[i].se--;
  }
  rep(i, 0, n + 1) {
    BIT<ll> bit(n);
    ll white = 0;
    rep(j, 0, 2 * n) {
      if (v[j].fi == 'W') {
        if (v[j].se >= i) white++;
        continue;
      }
      costB[i][v[j].se] = bit.sum(v[j].se + 1, n - 1) + white;
      bit.update(v[j].se, 1);
    }
  }
  rep(i, 0, n + 1) {
    BIT<ll> bit(n);
    ll black = 0;
    rep(j, 0, 2 * n) {
      if (v[j].fi == 'B') {
        if (v[j].se >= i) black++;
        continue;
      }
      costW[i][v[j].se] = bit.sum(v[j].se + 1, n - 1) + black;
      bit.update(v[j].se, 1);
    }
  }
  rep(i, 0, 2001) rep(j, 0, 2001) dp[i][j] = LL_INF;
  dp[0][0] = 0;
  rep(i, 0, n + 1) {
    rep(j, 0, n + 1) {
      if (dp[i][j] == LL_INF) continue;
      if (i + 1 <= n) chmin(dp[i + 1][j], dp[i][j] + costW[j][i]);
      if (j + 1 <= n) chmin(dp[i][j + 1], dp[i][j] + costB[i][j]);
    }
  }
  cout << dp[n][n] << endl;
#ifdef  LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s." << endl;
#endif
  return 0;
}

