int n;

struct SegmentTree{
	std::vector<int> seg;
	int sz = 1;

	SegmentTree(int n){
		while(sz < n) sz *= 2;
		seg.assign(sz * 2, 0);
	}

	void add(int k){
		k += sz - 1;
		seg[k]++;

		while(k){
			k = (k - 1) / 2;
			seg[k] = seg[2 * k + 1] + seg[2 * k + 2];
		}
	}

	int get(int a, int b){
		return get(a, b, 0, 0, sz);
	}

	int get(int a, int b, int k, int l, int r){
		if(b<=l||r<=a) return 0;
		if(a<=l&&r<=b) return seg[k];

		return get(a, b, 2 * k + 1, l, (l + r) / 2) + get(a, b, 2 * k + 2, (l + r) / 2, r);
	}

	int binary(int k){
		if(get(k, n) == 0) return k;

		int ok = n, ng = k + 1;

		while(abs(ok - ng) > 1){
			int mid = (ok + ng) / 2;

			if(get(k, mid)) ok = mid;
			else ng = mid;
		}

		return ok - 1;
	}
};

int main(){
	cin >> n; SegmentTree A(n), B(n);
	std::vector<std::pair<char, int>> vec(2 * n); int ans = 0;
	for(int i = 0; i < 2 * n; i++){
		char x; int y; cin >> x >> y; y--;
		vec[i] = {x, y};

		if(x == 'W'){
			int k = A.binary(y);

			if(k > y)
			for(int j = i; j > 0; j--){
				ans++; std::swap(vec[j], vec[j - 1]);
				if(vec[j].first == 'W' and vec[j].second == k) break;
			}

			A.add(y);
		}else if(x == 'B'){
			int k = B.binary(y);

			if(k > y)
			for(int j = i; j > 0; j--){
				ans++; std::swap(vec[j], vec[j - 1]);
				if(vec[j].first == 'B' and vec[j].second == k) break;
			}

			B.add(y);
		}
	}

	cout << ans << endl;
	return 0;
}

