class UnionFind {
public:
    vi par;
    vi rank;

    UnionFind(int n) {
        par = vi(n);
        iota(all(par), 0);
        rank = vi(n, 0);
    }

    int root(int x) {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);

        if (rank[x] < rank[y])
            swap(x, y);
        par[y] = x;

        if (rank[x] == rank[y])
            rank[x]++;
    }
};

