int solve() {
    int N;
    cin >> N;

    vector<pair<int, char>> ball(2 * N);
    map<int, int> white, black;
    for (int i = 0; i < 2 * N; ++i) {
        cin >> ball[i].sn >> ball[i].fi;
        if (ball[i].sn == 'W')
            white[ball[i].fi] = i;
        else
            black[ball[i].fi] = i;
    }

    int c_white = 1, c_black = 1;
    int res = 0;

    auto swapper = [&](pair<int, char> &b1, pair<int, char> &b2) {
        if (b1.sn == 'W') {
            if (b2.sn == 'W') swap(white[b1.fi], white[b2.fi]);
            if (b2.sn == 'B') swap(white[b1.fi], black[b2.fi]);
        } else {
            if (b2.sn == 'W') swap(black[b1.fi], white[b2.fi]);
            if (b2.sn == 'B') swap(black[b1.fi], black[b2.fi]);
        }
        swap(b1, b2);
    };

    rep(i, 2 * N) {
        if (ball[i].sn == 'W') {
            if (ball[i].fi == c_white) {
                c_white++;
                continue;
            }
        } else {
            if (ball[i].fi == c_black) {
                c_black++;
                continue;
            }
        }

        bool isW = white[c_white] < black[c_black];
        int npos = isW ? white[c_white] : black[c_black];

        // forbidden
        if (c_white > N) isW = false, npos = black[c_black];
        if (c_black > N) isW = true, npos = white[c_white];

        RREP(j, i, npos) {
            res++;
            swapper(ball[j], ball[j + 1]);
        }
        isW ? c_white++ : c_black++;
    }

    return res;
}

