        updBIT(pos[0][w], 1);
    }
    if(b < n){
        updBIT(pos[1][b], -1);
        ret = min(1ll*ret, sumBIT(pos[1][b]) + f(w, b+1));
        updBIT(pos[1][b], 1);
    }

    return dp[w][b] = ret;
}

