char c[maxn];
int a[maxn], per_w[maxn], per_b[maxn];
int dp[maxn][maxn];
int fen[maxn + 100];

int get (int idx) {
	int ret = 0;
	for (; idx; idx -= idx & -idx)
		ret += fen[idx];
	return ret;
}

int get (int l, int r) {
	return get (r) - get (l - 1);
}


void change (int idx, int x) {
	for (; idx < maxn; idx += idx & -idx)
		fen[idx] += x;
}

int main () {
	ios_base::sync_with_stdio (false);
	int n;
	cin >> n;
	for (int i = 1; i <= 2 * n; i++) {
		cin >> c[i] >> a[i];
		if (c[i] == 'W')
			per_w[a[i]] = i;
		else
			per_b[a[i]] = i;
	}
	for (int i = 0; i <= n; i++) {
		if (i != 0)
			change (per_w[i], 1);
		for (int j = 0; j <= n; j++) {
			if (i == 0 and j == 0)
				continue;
			if (j != 0)
				change (per_b[j], 1);

			if (i == 0) {
				int idx = per_b[j];
				dp[i][j] = dp[i][j - 1] + get (idx + 1, 2 * n);
			}
			else if (j == 0) {
				int idx = per_w[i];
				dp[i][j] = dp[i - 1][j] + get (idx + 1, 2 * n);
			}
			else {
				int idx = per_b[j];
				dp[i][j] = dp[i][j - 1] + get (idx + 1, 2 * n);
				idx = per_w[i];
				dp[i][j] = min (dp[i][j], dp[i - 1][j] + get (idx + 1, 2 * n));
			}
		}
		for (int j = 1; j <= n; j++)
			change (per_b[j], -1);
	}
	cout << dp[n][n] << endl;
	return 0;
}

