using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

//------------------------------------------------------------------------------
const int BIT_SIZE = 2000;

struct BIT {
  int n;
  int bit[BIT_SIZE + 1];

  BIT() {}
  BIT(int _n) {
    n = _n;
  }

  int sum(int i) {
    int s = 0;
    while(i > 0) {
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, int x) {
    while (i <= n) {
      bit[i] += x;
      i += i & -i;
    }
  }
};

//------------------------------------------------------------------------------
const int N_MAX = 2000;
const int K_MAX = N_MAX * 2;
const int INF = 1e9;

int N, K;
int c[K_MAX];
int a[K_MAX];

BIT *bs[2];
int mv[2][N_MAX + 1][N_MAX + 1];
int dp[N_MAX + 1][N_MAX + 1];

void solve() {
  REP(i, 2) bs[i] = new BIT(N);
  REP(i, K) {
    int c1 = c[i];
    int c2 = 1 - c1;
    int num = a[i];
    int sw1 = bs[c1]->sum(N) - bs[c1]->sum(num);
    FOR(j, 0, N) {
      int sw2 = bs[c2]->sum(N) - bs[c2]->sum(j);
      if (c1 == 0) mv[c1][num - 1][j] = sw1 + sw2;
      else mv[c1][j][num - 1] = sw1 + sw2;
    }
    bs[c1]->add(num, 1);
  }

  // DUMP2D(mv[0], N + 1, N + 1);
  // DUMP2D(mv[1], N + 1, N + 1);

  fill(dp[0], dp[N + 1], INF);
  dp[0][0] = 0;
  FOR(i, 0, N) FOR(j, 0, N) {
    if (i > 0) dp[i][j] = min(dp[i][j], dp[i - 1][j] + mv[0][i - 1][j]);
    if (j > 0) dp[i][j] = min(dp[i][j], dp[i][j - 1] + mv[1][i][j - 1]);
  }
  printf("%d\n", dp[N][N]);
}

void input() {
  scanf("%d", &N);
  K = N * 2;
  REP(i, K) {
    char buf[2];
    scanf("%s%d", buf, a + i);
    c[i] = (buf[0] == 'W' ? 0 : 1);
  }
}

int main() {
  input();
  solve();
  return 0;
}

