int BIT[MAXN];
void updBIT(int p, int val){
    p++;
    for(; p < MAXN; p += p&-p) BIT[p] += val;
}
int sumBIT(int p){
    p++;
    int ret = 0;
    for(; p; p -= p&-p) ret += BIT[p];
    return ret;
}

int dp[MAXN][MAXN];
int pos[2][MAXN];
int n;

int f(int w, int b){
    if(dp[w][b] != -1) return dp[w][b];
    if(w == n && b == n) return 0;
    int ret = INF;
    if(w < n){
        updBIT(pos[0][w], -1);
        ret = min(ret, sumBIT(pos[0][w]) + f(w+1, b));
        updBIT(pos[0][w], 1);
    }
    if(b < n){
        updBIT(pos[1][b], -1);
        ret = min(ret, sumBIT(pos[1][b]) + f(w, b+1));
        updBIT(pos[1][b], 1);
    }

    return dp[w][b] = ret;
}

