inline int _read_char() {
  return getchar();
  static char buf[1 << 16], *ptr = buf, *end_ptr = buf;
  if (ptr == end_ptr) {
    int len = fread(buf, 1, sizeof(buf), stdin);
    if (len <= 0) return EOF;
    ptr = buf;
    end_ptr = buf + len;
  }
  return *ptr++;
}

inline char rch() {
  char ch=_read_char();
  while(ch=='\0'||ch=='\n') ch=_read_char();
  return ch;
}

inline int rint() {
  int ch; bool sg = 0;
  do {
    ch = _read_char();
    if (ch == '-') sg = 1;
  } while (ch < '0' || ch > '9');
  int x = ch - '0';
  while (true) {
    ch = _read_char();
    if (ch < '0' || ch > '9') break;
    x = x * 10 + ch - '0';
  }
  return (sg?-x:x);
}

inline long long rlong() {
  int ch; bool sg = 0;
  do {
    ch = _read_char();
    if (ch == '-') sg = 1;
  } while (ch < '0' || ch > '9');
  long long x = ch - '0';
  while (true) {
    ch = _read_char();
    if (ch < '0' || ch > '9') break;
    x = x * 10 + ch - '0';
  }
  return (sg?-x:x);
}

