void init(int t,int k, int l, int r) {
	if (r - l == 1) {
		dat[t][k].push_back(p[t][l]); return;
	}
	int lb = k * 2 + 1, rb = k * 2 + 2;
	init(t,lb, l, (l + r) / 2);
	init(t,rb, (l + r) / 2, r);
	dat[t][k].resize(r - l);
	merge(dat[t][lb].begin(), dat[t][lb].end(), dat[t][rb].begin(), dat[t][rb].end(), dat[t][k].begin());
}
int query(int t,int a, int b, int c, int d, int k, int l, int r) {//[a,b),[c,d)
	if (b <= l || r <= a)return 0;
	if (a <= l&&r <= b) {
		int u = lower_bound(dat[t][k].begin(), dat[t][k].end(), d) - dat[t][k].begin();
		int v = lower_bound(dat[t][k].begin(), dat[t][k].end(), c) - dat[t][k].begin();
		return u - v;
	}
	int lb = query(t,a, b, c, d, k * 2 + 1, l, (l + r) / 2);
	int rb = query(t,a, b, c, d, k * 2 + 2, (l + r) / 2, r);
	return lb + rb;
}

