const int INF = (int)1e9 + 7;
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

int main() {
    int n; cin >> n;
    vector<pair<char, int>> ca(n * 2);
    for (auto &p: ca) cin >> p.first >> p.second, p.second--;
    vector<vector<int>> black(n, vector<int>(n + 1));
    vector<vector<int>> white(n, vector<int>(n + 1));
    {
        vector<bool> b(n), w(n);
        for (auto &p: ca) {
            char c = p.first;
            int i = p.second;
            vector<int> ge_b(n + 1), ge_w(n + 1);
            for (int j = n - 1; j >= 0; j--) {
                ge_b[j] = ge_b[j + 1] + b[j];
                ge_w[j] = ge_w[j + 1] + w[j];
            }
            for (int j = n; j >= 0; j--) {
                if (c == 'B') black[i][j] = ge_b[i + 1] + ge_w[j];
                if (c == 'W') white[i][j] = ge_b[j] + ge_w[i + 1];
            }
            (c == 'B' ? b[i] : w[i]) = true;
        }
    }
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, INF));
    dp[0][0] = 0;
    for (int i = 0; i <= n; i++) for (int j = 0; j <= n; j++) {
        if (i < n) chmin(dp[i + 1][j], dp[i][j] + black[i][j]);
        if (j < n) chmin(dp[i][j + 1], dp[i][j] + white[j][i]);
    }
    cout << dp[n][n] << endl;
    return 0;
}

