using namespace std;

vector<pair<char, int>> balls;
VI whites;
VI blacks;
int N;
int wmore[2048];
int bmore[2048];

int mem[2048][2048];
int wcost[2048][2048];
int bcost[2048][2048];

int main(int argc, const char* argv[]) {
	scanf("%d\n", &N);

	balls.resize(2 * N);
	whites.resize(N);
	blacks.resize(N);
	{
		int i = 0;
		foreach (b, balls) {
			scanf("%c %d\n", &b.first, &b.second);
			b.second--;
			if (b.first == 'W')
				whites[b.second] = i;
			else
				blacks[b.second] = i;
			i++;
		}
	}

	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++)
			if (whites[j] < whites[i])
				wmore[j]++;
	}

	for (int i = 0; i < N; i++) {
		for (int j = i+1; j < N; j++)
			if (blacks[j] < blacks[i])
				bmore[j]++;
	}

	{
		VI wpos(whites);
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j < N; j++) {
				int mypos = wpos[j] + wmore[j];
				int needpos = i + j;
				wcost[i][j] = mypos - needpos;
			}
			if (i < N) {
				int bb = blacks[i];
				for (int j = 0; j < N; j++)
					if (whites[j] < bb) {
						wpos[j]++;
					}
			}
		}
	}

	{
		VI bpos(blacks);
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j < N; j++) {
				int mypos = bpos[j] + bmore[j];
				int needpos = i + j;
				bcost[i][j] = mypos - needpos;
			}
			if (i < N) {
				int ww = whites[i];
				for (int j = 0; j < N; j++)
					if (blacks[j] < ww) {
						bpos[j]++;
					}
			}
		}
	}

	mem[0][0] = 0;
	for (int i = 1; i <= N; i++) {
		mem[i][0] = mem[i-1][0] + wcost[0][i-1];
	}

	for (int i = 1; i <= N; i++) {
		mem[0][i] = mem[0][i-1] + bcost[0][i-1];
	}

	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			mem[i][j] = min(mem[i-1][j] + wcost[j][i-1], mem[i][j-1] + bcost[i][j-1]);
		}
	}

	printf("%d\n", mem[N][N]);

	return 0;
}

