using Data = int;
const int len = 1 << 12;

struct BIT {
  vector<Data> data;
  BIT() : data(len, 0) {}
  void update(int i, Data value) {
    for (; i < len; i |= i+1) data[i] += value;
  }
  Data query(int i) {
    Data s = 0;
    for (; i >= 0; i = (i&i+1)-1) s += data[i];
    return s;
  }
};

int main()
{
  int n;
  cin>>n;
  int m=2*n;
  vector<pair<bool, int>> v(m);
  vecint bpos(n);
  vecint wpos(n);
  REP(i,m) {
    string s;
    int a;
    cin>>s>>a;
    --a;
    v[i] = make_pair(s=="B", a);
    if (s=="B") {
      bpos[a] = i;
    } else {
      wpos[a] = i;
    }
  }
  vector<vecint> bcnt(n+1, vecint(m+1));
  vector<vecint> wcnt(n+1, vecint(m+1));
  REP(i,n+1) {
    bcnt[i][0] = 0;
    wcnt[i][0] = 0;
    REP(j,m) {
      bool c;
      int a;
      tie(c,a) = v[j];
      bcnt[i][j+1] = bcnt[i][j] + (c && a < i ? 1 : 0);
      wcnt[i][j+1] = wcnt[i][j] + (!c && a < i ? 1 : 0);
    }
  }
  constexpr int INF = 1e9;
  vector<vecint> costb(n+1, vecint(n+1, 0));
  vector<vecint> costw(n+1, vecint(n+1, 0));
  REP(i,n+1) {
    REP(j,n+1) {
      int bi = bpos[i];
      costb[i][j] = i+j-bcnt[i][bi]-wcnt[j][bi];
      int wj = wpos[j];
      costw[i][j] = i+j-bcnt[i][wj]-wcnt[j][wj];
    }
  }
  vector<vecint> dp(n+1, vecint(n+1, INF));
  dp[0][0] = 0;
  REP(i,n+1) {
    REP(j,n+1) {
      if (i) dp[i][j] = min(dp[i][j], dp[i-1][j] + costb[i-1][j]);
      if (j) dp[i][j] = min(dp[i][j], dp[i][j-1] + costw[i][j-1]);
    }
  }
  cout<<dp[n][n]<<endl;
  return 0;
}

