//ARC 097 E Sorted and Sorted
/*
dp[i][j]:左からi個黒、j個白が埋まってるとした時の最小回数とすれば良い
dp[i+1][j]を考えるときに、i+1が書かれた黒ボールを(i+j+1)番目におけば良い
そのための操作回数は初期状態でi+1が書かれた黒ボールよりも左にある、
i+2以上の黒ボールの数とj+1以上の白ボールの数の合計値になる
これを前計算
*/
int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin>>n;
	vector<state> g(2*n);
	rep(i,2*n){
		cin>>g[i].c>>g[i].a;
		g[i].a--;
	}
	vector<vector<int>> dp(n+1,vector<int>(n+1,INF));
	vector<vector<int>> black(n+1,vector<int>(n+1,0));
	vector<vector<int>> white(n+1,vector<int>(n+1,0));
	vector<vector<int>> sumb(n+1,vector<int>(2*n+1,0));
	vector<vector<int>> sumw(n+1,vector<int>(2*n+1,0));
	rep(i,n){//位置xまでにある黒i以上の個数を求める(白も同様)
		rep(x,2*n){
			char color=g[x].c;
			int num=g[x].a;
			sumb[i][x+1]=sumb[i][x];
			sumw[i][x+1]=sumw[i][x];
			if(color=='B'){
				if(num>=i) sumb[i][x+1]++;
			}else{
				if(num>=i) sumw[i][x+1]++;
			}
		}
	}
	rep(x,2*n){//black[i][j]:黒iの位置xより左にある黒i以上,白j以上のボールの個数
		char color=g[x].c;
		int num=g[x].a;
		rep(j,n+1){
			if(color=='B'){
				black[num][j]=sumb[num][x]+sumw[j][x];
			}else{
				white[num][j]=sumw[num][x]+sumb[j][x];
			}
		}
	}
	dp[0][0]=0;
	rep(i,n+1)rep(j,n+1){
		if(i+1<=n) chmin(dp[i+1][j],dp[i][j]+black[i][j]);
		if(j+1<=n) chmin(dp[i][j+1],dp[i][j]+white[j][i]);
	}
	cout<<dp[n][n]<<endl;
}

