int val[1<<15];
void change(int num,int l,int r,int x,int k)
{
    if (l==r-1)
    {
        val[num]=k;
        return;
    }
    int mid=(l+r)/2;
    if (x<mid)
    {
        change(num*2+1,l,mid,x,k);
    }
    else
    {
        change(num*2+2,mid,r,x,k);
    }
    val[num]=val[num*2+1]+val[num*2+2];
}
int query(int num,int l,int r,int l0,int r0)
{
    if ((l0<=l)&&(r<=r0))
    {
        return val[num];
    }
    int mid=(l+r)/2;
    int ans=0;
    if (l0<mid)
    {
        ans+=query(num*2+1,l,mid,l0,r0);
    }
    if (mid<r0)
    {
        ans+=query(num*2+2,mid,r,l0,r0);
    }
    return ans;
}
