      }
      if (i - j != 0) {
        if (pos[1][i-j] <= i) add(pos[1][i-j],1);
        else add(pos[1][i-j],-1);
      }
    }
    int en = min(n/2,i) + 1;
    for (int j = 1 ; j <= i ; ++ j)
