int sum(int i)
{
    int s = 0;
    while(i > 0){
        s += bit[i];
        i -= i & -i;
    }
    return s;
}

void add(int i, int x)
{
    while(i <= 2 * N){
        bit[i] += x;
        i += i & -i;
    }
}

int dfs(int w, int b)
{
    if(~dp[w][b])return dp[w][b];
    if(w == N && b == N){
        return dp[w][b] = 0;
    }
    int ret = INF;
    if(w < N){
        int id = pos[w + 1][0];
        add(id, 1);
        int cost = id - sum(id);
        int res = dfs(w + 1, b) + cost;
        add(id, -1);
        ret = min(ret, res);
    }
    if(b < N){
        int id = pos[b + 1][1];
        add(id, 1);
        int cost = id - sum(id);
        int res = dfs(w, b + 1) + cost;
        add(id, -1);
        ret = min(ret, res);
    }
    return dp[w][b] = ret;
}

