int solve(int w, int b) {
    if (w==0 && b==0) return 0;

    int &res = dp[w][b];
    if (~res) return res;

    res = inf;
    int idx = w+b;


    if (w>0) {
	int at = mp[0][w];
	int dist = at-idx;
	for (int i=w+1; i<=n; i++) {
	    if (mp[0][i]<at) dist--;
	}
	for (int i=b+1; i<=n; i++) {
	    if (mp[1][i]<at) dist--;
	}
	//cout<<"w     "<<w<<" "<<b<<": "<<dist<<endl;

	dist = abs(dist);
	res = min(res, solve(w-1,b) + dist);
    }


    if (b>0) {
	int at = mp[1][b];
	int dist = at-idx;

	for (int i=b+1; i<=n; i++) {
	    if (mp[1][i]<at) {
		dist--;
	    }
	}
	for (int i=w+1; i<=n; i++) {
	    if (mp[0][i]<at) {
		dist--;
	    }
	}

	dist = abs(dist);
	res = min(res, solve(w,b-1) + dist);
    }


    return res;
}


