void solve() {
	ll N;
	cin>>N;
	vector<string> c(2*N);
	vector<ll> a(2*N);
	rep(i,2*N){
		cin>>c[i]>>a[i];
	}

	vector<ll> W(2*N),B(2*N);
	map<ll,ll> mW,mB;
	rep(i,2*N){
		if(c[i]=="W"){
			W[i]=a[i];
			mW[a[i]]=i;
		}else{
			B[i]=a[i];
			mB[a[i]]=i;
		}
	}

	constexpr ll bitlength = 1 + log2(2000);
	WaveletMatrix<ll,bitlength> wmW(W);
	WaveletMatrix<ll,bitlength> wmB(B);

	vector<vector<ll>> dp(N+1,vector<ll>(N+1,INF));
	dp[0][0]=0;
	rep(i,N+1)rep(j,N+1){
		if(i<N){
			ll windex=mW[i+1];
			ll maisu1=wmW.rangefreq(0, windex, i+2, N+1);
			ll maisu2=wmB.rangefreq(0, windex, j+1, N+1);
			chmin(dp[i+1][j],dp[i][j]+maisu1+maisu2);
		}
		if(j<N){
			ll bindex=mB[j+1];
			ll maisu3=wmW.rangefreq(0, bindex, i+1, N+1);
			ll maisu4=wmB.rangefreq(0, bindex, j+2, N+1);
			chmin(dp[i][j+1],dp[i][j]+maisu3+maisu4);
		}
	}

	p(dp[N][N]);
}

