  set<int> s1;
  set<int> s2;

  int res = 0;
  for(int i = 2 * n - 1;i >= 0;i--){
    if(a[i].first == 'W'){
      s1.insert(a[i].second);
      auto it = s1.lower_bound(a[i].second);
      if(it != s1.begin()){
        it--;
        int in = i;
        while(a[in + 1].first != 'W' || a[in + 1].second != *it){
          swap(a[in], a[in + 1]);
          in++;
          res++;
        }
        swap(a[in], a[in + 1]);
        res++;
      }
    }else{
      s2.insert(a[i].second);
      auto it = s2.lower_bound(a[i].second);
      if(it != s2.begin()){
        it--;
        int in = i;
        while(a[in + 1].first != 'B' || a[in + 1].second != *it){
          swap(a[in], a[in + 1]);
          in++;
          res++;
        }
        swap(a[in], a[in + 1]);
        res++;
      }
    }
  }
  return res;
}
