int t[maxn];
void add(int x,int d)
{
	while (x && x <= 2*n)
	{
		t[x] += d;
		x += lowbit(x);
	}
}

int sum(int x)
{
	int ret = 0;
	while (x)
	{
		ret += t[x];
		x -= lowbit(x);
	}
	return ret;
}

