		{
			add(pb[j], 1);
			w[i][j] = sum(2 * n) - sum(pw[i + 1]);
		}
		for (int j = 1; j <= n; j++)
		{
			add(pb[j], -1);
		}
	}

	for (int i = 1; i <= n; i++) add(pw[i], -1);

	for (int i = 0; i <= n; i++)
	{
		add(pb[i], 1);
