void in(){
    ios::sync_with_stdio(false);
    cout.tie(0);
    cin.tie(0);
    cin >> n;
    for(int i = 0; i < 2 * n; i++){
        char c;
        int x;
        cin >> c >> x;
        if(c == 'W')
            ind[0][x] = i;
        else
            ind[1][x] = i;
    }
}

void solve(){
    for(int i = 0; i <= n; i++){
        if(i != 0)
            add(0, ind[0][i] + 1, 1);
        for(int j = 0; j <= n; j++){
            if(j != 0)
                add(0, ind[1][j] + 1, 1);
            if(i + j != 0)
                dp[i][j] = 1e9;
            if(i != 0)
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + i + j - get(0, ind[0][i] + 1));
            if(j != 0)
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + j + i - get(0, ind[1][j] + 1));
        }
        for(int j = 1; j <= n; j++)
            add(0, ind[1][j] + 1, -1);
        memset(fen[1], 0, sizeof fen[1]);
    }
}

void out(){
    cout << dp[n][n];
}

void add(int c, int x, int v){
    for(; x <= n * 2; x += x & -x)
        fen[c][x] += v;
}

int get(int c, int x){
    int s = 0;
    for(; x; x -= x & -x)
        s += fen[c][x];
    return s;
}

