    for (int i = 1; i <= 2 * n; i++) {
        for (int j = i + 1; j <= 2 * n; j++) {
            if (s[i][0] == s[j][0] && s[i][0] ^ s[1][0] && a[i] > a[j]) {
                chk[i] = chk[j] = 1;
                mn[j] = min(mn[j], i), mx[i] = max(mx[i], j);
            }
        }
    }
    for (int i = 1; i <= 2 * n; i++) {
