		if(A[i].se == 1) continue;
		for(int j=1; j<i; j++) {
			if(A[j].se == 1) continue;
			if(A[j].fi > A[i].fi) WC[n][A[i].fi] += 1;
		}
	}

	for(int j=0; j<n; j++) {
		int cnt = 0;
		for(int i=1; i<=2*n; i++) {
			if(A[i].se == 0) {
				if(A[i].fi > j) cnt++;
			}
			else {
				BC[A[i].fi][j] = BC[A[i].fi][n] + cnt;
			}
