	for(int i=n; i>=0; i--) {

		for(int j=n; j>=0; j--) {

            if(i == n and j == n) continue;
            else if(i == n) DP[i][j] = WC[i][j+1] + DP[i][j+1];
            else if(j == n) DP[i][j] = BC[i+1][j] + DP[i+1][j];
            else DP[i][j] = min(BC[i+1][j]+ DP[i+1][j], 
                                WC[i][j+1] + DP[i][j+1]);
		}
	}

	cout<<DP[0][0]<<"\n";
	return 0;
}

