#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

int main() {
    ll N;
    cin >> N;

    struct Ball {
        char c;
        ll a;
        bool operator==(Ball rhs) {
            return (c == rhs.c && a == rhs.a);
        }
    };
    vector<Ball> balls(2 * N);
    for (ll i = 0; i < 2 * N; i++) {
        cin >> balls[i].c >> balls[i].a;
    }


    priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> pq[2];
    ll target[2] = { 1, 1 };

    vector<Ball> correct;
    for (ll i = 0; i < 2 * N; i++) {
        ll c = (balls[i].c == 'B' ? 0 : 1);
        pq[c].push({ balls[i].a, i });

        while (!pq[c].empty()) {
            pair<ll, ll> t = pq[c].top();
            if (t.first == target[c]) {
                target[c]++;
                pq[c].pop();
                correct.push_back({ balls[i].c, t.first });
            } else {
                break;
            }
        }
    }

    ll ans = 0;
    for (Ball b : correct) {
        for (ll i = 0; i < balls.size(); i++) {
            if (b == balls[i]) {
                ans += i;
                balls.erase(balls.begin() + i);
                break;
            }
        }
    }

    cout << ans << endl;
}

