    for (int i = 0; i < 2 * N; i++)
    {
        char c;
        int x;
        cin >> c >> x;
        x--;
        if (c == 'B')
            loc[0][x] = i;
        else
            loc[1][x] = i;
    }

    for (int i = 0; i < 2; i++)
    {
        for (int j = 0; j < N; j++)
        {
            int cloc = loc[i][j];
            int res = 0;
            nintersect[i][j][N] = res;
            for (int k = N - 1; k >= 0; k--)
            {
                if (cloc > loc[1-i][k])
                    res++;
                nintersect[i][j][k] = res;
            }
        }
    }

    for (int i = 0; i <= N; i++)
        for (int j = 0; j <= N; j++)
