int func(int l1, int r1, int l2, int r2, vector<int> v){
//	cout << l1 << " " << r1 << " " << l2 << " " << r2 << endl;
	int s1 = r1 - l1 + 1;
	int s2 = r2 - l2 + 1;
	if(s1 == 1 && s2 == 1) return 0;
	int res = 1e9;
	int cost = 0;
	int left = 0;
	int right = v.size()-1;
	if(s2 >= 1){
		vector<int> w;
		int p = 0, q = 0;
		for(int i=0; i<v.size(); ++i){
			if(v[i] == l2) p = i;
			if(v[i] == r2) q = i;
		}
		cost = p - left + right - q;
		if(q < p) --cost;
		for(int i=0; i<v.size(); ++i)
			if(i != p && i != q)
				w.push_back(v[i]);
		res = min(res, cost + func(l1, r1, l2+1, r2-1, w));
	}
	if(s1 >= 1){
		vector<int> w;
		int p = 0, q = 0;
		for(int i=0; i<v.size(); ++i){
			if(v[i] == l1) p = i;
			if(v[i] == r1) q = i;
		}
		cost = p - left + right - q;
		if(q < p) --cost;
		for(int i=0; i<v.size(); ++i)
			if(i != p && i != q)
				w.push_back(v[i]);
		res = min(res, cost + func(l1+1, r1-1, l2, r2, w));
	}
	if(s1 >= 1 && s2 >= 1){
		vector<int> w;
		int p = 0, q = 0;
		for(int i=0; i<v.size(); ++i){
			if(v[i] == l1) p = i;
			if(v[i] == r2) q = i;
		}
		cost = p - left + right - q;
		if(q < p) --cost;
		for(int i=0; i<v.size(); ++i)
			if(i != p && i != q)
				w.push_back(v[i]);
		res = min(res, cost + func(l1+1, r1, l2, r2-1, w));
		w.clear();
		p = 0, q = 0;
		for(int i=0; i<v.size(); ++i){
			if(v[i] == l2) p = i;
			if(v[i] == r1) q = i;
		}
		cost = p - left + right - q;
		if(q < p) --cost;
		for(int i=0; i<v.size(); ++i)
			if(i != p && i != q)
				w.push_back(v[i]);
		res = min(res, cost + func(l1, r1-1, l2+1, r2, w));
	}
	return res;
}

