const int N = 2000 + 10;
int dp[N][N];
bool visit[N][N];
int idx[2][N];
int n;
int c[N * 2];

void insert(int x, int y, int n) {
  for (; x <= n; x += x & -x) {
    c[x] += y;
  }
}

int query(int x) {
  int ret = 0;
  for (; x; x -= x & -x) {
    ret += c[x];
  }
  return ret;
}

int solve(int x, int y) {
  if (x == n && y == n) return 0;
  int& ret = dp[x][y];
  if (visit[x][y]) return ret;
  visit[x][y] = true;
  ret = INF;
  if (x + 1 <= n) {
    insert(idx[0][x], 1, n * 2);
    ret = min(ret, solve(x + 1, y) + idx[0][x] - 1 - query(idx[0][x] - 1));
    insert(idx[0][x], -1, n * 2);
  }
  if (y + 1 <= n) {
    insert(idx[1][y], 1, n * 2);
    ret = min(ret, solve(x, y + 1) + idx[1][y] - 1 - query(idx[1][y] - 1));
    insert(idx[1][y], -1, n * 2);
  }
  return ret;
}

