	dp[0][0] = 0;
	for (int i=0; i<=n; i++) {
		for (int j=0; j<=n; j++) if (i||j) {
			int cc = INT_MAX;
			if (i) cc = min(cc, dp[i-1][j] + cost[0][i-1][j]);
			if (j) cc = min(cc, dp[i][j-1] + cost[1][j-1][i]);
			dp[i][j] = cc;
		}
	}
	//printg((int*)dp, n+1, n+1, MAXN);
	return dp[n][n];
}

