const int N = 2005, INF = 1E9 + 7;

int n, v, bit[2 * N], pos[N][2], dp[N][N];
char c;

void upd(int u, int v)
{
    for (; u <= 2 * n; u += u & -u)
        bit[u] += v;
}

int que(int u)
{
    int ret = -1;
    for (; u > 0; u -= u & -u)
        ret += bit[u];
    return ret;
}

void init()
{
    fill(bit + 1, bit + 2 * n + 1, 0);
    for (int i = 1; i <= 2 * n; i++)
        upd(i, 1);
    for (int i = 1; i <= n; i++)
        upd(pos[i][1], -1);
}

int main()
{
    cin >> n;
    for (int i = 1; i <= 2 * n; i++)
