        pos[v][c == 'B'] = i;
    }
    for (int i = 0; i <= n; i++)
        for (int j = 0; j <= n; j++)
            dp[i][j] = INF;
    dp[0][0] = 0;
    for (int i = 0; i < 2 * n; i++)
    {
        init();
        int pw = 1, pb = n;
        for (int w = max(0, i - n); w <= n && w <= i; w++)
        {
            int b = i - w;
            for (; pw <= w; pw++)
                upd(pos[pw][0], -1);
            for (; pb > b; pb--)
                upd(pos[pb][1], 1);
            if (w < n)
                dp[w + 1][b] = min(dp[w + 1][b], dp[w][b] + que(pos[w + 1][0]));
            if (b < n)
                dp[w][b + 1] = min(dp[w][b + 1], dp[w][b] + que(pos[b + 1][1]));
        }
    }
    cout << dp[n][n];
}

#include<bits/stdc++.h>
using namespace std;
const int N=4005;
char c[N];
int a[N],tree[2][N],cntb[N][N],cntw[N][N],ind[2][N];
int dp[N][N];
int prev(int x)
{
    return (x&(x-1));
}
int next(int x)
{
    return 2*x-prev(x);
}
void update(int type, int ind, int diff)
{
    while(ind<=N)
    {
        tree[type][ind]+=diff;
        ind=next(ind);
    }
}
int get(int type, int ind1, int ind2)
{
    int ans=0;
    while(ind2)
    {
        ans+=tree[type][ind2];
        ind2=prev(ind2);
    }
    ind1--;
    while(ind1)
    {
        ans-=tree[type][ind1];
        ind1=prev(ind1);
    }
    return ans;
}
int main()
{
    int n;
    cin>>n;
    for(int i=1;i<=2*n;i++)
    {
        cin>>c[i]>>a[i];
        ind[c[i]=='W'][a[i]]=i;
    }
    for(int i=0;i<n;i++)
    {
        cntb[i][0]=get(0,ind[0][i+1]+1,2*n);
        for(int j=1;j<=n;j++)
        {
            update(1,ind[1][j],1);
            cntb[i][j]=get(1,ind[0][i+1]+1,2*n)+cntb[i][0];
        }
        for(int j=1;j<=n;j++)
            update(1,ind[1][j],-1);
        update(0,ind[0][i+1],1);
    }
    for(int i=0;i<n;i++)
        update(0,ind[0][i+1],-1);
    for(int i=0;i<n;i++)
    {
        cntw[i][0]=get(1,ind[1][i+1]+1,2*n);
        for(int j=1;j<=n;j++)
        {
            update(0,ind[0][j],1);
            cntw[i][j]=get(0,ind[1][i+1]+1,2*n)+cntw[i][0];
        }
        for(int j=1;j<=n;j++)
            update(0,ind[0][j],-1);
        update(1,ind[1][i+1],1);
    }
    for(int i=0;i<n;i++)
        update(1,ind[1][i+1],-1);
    dp[0][0]=0;
    for(int i=0;i<=n;i++)
    {
        for(int j=0;j<=n;j++)
        {
            if(i==0 && j==0) continue;
            if(i==0)
                dp[i][j]=dp[i][j-1]+cntw[j-1][i];
            else if(j==0)
                dp[i][j]=dp[i-1][j]+cntb[i-1][j];
            else
                dp[i][j]=min(dp[i-1][j]+cntb[i-1][j],dp[i][j-1]+cntw[j-1][i]);
        }
    }
    cout<<dp[n][n]<<endl;
    return 0;
}

