template<int Size>
class FenwickTree
{
public:

	i64 sum(int n)
	{
		i64 ans = 0;

		while (n > 0)
		{
			ans += data[n];
			n -= (n & -n);
		}

		return ans;
	}

	void add(int n, i64 num)
	{
		while (n < Size)
		{
			data[n] += num;
			n += (n & -n);
		}
	}

	int search(i64 k)
	{
		int lo = 0, hi = Size - 1;
		int ans = 0;

		while (lo <= hi)
		{
			int mid = (lo + hi) / 2;

			i64 q = sum(mid);

			if (q >= k)
			{
				ans = mid;
				hi = mid - 1;
			}
			else
			{
				lo = mid + 1;
			}
		}

		return ans;
	}

private:
	int data[Size];
};

int w[2005], b[2005];
int nextw[2005], nextb[2005];
int table[2005][2005];
int widx[2005], bidx[2005];
FenwickTree<2005> wtree[2005];
FenwickTree<2005> btree[2005];

int solve(int endw, int endb)
{
	if (endw == 0 && endb == 0)
		return 0;

	if (table[endw][endb] != -1)
		return table[endw][endb];

	int& res = table[endw][endb];
	res = 987654321;

	if (endb != 0)
	{
		int bi = bidx[endb];
		int bd = btree[bi].sum(endb - 1);
		int wi = nextw[bi];
		int wd = wtree[wi].sum(endw);

		res = min(res, solve(endw, endb - 1) + bd + wd);
	}

	if (endw != 0)
	{
		int wi = widx[endw];
		int wd = wtree[wi].sum(endw - 1);
		int bi = nextb[wi];
		int bd = btree[bi].sum(endb);

		res = min(res, solve(endw - 1, endb) + bd + wd);
	}

	return res;
}

int main()
{
	int n;
	scanf("%d", &n);

	int wi = 1, bi = 1;

	for (int i = 1; i <= n; i++)
		nextw[i] = nextb[i] = n + 1;

	for (int i = 0; i < 2 * n; i++)
	{
		char c[2];
		int k;

		scanf("%s %d", c, &k);

		if (c[0] == 'W')
		{
			w[wi] = k;
			widx[k] = wi;

			for (int j = 1; j < bi; j++)
				if (nextw[j] == n + 1)
					nextw[j] = wi;

			wi++;
		}
		else
		{
			b[bi] = k;
			bidx[k] = bi;

			for (int j = 1; j < wi; j++)
				if (nextb[j] == n + 1)
					nextb[j] = bi;

			bi++;
		}
	}

	for (int i = 1; i <= n; i++)
	{
		for (int j = i; j <= n; j++)
		{
			wtree[i].add(w[j], 1);
			btree[i].add(b[j], 1);
		}
	}

	memset(table, -1, sizeof(table));

	printf("%d\n", solve(n, n));

	return 0;
}

