class BIT{
  static const int MAX_N = 1 << 17;
  int n, bit[MAX_N+1];
public:
  BIT(int n_){
    n = n_;
    for(int i=0; i<n+1; i++) bit[i] = 0;
  }
  int sum(int i){
    int s = 0;
    while(i>0){
      s+=bit[i];
      i-=i&(-i);
    }
    return s;
  }
  void add(int i, int x){
    while(i<=n){
      bit[i]+=x;
      i+=i&(-i);
    }
  }
};

static const int INF = 1000000000;

int dp[4005][2005];

int calc(const vector<int>& A, const vector<string>& C, int j, int k, int p){
  int ret = 0;

  rep(i,p){
    string c = C[i];
    int a = A[i];

    if(c == "W"){
      if(a <= j) ret++;
    }else{
      if(a <= k) ret++;
    }
  }

  return ret;
}


int main(){
  int N;
  cin >> N;
  vector<string> C;
  vector<int> A;
  map<pair<string,int>,int> pos;
  rep(i,2*N){
    string c;
    int a;
    cin >> c >> a;
    C.push_back(c);
    A.push_back(a);
    pos[make_pair(c,a)] = i+1;
  }

  rep(i,4005) rep(j,2005) dp[i][j] = INF;

  BIT bit(2*N);

  dp[0][0] = 0;
  rep(i,2*N){
    rep(j,i+1){
      if(dp[i][j] == INF) continue;
      int k = i-j;
      if(k < 0 || k > N) continue;

      {
        int p = pos[make_pair("W",j+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + p-add-1);
      }
      {
        int p = pos[make_pair("B",k+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j] = min(dp[i+1][j], dp[i][j] + p-add-1);
      }
    }
  }

  cout << dp[2*N][N] << endl;

  return 0;
}

