void run() {
	scanf("%d",&n); REP(i,2*n) scanf(" %c%d",&c[i],&a[i]),--a[i];

	memset(pos,-1,sizeof(pos));
	REP(i,2*n) if(c[i]=='B') pos[0][a[i]]=i; else if(c[i]=='W') pos[1][a[i]]=i;
	//REP(k,2) { printf("pos%c:",k==0?'B':'W'); REP(i,n) printf(" %d",pos[k][i]); puts(""); }

	memset(cnt,0,sizeof(cnt));
	REP(i,2*n) ++cnt[i][c[i]=='B'?0:1][a[i]];
	REP(i,2*n) REP(k,2) FOR(j,1,n) cnt[i][k][j]+=cnt[i][k][j-1];
	FOR(i,1,2*n) REP(k,2) REP(j,n) cnt[i][k][j]+=cnt[i-1][k][j];

	/*REP(i,2*n) REP(k,2) REP(j,n) {
		int chk=0; REPE(ii,i) if(c[ii]==(k==0?'B':'W')&&a[ii]<=j) ++chk;
		assert(chk==cnt[i][k][j]);
	}*/

	REPE(i,n) REPE(j,n) dp[i][j]=INT_MAX; dp[0][0]=0;
	REPE(i,n) REPE(j,n) if(dp[i][j]!=INT_MAX) {
		if(i<n) {
			int idx=pos[0][i];
			int have=cnt[idx][0][i]+(j==0?0:cnt[idx][1][j-1])-1;
			int oth=idx-have;
			dp[i+1][j]=min(dp[i+1][j],dp[i][j]+oth);
		}
		if(j<n) {
			int idx=pos[1][j];
			int have=(i==0?0:cnt[idx][0][i-1])+cnt[idx][1][j]-1;
			int oth=idx-have;
			dp[i][j+1]=min(dp[i][j+1],dp[i][j]+oth);
		}
	}
	printf("%d\n",dp[n][n]);
}

