int go(int N,int b)
{
	if(N>2*n)return 0;
	int &ret=d[N][b];
	if(ret!=-1)return ret;
	ret=INF;
	int w=N-b-1;
	int B=b+1,W=w+1;
	if(b<n)
	{
		int cnt=a[0][B]-N;
		cnt+=tree[0].find(tree[0].Tree[b],1,2*n,a[0][B]+1,2*n)+tree[1].find(tree[1].Tree[w],1,2*n,a[0][B]+1,2*n);
		ret=min(ret,cnt+go(N+1,b+1));
	}
	if(w<n)
	{
		int cnt=a[1][W]-N;
		cnt+=tree[0].find(tree[0].Tree[b],1,2*n,a[1][W]+1,2*n)+tree[1].find(tree[1].Tree[w],1,2*n,a[1][W]+1,2*n);
		ret=min(ret,cnt+go(N+1,b));
	}
	return ret;
}
