const int inf = 1e9;
const int maxN = 4005;
int p[2][maxN];
int cost[2][maxN][maxN];
int dp[maxN][maxN];

int main() {
	int N; cin >> N; 
	for(int i = 1; i <= 2 * N; ++i) {
		char c; int x; cin >> c >> x;
		p[c == 'W'][x] = i;
	}
	for(int k = 0; k < 2; ++k) {
		for(int i = 1; i <= N; ++i) {
			for(int j = 1; j < i; ++j) cost[k][i][0] += (p[k][j] > p[k][i]);
			for(int j = 1; j <= N; ++j) cost[k][i][j] = cost[k][i][j - 1] + (p[1 - k][j] > p[k][i]); 
		}
	}
	for(int i = 0; i <= N; ++i) for(int j = 0; j <= N; ++j) dp[i][j] = inf;
	dp[0][0] = 0;
	for(int i = 0; i <= N; ++i) {
		for(int j = 0; j <= N; ++j) {
			if(i == N && j == N) continue;
			if(i < N) dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + cost[0][i + 1][j]);
			if(j < N) dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + cost[1][j + 1][i]);
		}
	}
	cout << dp[N][N] << endl;
}

