int main(){
  int N;
  cin >> N;
  vector<string> C;
  vector<int> A;
  map<pair<string,int>,int> pos;
  rep(i,2*N){
    string c;
    int a;
    cin >> c >> a;
    C.push_back(c);
    A.push_back(a);
    pos[make_pair(c,a)] = i+1;

    if(c=="W"){
      cntW[a][i] = 1;
    }else{
      cntB[a][i] = 1;
    }
  }

  rep(i,4005) rep(j,2005) dp[i][j] = INF;
  rep(i,4005){
    int cW = 0;
    int cB = 0;
    rep(j,2005){
      if(cntW[j][i] == 1) cW++;
      if(cntB[j][i] == 1) cB++;
      cntW[j][i] = cW;
      cntB[j][i] = cB;
    }
  }

  rep(i,2005){
    int cW = 0;
    int cB = 0;
    rep(j,4005){
      if(cntW[i][j] > 0) cW++;
      if(cntB[i][j] > 0) cB++;
      cntW[i][j] = cW;
      cntB[i][j] = cB;
    }
  }

  dp[0][0] = 0;
  rep(i,2*N){
    rep(j,i+1){
