      int k = i-j;
      if(k < 0 || k > N) continue;

      {
        int p = pos[make_pair("W",j+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + p-add-1);
      }
      {
        int p = pos[make_pair("B",k+1)];
        int add = calc(A, C, j, k, p-1);
        dp[i+1][j] = min(dp[i+1][j], dp[i][j] + p-add-1);
      }
    }
  }

  cout << dp[2*N][N] << endl;

  return 0;
}

