	ll x, y, z, x0, x1;
	while (!Q.empty()) {
		tie(x, y, z) = Q.top();
		Q.pop();
		if (y == N && z == N) {
			cout << -x << endl;
			return 0;
		}
		if (arr[y][z] >= 0)continue;
		arr[y][z] = -x;
		x0 = G[y][z][0];
		x1 = G[y][z][1];
		if (x0 >= 0) {
			Q.push(Ti(x - x0, y + 1, z));
		}
		if (x1 >= 0) {
			Q.push(Ti(x - x1, y, z + 1));
		}
	}
