	BIT(int n) {
		this->init(n);
	}
	init(int n) {
		dat.resize(n+1);
		size = n;
		rep(i,dat.size()) dat[i] = 0;
	}
	int sum(int i) {
		i++;
		int s = 0;
		while(i > 0) {
			s += dat[i];
			i -= i & -i;
		}
		return s;
	}
	void add(int i) {
		i++;
		while(i < dat.size()) {
			dat[i]++;
			i += i & -i;
		}
	}
};

