                dp2 = dp[i][j-1] + addr[1][j] - i - j + sum[0][i][addr[1][j]] + sum[1][j-1][addr[1][j]];

            if (dp1 == -1 && dp2 == -1) {dp[i][j] = 0; continue;}
            if (dp1 == -1) dp[i][j] = dp2;
            if (dp2 == -1) dp[i][j] = dp1;
            if (dp1 != -1 && dp2 != -1) dp[i][j] = min(dp1, dp2);

        }
    }

    cout<<dp[n][n]<<endl;
}

