using namespace std;
long long int N;

long long int solve(vector<pair<char, long long int>>ca){
	priority_queue<pair<pair<long long int, long long int>, pair<long long int, long long int>>, vector<pair<pair<long long int, long long int>, pair<long long int, long long int>>>, greater<pair<pair<long long int, long long int>, pair<long long int, long long int>>>>que;
	que.push(make_pair(make_pair(0, 0), make_pair(0, 0)));
	long long int ans = 0;
	map < pair < long long int, long long int >, long long int>memo;
	memo[make_pair(0, 0)] = 0;
	while( que.size() ){
		auto now = que.top(); que.pop();

		if( now.second.first == N && now.second.second == N ){
			return now.first.first;
		}
		if( memo.count(now.second) && memo[now.second] == now.first.first ){
			long long int nowpos = now.first.second;
			long long int i = nowpos;
			auto next = now;
			long long int count = 0;
			long long int b = now.second.first, w = now.second.second;
			if( now.second.first < N ){
				while( !( ca[i].first == 'B'&&ca[i].second == b + 1 ) ){
					if( ca[i].first == 'B'&&ca[i].second <= b ){
						i++;
						continue;
					}
					if( ca[i].first == 'W'&&ca[i].second <= w ){
						i++;
						continue;
					}
					i++;
					count++;
				}
				next.first.first += count;
				while( next.first.second < 2 * N && ( ( ca[next.first.second].first == 'B'&&ca[next.first.second].second <= b ) || ( ca[next.first.second].first == 'W'&&ca[next.first.second].second <= w ) ) ){
					next.first.second++;
				}
				next.second.first = b + 1;
				if( !memo.count(next.second) || memo[next.second] > next.first.first ){
					memo[next.second] = next.first.first;
					que.push(next);
				}
			}

			next = now;
			count = 0;
			i = nowpos;
			b = now.second.first, w = now.second.second;
			if( now.second.second < N ){
				while( !( ca[i].first == 'W'&&ca[i].second == w + 1 ) ){
					if( ca[i].first == 'B'&&ca[i].second <= b ){
						i++;
						continue;
					}
					if( ca[i].first == 'W'&&ca[i].second <= w ){
						i++;
						continue;
					}
					i++;
					count++;
				}
				next.first.first += count;
				while( next.first.second < 2 * N && ( ( ca[next.first.second].first == 'B'&&ca[next.first.second].second <= b ) || ( ca[next.first.second].first == 'W'&&ca[next.first.second].second <= w ) ) ){
					next.first.second++;
				}
				next.second.second = w + 1;
				if( !memo.count(next.second) || memo[next.second] > next.first.first ){
					memo[next.second] = next.first.first;
					que.push(next);
				}
			}
		}
	}
	return ans;
}


