int lowbit(int i) {
    return i&(-i);
}
void add (int i) {
    int n = MAXN*2;
    while (i < n) {
        tree[i]++;
        i += lowbit(i);
    }
}
int query (int i) {
    int ret = 0;
    while (i > 0) {
        ret += tree[i];
        i -= lowbit(i);
    }
    return ret;
}
int query (int i, int j) {
    if (i > j) return 0;
    if (i == 0) return query(j);
    return query(j) - query(i-1);
}

void solve(int i, int j) {
    if (dp[i][j] != -1) return;
    int val = INT_MAX;
    if (i > 0) {
        solve(i-1, j);
        val = min(val, dp[i-1][j] + costw[i][j]);
    }
    if (j > 0) {
        solve(i, j-1);
        val = min(val, dp[i][j-1]+ costb[i][j]);
    }
    dp[i][j] = val;
}


