/* Binary Indexed Tree(0-index) */

struct BIT{
  typedef int Type;
  int bit_size;
  vector<Type> data;

  BIT(int n){
    bit_size = n;
    data.assign(n+1,0);
  }

  //add x to kth value
  void add(int k,Type x){
    k += 1;

    while(k<=bit_size){
      data[k]+=x;
      k+= k&(-k); }
  }

  //sum of [1,k]
  Type query(int k){
    k += 1;

    Type rec=0;
    while(k>0){
      rec+=data[k];
      k-= k&(-k);
    }

    return rec;
  }
};

int dp[SIZE][SIZE];

int main(){
  int n;
