    scanf(" %c %d", &c, &a);
    a--;
    if(c == 'B') p[0][a] = i;
    else p[1][a] = i;
  }


  for(int i=0;i<=n;i++){
    for(int j=0;j<=n;j++){
      dp[i][j] = INF;
    }
  }

  dp[0][0] = 0;

  for(int i=0;i<=n;i++){
    BIT bit((n+1) * 2);

    for(int j=i;j<n;j++) bit.add(p[0][j], 1);
    for(int j=0;j<n;j++) bit.add(p[1][j], 1);

    for(int j=0;j<=n;j++){
      if(i < n) dp[i+1][j] = min(dp[i+1][j], dp[i][j] + bit.query(p[0][i]-1));
      if(j < n) dp[i][j+1] = min(dp[i][j+1], dp[i][j] + bit.query(p[1][j]-1));
      if(j < n) bit.add(p[1][j], -1);
    }
  }

  printf("%d\n", dp[n][n]);

  return 0;
}

