int bb[2005][2005];    // bb[i][j]: i番目(0-indexed)の黒より左側に0-j番目の白が何個あるか

int main(int argc, char* argv[])
{
    int n;
    scanf("%d", &n);
    vector<int> a(n), b(n), pa(n), pb(n);
