        if(str[0]=='W') {
            a[cnta]=tmp-1;
            pa[tmp-1]=cnta;
            aposi[cnta]=i;
            cnta++;
        }
        else {
            b[cntb]=tmp-1;
            pb[tmp-1]=cntb;
            bposi[cntb]=i;
            cntb++;
        }
    }
    assert(cnta==n);
    assert(cntb==n);

    {
        set<int> za;
        for(i=0; i<=n; i++) {
            vector<int> va;
            copy( za.begin(), za.end(), back_inserter( va ));

            for(j=0; j<n; j++) {
                bb[j][i] = lower_bound( va.begin(), va.end(), bposi[pb[j]] ) - va.begin();
            }
            if(i<n) {
                za.insert(aposi[pa[i]]);
            }
        }
    }

