        set<int> zb;
        for(i=0; i<=n; i++) {
            vector<int> vb;
            copy( zb.begin(), zb.end(), back_inserter( vb ));

            for(j=0; j<n; j++) {
                aa[j][i] = lower_bound( vb.begin(), vb.end(), aposi[pa[j]] ) - vb.begin();
            }
            if(i<n) {
                zb.insert(bposi[pb[i]]);
            }
        }
