    for(i=0; i<=n; i++) {
        for(j=0; j<=n; j++) {
            if(i==0 && j==0) {
                dp[i][j]=0;
            }
            else {
                dp[i][j]=INF;
                if(i>0) {
                    dp[i][j]=MIN(dp[i][j], dp[i-1][j] + aposi[pa[i-1]] - aa[i-1][j] - pa[i-1]);
                }
                if(j>0) {
                    dp[i][j]=MIN(dp[i][j], dp[i][j-1] + bposi[pb[j-1]] - bb[j-1][i] - pb[j-1]);
