}

#include<bits/stdc++.h>
using namespace std;
using ll = int64_t;
template <typename T>
class Bit{
    private:
        ll size;
        T *data;
        T identity_ele;

    public:

        Bit(ll size, T identity_ele){
            ll newsize = 1;
            while(newsize < size)  newsize = newsize << 1;
            this->size = newsize + 1;
            this->identity_ele = identity_ele;
            data = new ll[this->size];
            for(ll i = 0; i < size; ++i){
                data[i] = identity_ele;
            }
        }

        /*
         * 0-origin
         */
        T sum(ll pos){
            pos++;
            T ret = identity_ele;
            while(pos > 0){
                ret += data[pos];
                pos -= pos & -pos;
            }
            return ret;
        }

        /*
         * 0-origin
         */
        void add(ll pos, T delta){
            pos++;
            while(pos <= size){
                data[pos] = data[pos] + delta;
                pos += pos & -pos;
            }
        }
};

const ll INF = 5e15;

int main(){
    ll N;
    cin >> N;
    vector<ll> white(N + 1), black(N + 1);
    for(ll i = 0; i < 2 * N; i++){
        char c;
        ll a;
        cin >> c >> a;
        (c == 'W' ? white : black)[a] = i;
    }
    vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, INF));
    Bit<ll> B(2 * N, 0);
    dp[0][0] = 0;
    for(ll update = 1; update <= 2 * N; update++){
        vector<vector<ll>> nextdp(N + 1, vector<ll>(N + 1, INF));
        ll b = min(N, update - 1);
        ll w = (update - 1) - b;
        for(ll i = b + 1; i <= N; i++) B.add(black[i], 1);
        for(ll i = w + 1; i <= N; i++) B.add(white[i], 1);
        while(0 <= b && b <= N && 0 <= w && w <= N){
            if(0 <= b && b <= N && 0 <= w + 1 && w + 1 <= N) nextdp[w + 1][b] = min(nextdp[w + 1][b], dp[w][b] + B.sum(white[w + 1]) - 1);
            if(0 <= b + 1 && b + 1 <= N && 0 <= w && w <= N) nextdp[w][b + 1] = min(nextdp[w][b + 1], dp[w][b] + B.sum(black[b + 1]) - 1);
            if(w + 1 > N) break;
            B.add(black[b], 1);
            B.add(white[w + 1], -1);
            b--;
            w++;
        }
        dp = nextdp;
        for(ll i = b + 1; i <= N; i++) B.add(black[i], -1);
        for(ll i = w + 1; i <= N; i++) B.add(white[i], -1);
    }
    cout << dp[N][N] << endl;
    return 0;
}

