int bl[2020], wh[2020], bit[4040], dp[2020][2020];

void bitAdd(int n, int a){
	for(int i=n; i<4040; i += i&(-i)){
		bit[i] += a;
	}
}

int bitSum(int n){
	int res=0;
	for(int i=n; i>0; i -= i&(-i)){
		res += bit[i];
	}
	return res;
}

int main() {
	int N;
	cin >> N;
	for(int i=1; i<=N*2; ++i){
		char c;
		int a;
		cin >> c >> a;
		if(c=='B') bl[a]=i;
		else wh[a]=i;
	}
	dp[0][0]=0;
	for(int i=1; i<=N; ++i){
		bitAdd(bl[i], 1);
		dp[i][0]=dp[i-1][0]+bl[i]-bitSum(bl[i]);
	}
	for(int i=1; i<=N; ++i){
		for(int j=1; j<=N; ++j) bitAdd(bl[j], -1);
		bitAdd(wh[i], 1);
		dp[0][i]=dp[0][i-1]+wh[i]-bitSum(wh[i]);
		for(int j=1; j<=N; ++j){
			bitAdd(bl[j], 1);
			dp[j][i]=dp[j-1][i]+bl[j]-bitSum(bl[j]);
			dp[j][i]=min(dp[j][i], dp[j][i-1]+wh[i]-bitSum(wh[i]));
		}
	}
	cout << dp[N][N] << endl;
	return 0;
}

