        ret = solve(i-1 , j) + sum[0][rev[0][i] + 1][i-1] + sum[1][rev[0][i] + 1][j];
        ll op = solve(i , j-1) + sum[1][rev[1][j] + 1][j-1] + sum[0][rev[1][j] + 1][i];
        ret = min(ret , op);
        return dp[i][j] = ret;
}
