	}
	long long int ans = solve(ca);
	reverse(ca.begin(), ca.end());
	for( size_t i = 0; i < 2 * N; i++ ){
		ca[i].second = N - ca[i].second + 1;
	}
	ans = min(ans, solve(ca));
	cout << ans << endl;
}

