int main() {
    std::iostream::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    // code here.
    int n = input<int>();

    vector<pair<bool, int>> a(2 * n);

    for (int i = 0; i != 2 * n; ++i) {
        a[i].first  = (input<char>() == 'W');
        a[i].second = input<int>();
    }


    vector<vector<int>> dp(n + 1, vector<int>(n + 1));

    vector<int> index_of0(n + 1, -1), index_of1(n + 1, -1);
    for (int i = 0; i != 2 * n; ++i)
        (a[i].first == 0 ? index_of0 : index_of1)[a[i].second] = i;

    vector<vector<int>> pref_counts0(2 * n, vector<int>(n + 1)), pref_counts1(2 * n, vector<int>(n + 1));
    for (int i = 0; i != 2 * n; ++i)
        for (int j = 0; j <= n; ++j) {
            pref_counts0[i][j] = 0;

            if (i)
                pref_counts0[i][j] += pref_counts0[i - 1][j];
            if (a[i].first == 0 and a[i].second <= j)
                ++pref_counts0[i][j];
        }

    for (int i = 0; i != 2 * n; ++i)
        for (int j = 0; j <= n; ++j) {
            pref_counts1[i][j] = 0;

            if (i)
                pref_counts1[i][j] += pref_counts1[i - 1][j];
            if (a[i].first == 1 and a[i].second <= j)
                ++pref_counts1[i][j];
        }


    auto count = [&](int i, int j, bool tp, int vl) {
        int ind = (tp == 0 ? index_of0 : index_of1)[vl];

        int ans = ind;
        if (ind > 0) {
            ans -= pref_counts0[ind - 1][i];
            ans -= pref_counts1[ind - 1][j];
        }
        return ans;
    };

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= n; ++j)
            if (i + j == 0)
                dp[i][j] = 0;
            else {
                dp[i][j] = TYPEMAX(int);
                if (i)
                    dp[i][j] = min(dp[i][j], dp[i - 1][j] + (int)count(i, j, 0, i));
                if (j)
                    dp[i][j] = min(dp[i][j], dp[i][j - 1] + (int)count(i, j, 1, j));
            }


    cout << dp.back().back() << "\n";

    return 0;
}

