using ll = int64_t;
template <typename T>
class SegmentTree{
    public:
        ll size;
        vector<T> node;
        T identity_ele;  //comp(x, identity_ele) == x
        function<T(T, T)> comp;

        SegmentTree(const vector<T> &v, function<T(T, T)> comp, T identity_ele){
            ll tmp = 1;
            while(tmp < v.size()) tmp = (tmp << 1);
            this->size = tmp;
            this->identity_ele = identity_ele;
            this->comp = comp;
            node.resize(2 * size - 1);
            for(ll i = 0; i < v.size(); i++){
                node[i + size - 1] = v[i];
            }
            for(ll i = size - 2; 0 <= i; i--){
                node[i] = comp(node[i * 2 + 1], node[i * 2 + 2]);
            }
        }

        void update(ll pos, T value){
            pos += size - 1;
            node[pos] = value;
            while(pos > 0){
                pos = (pos - 1) / 2;
                node[pos] = comp(node[2 * pos + 1], node[2 * pos + 2]);
            }
        }

        T query(ll a, ll b){
            return subQuery(a, b, 0, 0, size);
        }

        T subQuery(ll a, ll b, ll k, ll l, ll r){
            return (r <= a || b <= l ? identity_ele : (a <= l && r <= b ? node[k] : comp(subQuery(a, b, k * 2 + 1, l, (l + r) / 2), subQuery(a, b, k * 2 + 2, (l + r) / 2, r))));
        }
};

const ll INF = 5e15;

int main(){
    ll N;
    cin >> N;
    vector<ll> white(N + 1), black(N + 1);
    for(ll i = 0; i < 2 * N; i++){
        char c;
        ll a;
        cin >> c >> a;
        (c == 'W' ? white : black)[a] = i;
    }
    vector<ll> init(2 * N, 0);
    auto cmp = [](ll a, ll b){return a + b;};
    SegmentTree<ll> S(init, cmp, 0);
    vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, INF));
    dp[0][0] = 0;
    for(ll update = 1; update <= 2 * N; update++){
        for(ll i = update; i <= N; i++) S.update(black[i], 1);
        for(ll i = max<ll>(1, update - N); i <= N; i++) S.update(white[i], 1);
        for(ll b = min(N, update - 1); b >= 0; b--){
            ll w = (update - 1) - b;
            if(0 <= b && b <= min(N, update) && 0 <= w + 1 && w + 1 <= min(N, update)) dp[w + 1][b] = min(dp[w + 1][b], dp[w][b] + S.query(0, white[w + 1]));
            if(0 <= b + 1 && b + 1 <= min(N, update) && 0 <= w && w <= min(N, update)) dp[w][b + 1] = min(dp[w][b + 1], dp[w][b] + S.query(0, black[b + 1]));
            if(w + 1 > N) break;
            S.update(black[b], 1);
            S.update(white[w + 1], 0);
        }
        for(ll i = 0; i < 2 * N; i++) S.update(i, 0);
    }
    cout << dp[N][N] << endl;
    return 0;
}

