LL n, m, i, j, k, l, r, t, bl, wh, ans;
LL dp[N][N], xe[N*2], a[2][N];
char c;

LL get ( LL x ){
	LL sum = 0;
	while ( x > 0 ){
		sum += xe[x];
		x -= (x & -x);
	}
	return sum;
}

void upd ( LL x, LL val ){
	if ( !x ) return;
	while ( x < 2*N ){
		//if ( val == -1 ) cout << x << endl;
		xe[x] += val;
		x += (x & -x);
	}
}

