			dp[i][j] = N*N;
		}
	}

	dp[0][0] = 0;

	for ( bl = 0; bl <= n; bl++ ){
		for ( i = 0; i < 2*N; ++i ) xe[i] = 0;
		for ( i = 1; i <= n; ++i ){
			upd(a[1][i],1);
		}
		for ( i = bl + 1; i <= n; ++i ){
			upd(a[0][i],1);
