ll powmod(ll x, ll y) 
{ 
    ll res = 1;  
    x = x % MOD;
    while (y > 0) 
    { 
        if (y & 1) 
            res = (res*x) % MOD; 
        y = y>>1; // y = y/2 
        x = (x*x) % MOD;   
    } 
    return res; 

} 

void merge(vector<int>&temp,int low,int high,int &inv){
    vector<int>aux;
    int mid=(low+high)/2;
    int l1=low,r1=mid;
    int l2=mid+1,r2=high;
    while(l1<=r1 and l2<=r2){
        if(temp[l1]<temp[l2])
            aux.pb(temp[l1++]);
        else 
            {aux.pb(temp[l2++]);inv+=r1-l1+1;}
    }

    while(l1<=r1)
        aux.pb(temp[l1++]);    
    while(l2<=r2)
        aux.pb(temp[l2++]);

    for(int i=low;i<=high;i++)
        temp[i]=aux[i-low];
}

void mergesort(vector<int>&temp,int low,int high,int &inv){
    if(low==high)
        return;
    int mid=(low+high)/2;
    mergesort(temp,low,mid,inv);
    mergesort(temp,mid+1,high,inv);
    merge(temp,low,high,inv); 
}
int calinv(vector<int>&v){
    int inv=0;
    mergesort(v,0,v.size()-1,inv);
    return inv;
}
