void solve(){
    for(long long i = 0; i <= n; i++){
        if(i != 0)
            add(0, ind[0][i] + 1, 1);
        for(long long j = 0; j <= n; j++){
            if(j != 0)
                add(0, ind[1][j] + 1, 1);
            if(i + j != 0)
                dp[i][j] = 1e9;
            if(i != 0)
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + i + j - get(0, ind[0][i] + 1));
            if(j != 0)
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + j + i - get(0, ind[1][j] + 1));
        }
        for(long long j = 1; j <= n; j++)
            add(0, ind[1][j] + 1, -1);
        memset(fen[1], 0, sizeof fen[1]);
    }
}

