void update(vector<int>& rowvec, int index, int val) {
	int diff = val;
	while (index < rowvec.size()) {
		rowvec[index] += diff;
		index = index + (index & (-index));
	}
}
int prefixSum(vector<int>& rowvec, int index) {
	int res = 0;
	while (index > 0) {
		res += rowvec[index];
		index = index - (index & (-index));
	}

	return res;
}

