using namespace std;

class BIT{
public:
  typedef long long ll;
  ll n;
  vector<ll> bit;
  BIT():n(-1){};
  BIT(ll n_){
    n=1;
    while(n < n_+2) n *= 2;
    bit.resize(n+1, 0);
  }

  //[0, i]までの総和を得る
  ll sum(ll i){
    assert( i >= 0 && i <= n );
    i++;

    ll s=0;
    while(i>0){
      s = (s + bit[i]);
      i -= i & -i;
    }
    return s;
  }

  //i番目の要素にx加算(0 オリジン)
  void add(ll i,ll x){
    assert( i >= 0 && i <= n );
    i+=2;

    while(i <= n){
      bit[i] = (bit[i] + x);
      i += i & -i;
    }
  }

  ll sum(int l,int r){ //[l, r) 0オリジン
    assert(l <= r);
    assert( 0 <= l && l <= n);
    assert( 0 <= r && r <= n);
    return sum(r) - sum(l);
  }
};

int N, W[2005], B[2005];
int memo[2005][2005], used[2005][2005];

int dfs(int wnum, int bnum, BIT &bitw, BIT &bitb){

  if( used[wnum][bnum] ) return memo[wnum][bnum];

  used[wnum][bnum] = 1;

  if( wnum == N + 1 && bnum == N + 1 ) return 0;

  int res = 1e9;

  if( wnum <= N ){
    int cnt = bitw.sum( 0, W[wnum] ) + bitb.sum( 0, W[wnum] );
    bitw.add( W[wnum], -1 );
    res = min( res, cnt + dfs( wnum + 1, bnum, bitw, bitb ) );
    bitw.add( W[wnum], 1 );
  }

  if( bnum <= N ){
    int cnt = bitb.sum( 0, B[bnum] ) + bitw.sum( 0, B[bnum] );
    bitb.add( B[bnum], -1 );
    res = min( res, cnt + dfs( wnum, bnum + 1, bitw, bitb ) );
    bitb.add( B[bnum], 1 );
  }

  return memo[wnum][bnum] = res;
}

