			posb[x] = i;
		}
		if(ch == 'W') {
			update(x, 1, 1);
			cw++;
			posw[x] = i;
		}
		for (int j = 0; j <= n; j++) {
			pb[i][j] = getsum(n, 0) - getsum(j, 0);
			pw[i][j] = getsum(n, 1) - getsum(j, 1);
		}
	}

	vector <vector<int>> dp(n + 1, vector<int>(n + 1, 0));
	for (int i = 1; i <= n; i++) {
		dp[i][0] = dp[i - 1][0] + pb[posb[i]][i] + pw[posb[i]][0];
		dp[0][i] = dp[0][i - 1] + pb[posw[i]][i] + pb[posw[i]][0];
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			int a = dp[i - 1][j] + pb[posb[i]][i] + pw[posb[i]][j];
			int b = dp[i][j - 1] + pw[posw[j]][j] + pb[posw[j]][i];
			dp[i][j] = min(a, b);
		}
	}
	cout << dp[n][n];
}

