		int base = 0;
		int cnt = 0;
		for (int i = 0; i < N * 2; i++)
		{
			if (C[i] == c)
			{
				if (A[i] > c1 + 1)
				{
					base++;
				}
				else if (A[i] == c1 + 1)
				{
					break;
				}
			}
			else
			{
				add(A[i], 1);
				cnt++;
			}
		}

		for (int c2 = 0; c2 <= N; c2++)
		{
			if (c == 'B')
			{
				cost[c1][c2][k] = base + (cnt - sum(c2 + 1));
			}
			else
			{
				cost[c2][c1][k] = base + (cnt - sum(c2 + 1));
			}
		}
	}

