				dp[b+1][w]=min(dp[b+1][w],dp[b][w]+sm-que(B[b]));
			}
			if (w<N){
				dp[b][w+1]=min(dp[b][w+1],dp[b][w]+sm-que(W[w]));
			}
			if (b>0 && w<N){
				add(B[b-1],-1);
				b--;
				add(W[w],1);
				w++;
			}
		}
	}
	cout<<dp[N][N]<<endl;
	return 0;
}

