}
int query(int p) {
  int res = 0;
  for ( ; p ; p -= lowbit(p))
    res += bit[p];
  return res;
}
int ask(int x,int p,int cur) {
  if (x <= cur) return query(x) - 1;
  else return x - p + query(n) - query(x);
}
int main() {
