    int st = max(0,i - n/2);
    for (int j = 1 ; j <= i ; ++ j)
      if ((col[j] == 0 && val[j] > st)||(col[j] == 1 && val[j] > i - st)) add(j,1);
    for (int j = i + 1 ; j <= n ; ++ j)
      if ((col[j] == 1 && val[j] <= i - st) || (col[j] == 0 && val[j] <= st)) add(j,1);
    for (int j = st ; j <= i && j <= n/2 ; ++ j) {
      dp[i+1][j] = min(dp[i+1][j],dp[i][j] + ask(pos[1][i-j+1],i+1,i));
