vector<int> X, Y;
int Mx[2][MN];
int cnt[2][MN][MN], psum[2][MN][MN];

int calc(int t, int l, int r, int x) {
    if(l > r) return 0;
    return psum[t ^ 1][x][r] - (l? psum[t ^ 1][x][l - 1] : 0);
}

int cc[MN][MN];
int dp(int pos1, int pos2) {
    if(pos1 == N && pos2 == N) return 0;
    int &ret = cc[pos1][pos2];
    if(ret != -1) return ret;

    ret = 1e9;
    if(pos1 < N) {
        ret = min(ret, dp(pos1 + 1, pos2) + calc(0, pos2, N - 1, pos1));
    }
    if(pos2 < N) {
        ret = min(ret, dp(pos1, pos2 + 1) + calc(1, pos1, N - 1, pos2));
    }
    return ret;
}

