typedef long long ll;

struct BIT{
  int size;
  vector< ll > t;
  void init(int n){
    size=n;
    t.resize(n,0);
  }

  void add(int i,ll x){
    i++;
    while( i < size ){
      t[i]+=x;
      i+=(i&-i);
    }
  }

  ll sum(int i){
    i++;
    ll res=0;
    while(i){
      res+=t[i];
      i-=(i&-i);
    }
    return res;
  }
};



