      black.add(i, 1);
    else
      white.add(i, 1);
  }
  for (int i = 0; i <= n; i++) {
    BIT moved(1 << 13), moved2(1 << 13);
    for (int j = 0; j < i - 1; j++) {
      moved.add(winv[j], 1);
      moved2.add(winv[j], 1);
    }
