              black.sum(binv[0]) + white.sum(binv[0]) - moved.sum(binv[0]);
          moved.add(binv[0], 1);
          continue;
        }
        dp[0][j + 1] = dp[0][j] + black.sum(binv[j]) + white.sum(binv[j]) -
                       moved.sum(binv[j]);
        moved.add(binv[j], 1);
        continue;
      }
    } else {
