            // 数字iが書かれた黒を手前に持ってくるまでの総回数
            int aa = 0;
            int bb = 0;
            for (int k=0; k<2*N; k++)
            {
                if (a[k] == i) break;
                if (a[k] > i || a[k] < -j) aa++;
            }

            for (int k=0; k<2*N; k++)
            {
                if (a[k] == -j) break;
                if (a[k] > i || a[k] < -j) bb++;
            }

            dp[i][j] = min(dp[i-1][j] + aa, dp[i][j-1] + bb);
        }
    }

    cout << dp[N][N] << "\n";

    return 0;
}

