	cin >> n;

	map<int, map<char,int>> inv;
	for (int i = 0; i < 2*n; i++)
	{
		string cc;
		cin >> cc >> arr[i];

		colors[i] = cc[0];
		inv[colors[i]][arr[i]] = i;
	}

	vector<int> less_cnt(2*n);
	vector<vector<int>> others_before(2*n);
	for (int i = 0; i < 2*n; i++)
	{
		for (int j = 0; j < i; j++)
		{
			if (colors[j] == colors[i] && arr[j] < arr[i])
				less_cnt[i]++;
			if (colors[j] != colors[i])
			{
				others_before[i].push_back(arr[j]);
			}
		}
		sort(others_before[i].begin(), others_before[i].end());
	}

	for (int b_c = 0; b_c <= n; b_c++)
	{
		for (int w_c = 0; w_c <= n; w_c++)
		{
			if (b_c == 0 && w_c == 0)
				continue;
			int val = 100000000;
			if (b_c > 0)
			{
				int tmp = dp[b_c - 1][w_c];
				int pos = inv['B'][b_c];
				int move_cnt = pos - less_cnt[pos] - (upper_bound(others_before[pos].begin(), others_before[pos].end(), w_c) - others_before[pos].begin());
				if (move_cnt < 0)
					throw 1;
				val = min(val, tmp + move_cnt);
			}
			if (w_c > 0)
			{
				int cand = dp[b_c][w_c - 1];
				int pos = inv['W'][w_c];
				int move_cnt = pos - less_cnt[pos] - (upper_bound(others_before[pos].begin(), others_before[pos].end(), b_c) - others_before[pos].begin());
				if (move_cnt < 0)
					throw 1;
				cand += move_cnt;
				val = min(val, cand);
			}
			if (val < 0 || val == 100000000)
				throw 1;
			dp[b_c][w_c] = val;
		}
	}

	cout << dp[n][n];

	return 0;
}

