int main() {
	int n; cin >> n;
	int b[4000]; int w[4000]; int invb[2000], invw[2000];
	fill(b, b + n, -1);
	fill(w, w + n, -1);
	rep(i, 2*n) {
		char t; cin >> t;
		if (t == 'B') {
			cin >> b[i]; b[i]--;
			invb[b[i]] = i;
		}
		else if (t == 'W') {
			cin >> w[i]; w[i]--;
			invw[w[i]] = i;
		}
	}
	rep(i, n) {
		int x = invb[i];
		int cnt = 0;
		rep(j, x) {
			if (b[j] > i)cnt++;
		}
		rep(j, x) {
			if (w[j] < 0)continue;
			costb[i][w[j]]++;
		}
		per(j, n-1) {
			costb[i][j] += costb[i][j + 1];
		}
		rep(j, n) {
			costb[i][j] += cnt;
		}
		x = invw[i];
		cnt = 0;
		rep(j, x) {
			if (w[j] > i)cnt++;
		}
		rep(j, x) {
			if (b[j] < 0)continue;
			costw[i][b[j]]++;
		}
		per(j, n-1) {
			costw[i][j] += costw[i][j + 1];
		}
		rep(j, n) {
			costw[i][j] += cnt;
		}
	}
	rep(i, n) {
		int x = invb[i];
		rep(j, x) {
			if (b[j] > i)costb[i][n]++;
		}
		x = invw[i];
		rep(j, x) {
			if (w[j] > i)costw[i][n]++;
		}
	}
	dp[0][0] = 0;
	rep(i, n+1) {
		rep(j, n+1) {
			if (i == 0 && j == 0)continue;
			int nex = 1e+9;
			if (i > 0) {
				nex = min(nex,dp[i - 1][j] + costb[i-1][j]);
			}
			if (j > 0) {
				nex = min(nex,dp[i][j - 1] + costw[j-1][i]);
			}
			dp[i][j] = nex;
		}
	}
	cout << dp[n][n] << endl;
	return 0;
}

