class BIT {
public:
	vint dat;
	int n;
	BIT(int _n) {
		n = 1;
		while (n <= _n)	n <<= 1;
		dat.assign(n + 1, 0);
	}

	void add(int k, int v) {
		k++;
		while (k <= n) {
			dat[k] += v;
			k += -k & k;
		}
	}

	int get(int k) {
		k++;
		int ret = 0;
		while (k > 0) {
			ret += dat[k];
			k -= -k & k;
		}
		return ret;
	}
};

