				for(int j=0;j<i;j++){
					if(v[j] < N){
						if(v[j] > v[i]) ++flipW[v[i]];
					} else {
						++cntW[v[i]][v[j]-N];
					}
				}
				for(int j=N-2;j>=0;j--) cntW[v[i]][j] += cntW[v[i]][j+1];
