				for(int j=0;j<i;j++){
					if(v[j] < N){
						++cntB[v[i]-N][v[j]];
					} else {
						if(v[j] > v[i]) ++flipB[v[i]-N];
					}
				}
				for(int j=N-2;j>=0;j--) cntB[v[i]-N][j] += cntB[v[i]-N][j+1];
			}
		}
		vector<vector<int>> dp(N+1, vector<int>(N+1, 4*N*N));
		dp[0][0] = 0;
		for(int i=0;i<=N;i++){
			for(int j=0;j<=N;j++){
				if(i < N){
					dp[i+1][j] = min(dp[i+1][j], dp[i][j] + flipW[i] + cntW[i][j]);
				}
				if(j < N){
					dp[i][j+1] = min(dp[i][j+1], dp[i][j] + flipB[j] + cntB[j][i]);
				}
			}
		}
		cout << dp[N][N] << endl;
	}
}

