const int MAX_N = 4040;

class Bit {
public:
    Bit(int n);
    int sum(int i);
    void add(int i, int x);
private:
    int dat[MAX_N];
    int size;
};

Bit::Bit(int n) {
    size = n;
}

int Bit::sum(int i) {
    int s = 0;
    --i;
    while (0 <= i) {
        s += dat[i];
        i = (i & (i + 1)) - 1;
    }
    return s;
}

void Bit::add(int i, int x) {
    while (i < size) {
        dat[i] += x;
        i |= i + 1;
    }
}

int length_h[2020*2020];
int length_v[2020*2020];
int dist[2020*2020];
int w[2020];
int b[2020];

int solve(int n, int *w, int *b, Bit &bit_w, Bit &bit_b) {
    fill(length_h, length_h + 2020*2020, 0);
    fill(length_v, length_v + 2020*2020, 0);

    rep (y, 0, n) {
        rep (x, 0, n) {
            length_h[y*(n+1) + x] = bit_b.sum(w[x]);
        }
        bit_b.add(b[y], -1);
    }

    rep (x, 0, n) {
        rep (y, 0, n) {
            length_v[y*(n+1) + x] = bit_w.sum(b[y]);
        }
        bit_w.add(w[x], -1);
    }

    int d;

    fill(dist, dist + 2020*2020, INT_MAX);
    dist[0] = 0;

    d = 0;
    rep (x, 1, n + 1) {
        d += length_h[x - 1];
        dist[x] = d;
    }

    d = 0;
    rep (y, 1, n + 1) {
        d += length_v[(y - 1)*(n+1)];
        dist[y*(n+1)] = d;
    }

    rep (y, 1, n + 1) {
        rep (x, 1, n + 1) {
            dist[y*(n+1) + x] =
                min(
                    dist[y*(n+1) + x - 1] + length_h[y*(n+1) + x - 1],
                    dist[(y - 1)*(n+1) + x] + length_v[(y - 1)*(n+1) + x]);
        }
    }

    int ans = dist[n*(n+1) + n];

    rep (i, 0, n) {
        rep (j, i + 1, n) {
            if (w[j] < w[i]) {
                ++ans;
            }
            if (b[j] < b[i]) {
                ++ans;
            }
        }
    }

    return ans;
}


