const int BIT_MAX = 4010;

template <class T> class BIT{
	T x[BIT_MAX + 1];

public:

	BIT(){
		fill(x,x+BIT_MAX+1,0);
	}

	void add(int a , T b){
		for(++a ; a <= BIT_MAX ; a += a & -a) x[a] += b;
	}

	T get(int a){
		T b = 0;
		for(++a ; a > 0 ; a -= a & -a) b += x[a];
		return b;
	}
};

