ll mod = 1e9 + 7;

int n, a[maxn<<1]; char c[maxn<<1][2];
int pw[maxn], pb[maxn];

int w[maxn][maxn], b[maxn][maxn], f[maxn][maxn];

int t[maxn<<1];
void add(int x,int d)
{
	while (x && x <= 2*n)
	{
		t[x] += d;
		x += lowbit(x);
	}
}

int sum(int x)
{
	int ret = 0;
	while (x)
	{
		ret += t[x];
		x -= lowbit(x);
	}
	return ret;
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= 2*n; i++)
	{
		scanf("%s%d", c[i], a+i);
		if (c[i][0] == 'W') pw[a[i]] = i;
		else pb[a[i]] = i;
	}

	for (int i = 0; i <= n; i++)
	{
		add(pw[i], 1);
		for (int j = 0; j <= n; j++)
		{
			add(pb[j], 1);
			w[i][j] = sum(2 * n) - sum(pw[i + 1]);
		}
		for (int j = 1; j <= n; j++)
		{
			add(pb[j], -1);
		}
	}

	for (int i = 1; i <= n; i++) add(pw[i], -1);

	for (int i = 0; i <= n; i++)
	{
		add(pb[i], 1);
		for (int j = 0; j <= n; j++)
		{
			add(pw[j], 1);
			b[j][i] = sum(2 * n) - sum(pb[i + 1]);
		}
		for (int j = 1; j <= n; j++)
		{
			add(pw[j], -1);
		}
	}

	for (int i = 0; i <= n; i++)
	{
		for (int j = 0; j <= n; j++) if(i||j)
		{
			if (!i) f[i][j] = f[i][j - 1] + b[i][j - 1];
			else if (!j) f[i][j] = f[i - 1][j] + w[i - 1][j];
			else f[i][j] = MIN(f[i - 1][j] + w[i - 1][j], f[i][j - 1] + b[i][j-1]);
		}
	}
	printf("%d", f[n][n]);
}

