#include <bits/stdc++.h>
using namespace std;

struct BIT
{
    static const int N= 4006;
    int a[N];
    int n;
    void init(int _n)
    {
        memset(a,0,sizeof(a));
        n = _n;
    }
    void update(int pos,int val)
    {
        for (int i=pos;n>=i;i+=i&(-i))
        {
            a[i] += val;
        }
    }
    int Q(int pos)
    {
        int ret=0;
        for (int i=pos;i>0;i-=i&(-i))
        {
            ret += a[i];
        }
        return ret;
    }
    int Q2(int L,int R)
    {
        return Q(R) - Q(L-1);
    }
} bit;

const int N = 4006;

int dp[N][N];

int a[N],b[N];
int pos[N];

int main ()
{
    int n;
    cin >> n;
    for (int i=1;2*n>=i;i++)
    {
        char c;
        int x;
        cin >> c >> x;
        if (c == 'W') a[i] = 1,b[i] = x;
        else a[i] = 2,b[i] = x;
        pos[ (a[i]-1)*n + x ] = i;
    }
    memset(dp,(0x3f3f3f3f),sizeof(dp));
    dp[0][0] = 0;
    for (int i=0;n>=i;i++)
    {
        bit.init(2*n);
        for (int j=1;n>=j;j++)
        {
            if (j <= i) ;
            else bit.update(pos[j],1);
            bit.update(pos[j+n],1);
        }
        for (int j=0;n>=j;j++)
        {
            if (j) bit.update(pos[j+n],-1);
            if (i != n) dp[i+1][j] = min(dp[i+1][j],dp[i][j] + bit.Q2(1,pos[i+1]-1));
            if (j != n) dp[i][j+1] = min(dp[i][j+1],dp[i][j] + bit.Q2(1,pos[j+n+1]-1));
        }
    }
    cout << dp[n][n] << endl;
}

