int main(){
    cin >> n;
    for(int i = 1;i <= 2 * n;i++){
        char s[5];
        scanf("%s%d", s, &a[i]);
        if(s[0] == 'W'){
            c[i] = 0;
        }else{
            c[i] = 1;
        }
        pos[c[i]][a[i]] = i;
    }
    for(int i = 0;i <= n;i++){
        for(int j = 0;j <= n;j++){
            dp[i][j] = 1e18;
        }
    }
    dp[0][0] = 0;
    for(int len = 0;len < 2 * n;len++){
        memset(d, 0, sizeof(d));
        for(int i = 1;i <= max(0, len - n);i++){
            add(pos[0][i], 1);
        }
        for(int i = 1;i <= min(n, len);i++){
            add(pos[1][i], 1);
        }
        for(int i = max(len - n, 0);i <= min(n, len);i++){
            int j = len - i;
            if(i < n){
                int p = pos[0][i + 1];
                int s = sum(p);
                int pp = p + len - s; 
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + pp - (len + 1));
            }
            if(j < n){
                int p = pos[1][j + 1];
                int s = sum(p);
                int pp = p + len - s; 
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + pp - (len + 1));
            }
            if(i + 1 >= 1 and i + 1 <= n){
                add(pos[0][i + 1], 1);
            }
            if(j >= 1 and j <= n){
                add(pos[1][j], -1);    
            }
        }
    }
    cout << dp[n][n] << endl;
    return 0;
}

