void solve(){
	int N;
	cin>>N;
	vector<int> C(N*2);
	vector<int> indexW(N+1,0),indexB(N+1,0);
	for(int i=0;i<2*N;++i){
		char col;
		int val;
		cin>>col >> val;
		if(col=='B'){
			indexB[val] = i+1;
			val+=N;
		}else{
			indexW[val] = i+1;
		}
		C[i] = val;
	}
	vector<vector<int> > dp(N+1,vector<int>(N+1,INF));
	vector<vector<int> > costW(N+1,vector<int>(N+1,0));
	vector<vector<int> > costB(N+1,vector<int>(N+1,0));
	BITree bitW(2*N);
	for(int i=0;i<=N;++i){
		bitW.add(indexW[i],1);

		BITree bitB(2*N);
		for(int j=0;j<=N;++j){
			bitB.add(indexB[j],1);
			if(i+1<=N){
				int ter = indexW[i+1] - 1;
				int res = bitW.sum(ter) + bitB.sum(ter);
				costW[i][j] = ter-res;
			}
			if(j+1<=N){
				int ter = indexB[j+1] - 1;
				int res = bitW.sum(ter)+bitB.sum(ter);
				costB[i][j]=ter-res;
			}
		}
	}
	dp[0][0] = 0;
	for(int i=0;i<=N;++i){
		for(int j=0;j<=N;++j){
			if(i+1<=N){
				dp[i+1][j] = min(dp[i+1][j],
					dp[i][j]+costW[i][j]);
			}
			if(j+1<=N){
				dp[i][j+1] = min(dp[i][j+1],
					dp[i][j]+costB[i][j]);
			}
		}
	}
	int ans = dp[N][N];
	cout << ans << endl;
}

