    //cost_w[i][j]:=黒をi個(0〜i-1)、白をj個(0〜j-1)置いてるときに番号jの白を置くときにかかる転倒数
    int cost_b[N][N+1], cost_w[N+1][N];
    rep(i, N){
        cost_b[i][0] = 0;
        //最初自分より右ですでに置かれてるものの数を数える
        rep(k, i){
            if(b[k] > b[i]) cost_b[i][0]++;
        }
        rep(j, N){
            cost_b[i][j+1] = cost_b[i][j];
            if(w[j] > b[i]) cost_b[i][j+1]++;
        }
    }
    rep(j, N){
        cost_w[0][j] = 0;
        rep(k, j){
            if(w[k] > w[j]) cost_w[0][j]++;
        }
        rep(i, N){
            cost_w[i+1][j] = cost_w[i][j];
            if(b[i] > w[j]) cost_w[i+1][j]++;
        }
    }
    //dp[i][j]:=黒を番号の小さい方からi個、白を小さい方からj個並べるのに必要な最小の操作の回数
    int dp[N+1][N+1];
    dp[0][0] = 0;
    rep2(i, 1, N){
        dp[i][0] = dp[i-1][0] + cost_b[i-1][0];
        dp[0][i] = dp[0][i-1] + cost_w[0][i-1];
    }
    rep2(i, 1, N){
        rep2(j, 1, N){
            dp[i][j] = min(dp[i-1][j]+cost_b[i-1][j], dp[i][j-1]+cost_w[i][j-1]);
        }
    }
    cout << dp[N][N] << endl;
}

