	for (int i = 0; i < 2 * N; i++) {
		string s; cin >> s;
		int x; cin >> x;
		if (s == "B") balls[i] = -x;
		else balls[i] = x;
	}

	// Build all black
	for (int i = 0; i < 2 * N; i++) {
		if (balls[i] > 0) continue;
		int x = -balls[i];
		for (int j = 0; j < i; j++) if (balls[j] > 0) FB[x][balls[j]] = 1;
		for (int j = N; j >= 0; j--) FB[x][j] += FB[x][j + 1];
	}

	// Build all while
	for (int i = 0; i < 2 * N; i++) {
		if (balls[i] < 0) continue;
		int x = balls[i];
		for (int j = 0; j < i; j++) if (balls[j] < 0) FW[x][-balls[j]] = 1;
		for (int j = N; j >= 0; j--) FW[x][j] += FW[x][j + 1];
	}

	int base = 0;
	for (int i = 0; i < 2 * N; i++) {
		if (balls[i] < 0){
			for (int j = 0; j < i; j++) if (balls[j] < 0 && balls[j] < balls[i])  base += 1;
		}
		else{
			for (int j = 0; j < i; j++) if (balls[j] > 0 && balls[j] > balls[i])  base += 1;
		}
	}

	for (int i = N; i >= 1; i--) for (int j = N; j >= 1; j--) {
		dp[i][j] = min(FB[i][j] + dp[i + 1][j], FW[j][i] + dp[i][j + 1]);
	}
	cout << dp[1][1] + base << endl;
}

