	for(int i=1;i<=n;i++)
	{
		Add(ps[0][i]);
		for(int j=1;j<=2*n;j++)
			S1[i][j]=Ask(j-1);
	}
	memset(tree,0,sizeof tree);
	for(int i=1;i<=n;i++)
	{
		Add(ps[1][i]);
		for(int j=1;j<=2*n;j++)
			S2[i][j]=Ask(j-1);
	}
	memset(F,0x3f,sizeof F); F[0][0]=0;
