struct BIT{
private:
    vector<ll> a;
    int n;
public:
    BIT(int sz){
        n=sz;
        a.resize(sz+1);
    }
    ll sum(int i){
        ll res=0;
        while(i>0){
            res+=a[i];
            i-=i&-i;
        }
        return res;
    }
    ll sum(int i,int j){
        return sum(j)-sum(i-1);
    }
    void add(int i,ll x){
        while(i<=n){
            a[i]+=x;
            i+=i&-i;
        }
    }
};

int main(){
    int n;
    cin>>n;
    vector<pair<int,int>> w,b;
    w.reserve(n),b.reserve(n);
    rep(i,n+n){
        char c;
        int a;
        cin>>c>>a;
        if(c=='W')w.push_back({a,i+1});
        else b.push_back({a,i+1});
    }
    sort(begin(w),end(w));
    sort(begin(b),end(b));
    int cntw[n+1][n+1],cntb[n+1][n+1];
    rep(i,n+1){
        BIT bit(n+n);
        rep(j,i){
            bit.add(w[j].second,1);
        }
        rep(j,n+1){
            if(i<n)cntw[i][j]=bit.sum(w[i].second,n+n);
            if(j<n){
                cntb[i][j]=bit.sum(b[j].second,n+n);
                bit.add(b[j].second,1);
            }
        }
    }
    int dp[n+1][n+1];
    fill(dp[0],dp[n+1],inf);
    dp[0][0]=0;
    rep(i,n+1){
        rep(j,n+1){
            if(i<n)dp[i+1][j]=min(dp[i+1][j],dp[i][j]+w[i].second+cntw[i][j]-(i+j+1));
            if(j<n)dp[i][j+1]=min(dp[i][j+1],dp[i][j]+b[j].second+cntb[i][j]-(i+j+1));
        }
    }
    cout<<dp[n][n]<<endl;
}

