struct BIT {
  int n;
  vector<ll> tree;
  BIT(int n):n(n),tree(n+1) {} 
  void fill(ll val) {
    REP(i, n+1) tree[i] = (i&-i) * val;
  }
  void add(int idx, ll val) {
    for (int x=idx+1; x<=n; x+=x&-x) tree[x] += val;
  }
  // sum[0, idx]
  ll range(int idx) {
    ll sum=0;
    for (int x=idx+1; x>0; x-=x&-x) sum += tree[x];
    return sum;
  }
  // sum[a, b]
  ll range(int a, int b) {
    return range(b) - range(a - 1);
  }
};

ll inversion_number(vector<int>A, int N) {
  ll ans = 0;
  // normalize(A); // 座標圧縮
  BIT bit(N + 5);
  REP(i, N) {
    ans += bit.range(N - A[i]);
    bit.add(N - A[i], 1);
  }
  return ans;
}

