int lowbit(int x)
{
	return -x&x;
}
void modify(int x)
{
	while(x<=n*2)
	{
		++tree[x];
		x+=lowbit(x);
	}
}
int Query(int x)
{
	int y=0;
	while(x)
	{
		y+=tree[x];
		x-=lowbit(x);
	}
	return y;
}
int main()
{
	scanf("%d\n",&n);
	for(i=1;i<=n*2;++i)
	{
		scanf("%c %d\n",&c[i],&a[i]);
