template <typename T>
struct BIT {
  vector<T> bit;
  int size;
  BIT(int _size) : bit(vector<T>(_size + 1, 0)), size(_size) {}
  void add(int index, T value) {
    for (int i = index + 1; i <= size; i += (i & -i)) bit[i] += value;
  }
  T sum(int a, int b) {  //sum of[a,b)
    return sum(b) - sum(a);
  }
  T sum(int a) {  // sum of[0,a) = sum of bit[0]~bit[a]
    T ret = 0;
    for (int i = a; i > 0; i -= (i & -i)) ret += bit[i];
    return ret;
  }
};
class Solver {
 public:
  int n;
  vector<int> pw, pb;
  Solver(LL n) : n(n), pw(n), pb(n){};

  void solve() {
    for (int i = 0; i < 2 * n; ++i) {
      char c;
      int a;
      cin >> c >> a;
      if (c == 'B') {
        pb[--a] = i;
      } else {
        pw[--a] = i;
      }
