    vector<vector<int>> dp(n + 1, vector<int>(n + 1));
    vector<BIT<int>> bits(n + 1, BIT<int>(2 * n));
    BIT<int> tmp(2 * n);
    bits[0] = tmp;
    int cnt = 0;
    for (int w = 1; w <= n; ++w) {
      cnt += tmp.sum(pw[w - 1], 2 * n);
      tmp.add(pw[w - 1], 1);
      dp[0][w] = cnt;
      bits[w] = tmp;
    }
    for (int b = 1; b <= n; ++b) {
      dp[b][0] = dp[b - 1][0] + bits[0].sum(pb[b - 1], 2 * n);
      bits[0].add(pb[b - 1], 1);
      for (int w = 1; w <= n; ++w) {
        dp[b][w] = dp[b][w - 1] + bits[w - 1].sum(pw[w - 1], 2 * n);
        dp[b][w] = min(dp[b][w], dp[b - 1][w] + bits[w].sum(pb[b - 1], 2 * n));
        bits[w].add(pb[b - 1], 1);
      }
    }
    cout << dp[n][n] << endl;
  }
};

