using namespace std;
//-------------------------------------------------------------------
ll M=1;
std::vector<ll> W, B;
void init(int N){
  while(M<N) M*=2;
  M=M*2-1;
  for(int i=0;i<M;i++) {
    W.push_back(0);
    B.push_back(0);
  }
}
void update(int l, int r, int k, int mode){
  k+=(M+1)/2-1;
  (mode==1?W[k]:B[k])++;
  while(k>0){
    k = (k-1)/2;
    (mode==1?W[k]:B[k]) = (mode==1?W[k*2+1]+W[k*2+2]:B[k*2+1]+B[k*2+2]);
  }
}
ll query(int a, int b, int l, int r, int k, int mode){
  if(r<=a || b<=l) return 0;
  if(a<=l && r<=b) return (mode==1?W[k]:B[k]);
  ll A = query(a, b, l, (l+r)/2, k*2+1, mode);
  ll B = query(a, b, (l+r)/2, r, k*2+2, mode);
  return A + B;
}
//-------------------------------------------------------------------

