      if(j==N+1) (c=='W'?big_w[a][j]:big_b[a][j]) = tmp;
      else (c=='W'?big_w[a][j]:big_b[a][j]) = tmp + query(j, (M+1)/2, 0, (M+1)/2, 0, (c=='W'?-1:1));
    }

    update(0, (M+1)/2, a, (c=='W'?1:-1));
  }
  vvl dp = vv(N+1, N+1, 0, ll);
  for(int i=0;i<=N;i++){
    for(int j=0;j<=N;j++){
      if(i==0&&j==0) continue;
      dp[i][j] = min((i==0?INF:dp[i-1][j]+big_w[i][j+1]),(j==0?INF:dp[i][j-1]+big_b[j][i+1]));
