void add_BIT(int N, int BIT[], int i, int k)
{
	while (i <= N) {
		BIT[i] += k;
		i += (i & -i);
	}
}

int sum_BIT(int BIT[], int r)
{
	int sum = 0;
	while (r > 0) {
		sum += BIT[r];
		r -= (r & -r);
	}
	return sum;
}

int main()
{
	int i, N, a, pos[2][2001];
	char c;
	scanf("%d", &N);
	for (i = 1; i <= N * 2; i++) {
		scanf(" %c %d", &c, &a);
		if (c == 'B') pos[0][a] = i;
		else pos[1][a] = i;
	}

	const int sup = 1 << 30;
	int j, BIT[4001] = {}, dp[2001][2001];
	for (i = 0; i <= N; i++) for (j = 0; j <= N; j++) dp[i][j] = sup;
	for (i = 0, dp[0][0] = 0; i < N; i++) {
		for (j = 1; j <= i; j++) add_BIT(N * 2, BIT, pos[0][j], 1);
		for (j = 0; j < N; j++) {
			if (dp[i][j] + pos[0][i+1] - sum_BIT(BIT, pos[0][i+1]) - 1 < dp[i+1][j]) dp[i+1][j] = dp[i][j] + pos[0][i+1] - sum_BIT(BIT, pos[0][i+1]) - 1;
			if (dp[i][j] + pos[1][j+1] - sum_BIT(BIT, pos[1][j+1]) - 1 < dp[i][j+1]) dp[i][j+1] = dp[i][j] + pos[1][j+1] - sum_BIT(BIT, pos[1][j+1]) - 1;
			add_BIT(N * 2, BIT, pos[1][j+1], 1);
		}
		if (dp[i][N] + pos[0][i+1] - sum_BIT(BIT, pos[0][i+1]) - 1 < dp[i+1][N]) dp[i+1][N] = dp[i][N] + pos[0][i+1] - sum_BIT(BIT, pos[0][i+1]) - 1;
		for (j = 1; j <= N * 2; j++) BIT[j] = 0;
	}
	for (i = 1; i <= N; i++) add_BIT(N * 2, BIT, pos[0][i], 1);
	for (j = 0; j < N; j++) {
		if (dp[N][j] + pos[1][j+1] - sum_BIT(BIT, pos[1][j+1]) - 1 < dp[N][j+1]) dp[N][j+1] = dp[N][j] + pos[1][j+1] - sum_BIT(BIT, pos[1][j+1]) - 1;
		add_BIT(N * 2, BIT, pos[1][j+1], 1);
	}
	printf("%d\n", dp[N][N]);
	fflush(stdout);
	return 0;
}

