int n;
int white[2010][2010];
int black[2010][2010];
int dp[2010][2010];

void init(int n){
	int i,j;
	for(i=0;i<=n;i++){
		for(j=0;j<=n;j++){
			dp[i][j]=-1;
		}
	}
}

int search(int w,int b){
	int s,t;

	if(dp[w][b]!=-1) return dp[w][b];
	if(w==n&&b==n){
		return 0;
	}else if(w==n){
		dp[w][b]=search(w,b+1)+black[b+1][w];
	}else if(b==n){
		dp[w][b]=search(w+1,b)+white[w+1][b];
	}else{
		s=search(w+1,b)+white[w+1][b];
		t=search(w,b+1)+black[b+1][w];

		dp[w][b]=min(s,t);
	}
	return dp[w][b];
}

