    dp[POS(i,0)]=dp[POS(i-1,0)]+(i-sum(bit,b[i]));
  }
  initBIT(bit);
  for(j=1;j<=n;j++){
    add(bit,w[j],1);
    dp[POS(0,j)]=dp[POS(0,j-1)]+(j-sum(bit,w[j]));
