class SumBinaryIndexedTree(val size:Int, private val mArray:Array<Int>){
    companion object {
        operator fun invoke(size:Int):SumBinaryIndexedTree{
            return SumBinaryIndexedTree(size, Array(size){0})
        }
    }
    private fun up(index:Int):Int{
        return index + ((index + 1) and (index.inv()))
    }
    private fun left(index:Int):Int{
        return index - ((index + 1) and (index.inv()))
    }
    operator fun get(index:Int):Int{
        var idx = left(index)
        var res = mArray[index]
        while (idx >= 0){
            res += mArray[idx]
            idx = left(idx)
        }
        return res
    }
    fun plusAt(index:Int, diff:Int):Unit{
        var idx = index
        while (idx < mArray.size){
            mArray[idx] = diff + mArray[idx]
            idx = up(idx)
        }
    }
}
