fun f(b:Int, w:Int, blackCost:Array<Array<Int>>, whiteCost:Array<Array<Int>>, memo:Array<Array<Int>>):Int{
    if (b == 0 && w == 0) return 0
    if (b < 0 || w < 0) return Int.MAX_VALUE shr 2
    if (memo[b][w] < 0){
        memo[b][w] = min(f(b - 1, w, blackCost, whiteCost, memo) + blackCost[b][w], f(b, w - 1, blackCost, whiteCost, memo) + whiteCost[w][b])
    }
    return memo[b][w]
}

