import java.lang.Math.min
class SumBinaryIndexedTree(implement: BinaryIndexedTree<Int>):BinaryIndexedTree<Int> by implement{
    companion object {
        inline operator fun invoke(size:Int):SumBinaryIndexedTree{
            return SumBinaryIndexedTree(BinaryIndexedTreeTemplate<Int>(size, 0, Int::plus))
        }
    }
}

interface BinaryIndexedTree<T> {
    operator fun get(index:Int):T
    fun plusAt(index:Int, diff:T):Unit
}
class BinaryIndexedTreeTemplate<T> (val size:Int, private val monoidPlus:(T, T) -> T, private val mArray:Array<T>): BinaryIndexedTree<T>{
    companion object {
        inline operator fun <reified T> invoke(size:Int, zero:T, noinline monoidPlus:(T, T) -> T):BinaryIndexedTreeTemplate<T>{
            return BinaryIndexedTreeTemplate(size, monoidPlus, Array(size){zero})
        }
    }
    private inline fun up(index:Int):Int{
        return index + ((index + 1) and (index.inv()))
    }
    private inline fun left(index:Int):Int{
        return index - ((index + 1) and (index.inv()))
    }
    private fun accumulate(a:T, b:T):T = monoidPlus(a, b)
    override operator fun get(index:Int):T{
        var idx = left(index)
        var res = mArray[index]
        while (idx >= 0){
            res = accumulate(res, mArray[idx])
            idx = left(idx)
        }
        return res
    }
    override fun plusAt(index:Int, diff:T):Unit{
        var idx = index
        while (idx < mArray.size){
            mArray[idx] = accumulate(diff, mArray[idx])
            idx = up(idx)
        }
    }
}
