	static void solve()
	{
		int n = ni();
		int[] a = new int[2*n];
		for(int i = 0;i < 2*n;i++){
			char c = nc();
			if(c == 'W'){
				a[i] = -ni();
			}else{
				a[i] = ni();
			}
		}

		long[][] dp = new long[n+1][n+1];
		for(int i = 0;i <= n;i++){
			Arrays.fill(dp[i], Integer.MAX_VALUE);
		}
		dp[0][0] = 0;

		boolean[][] fronts = new boolean[n+1][n+1];
		int[] fs = new int[n+1];
		boolean[][] fronts2 = new boolean[n+1][n+1];
		int[] fs2 = new int[n+1];
		for(int i = 0;i < n+1;i++){
			boolean[] front = new boolean[n+1];
			int f = 0;
			for(int j = 0;j < 2*n;j++){
				if(a[j] == i+1)break;
				if(a[j] < 0){
					front[-a[j]] = true;
				}else if(a[j] < i+1)continue;
				f++;
			}
			fronts[i] = front;
			fs[i] = f;
		}
		for(int i = 0;i < n+1;i++){
			boolean[] front = new boolean[n+1];
			int f = 0;
			for(int j = 0;j < 2*n;j++){
				if(a[j] == -(i+1))break;
				if(a[j] > 0){
					front[a[j]] = true;
				}else if(a[j] > -(i+1))continue;
				f++;
			}
			fronts2[i] = front;
			fs2[i] = f;
		}

		for(int i = 0;i < n+1;i++){
			for(int j = 0;j < n+1;j++){
//				tr(i, j, fs, fs2);
				if(i < n){
					dp[i+1][j] = Math.min(
							dp[i+1][j], dp[i][j] + fs[i]);
					if(j+1 <= n && fronts[i][j+1])fs[i]--;
				}
				if(j < n){
					dp[i][j+1] = Math.min(
							dp[i][j+1], dp[i][j] + fs2[j]);
					if(i+1 <= n && fronts2[j][i+1])fs2[j]--;
				}
			}
		}
//		tr(dp);
		out.println(dp[n][n]);
	}


