    for (int i = 0; i < n * 2; i ++) {
      inv[c[i][0]][c[i][1]] = i;

      for (int j = 0; j < n; j ++) {
        sum[0][i + 1][j] = sum[0][i][j] + (c[i][0] == 0 && c[i][1] > j ? 1: 0);
        sum[1][i + 1][j] = sum[1][i][j] + (c[i][0] == 1 && c[i][1] > j ? 1: 0);
      }
    }

    int[][] dp = new int[n + 1][n + 1];
    for (int[] v :dp) Arrays.fill(v, Integer.MAX_VALUE / 2);
