public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			P[] p = new P[2*n];
			for (int i = 0; i < 2*n; i++) {
				p[i] = new P(in.nextChar(), in.nextInt());
			}

			int[] idxB = new int[n+1], idxW = new int[n+1];
			for (int i = 1; i <= n; i++) {
				for (int j = 0; j < 2*n; j++) {
					if (p[j].c == 'B' && p[j].a == i) idxB[i] = j;
					if (p[j].c == 'W' && p[j].a == i) idxW[i] = j;
				}
			}
			int[][] costB = new int[n+1][2*n], costW = new int[n+1][2*n];
			for (int i = 0; i <= n; i++) {
				for (int j = 0; j < 2*n; j++) {
					costB[i][j] = (j-1 >= 0 ? costB[i][j-1] : 0) + (p[j].c == 'B' && p[j].a > i ? 1 : 0);
					costW[i][j] = (j-1 >= 0 ? costW[i][j-1] : 0) + (p[j].c == 'W' && p[j].a > i ? 1 : 0);
				}
			}

			long[][] dp = new long[n+1][n+1];
			fill(dp, LINF);
			dp[0][0] = 0;
			for (int b = 0; b <= n; b++) {
				for (int w = 0; w <= n; w++) {
					if (b < n) dp[b+1][w] = Math.min(dp[b+1][w], dp[b][w] + costB[b+1][idxB[b+1]] + costW[w][idxB[b+1]]);
					if (w < n) dp[b][w+1] = Math.min(dp[b][w+1], dp[b][w] + costB[b][idxW[w+1]] + costW[w+1][idxW[w+1]]);
				}
			}

			out.println(dp[n][n]);

		}

		class P {
			char c;
			int a;

			public P(char c, int a) {
				super();
				this.c = c;
				this.a = a;
			}

			@Override
			public String toString() {
				return "P [c=" + c + ", a=" + a + "]";
			}
		}
	}

	static void fill(long[][] a, long v) {
		for (int i = 0; i < a.length; i++) {
			for (int j = 0; j < a[0].length; j++) {
				a[i][j] = v;
			}
		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
