import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        boolean[] col = new boolean[2 * n];
        int[] num = new int[2 * n];
        int[] rb = new int[n + 1];
        int[] rw = new int[n + 1];
        for (int i = 0; i < 2 * n; i++) {
            col[i] = sc.nextChars(1)[0] == 'B';
            num[i] = sc.nextInt();
            if (col[i]) rb[num[i]] = i;
            else rw[num[i]] = i;
        }
        int[][] b = new int[2 * n + 1][n + 1];
        int[][] w = new int[2 * n + 1][n + 1];
        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= n; j++) {
                if (col[i - 1]) {
                    w[i][j] = w[i - 1][j];
                    b[i][j] = j >= num[i - 1] ? b[i - 1][j] : b[i - 1][j] + 1;
                } else {
                    b[i][j] = b[i - 1][j];
                    w[i][j] = j >= num[i - 1] ? w[i - 1][j] : w[i - 1][j] + 1;
                }
            }
        }
        final int INF = 1 << 29;
        int[][] dp = new int[n + 1][n + 1];
        for (int k = 1; k <= 2 * n; k++) {
            for (int i = Math.max(0, k - n); i <= Math.min(n, k); i++) {
                int j = k - i;
                int cw = i > 0 ? dp[i - 1][j] + w[rw[i]][i] + b[rw[i]][j] : INF;
                int cb = j > 0 ? dp[i][j - 1] + w[rb[j]][i] + b[rb[j]][j] : INF;
                dp[i][j] = Math.min(cw, cb);
            }
        }
        out.writeln(dp[n][n]);
    }
}


