import java.util.Arrays;

class SegmentTreeRSQ {
  public int M, H, N;
  public long[] st;
  public long[] plus;

  public SegmentTreeRSQ(int n) {
    N = n;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    plus = new long[H];
  }

  public SegmentTreeRSQ(int[] a) {
    N = a.length;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    plus = new long[H];
    for (int i = 0; i < N; i++) {
      st[H + i] = a[i];
    }
    for (int i = (M >> 1) - 1; i >= 1; i--) {
      propagate(i);
    }
  }

  public void add(int pos, int v) {
    for (int i = H + pos; i >= 1; i >>>= 1) {
      st[i] += v;
    }
  }

  private void propagate(int i) {
    int count = H / Integer.highestOneBit(i);
    st[i] = st[2 * i] + st[2 * i + 1] + plus[i] * count;
  }

  public void add(int l, int r, int v) {
    if (l < r)
      add(l, r, v, 0, H, 1);
  }

  private void add(int l, int r, int v, int cl, int cr, int cur) {
    if (cur >= H) {
      st[cur] += v;
    } else if (l <= cl && cr <= r) {
      plus[cur] += v;
      propagate(cur);
    } else {
      int mid = cl + cr >>> 1;
      if (cl < r && l < mid) {
        add(l, r, v, cl, mid, 2 * cur);
      }
      if (mid < r && l < cr) {
        add(l, r, v, mid, cr, 2 * cur + 1);
      }
      propagate(cur);
    }
  }

  private long gsum;

  public long sum(int l, int r) {
    gsum = 0;
    sum(l, r, 0, H, 1);
    return gsum;
  }

  private void sum(int l, int r, int cl, int cr, int cur) {
    if (l <= cl && cr <= r) {
      gsum += st[cur];
    } else {
      int mid = cl + cr >>> 1;
      if (cl < r && l < mid) {
        sum(l, r, cl, mid, 2 * cur);
      }
      if (mid < r && l < cr) {
        sum(l, r, mid, cr, 2 * cur + 1);
      }
      gsum += plus[cur] * (Math.min(r, cr) - Math.max(l, cl));
    }
  }
}


public class Main {

  private static void solve() {
    int n = ni();
    int[][] p = new int[2 * n][2];
    for (int i = 0; i < 2 * n; i++) {
      p[i][0] = ns()[0] == 'W' ? 0 : 1;
      p[i][1] = ni() - 1;
    }

    int[][] dp = new int[n + 1][n + 1];
    int[][] inv = new int[2][n];
    for (int i = 0; i < n * 2; i++) {
      inv[p[i][0]][p[i][1]] = i;
    }

    SegmentTreeRSQ st1 = new SegmentTreeRSQ(n * 2);
    SegmentTreeRSQ st2 = new SegmentTreeRSQ(n * 2);

    for (int[] v : dp)
      Arrays.fill(v, Integer.MAX_VALUE / 10);
    dp[0][0] = 0;

    for (int i = 0; i <= n; i++) {
      if (i > 0) {
        Arrays.fill(st2.plus, 0);
        Arrays.fill(st2.st, 0);

        for (int j = 0; j <= n; j++) {
          if (j > 0)
            st2.add(inv[1][j - 1], 1);
          int x = inv[0][i - 1];
          x -= (int) st1.sum(0, inv[0][i - 1]);
          x -= (int) st2.sum(0, inv[0][i - 1]);
          dp[i][j] = Math.min(dp[i][j], dp[i - 1][j] + x);
        }
        st1.add(inv[0][i - 1], 1);
      }

      Arrays.fill(st2.plus, 0);
      Arrays.fill(st2.st, 0);
      for (int j = 1; j <= n; j++) {
        st2.add(inv[1][j - 1], 1);
        int x = inv[1][j - 1];
        x -= (int) st1.sum(0, inv[1][j - 1]);
        x -= (int) st2.sum(0, inv[1][j - 1]);
        dp[i][j] = Math.min(dp[i][j], dp[i][j - 1] + x);
      }
    }
    System.out.println(dp[n][n]);
  }



