import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	Scanner sc = new Scanner(System.in);

	void run() {
		int n = sc.nextInt();
		/*
		 * int b[] = new int[n]; int w[] = new int[n];
		 * 
		 * for(int i =0 ; i < n ; i++){ String c = sc.next(); int a =
		 * sc.nextInt()-1; if(c.startsWith("B")){ b[a] = i; }else{ w[a] = i; } }
		 */
		int[] b = new int[2 * n];
		int[] w = new int[2 * n];

		int[] ib = new int[n + 1];
		int[] iw = new int[n + 1];

		for (int i = 0; i < n * 2; i++) {
			String c = sc.next();
			int a = sc.nextInt();
			if (c.startsWith("B")) {
				b[i] = a;
				w[i] = -1;
				ib[a] = i;
			} else {
				w[i] = a;
				b[i] = -1;
				iw[a] = i;
			}
		}

		int[][] bbb = new int[n * 2 + 1][n + 1];
		int[][] www = new int[n * 2 + 1][n];
		for (int i = 1; i < n * 2; i++) {
			for (int j = 0; j < n; j++) {
				if (b[i] > 0 && b[i] < j + 1) {
					bbb[i][j] = bbb[i - 1][j] + 1;
				} else {
					bbb[i][j] = bbb[i - 1][j];
				}
				if (w[i] > 0 && w[i] < j + 1) {
					www[i][j] = www[i - 1][j] + 1;
				} else {
					www[i][j] = www[i - 1][j];
				}
			}
		}

		int dp[][] = new int[n + 1][n + 1];

		int ub = upperbound(n, b, w);

		for (int i = 0; i < n + 1; i++) {
			Arrays.fill(dp[i], Integer.MAX_VALUE / 3);
		}

		dp[0][0] = 0;
		for (int i = 0; i < 2 * n; i++) {

			for (int bb = Math.max(0, i - n); bb <= i && bb <= n; bb++) {
				int ww = i - bb;

				if (dp[bb][ww] >= ub) {
					continue;
				}
				// System.out.println(i+" "+bb+" "+ ww);
				// b

				if (bb < n) {
					int ibx = ib[bb + 1];
					int scb = ibx - www[ibx][ww] - bbb[ibx][bb];
					dp[bb + 1][ww] = Math.min(dp[bb + 1][ww], dp[bb][ww] + scb);
				}
				if (ww < n) {
					int iwx = iw[ww + 1];
					int scw = iwx - www[iwx][ww] - bbb[iwx][bb];
					dp[bb][ww + 1] = Math.min(dp[bb][ww + 1], dp[bb][ww] + scw);
				}
			}
		}
		System.out.println(Math.min(dp[n][n], ub));

	}

	int upperbound(int n, int b[], int w[]) {
		int af = 0;
		int bf = 0;
		int ans = 0;

		boolean used[] = new boolean[2 * n];
		for (int i = 0; i < 2 * n; i++) {

			// System.out.println("searching " +i+"th element
			// -------------------------" +af+" "+bf);
			for (int j = 0; j < 2 * n; j++) {
				// System.out.println(" checking: "+j + " "+b[j]+" "+w[j]);
				if (used[j]) {
					continue;
				}
				if (af + 1 == b[j]) {
					// System.out.println("isBlackMinimum");
					used[j] = true;
					af++;
					break;
				}
				if (bf + 1 == w[j]) {
					// System.out.println("isWhiteMinimum");
					used[j] = true;
					bf++;
					break;
				}

				ans++;

			}
		}
		return ans;
	}
}

