				w[i] = -1;
			} else {
				w[i] = a;
				b[i] = -1;
			}
		}


		int dp[][] = new int[n + 1][n + 1];

		int ub = upperbound(n,b,w);

		for (int i = 0; i < n + 1; i++) {
