import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int[][] ball = new int[2*n][2];
        for (int i = 0; i < 2*n ; i++) {
            char c = in.nextToken().toCharArray()[0];
            ball[i][0] = c == 'B' ? 1 : 0;
            ball[i][1] = in.nextInt()-1;
        }

        int ans = (int)1e9;
        for (int k = 0 ; k <= 1 ; k++) {
            int[][] b2 = new int[2*n][2];
            for (int i = 0; i < ball.length ; i++) {
                b2[i] = ball[i].clone();
            }

            int total = 0;
            int nextW = 0;
            int nextB = 0;
            for (int i = 0; i < 2 * n; i++) {
                int idx = -1;
                for (int j = i; j < 2 * n; j++) {
                    if (b2[j][0] == 0 && b2[j][1] == nextW) {
                        idx = j;
                        nextW++;
                        break;
                    } else if (b2[j][0] == 1 && b2[j][1] == nextB) {
                        idx = j;
                        nextB++;
                        break;
                    }
                }
                for (int j = idx; j >= i + 1; j--) {
                    swap(b2, j, j - 1);
                    total++;
                }
            }

            for (int i = 0; i < ball.length/2; i++) {
                swap(ball, i, ball.length-1-i);
            }
            for (int i = 0; i < ball.length ; i++) {
                ball[i][1] = n-1-ball[i][1];
            }
            ans = Math.min(ans, total);
        }

        out.println(ans);
        out.flush();
    }

    public static void swap(int[][] ball, int i, int j) {
        for (int k = 0 ; k <= 1 ; k++) {
            int tmp = ball[i][k];
            ball[i][k] = ball[j][k];
            ball[j][k] = tmp;
        }
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static int[][]memo,inv[];
    static int[][]a;
    static int dp(int i,int j){
        if (i+j==a.length)
            return 0;
        if (memo[i][j]!=-1)
            return memo[i][j];
        int ans=(int)1e9;
        if (i<a.length/2){
            ans=Math.min(ans,inv[0][i+1][j]+dp(i+1,j));
        }
        if (j<a.length/2){
            ans=Math.min(ans,inv[1][j+1][i]+dp(i,j+1));
        }
        return memo[i][j]=ans;
    }
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n= sc.nextInt();
        a= new int[2*n][2];
        for (int i =0;i<2*n;i++){
            int t = sc.next().charAt(0)=='W'?0:1;
            a[i][0]=sc.nextInt();
            a[i][1]=t;
        }
        inv= new int[2][n+1][n+1];

        FenwickTree[] fn = new FenwickTree[2];
        fn[0]= new FenwickTree(n+1);
        fn[1]=new FenwickTree(n+1);
        for (int i =0;i<2*n;i++){
            int c=a[i][1];
            int v = a[i][0];
            for (int j=0;j<=n;j++){
                inv[c][v][j]=fn[c].rsq(v+1,n+1)+fn[1^c].rsq(j+1,n+1);
            }
            fn[c].point_update(v,1);
        }
        memo= new int[n+1][n+1];
        for (int[]x:memo)Arrays.fill(x,-1);
        pw.println(dp(0,0));
        pw.flush();
    }
    static class FenwickTree { // one-based DS

        int n;
        int[] ft;

        FenwickTree(int size) { n = size; ft = new int[n+1]; }

        int rsq(int b) //O(log n)
        {
            int sum = 0;
            while(b > 0) { sum += ft[b]; b -= b & -b;}		//min?
            return sum;
        }

        int rsq(int a, int b) { return rsq(b) - rsq(a-1); }

        void point_update(int k, int val)	//O(log n), update = increment
        {
            while(k <= n) { ft[k] += val; k += k & -k; }		//min?
        }
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(FileReader r) {
            br = new BufferedReader(r);
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public int[] nextIntArr(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < arr.length; i++)
                arr[i] = nextInt();
            return arr;
        }

        public boolean ready() throws IOException {
