    static void swap(int i) {
        int     tmpa = a[i]; a[i] = a[i+1]; a[i+1] = tmpa;
        boolean tmpc = c[i]; c[i] = c[i+1]; c[i+1] = tmpc;
    }

    static boolean scan() {
        boolean finish = true;
        int w = 0, b = 0;
        for (int i=0; i<n*2; i++) {
            if (c[i]) { nth[i] = ++w; }
            else      { nth[i] = ++b; }
            if (a[i] != nth[i]) finish = false;
        }
        return finish;
    }


    static void print() {
        /*
        for (int i=0; i<n*2; i++) {
