/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            ESortedAndSorted solver = new ESortedAndSorted();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class ESortedAndSorted {
        Debug debug = new Debug(false);

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] T = new int[n * 2 + 1];
            int[] A = new int[n * 2 + 1];
            int[][] invIndex = new int[2][n + 1];
            for (int i = 1; i <= n * 2; i++) {
                T[i] = in.readChar() == 'B' ? 0 : 1;
                A[i] = in.readInt();
                invIndex[T[i]][A[i]] = i;
            }


            int[][][] ps = new int[2][n * 2 + 1][n + 1];
            for (int i = 0; i < 2; i++) {
                for (int j = 1; j <= n * 2; j++) {
                    System.arraycopy(ps[i][j - 1], 0, ps[i][j], 0, n + 1);
                    if (T[j] != i) {
                        continue;
                    }
                    ps[i][j][A[j]] = 1;
                }
            }

            for (int i = 0; i < 2; i++) {
                for (int j = 0; j <= n * 2; j++) {
                    for (int k = 1; k <= n; k++) {
                        ps[i][j][k] += ps[i][j][k - 1];
                    }
                }
            }

            int inf = (int) 1e9;
            int[][] dp = new int[n * 2 + 1][n + 1];
            SequenceUtils.deepFill(dp, inf);
            dp[0][0] = 0;
            for (int i = 1; i <= 2 * n; i++) {
                for (int j = 0; j <= n && j <= i; j++) {
                    int b = j;
                    int w = i - j;

                    if (w < 0 || w > n) {
                        continue;
                    }

                    if (b > 0) {
                        //put B
                        int index = invIndex[0][j];
                        int cross = index - 1 - (ps[0][index - 1][j] + ps[1][index - 1][w]);
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1] + cross);
                    }
                    if (w > 0) {
                        int index = invIndex[1][w];
                        int cross = index - 1 - (ps[0][index - 1][b] + ps[1][index - 1][w]);
                        dp[i][j] = Math.min(dp[i][j], dp[i - 1][j] + cross);
                    }
                }
            }

            debug.debug("ps", ps);
            debug.debug("dp", dp);
            int ans = dp[n * 2][n];
            out.println(ans);
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
