import java.util.*;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    static int scanInt() {
        return Integer.parseInt(scanner.next());
    }

    public static void main(String[]$) {
        int n = scanInt();
        int m = scanInt();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = scanInt() - 1;
        }

        UnionFind unionFind = new UnionFind(n);
        for (int i = 0; i < m; i++) {
            unionFind.unite(scanInt() - 1, scanInt() - 1);
        }

        int ans = 0;
        for (int parent : unionFind.parents()) {
            Set<Integer> children = unionFind.children(parent);
            Set<Integer> set = new HashSet<>();
            for (int child : children) {
                set.add(p[child]);
            }

            for (int child : children) {
                if (set.contains(child)) {
                    ans++;
                }
            }
        }

        System.out.println(ans);
    }

    static class UnionFind {
        private int[] parent;
        private Set<Integer> parents;
        private Set<Integer>[] children;

        UnionFind(int n) {
            parent = new int[n];
            parents = new HashSet<>();
            children = new Set[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                parents.add(i);
                children[i] = new HashSet<>();
                children[i].add(i);
            }
        }

        int root(int x) {
            while (parent[x] != x) {
                x = parent[x] = parent[parent[x]];
            }
            return x;
        }

        void unite(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (children[x].size() < children[y].size()) {
                    parent[y] = x;
                    parents.remove(y);
                    children[x].addAll(children[y]);
                } else {
                    parent[x] = y;
                    parents.remove(x);
                    children[y].addAll(children[x]);
                }
            }
        }

        Set<Integer> parents() {
            return parents;
        }

        Set<Integer> children(int x) {
            return children[root(x)];
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		int n = sc.nextInt();
		int[] v = new int[2 * n + 1];
		char[] c = new char[2 * n + 1];
		int[] mapw = new int[n + 1];
		int[] mapb = new int[n + 1];
		for (int i = 1; i < c.length; i++) {
			c[i] = sc.next().charAt(0);
			v[i] = sc.nextInt();
			if (c[i] == 'W') {
				mapw[v[i]] = i;
			} else
				mapb[v[i]] = i;
		}
		FenwickTree ft = new FenwickTree(2 * n);
		for (int i = 1; i <= 2 * n; i++)
			ft.point_update(i, 1);

		int minw = 1;
		int minb = 1;
		long ans = 0;
		while (minw != n + 1 && minb != n + 1) {
			if (mapw[minw] < mapb[minb]) {
				ft.point_update(mapw[minw], -1);
				ans += ft.rsq(mapw[minw]);
				minw++;
			} else {
				ft.point_update(mapb[minb], -1);
				ans += ft.rsq(mapb[minb]);
				minb++;
			}
		}
		while (minw != n + 1) {
			ft.point_update(mapw[minw], -1);
			ans += ft.rsq(mapw[minw]);
			minw++;
		}
		while (minb != n + 1) {
			ft.point_update(mapb[minb], -1);
			ans += ft.rsq(mapb[minb]);
			minb++;
		}
		pw.println(ans);
		pw.close();

	}

	static class FenwickTree { // one-based DS

		int n;
		int[] ft;

		FenwickTree(int size) {
			n = size;
			ft = new int[n + 1];
		}

		int rsq(int b) // O(log n)
		{
			int sum = 0;
			while (b > 0) {
				sum += ft[b];
				b -= b & -b;
			} // min?
			return sum;
		}

		int rsq(int a, int b) {
			return rsq(b) - rsq(a - 1);
		}

		void point_update(int k, int val) // O(log n), update = increment
		{
			while (k <= n) {
				ft[k] += val;
				k += k & -k;
			} // min?
		}

		int point_query(int idx) // c * O(log n), c < 1
		{
			int sum = ft[idx];
			if (idx > 0) {
				int z = idx ^ (idx & -idx);
				--idx;
				while (idx != z) {
					sum -= ft[idx];
					idx ^= idx & -idx;
				}
			}
			return sum;
		}

	}

	static class Scanner {
		BufferedReader br;
		StringTokenizer st;

		public Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public double nextDouble() throws IOException {
			return Double.parseDouble(next());
		}

		public int[] nextIntArr(int n) throws IOException {
			int[] arr = new int[n];
			for (int i = 0; i < n; i++) {
				arr[i] = Integer.parseInt(next());
			}
			return arr;
		}

	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int[][] balls = new int[2*n][2];
        for (int i = 0; i < 2*n ; i++) {
            int c = in.nextToken().toCharArray()[0] == 'W' ? 0 : 1;
            int a = in.nextInt()-1;
            balls[i][0] = c;
            balls[i][1] = a;
        }

        int[][][] costTable = new int[2][n][];
        for (int i = 0; i < 2*n ; i++) {
            int co = balls[i][0];
            int wo = co ^ 1;
            int sameCost = 0;
            int[] tbl = new int[n+1];
            for (int j = 0; j < i ; j++) {
                if (balls[j][0] == wo) {
                    tbl[balls[j][1]]++;
                } else if (balls[j][1] > balls[i][1]) {
                    sameCost++;
                }
            }
            for (int j = n-2 ; j >= 0 ; j--) {
                tbl[j] += tbl[j+1];
            }
            for (int j = 0; j <= n; j++) {
                tbl[j] += sameCost;
            }
            costTable[co][balls[i][1]] = tbl;
        }

        final int INF = (int)1e9;
        int[][] dp = new int[n+1][n+1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], INF);
        }

        dp[0][0] = 0;
        for (int i = 0; i <= n ; i++) {
            for (int j = 0; j <= n ; j++) {
                int base = dp[i][j];
                if (base == INF) {
                    continue;
                }
                if (i+1 <= n) {
                    dp[i+1][j] = Math.min(dp[i+1][j], base + costTable[0][i][j]);
                }
                if (j+1 <= n) {
                    dp[i][j+1] = Math.min(dp[i][j+1], base + costTable[1][j][i]);
                }
            }
        }

        out.println(dp[n][n]);
        out.flush();
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

