    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.nextInt();

        n *= 2;

        ball[] ball = new ball[n];
        ball[] ball2 = new ball[n];

        for (int i = 0; i < n; i++) {
            ball[i] = new ball(in.nextString().charAt(0), in.nextInt());
            ball2[i] = new ball(ball[i].c, ball[i].a);
        }


        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            char c = ball[i].c;
            int num = ball[i].a;

            int gi = i;
            int gn = num;
            for (int j = i - 1; j >= 0; j--) {
                if (c == ball[j].c) {
                    if (ball[j].a > gn) {
                        gn = ball[j].a;
                        gi = j;
                    }
                }
            }

            if (gi < i) {
                ball tb = ball[gi];

                for (int j = gi; j < i; j++) {
                    ball[j] = ball[j + 1];
                }

                ball[i] = tb;


                ans += i - gi;
            }
        }

        int ans2 = 0;

        ball = ball2;

        for (int i = 0; i < n; i++) {
            char c = ball[i].c;
            int num = ball[i].a;

            int gi = i;
            int gn = num;
            for (int j = i + 1; j < n; j++) {
                if (c == ball[j].c) {
                    if (ball[j].a < gn) {
                        gn = ball[j].a;
                        gi = j;
                    }
                }
            }

            if (gi > i) {
                ball tb = ball[gi];

                for (int j = i + 1; j <= gi; j++) {
                    ball[j] = ball[j - 1];
                }

                ball[i] = tb;


                ans2 += gi - i;
            }
        }
        System.out.println(Math.min(ans, ans2));

    }

