        int rec(int w, int b) {
            int i = w + b;
            if (i == 0) return 0;
            if (memo[w][b] >= 0) return memo[w][b];
            int ans = Integer.MAX_VALUE;
            if (w > 0) {
//            dump(1, w, pos[1][w]);
                bit.add(pos[1][w], 1);
                ans = Math.min(ans, rec(w - 1, b) + bit.sum(pos[1][w] - 1));
                bit.add(pos[1][w], -1);
            }
            if (b > 0) {
                bit.add(pos[0][b], 1);
                ans = Math.min(ans, rec(w, b - 1) + bit.sum(pos[0][b] - 1));
                bit.add(pos[0][b], -1);
            }
            return memo[w][b] = ans;
        }

        class BIT {
            final int n;
            final int[] bit;

            public BIT(int size) {
                n = size;
                bit = new int[n + 1];
            }

            public int sum(int i) {
                int res = 0;
                for (; i > 0; i -= i & -i) {
                    res += bit[i];
                }
                return res;
            }

            public void add(int i, int x) {
                if (i == 0) throw new RuntimeException();
                for (; i <= n; i += i & -i) {
                    bit[i] += x;
                }
            }

        }

