public class Main {

    class ball {
        char c;
        int a;

        public ball(char c, int a) {
            this.c = c;
            this.a = a;
        }
    }

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.nextInt();

        n *= 2;

        ball[] ball = new ball[n];
        ball[] ball2 = new ball[n];

        for (int i = 0; i < n; i++) {
            ball[i] = new ball(in.nextString().charAt(0), in.nextInt());
            ball2[i] = new ball(in.nextString().charAt(0), in.nextInt());
        }


        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            char c = ball[i].c;
            int num = ball[i].a;

            int gi = i;
            int gn = num;
            for (int j = i - 1; j >= 0; j--) {
                if (c == ball[j].c) {
                    if (ball[j].a > gn) {
                        gn = ball[j].a;
                        gi = j;
                    }
                }
            }

            if (gi < i) {
                ball tb = ball[gi];

                for (int j = gi; j < i; j++) {
                    ball[j] = ball[j + 1];
                }

                ball[i] = tb;


                ans += i - gi;
            }
        }

        int ans2 = 0;

        ball = ball2;

        for (int i = 0; i < n; i--) {
            char c = ball[i].c;
            int num = ball[i].a;

            int gi = i;
            int gn = num;
            for (int j = i + 1; j < n; j++) {
                if (c == ball[j].c) {
                    if (ball[j].a < gn) {
                        gn = ball[j].a;
                        gi = j;
                    }
                }
            }

            if (gi > i) {
                ball tb = ball[gi];

                for (int j = i + 1; j <= gi; j++) {
                    ball[j] = ball[j - 1];
                }

                ball[i] = tb;


                ans2 += gi - i;
            }
        }
        System.out.println(Math.min(ans, ans2));

    }

    Set<Integer> ind = new HashSet<>();
    Set<Integer> num = new HashSet<>();

    void dfs(int u, List[] g, int[] p, boolean[] vis) {

        ind.add(u);
        num.add(p[u]);

        vis[u] = true;

        for (int i = 0; i < g[u].size(); i++) {
            int v = (int) g[u].get(i);

            if (!vis[v])
                dfs(v, g, p, vis);
        }
    }

