import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	Scanner sc = new Scanner(System.in);

	void run() {
		int n = sc.nextInt();
		/*
		 * int b[] = new int[n]; int w[] = new int[n];
		 * 
		 * for(int i =0 ; i < n ; i++){ String c = sc.next(); int a =
		 * sc.nextInt()-1; if(c.startsWith("B")){ b[a] = i; }else{ w[a] = i; } }
		 */
		int[] b = new int[2 * n];
		int[] w = new int[2 * n];

		int[] ib = new int[n + 1];
		int[] iw = new int[n + 1];

		for (int i = 0; i < n * 2; i++) {
			String c = sc.next();
			int a = sc.nextInt();
			if (c.startsWith("B")) {
				b[i] = a;
				w[i] = -1;
				ib[a] = i;
			} else {
				w[i] = a;
				b[i] = -1;
				iw[a] = i;
			}
		}

		int[][] bbb = new int[n * 2 + 1][n];
		int[][] www = new int[n * 2 + 1][n];
		for (int i = 1; i < n * 2; i++) {
			for (int j = 0; j < n; j++) {
				if (b[i] > 0 && b[i] < j + 1) {
					bbb[i][j] = bbb[i - 1][j] + 1;
				} else {
					bbb[i][j] = bbb[i - 1][j];
				}
				if (w[i] > 0 && w[i] < j + 1) {
					www[i][j] = www[i - 1][j] + 1;
				} else {
					www[i][j] = www[i - 1][j];
				}
			}
		}

		int dp[][] = new int[n + 1][n + 1];

		int ub = upperbound(n, b, w);

		for (int i = 0; i < n + 1; i++) {
			Arrays.fill(dp[i], Integer.MAX_VALUE / 3);
		}

		dp[0][0] = 0;
		for (int i = 0; i < 2 * n; i++) {

			for (int bb = Math.max(0, i - n); bb <= i && bb <= n; bb++) {
				int ww = i - bb;

				if (dp[bb][ww] >= ub) {
					continue;
				}
				// System.out.println(i+" "+bb+" "+ ww);
				// b

				if (bb < n) {
					int ibx = ib[bb + 1];
					int scb = ibx - www[ibx][Math.min(ww,n)] - bbb[ibx][bb];
					dp[bb + 1][ww] = Math.min(dp[bb + 1][ww], dp[bb][ww] + scb);
				}
				if (ww < n) {
					int iwx = iw[ww + 1];
					int scw = iwx - www[iwx][ww] - bbb[iwx][Math.min(bb,n)];
					dp[bb][ww + 1] = Math.min(dp[bb][ww + 1], dp[bb][ww] + scw);
				}
			}
		}
		System.out.println(Math.min(dp[n][n], ub));

	}

	int upperbound(int n, int b[], int w[]) {
		int af = 0;
		int bf = 0;
		int ans = 0;

		boolean used[] = new boolean[2 * n];
		for (int i = 0; i < 2 * n; i++) {

			// System.out.println("searching " +i+"th element
			// -------------------------" +af+" "+bf);
			for (int j = 0; j < 2 * n; j++) {
				// System.out.println(" checking: "+j + " "+b[j]+" "+w[j]);
				if (used[j]) {
					continue;
				}
				if (af + 1 == b[j]) {
					// System.out.println("isBlackMinimum");
					used[j] = true;
					af++;
					break;
				}
				if (bf + 1 == w[j]) {
					// System.out.println("isWhiteMinimum");
					used[j] = true;
					bf++;
					break;
				}

				ans++;

			}
		}
		return ans;
	}
}

package chap16;
import java.io.*;
import java.util.*;
import java.math.*;
// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    long mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){
        int n = ni();
        int res[][] = new int[2*n][2];
        for(int i = 0; i < 2*n; i++) {
        	String[] s = ns().split(" ");
        	res[i][0] = s[0].equals("W") ? 0 : 1;
        	res[i][1] = Integer.parseInt(s[1])-1;
        }
        int[][] whiteupper = new int[2*n][n+1];
        int[][] blackupper = new int[2*n][n+1];
        for(int i = 0; i < 2*n; i++) {
        	for(int j = 0; j <= n; j++) {
        		if(i>0) whiteupper[i][j]=whiteupper[i-1][j];
        		if(i>0) blackupper[i][j]=blackupper[i-1][j];
        	}
        	if(res[i][0]==0) {
        		for(int j = 0; j <= res[i][1]; j++) {
        			whiteupper[i][j]++;
        		}
        	}
        	else {
        		for(int j = 0; j <= res[i][1]; j++) {
        			blackupper[i][j]++;
        		}
        	}
        }
        int[] wplace = new int[n];
        int[] bplace = new int[n];
        for(int i = 0; i < 2*n; i++) {
        	if(res[i][0]==0) wplace[res[i][1]] = i;
        	else bplace[res[i][1]] = i;
        }
        long[][] dp = new long[n+1][n+1];
        for(int i = 0; i <= n; i++) {
        	Arrays.fill(dp[i], inf);
        }
        dp[0][0] = 0;
        for(int i = 0; i <= n; i++) {
        	for(int j = 0; j <= n; j++) {
        		if(i>0) dp[i][j] = dp[i-1][j] + whiteupper[wplace[i-1]][i]+ 
        				blackupper[wplace[i-1]][j];
        		if(j>0) dp[i][j] = Math.min(dp[i][j], dp[i][j-1] + 
        				blackupper[bplace[j-1]][j]+
        				whiteupper[bplace[j-1]][i]);
        	}
        }
        out.println(dp[n][n]);
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

