			BIT[] bbits = new BIT[n+1];
			for(int i = 0; i < bbits.length; i++) {
				bbits[i] = new BIT(2*n);
				for(int j = 0; j < i; j++) {
					bbits[i].update(bRev[j], 1);
				}
			}
			BIT[] wbits = new BIT[n+1];
			for(int i = 0; i < wbits.length; i++) {
