				for(int j = 0; j < i; j++) {
					wbits[i].update(wRev[j], 1);
				}
			}
			long[][] dp = new long[n+1][n+1];
			for(int a = 0; a < dp.length; a++) {
				Arrays.fill(dp[a], 1L << 50);
