            var B = new int[n];
            for (int i = 0; i < 2 * n; i++)
            {
                var s = rs;
                var v = ri - 1;
                if (s == "W") W[v] = i;
                else B[v] = i;
            }
            var add = 0L;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                {
                    if (W[i] > W[j]) add++;
                    if (B[i] > B[j]) add++;
                }


            //白のボール i より手前にある j 以上の黒のボールの数
            var f = new long[n + 1, n + 1];
            //黒のボール i より手前にある j 以上の白のボールの数
            var g = new long[n + 1, n + 1];

            var ws = new Set<int>();
            var bs = new Set<int>();
            for (int i = 0; i < n; i++)
            {
                ws.Add(W[i]); bs.Add(B[i]);
            }
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    var lb1 = ws.LowerBound(B[j]);
                    var lb2 = bs.LowerBound(W[j]);
                    g[j, i] = lb1;
                    f[j, i] = lb2;
                }
                ws.Remove(W[i]); bs.Remove(B[i]);
            }

            var dp = new long[n + 2, n + 2];
            for (int i = 0; i <= n; i++)
                for (int j = 0; j <= n; j++)
                    dp[i, j] = INF;
            dp[0, 0] = 0;
            for (int i = 0; i <= n; i++)
                for (int j = 0; j <= n; j++)
                {
                    dp[i + 1, j] = Min(dp[i + 1, j], dp[i, j] + f[i, j]);
                    dp[i, j + 1] = Min(dp[i, j + 1], dp[i, j] + g[j, i]);
                }

            Console.WriteLine(dp[n, n] + add);
        }
