    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int[] white = new int[N];
        int[] black = new int[N];
        for(int i=0;i<2*N;i++){
            if(re.s() == "W"){
                white[re.i()-1] = i;
            }
            else{
                black[re.i()-1] = i;
            }
        }
        int wp = 0;
        int bp = 0;
        int p = 0;
        int[] whiteafter = new int[N];
        int[] blackafter = new int[N];
        while(bp != N || wp != N){
            if(bp == N){
                whiteafter[wp] = p;
                wp++;
            }
            else if(wp == N){
                blackafter[bp] = p;
                bp++;
            }
            else{
                if(black[bp] < white[wp]){
                    blackafter[bp] = p;
                    bp++;
                }
                else{
                    whiteafter[wp] = p;
                    wp++;
                }
            }
            p++;
        }
        int[] F = new int[2*N];
        int[] T = new int[2*N];
        for(int i=0;i<N;i++){
            F[white[i]] = i;
            T[whiteafter[i]] = i;
            F[black[i]] = i+N;
            T[blackafter[i]] = i+N;
        }
        sb.Append(Swap(F,T,2*N)+"\n");
    }
    long Swap(int[] F,int[] T,int N){
        int[] newArray = new int[N];
        int[] FS = new int[N];
        int[] TS = new int[N];
        for(int i=0;i<N;i++){
            FS[F[i]] = i;
            TS[T[i]] = i;
        }
        for(int i=0;i<N;i++){
            newArray[FS[i]] = TS[i];
        }
        return Swap(newArray,N);
    }
    long Swap(int[] P, int N){
        SegTree Seg = new SegTree(N,this);
        long ans = 0;
        for(int i=0;i<N;i++){
            ans += Seg.Sum(P[i],N-1);
            Seg.Add(P[i]);
        }
        return ans;
    }
}
struct SegTree{
    Solve Sol;
    public int[] X;
    int C;
    //葉の最初の場所
    public int segf;
    //segfのbit
    public int segfb;
    //葉の深さの内浅い方
    public int depth;
    //浅い葉の内座標が最大のもの
    public int borderP;
    //はみ出すものの数
    public int border;
    public SegTree(int N,Solve So){
        Sol = So;
        C = 0;
        X = new int[2*N-1];
        for(depth = 1;(1 << depth) <= N;depth++){
            ;
        }
        segf = N-1;
        borderP = (1 << depth) - 2;
        border = 2*N - borderP - 2;
        segfb = border/2;
    }
    public int ToBit(int p){
        if(p >= border){
            return segfb + p - border;
        }
        else{
            return p;
        }
    }
    //葉のある場所
    public int ToLeaf(int p){
        if(p >= border){
            return segf + p - border;
        }
        else{
            return borderP + p + 1;
        }
    }
    //葉の示す頂点
    public int ToPoint(int leaf){
        if(leaf > borderP){
            return leaf - borderP - 1;
        }
        else{
            return leaf - segf + border;
        }
    }
    public void Add(int p){
        //葉の作業
        X[ToLeaf(p)]++;
        //親の作業
        for(int v=ToLeaf(p);v!=0;v=(v-1)/2){
            int spa = (v-1)/2;
            int sl = (v-1)/2*2+1;
            int sr = (v-1)/2*2+2;
            X[spa]++;
        }
    }

    //vの子の内bより大きいものに(bは子孫,bはToBitしたもの)
    void More(int b,int v,int depth){
        if((b & (1 << depth)) == 0){
            //右の子は全てbより大きい
            if(((b+1) % (1 << depth)) != 0){
                More(b,v*2+1,depth-1);
                Act(v*2+2);
            }
            else{
                Act(v*2+2);
            }
        }
        else{
            //左の子は全てb未満
            More(b,v*2+2,depth-1);
        }
    }
    //vの子の内bより小さなものに(bは子孫,bはToBitしたもの)
    void Less(int b,int v,int depth){
        if((b & (1 << depth)) == 0){
            //右の子は全てbより大きい
            Less(b,v*2+1,depth-1);
        }
        else{
            //左の子は全てb未満
            if(b % (1 << depth) != 0){
                Act(v*2+1);
                Less(b,v*2+2,depth-1);
            }
            else{
                //右の子は全てb以上
                Act(v*2+1);
            }
        }
    }
    void Section(int bl,int br,int v,int dl,int dr){
        if(v >= segf){
            //葉
            Act(v);
        }
        else{
            if((bl & (1 << dl)) == 0 && (br & (1 << dr)) == 0){
                //両方左
                Section(bl,br,v*2+1,dl-1,dr-1);
            }
            else if((bl & (1 << dl)) != 0 && (br & (1 << dr)) != 0){
                //両方右
                Section(bl,br,v*2+2,dl-1,dr-1);
            }
            else{
                //左と右に分かれた
                if(bl % (1 << dl) != 0){
                    More(bl-1,v*2+1,dl-1);
                }
                else{
                    //左は全て含まれる
                    Act(v*2+1);
                }
                if((br + 1) % (1 << dl) != 0){
                    Less(br+1,v*2+2,dr-1);
                }
                else{
                    //右は全て含まれる
                    Act(v*2+2);
                }
            }
        }
    }
    public int Sum(int l0,int r0){
        C = 0;
        int bl = ToBit(l0);
        int br = ToBit(r0);
        int dl = l0 >= border ? depth - 2 : depth - 1;
        int dr = r0 >= border ? depth - 2 : depth - 1;
        Section(bl,br,0,dl,dr);
        return C;
    }
    void Act(int v){
        C += X[v];
    }
}
