namespace ARC097E {
    class Program {
        static void Main(string[] args) {
            int N = int.Parse(Console.ReadLine());
            List<ball> balls = new List<ball>();
            for (int i = 0; i < 2 * N; i++) {
                string[] input = Console.ReadLine().Split(' ').ToArray();
                string A = input[0];
                int B = int.Parse(input[1]);
                ball bb = new ball();
                bb.num = B;
                bb.color = (A == "B") ? true : false;
                balls.Add(bb);
            }
            int blp = N;
            int whp = N;
            int ans = 0;
            while (blp > 0 || whp > 0) {
                int num = 0;
                int blnum = 0;
                int blres = 0;
                int whnum = 0;
                int whres = 0;
                List<int> bls = new List<int>();
                List<int> whs = new List<int>();
                int blmax = 100000;
                int whmax = 100000;
                List<List<int>> bl = new List<List<int>>();
                List<int> blx = new List<int>();
                List<List<int>> wh = new List<List<int>>();
                List<int> whx = new List<int>();
                for (int i = 0; i < 2 * N; i++) {
                    ball b = balls[i];
                    if (balls[i].color) {
                        if (b.num > blmax || blmax == 100000) {
                            blmax = b.num;
                        }
                        blnum++;
                        bls.Add(i);
                        blres += i - num - blnum;
                    } else {
                        if (b.num > whmax || whmax == 100000) {
                            whmax = b.num;
                        }
                        whnum++;
                        whs.Add(i);
                        whres += i - num - whnum;
                    }
                    if (blmax == blnum) {
                        int j = 1;
                        while (i + j < 2 * N) {
                            ball c = balls[i + j];
                            if (!c.color) {
                                if (b.num > whmax) {
                                    whmax = b.num;
                                }
                                whnum++;
                                whs.Add(i);
                                whres += i - num - whnum;
                            }
                            if (whmax == whnum) {
                                break;
                            }
                        }
                        if (blres < whres) {
                            int x = solve(bls.ToArray());
                            ans += x + blres;
                            for (int k = bls.Count - 1; k >= 0; k--) {
                                balls.RemoveAt(bls[k]);
                            }
                        } else {
                            int x = solve(whs.ToArray());
                            ans += x + whres;
                            for (int k = whs.Count - 1; k >= 0; k--) {
                                balls.RemoveAt(whs[k]);
                            }
                        }
                        break;
                    }
                }
            }
            Console.WriteLine(ans);
        }

        public static int solve(int[] sort) {
            List<int> li = sort.ToList();
            int k = 1;
            int ans = 0;
            while(li.Count > 0) {
                for(int i = 0; i < li.Count; i++) {
                    if(li[i] == k) {
                        ans += i;
                        li.RemoveAt(i);
                        break;
                    }
                }
            }
            return ans;
        }

        class ball {
            public int num;
            public bool color;
        }
    }
