				int done = N - bb + N - ww;

				// choose next w
				if(ww > 0){
					int ii = Winv[ww - 1];
					int lw = SW[ii][ww - 1];
					int lb = SB[ii][bb];
					int r = NN - done - lw - lb - 1;

					int npos = bb * M + (ww - 1);
					min[npos] = Math.Min(min[npos], cost + r);
				}

				// choose next b
				if(bb > 0){
					int ii = Binv[bb - 1];
					int lw = SW[ii][ww];
					int lb = SB[ii][bb - 1];
					int r = NN - done - lw - lb - 1;

					int npos = (bb - 1) * M + ww;
					min[npos] = Math.Min(min[npos], cost + r);
				}
			}
		}

		Console.WriteLine(min[0]);


	}
	int NN;

	int N;
	char[] C;
	int[] A;
	public Sol(){
		N = ri();
		NN = N * 2;
		C = new char[NN];
		A = new int[NN];
		for(int i=0;i<NN;i++){
			var ss = rsa();
			C[i] = ss[0][0];
			A[i] = int.Parse(ss[1]) - 1;
		}
