class Solver
{
    int[][] ctw, ctb;
    int[] invw, invb;
    Pi[] rw,rb;

    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        ctw = Create(N+1,()=>new int[N+1]); ctb=Create(N+1,()=>new int[N+1]); //iが書かれているボールよりも左にある、jより大きいの数が書かれている自分とは違う色のボールが何個あるか
        invw = new int[N + 1]; invb = new int[N + 1];//各色での転倒数
        rw = new Pi[N+1]; rb = new Pi[N + 1];
        rw[0] = new Pi(-1, 0);
        rb[0] = new Pi(-1, 0);
        for (int i = 0; i < N * 2; i++)
        {
            char c; int a;
            sc.Make(out c, out a); 
            if (c == 'W')
            {
                rw[a] = new Pi(i, a);
            }
            else
            {
                rb[a] = new Pi(i, a);
            }
        }
        Array.Sort(rw, (a, b) => a.v1 - b.v1);
        Array.Sort(rb, (a, b) => a.v1 - b.v1);
        InversionNumber(rw.Skip(1).Select(v => v.v2).ToArray(), invw);
        InversionNumber(rb.Skip(1).Select(v => v.v2).ToArray(), invb);
        {
            var idx = 0;
            var use = new bool[N + 1];
            for (int i = 1; i <= N; i++)
            {
                while (idx <= N && rb[idx].v1 < rw[i].v1)
                {
                    use[rb[idx].v2] = true;
                    idx++;
                }
                var ct = 0;
                for (int j = N - 1; j >= 0; j--)
                {
                    ct += ToInt32(use[j + 1]);
                    ctw[rw[i].v2][j] = ct;
                }
            }
        }
        {
            var idx = 0;
            var use = new bool[N + 1];
            for (int i = 1; i <= N; i++)
            {
                while (idx <= N && rw[idx].v1 < rb[i].v1)
                {
                    use[rw[idx].v2] = true;
                    idx++;
                }
                var ct = 0;
                for (int j = N - 1; j >= 0; j--)
                {
                    ct += ToInt32(use[j + 1]);
                    ctb[rb[i].v2][j] = ct;
                }
            }
        }
        //白をi個,黒をj個並べたときの最小値
        var dp = Create(N + 1, () => Create(N+1,()=>int.MaxValue/2));
        dp[0][0] = 0;
        for (int i = 0; i <= N; i++)
            for (int j = 0; j <= N; j++)
            {
                if (i > 0)
                {
                    chmin(ref dp[i][j], dp[i - 1][j] + invw[i] + ctw[i][j]);
                }
                if (j > 0)
                {
                    chmin(ref dp[i][j], dp[i][j - 1] + invb[j] + ctb[j][i]);
                }
            }
        WriteLine(dp[N][N]);
    }
    public static long InversionNumber(int[] A,int[] ct)
    {
        var bit = new BIT(A.Length + 1);
        var res = 0L;
        for (var i = 0; i < A.Length; i++)
        {
            var t = bit[A[i]];
            t = i - t;
            bit.add(A[i], 1);
            ct[A[i]] = (int)t;
            res += t;
        }
        return res;
    }
}

public class BIT
{
    //1-indexed
    long[] data;
    public BIT(int num)
    {
        data = new long[num + 1];
    }
    public long this[int index]
    {
        get { var s = 0L; for (var i = index; i > 0; i -= i & -i) s += data[i]; return s; }
    }
    public void add(int index, long value)
    {
        for (var i = index; i < data.Length; i += i & -i) data[i] += value;
    }
}
