class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var p = new P[n * 2];
        var idx = new int[2][];
        for (int i = 0; i < 2; i++)
        {
            idx[i] = new int[n];
        }
        for (int i = 0; i < n * 2; i++)
        {
            char c;
            int a;
            sc.Multi(out c, out a);
            int cc = c == 'B' ? 0 : 1;
            --a;
            p[i] = new P(cc, a);
            idx[cc][a] = i;
        }
        int ans = 0;
        int b = 0, w = 0;
        while (b < n || w < n) {
            if (w == n || b < n && idx[0][b] < idx[1][w]) {
                for (int i = idx[0][b] - 1; i >= 0 ; i--)
                {
                    if (p[i].v1 == 0 && p[i].v2 > b || p[i].v1 == 1 && p[i].v2 > w) {
                        ++ans;
                    }
                }
                ++b;
            }
            else {
                for (int i = idx[1][w] - 1; i >= 0 ; i--)
                {
                    if (p[i].v1 == 0 && p[i].v2 > b || p[i].v1 == 1 && p[i].v2 > w) {
                        ++ans;
                    }
                }
                ++w;
            }
        }
        Prt(ans);

    }
}

