    public void Run() {
        var n = ni();
        var c = new char[n * 2];
        var a = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            c[i] = ns()[0];
            a[i] = ni();
        }

        var blackPos = new int[n + 1];
        var whitePos = new int[n + 1];

        for (int i = 0; i < n * 2; i++) {
            if (c[i] == 'B') blackPos[a[i]] = i;
            if (c[i] == 'W') whitePos[a[i]] = i;
        }

        var memo = new int?[n + 2, n + 2];
        var bit = new BinaryIndexTree(2 * n);
        for (int i = 0; i < 2 * n; i++) {
            bit.Add(i, 1);
        }

        int dfs(int black, int white) {
            if (black == n + 1 && white == n + 1) return 0;
            ref var ret = ref memo[black, white];
            if (!ret.HasValue) {
                int val = int.MaxValue;

                if (black <= n) {
                    var pos = blackPos[black];
                    bit.Add(pos, -1);
                    var cost = (int)bit.Sum(0, pos + 1);
                    val = Math.Min(val, dfs(black + 1, white) + cost);
                    bit.Add(pos, +1);
                }

                if (white <= n) {
                    var pos = whitePos[white];
                    bit.Add(pos, -1);
                    var cost = (int)bit.Sum(0, pos + 1);
                    val = Math.Min(val, dfs(black, white + 1) + cost);
                    bit.Add(pos, +1);
                }
                ret = val;
            }
            return ret.Value;
        }

        cout.WriteLine(dfs(1, 1));
    }
}


public class BinaryIndexTree {
    private readonly long[] array;
    public BinaryIndexTree(int size) {
        array = new long[size];
    }
    public long Sum(int begin, int end) {
        if (begin != 0) {
            return Sum(0, end) - Sum(0, begin);
        }

        long val = 0;
        end--;
        for (; end >= 0; end = (end & (end + 1)) - 1) {
            val += array[end];
        }

        return val;
    }

    public void Add(int k, long val) {
        for (; k < array.Length; k |= k + 1) {
            array[k] += val;
        }
    }

    /// <summary>return min pos where sum(A[0] .. A[pos]) >= w</summary>
    public int LowerBound(long w) {
        if (w <= 0) {
            return 0;
        }

        int x = 0, k = 1, N = array.Length;
        while ((k << 1) <= N) {
            k <<= 1;
        }

        for (; k > 0; k >>= 1) {
            if (x + k - 1 < N && array[x + k - 1] < w) {
                w -= array[x + k - 1];
                x += k;
            }
        }
        return x;
    }
}


