    public long sum(int j) {
        long ret = 0;
        for (int i = j - 1; i >= 0; i = (i & i + 1) - 1) ret += bit[i];
        return ret;
    }
    // [j, k)
    public long sum(int j, int k) => sum(k) - sum(j);
}
