class Program
{
    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    private static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var pr = new Program();
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        memo = Enumerable.Repeat(0, num + 1).Select(_ => Enumerable.Repeat(-1L, num+1).ToArray()).ToArray();
        memo[0][0] = 0;
        wh = Enumerable.Repeat(0, num + 1).Select(_ => new long[num + 1]).ToArray();
        bl= Enumerable.Repeat(0, num + 1).Select(_ => new long[num + 1]).ToArray();
        var ball = new Pair<char, int>[num * 2];
        for (var i = 0; i < 2 * num; i++)
        {
            char c;int v;
            Input.Make(out c, out v);
            ball[i] = new Pair<char, int>(c,--v);
        }
        var b = new int[num];
        var w = new int[num];
        for(var i = 0; i < ball.Length; i++)
        {
            char c = ball[i].v1;int v = ball[i].v2;
            var bsum = new int[num + 1];
            var wsum = new int[num + 1];
            for(var j=num;j>0;j--)
            {
                bsum[j - 1] = bsum[j] + b[j - 1];
                wsum[j - 1] = wsum[j] + w[j - 1];
            }
            for (var j = num; j >= 0; j--)
                if (c == 'B') bl[v][j] = wsum[j] + bsum[v+1];
                else wh[v][j] = wsum[v+1] + bsum[j];
            if (c == 'B')
                b[v]++;
            else w[v]++;
        }
        WriteLine(dp(num, num));
        return;
    }
    long[][] memo;
    long[][] wh;
    long[][] bl;
    long dp(int i,int j)
    {
        if (memo[i][j] != -1) return memo[i][j];
        var m = long.MaxValue;
        if (i > 0) chmin(ref m, dp(i - 1, j) + wh[i-1][j]);
        if (j > 0) chmin(ref m, dp(i, j - 1) + wh[i][j-1]);
        return memo[i][j] = m;
    }
}

