class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        var idx = new int[2][];
        var a = new P[n * 2];
        var uc = new int[2][][];
        for (int i = 0; i < 2; i++)
        {
            idx[i] = new int[n];
            uc[i] = new int[n][];
        }

        for (int i = 0; i < n * 2; i++)
        {
            char c;
            int b;
            sc.Multi(out c, out b);
            --b;
            int d = c == 'W' ? 0 : 1;
            a[i] = new P(d, b);
            idx[d][b] = i;
            uc[d][b] = new int[n + 1];
            for (int j = 0; j < i; j++)
            {
                if (a[j].v1 == d) {
                    if (a[j].v2 > b) ++uc[d][b][n];
                }
                else {
                    ++uc[d][b][a[j].v2];
                }
            }
            for (int j = n - 1; j >= 0 ; j--)
            {
                uc[d][b][j] += uc[d][b][j + 1];
            }
        }
        var dp = new int[n + 1][];
        for (int i = 0; i < n + 1; i++)
        {
            dp[i] = new int[n + 1];
            for (int j = 0; j < n + 1; j++)
            {
                dp[i][j] = M;
            }
        }
        dp[0][0] = 0;
        for (int i = 0; i < n + 1; i++)
        {
            for (int j = 0; j < n + 1; j++)
            {
                if (i < n) {
                    dp[i + 1][j] = Math.Min(dp[i + 1][j], dp[i][j] + uc[0][i][j]);
                }
                if (j < n) {
                    dp[i][j + 1] = Math.Min(dp[i][j + 1], dp[i][j] + uc[1][j][i]);
                }
            }
        }
        Prt(dp[n][n]);

    }
}

