    static void Main()
    {
        int n = sc.Int;
        var wind = new int[n];
        var bind = new int[n];
        for (int i = 0; i < n * 2; i++)
        {
            char c;
            int p;
            sc.Multi(out c, out p);
            --p;
            if (c == 'W') {
                wind[p] = i;
            }
            else {
                bind[p] = i;
            }
        }
        long ans = 0;
        int w = 0, b = 0;
        var bit = new BIT(n * 2);
        while (w < n || b < n)
        {
            if (w == n) {
                ans += bind[b] - bit.sum(bind[b]);
                bit.add(bind[b], 1);
                ++b;
                continue;
            }
            if (b == n) {
                ans += wind[w] - bit.sum(wind[w]);
                bit.add(wind[w], 1);
                ++w;
                continue;
            }
            long bc = bind[b] - bit.sum(bind[b]);
            long wc = wind[w] - bit.sum(wind[w]);
            if (bc < wc) {
                ans += bc;
                bit.add(bind[b], 1);
                ++b;
            }
            else {
                ans += wc;
                bit.add(wind[w], 1);
                ++w;
            }
        }
