type BinaryIndexedTree []int
func (BIT BinaryIndexedTree) Get(idx int) int {
  b := 0
  for i := idx; 0 < i; i -= i & (-i) {
    b += BIT[i]
  }
  return b
}
func (BIT *BinaryIndexedTree) Update(idx, v int) {
  N := len((*BIT))
  d := v - BIT.Get(idx) + BIT.Get(idx - 1)
  for i := idx; i < N; i += i & (-i) {
    (*BIT)[i] += d
  }
}
func (BIT BinaryIndexedTree) Query(s, t int) int {
  return BIT.Get(t) - BIT.Get(s)
}
func (BIT *BinaryIndexedTree) Increment(idx int) {
  N := len((*BIT))
  for i := idx; i < N; i += i & (-i) {
    (*BIT)[i]++
  }
}

func InitBIT(N int) BinaryIndexedTree {
  BIT := make([]int, N + 1)
  return BIT
}

type Balls [][]int
func (B Balls) Len() int { return len(B) }
func (B Balls) Less(i, j int) bool { return B[i][0] < B[j][0] }
func (B Balls) Swap(i, j int) { B[i], B[j] = B[j], B[i] }

func Solve() {
  N := NextInt()
  B := make([][]int, 0)
  W := make([][]int, 0)
  for i := 0; i < 2 * N; i++ {
    CA := strings.Split(NextLine(), " ")
    A, _ := strconv.Atoi(CA[1])
    if CA[0] == "B" {
      B = append(B, []int{A, i + 1})
    } else {
      W = append(W, []int{A, i + 1})
    }
  }
  sort.Sort(sort.Reverse(Balls(B)))
  sort.Sort(sort.Reverse(Balls(W)))
  BITB := InitBIT(2 * N)
  BITW := InitBIT(2 * N)
  CB := make([][]int, N)
  CW := make([][]int, N)
  for i := range CB {
    CB[i] = make([]int, N + 1)
    CW[i] = make([]int, N + 1)
  }
  for i := range CB {
    CB[N - 1 - i][0] = BITB.Query(0, B[i][1])
    BITB.Increment(B[i][1])
    CW[N - 1 - i][0] = BITW.Query(0, W[i][1])
    BITW.Increment(W[i][1])
    for j := range CB[i][1:] {
      CB[N - 1 - i][j + 1] += CB[N - 1 - i][j]
      if B[i][1] < W[N - 1 - j][1] { CB[N - 1 - i][j + 1]++ }
      CW[N - 1 - i][j + 1] += CW[N - 1 - i][j]
      if W[i][1] < B[N - 1 - j][1] { CW[N - 1 - i][j + 1]++ }
    }
  }
  DP := make([][]int, N + 1)
  for i := range DP {
    DP[i] = make([]int, N + 1)
    for j := range DP[i] {
      DP[i][j] = N * N * N
    }
  }
  DP[0][0] = 0
  for i := range DP {
    for j := range DP[i] {
      if 0 < i { DP[i][j] = MinInt(DP[i - 1][j] + CB[i - 1][j], DP[i][j]) }
      if 0 < j { DP[i][j] = MinInt(DP[i][j - 1] + CW[j - 1][i], DP[i][j]) }
    }
  }
  Write(DP[N][N])
  return
}

func main() {
  Solve()
  Output()
}

