func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	dp := makeGrid(n+1, n+1)
	ww := makeGrid(n<<1+1, n+1)
	bb := makeGrid(n<<1+1, n+1)

	wa := map[int]int{}
	ba := map[int]int{}
	for i := 0; i < n<<1; i++ {
		c := getNextString(scanner)
		a := getNextInt(scanner)
		if c == "W" {
			ww[i+1][a]++
			wa[a] = i
			continue
		}
		bb[i+1][a]++
		ba[a] = i
	}
	for i := 0; i < n<<1+1; i++ {
		for j := 0; j < n; j++ {
			ww[i][j+1] += ww[i][j]
			bb[i][j+1] += bb[i][j]
		}
	}
	for j := 0; j < n+1; j++ {
		for i := 0; i < n<<1; i++ {
			ww[i+1][j] += ww[i][j]
			bb[i+1][j] += bb[i][j]
		}
	}
	for i := 0; i < n+1; i++ {
		for j := 0; j < n+1; j++ {
			dp[i][j] = math.MaxInt32
		}
	}
	dp[0][0] = 0
	for w := 0; w < n+1; w++ {
		for b := 0; b < n+1; b++ {
			if w < n {
				dp[w+1][b] = min(dp[w+1][b], dp[w][b]+cost(n, w, b, wa[w+1], wa[w+1], ww, bb))
			}
			if b < n {
				dp[w][b+1] = min(dp[w][b+1], dp[w][b]+cost(n, w, b, ba[b+1], ba[b+1], ww, bb))
			}
		}
	}
	fmt.Fprintln(writer, dp[n][n])
}

func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func cost(n, w, b, wi, bi int, ww, bb [][]int) int {
	costw := ww[n<<1][w] - ww[wi][w]
	costb := bb[n<<1][b] - bb[bi][b]
	return costw + costb
}

