//最大流、O(|V||E|^2)
template Flow_Dinic() {
    class Edge {
    public:
        this(long to, long capacity) {
            this.to = to;
            this.capacity = capacity;
        }
        long to;
        long capacity;
        Edge reverse;
    }

    //gを残余グラフにする
    void residualise(Edge[][] g) {
        foreach(u; iota(g.length)) {
            foreach(e; g[u]) {
                if(e.capacity != 0) {
                    e.reverse = new Edge(u, 0);
                    e.reverse.reverse = e;
                    g[e.to] ~= e.reverse;
                }
            }
        }
    }

    const long INF = long.max / 2;

    //gは残余グラフ
    //gは計算の結果書き換わる
    long solve(Edge[][] g, long s, long t) {
        long ret;
        while(true) {
            auto level = new long[](g.length);
            level[] = INF;
            auto q = DList!long(s);
            level[s] = 0;
            //level graph
            auto lg = new Edge[][](g.length, 0);
            while(!q.empty()) {
                auto u = q.front();
                q.removeFront();
                if(u == t) {
                    break;
                }
                foreach(e; g[u]) {
                    if(e.capacity > 0 && level[e.to] >= level[u] + 1) {
                        level[e.to] = level[u] + 1;
                        q.insertBack(e.to);
                        lg[u] ~= e;
                    }
                }
            }
            if(level[t] == INF) {
                break;
            }
            auto iter = new long[](g.length);
            long dfs(long u, long c_min) {
                if(u == t) {
                    return c_min;
                }
                foreach(i; iota(iter[u], lg[u].length)) {
                    iter[u] = i;
                    long f = dfs(lg[u][i].to, min(c_min, lg[u][i].capacity));
                    if(f > 0) {
                        lg[u][i].capacity -= f;
                        lg[u][i].reverse.capacity += f;
                        return f;
                    }
                }
                return 0;
            }
            while(true) {
                long f = dfs(s, INF);
                if(f == 0) {
                    break;
                }
                ret += f;
            }
        }
        return ret;
    }
}

