enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

struct Ball{
    bool color;
    long value;
}

void main() {
    long N;
    scanln(N);
    Ball[] xs;
    xs = new Ball[2*N];
    foreach(i; 0..2*N) {
        char color;
        long value;
        scanln(color, value);
        xs[i].color = color=='B';
        xs[i].value = value - 1;
    }

    long[] as = new long[N];
    long[] bs = new long[N];
    foreach(i, x; xs) {
        (x.color ? as : bs)[x.value] = i;
    }

    long[][] fss = new long[][](N, N+1);
    foreach(k, x; xs) {
        foreach(i; 0..N) {
            if (k<=as[i]) continue;
            if (x.color && x.value>=i) continue;
            fss[i][x.color ? 0 : x.value+1]++;
        }
    }
    foreach(i; 0..N) foreach(j; 0..N) {
        fss[i][j+1] += fss[i][j];
    }

    long[][] gss = new long[][](N+1, N);
    foreach(k, x; xs) {
        foreach(j; 0..N) {
            if (k<=bs[j]) continue;
            if (!x.color && x.value>=j) continue;
            gss[!x.color ? 0 : x.value+1][j]++;
        }
    }
    foreach(j; 0..N) foreach(i; 0..N) {
        gss[i+1][j] += gss[i][j];
    }

    long[][] dp = (N+1).rep!(()=>(N+1).rep!(()=>INF));
    dp[0][0] = 0;

    foreach(i; 0..N+1) foreach(j; 0..N+1) {
        if (i<N) {
            dp[i+1][j] = min(dp[i+1][j], dp[i][j]+fss[i][j]);
        }
        if (j<N) {
            dp[i][j+1] = min(dp[i][j+1], dp[i][j]+gss[i][j]);
        }
    }

    dp[N][N].writeln;
}

