void main(){
  auto n = readLong();
  alias Ball = Tuple!(char, long);
  Ball[] ball;
  foreach(i; iota(2*n)) {
    char ci;
    long ai;
    readlnTo(ci, ai);
    ball ~= Ball(ci, ai);
  }

  // cb[k, l]: k番目まででlより大きい黒の数
  // cw[k, l]: k番目まででlより大きい白の数
  auto cb = new long[][](2*n, n+1);
  auto cw = new long[][](2*n, n+1);
  foreach(i; iota(2*n)) {
    if(i > 0) {
      cb[i] = cb[i-1].dup;
      cw[i] = cw[i-1].dup;
    }
    auto c = ball[i][0];
    auto num = ball[i][1];
    foreach(j; iota(num)) {
      if(c == 'W') {
        ++cw[i][j];
      } else {
        ++cb[i][j];
      }
    }
  }

  long[Ball] b2n;
  foreach(i; iota(2*n)) {
    b2n[ball[i]] = i;
  }

  // dp[i][j]: wをi個，bをj個置いたときの答え
  auto dp = new long[][](n+1, n+1);
  foreach(i; iota(n+1)) {
    foreach(j; iota(n+1)) {
      if(i == 0 && j == 0) {
        continue;
      }
      if(i == 0) {
        dp[i][j] = dp[i][j-1] + cb[b2n[Ball('B', j)]][j] + cw[b2n[Ball('B', j)]][i];
        continue;
      }
      if(j == 0) {
        dp[i][j] = dp[i-1][j] + cw[b2n[Ball('W', i)]][i] + cb[b2n[Ball('W', i)]][j];
        continue;
      }
      dp[i][j] = min(dp[i-1][j] + cw[b2n[Ball('W', i)]][i] + cb[b2n[Ball('W', i)]][j],
          dp[i][j-1] + cb[b2n[Ball('B', j)]][j] + cw[b2n[Ball('B', j)]][i]);
    }
  }
  writeln(dp[n][n]);
}

