pair<int,int>in[4005]; 
int ypa(int a,int b)
{
	if(a>n&&b>n)return 0;
	if (f[a][b]!=-1) return f[a][b];
	f[a][b]=1e8;
	if(a<=n)f[a][b]=min(f[a][b],ypa(a+1, b)+u[0][a+1][ar[0][a]]+u[1][b][ar[0][a]]);
	if(b<=n)f[a][b]=min(f[a][b],ypa(a, b+1)+u[0][a][ar[1][b]]+u[1][b+1][ar[1][b]]);
	return f[a][b];
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=2*n;++i)
	{
		string c;
		cin>>c>>in[i].second;
		in[i].first=(c=="B");
		ar[in[i].first][in[i].second]=i;
	}
	int t;
	for(int i=0;i<=1;i++)
	{
		for(int j=1;j<=n;j++)
		{
			t=0;
			for(int k=1;k<=2*n;k++)
			{
				if(in[k].first==i&&in[k].second>=j)
				{
					t++;
				}
				u[i][j][k]=t;
			}
		}
	}
	memset(f,-1,sizeof(f));
	printf("%d",ypa(1,1));
	return 0;
}

