void solve() {
    cin >> n;
    v.pb({0, 0});
    for (int i = 1; i <= 2 * n; ++i) {
        char c;
        int x;
        cin >> c >> x;
        pos[c == 'B'][x] = i;
        for (int j = 0; j <= n; ++j) {
            pref[0][i][j] = pref[0][i - 1][j];
            pref[1][i][j] = pref[1][i - 1][j];
