            ans += w[nw] - bit.sum(w[nw])
            bit_w.add(w[nw], -1)
            bit.add(w[nw], 1)
            nw += 1
        else:
            ans += b[nb] - bit.sum(b[nb])
            bit_b.add(b[nb], -1)
            bit.add(b[nb], 1)
            nb += 1

    if nw == n:
        np = nb
        r = b
    else:
        np = nw
        r = w

    for i in range(np, n):
        for j in range(i + 1, n):
            if r[j] < r[i]:
                ans += 1

    return ans


