def solve(f):
    n = f.read_int()
    b = [None] * (2*n)
    d = {}
    for i in xrange(2*n):
        ci, ai = f.read_str_list()
        b[i] = (ci, int(ai))
        d[(ci, int(ai))] = i+1

    bit = BinaryIndexedTree(2*n)
    for i in xrange(1,2*n+1):
        bit.add(i,1)

    dp = [[float('inf')]*(n+1) for _ in xrange(n+1)]
    dp[0][0] = 0

    for wi in xrange(n+1):
        for bi in xrange(n+1):
            if bi < n: dp[wi][bi+1] = min(dp[wi][bi+1], dp[wi][bi] + bit.sum(d[('B', bi+1)]-1))
            if wi < n: dp[wi+1][bi] = min(dp[wi+1][bi], dp[wi][bi] + bit.sum(d[('W', wi+1)]-1))
            if bi < n: bit.add(d[('B', bi+1)], -1)
        for bi in xrange(n):
            bit.add(d[('B', bi+1)], 1)
        if wi < n: bit.add(d[('W', wi+1)], -1)

    return dp[n][n]


class BinaryIndexedTree(object):
    """Binary Indexed Tree (1-indexed)"""
    def __init__(self, size, default=0):
        self.bit = [default for _ in range(size + 1)]
        self.size = size

    def sum(self, i):
        """sum 1 to i"""
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def add(self, i, x):
        """add x to bit[i]"""
        while i <= self.size:
            self.bit[i] += x
            i += i & -i


