def get_l(X, balls):
    if len(X):
        return balls.index(X[0])
    else:
        return 4000

def get_r(X, balls):
    if len(X):
        return balls.index(X[-1])
    else:
        return -4000

B = deque(["B{}".format(i) for i in range(1, N+1)])
W = deque(["W{}".format(i) for i in range(1, N+1)])

l = 0
r = 2*N-1
ans = 0

while l < r:
    bl = get_l(B, balls)
    wl = get_l(W, balls)
    br = get_r(B, balls)
    wr = get_r(W, balls)
    m = min(bl - l, wl - l, r - wr, r - br)

    if bl - l ==  m:
        if bl != l:
            ans += bl-l
            del balls[bl]
            balls.insert(l, B[0])
        B.popleft()
        l += 1
    elif wl - l ==  m:
        if wl != l:
            ans += wl-l
            del balls[wl]
            balls.insert(l, W[0])
        W.popleft()
        l += 1

    elif r - br ==  m:
        if br != r:
            ans += r - br
            balls.insert(r, B[-1])
            del balls[br]
        B.pop()
        r -= 1

    elif r - wr ==  m:
        if wr != r:
            ans += r - wr
            balls.insert(r, W[-1])
            del balls[wr]
        W.pop()
        r -= 1

print(ans)

