import heapq


class Bit:
    def __init__(self, n):
        self.size = n
        self.tree = [0] * n

    def sum(self, i):
        s = 0
        i -= 1
        while i >= 0:
            s += self.tree[i]
            i = (i & (i + 1)) - 1
        return s

    def add(self, i, x):
        while i < self.size:
            self.tree[i] += x
            i |= i + 1

INF = 10 ** 9

bit_w = None
bit_b = None


def solve(n, w, b):

    length_h = [[0] * (n + 1) for _ in range(n + 1)]
    length_v = [[0] * (n + 1) for _ in range(n + 1)]

    for y in range(n):
        for x in range(n):
            length_h[x][y] = bit_b.sum(w[x])
        bit_b.add(b[y], -1)
    for x in range(n):
        length_h[x][n] = bit_b.sum(w[x])

    for x in range(n):
        for y in range(n):
            length_v[x][y] = bit_w.sum(b[y])
        bit_w.add(w[x], -1)
    for y in range(n):
        length_v[n][y] = bit_w.sum(b[y])


    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    dist[0][0] = 0
    pq = []
    heapq.heappush(pq, (0, 0, 0))

    while pq:
        d, x, y = heapq.heappop(pq)
        if x < n:
            alt = dist[x][y] + length_h[x][y]
            if alt < dist[x + 1][y]:
                dist[x + 1][y] = alt
                heapq.heappush(pq, (alt, x + 1, y))
        if y < n:
            alt = dist[x][y] + length_v[x][y]
            if alt < dist[x][y + 1]:
                dist[x][y + 1] = alt
                heapq.heappush(pq, (alt, x, y + 1))

    ans = dist[n][n]
    for i in range(n):
        for j in range(i + 1, n):
            if w[j] < w[i]:
                ans += 1
            if b[j] < b[i]:
                ans += 1

    return ans


def main():
