fn main() {
    let n: usize = readln();
    let v: Vec<(String, usize)> = readlns(2 * n);
    let mut index_b: HashMap<usize, usize> = HashMap::new();
    let mut index_w: HashMap<usize, usize> = HashMap::new();

    let L = 63;
    let B = (v.len() + L - 1) / L;
    let mut bucket_b = vec![vec![0; n + 2]; B];
    let mut bucket_w = vec![vec![0; n + 2]; B];
    for (idx, &(ref c, x)) in v.iter().enumerate() {
        let b = idx / L;
        if c == "B" {
            bucket_b[b][x] += 1;
        } else {
            bucket_w[b][x] += 1;
        }
    }
    for i in 0..B {
        for j in (1..n + 1).rev() {
            bucket_b[i][j - 1] += bucket_b[i][j];
            bucket_w[i][j - 1] += bucket_w[i][j];
        }
    }

    for (idx, &(ref c, x)) in v.iter().enumerate() {
        if c == "B" {
            index_b.insert(x, idx);
        } else {
            index_w.insert(x, idx);
        }
    }

    let mut dp = vec![vec![1000000000000i64; n + 2]; n + 2];
    dp[1][1] = 0;

    for b in 1..n + 2 {
        for w in 1..n + 2 {
            if b <= n {
                let idx = index_b[&b];
                // count x >= b or x >= w in v[0, idx]
                let id = idx / L;
                let mut cost = 0;
                for i in 0..id {
                    cost += bucket_b[i][b];
                    cost += bucket_w[i][w];
                }
                let begin = id * L;
                for i in begin..idx {
                    if v[i].0 == "B" && v[i].1 >= b {
                        cost += 1;
                    }
                    if v[i].0 == "W" && v[i].1 >= w {
                        cost += 1;
                    }
                }
                dp[b + 1][w] = min(dp[b + 1][w], dp[b][w] + cost);
            }
            if w <= n {
                let idx = index_w[&w];
                // count x >= b or x > w in v[0, idx]
                let id = idx / L;
                let mut cost = 0;
                for i in 0..id {
                    cost += bucket_b[i][b];
                    cost += bucket_w[i][w];
                }
                let begin = id * L;
                for i in begin..idx {
                    if v[i].0 == "B" && v[i].1 >= b {
                        cost += 1;
                    }
                    if v[i].0 == "W" && v[i].1 >= w {
                        cost += 1;
                    }
                }
                dp[b][w + 1] = min(dp[b][w + 1], dp[b][w] + cost);
            }
        }
    }

    println!("{}", dp[n + 1][n + 1]);
}

