fn main() {
    input! {
        n: usize,
        balls: [(chars, usize1); 2*n]
    };
    let mut color = balls.iter().cloned().map(|x| ifv!(x.0[0] == 'B', 0, 1)).collect::<Vec<_>>();
    let mut number = balls.iter().cloned().map(|x| x.1).collect::<Vec<_>>();

    let mut lower = dvec!(0; 2, 2*n+1, n+1);
    for i in 1..2*n {
        for k in 0..2 {
            for j in 0..n+1 {
                lower[k][i][j] = lower[k][i-1][j];
            }
        }
        for j in number[i-1]+1..n+1 {
            lower[color[i-1]][i][j] += 1;
        }
    }

    let mut position = dvec!(0; 2, n);
    for i in 0..2*n {
        position[color[i]][number[i]] = i;
    }

    let INF = 1000000000i64;
    let mut dp = dvec!(INF; n+1, n+1);
    dp[0][0] = 0;
    for i in 0..n+1 {
        for j in 0..n+1 {
            let base = dp[i][j];
            let left = i+j;
            for k in 0..2 {
                let ti = i+(k^1);
                let tj = j+k;
                if ti > n || tj > n {
                    continue;
                }
                let num = ifv!(k == 0, i, j);
                let pos = position[k][num];
                let cost = (pos-lower[0][pos][ti]-lower[1][pos][tj]) as i64;
                dp[ti][tj] = min(dp[ti][tj], base+cost);
            }
        }
    }
    println!("{}", dp[n][n]);
}

