    for (&(ref color, index),p) in balls.iter().zip(0..2*n) {
        if color == &vec!['W'] {
            position[0][index] = p;
        } else {
            position[1][index] = p;
        }
    }
    let mut less_than = dvec!(0; 2, n+1, 2*n);
    for c in 0..2 {
