            B[a[i]] = i;
        }
    }

    const INF: usize = 1_000_000_000_000_000;
    let mut dp = vec![vec![INF; N + 1]; N + 1];
    dp[0][0] = 0;
    let mut x = vec![vec![0; N + 1]; N + 1];
    for i in 0..(N + 1) {
        x[i][0] = (0..W[i]).filter(|&k| c[k] == 'W' && a[k] > i).count()
            + (0..W[i]).filter(|&k| c[k] == 'B').count();
        for j in 1..(N + 1) {
            x[i][j] = if B[j] < W[i] {
                x[i][j - 1] - 1
            } else {
                x[i][j - 1]
            };
        }
    }
    let mut y = vec![vec![0; N + 1]; N + 1];
    for j in 0..(N + 1) {
        y[0][j] = (0..B[j]).filter(|&k| c[k] == 'B' && a[k] > j).count()
            + (0..B[j]).filter(|&k| c[k] == 'W').count();
        for i in 1..(N + 1) {
            y[i][j] = if W[i] < B[j] {
                y[i - 1][j] - 1
            } else {
                y[i - 1][j]
            };
        }
    }
    for i in 0..(N + 1) {
        for j in 0..(N + 1) {
            dp[i][j] = if i == 0 && j == 0 {
                0
            } else if i == 0 {
                dp[i][j - 1] + y[i][j]
            } else if j == 0 {
                dp[i - 1][j] + x[i][j]
            } else {
                std::cmp::min(dp[i][j - 1] + y[i][j], dp[i - 1][j] + x[i][j])
            };
        }
    }
    let ans = dp[N][N];

    println!("{}", ans);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

