    for i in 0..A.len(){
        for k in 0..B.len(){
            for j in 0..B[0].len(){
                C[i][j] += A[i][k]*B[k][j];
            }
        }
    }
    return C;
}


fn matpow2(A:&mut Vec<Vec<f64>>, n:usize) -> Vec<Vec<f64>>{
    let mut B = vec![vec![0.0;A.len()];A.len()];
    for i in 0..A.len(){
        B[i][i] = 1.0;
    }
    let mut n = n;
    let mut tmp = A.clone();
    while(n>0){
        if n&1 == 1{B = matmul2(&B, &tmp);}
        tmp = matmul2(&tmp, &tmp);
        n>>=1;
    }
    return B;
}
fn dijkstra(s:usize, g:&Vec<Vec<(usize, i64)>>)->Vec<i64>{
    let mut dist = vec![INF;g.len()];
    dist[s] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, s));
    while(h.len() != 0){
        let mut t = h.pop().unwrap();
        let mut d = t.0 * -1;
        let mut v = t.1;
        if dist[v]<d{
            continue;
        }
        for i in 0..g[v].len(){
            let n = g[v][i].0;
            let dd = g[v][i].1;
            if dist[n]>d+dd{
                dist[n] = d+dd;
                h.push((dist[n]*-1, n));
            }
        }
    }
    return dist;
}
fn base_number(n:usize, x:usize)->Vec<usize>{
    if n == 0{
        return vec![0];
    }
    let mut n = n;
    let mut res = vec![];
    let mut p = 0;
    while(true){
        if usize::pow(x, p)>n{
            break;
        }
        p+=1;
    }

    for i in (0..p).rev(){
        res.push(n/usize::pow(x, i));
        n = n-(n/usize::pow(x, i))*usize::pow(x, i);
    }

    return res
}
