    let is_b = cs[0].0 == 'B';
    let mut vs: Vec<_> = cs.iter().enumerate().map(|(i, v)|
        (if is_b && v.0 == 'B' { 0 } else { 1 }, v.1, i)
    ).collect();
    vs.sort();
    // debug!(vs);

    let mut ans = 0;
    for (_, _, idx) in vs {
        let mut swap = 0;
        let mut cur = idx;
        let mut found_swap = 0;

        while cur > 0 {
            cur -= 1;

            if cs[cur].0 != '-' {
                swap += 1;
            }

            // +1箇所を探す
            if cs[idx].0 == cs[cur].0 && cs[idx].1 < cs[cur].1 {
                found_swap = swap;
            }
        }

        // debug!(cs[idx], found_swap);
        ans += found_swap;
        cs[idx] = ('-', 0);
    }
    puts!("{}\n", ans);
