use std::cmp;

const INF: u32 = 1_000_000_000;

fn make_counts(balls: &[(usize, usize)], color: usize, x: usize) -> Vec<u32> {
    balls.iter().lscan(0, |&acc, &(c, a)| {
        if c == color && a >= x { acc + 1 } else { acc }
    }).skip(1).collect()
}

fn main() {
    read!(n = usize);
    let mut balls = Vec::new();
    let mut num_to_i = [vec![0; n], vec![0; n]];
    for (i, (c, a)) in read_lines::<(char, usize_)>().enumerate() {
        let c = if c == 'W' { 0 } else { 1 };
        balls.push((c, a));
        num_to_i[c][a] = i;
    }
    let count_ge: [Vec<Vec<u32>>; 2] = [
        (0..=n).map(|x| make_counts(&balls, 0, x)).collect(),
        (0..=n).map(|x| make_counts(&balls, 1, x)).collect()
    ];

    let mut init = vec![INF; n+1];
    init[0] = 0;
    let ans = iterate((0usize, init), |(k, memo)| {
        (k+1, (0..=n).map(|n_w| {
            if k+1 < n_w || n + n_w < k+1 {
                return INF;
            }
            let n_b = k+1 - n_w;
            let val1 = if n_w == 0 { INF } else {
                let i = num_to_i[0][n_w-1];
                memo[n_w-1] + count_ge[0][n_w][i] + count_ge[1][n_b][i]
            };
            let val2 = if n_b == 0 { INF } else {
                let i = num_to_i[1][n_b-1];
                memo[n_w] + count_ge[0][n_w][i] + count_ge[1][n_b][i]
            };
            cmp::min(val1, val2)
        }).collect())
    }).nth(2*n).unwrap().1.into_iter().min().unwrap();
    echo!(ans);
}

