pub const INF: u64 = 1 << 60;

fn solve() {
    let n = get!(usize);
    let ca = get!(String, usize; 2*n);

    let mut cost_b = vec![vec![0; n + 1]; n + 1];
    let mut cost_w = vec![vec![0; n + 1]; n + 1];

    let mut b = vec![0; n];
    let mut w = vec![0; n];

    for (i, (c, a)) in ca.into_iter().enumerate() {
        if c == "B" {
            b[a - 1] = i;
        } else {
            w[a - 1] = i;
        }
    }

    {
        for i in 0..n {
            let lb = b[i..].iter().filter(|&&x| x < b[i]).count();
            let mut left = (0..n).filter(|&j| w[j] < b[i]).collect::<HashSet<_>>();

            for j in 0..n + 1 {
                cost_b[i][j] = lb + left.len();
                left.remove(&j);
            }
        }
    }

    {
        for i in 0..n {
            let lw = w[i..].iter().filter(|&&x| x < w[i]).count();
            let mut left = (0..n).filter(|&j| b[j] < w[i]).collect::<HashSet<_>>();

            for j in 0..n + 1 {
                cost_w[j][i] = lw + left.len();
                left.remove(&j);
            }
        }
    }

    let mut dp = vec![vec![INF; n + 1]; n + 1];

    dp[0][0] = 0;
    for i in 0..n + 1 {
        for j in 0..n + 1 {
            if i > 0 {
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + cost_b[i - 1][j] as u64);
            }
            if j > 0 {
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + cost_w[i][j - 1] as u64);
            }
        }
    }

    println!("{}", dp[n][n]);
}

