    }

    let mut cnt_w = vec![vec![0; n + 1]; 2 * n + 1];
    for i in 1..2 * n + 1 {
        for j in 0..n {
            if i > 0 {
                cnt_w[i][j] = cnt_w[i - 1][j];
            }
            if !balls[i - 1].color && balls[i - 1].num >= j {
                cnt_w[i][j] += 1;
            }
        }
    }
    // println!("cnt_w {:?}", cnt_w);

    let mut cnt_b = vec![vec![0; n + 1]; 2 * n + 1];
    for i in 1..2 * n + 1 {
        for j in 0..n {
            if i > 0 {
                cnt_b[i][j] = cnt_b[i - 1][j];
            }
            if balls[i - 1].color && balls[i - 1].num >= j {
                cnt_b[i][j] += 1;
            }
        }
    }
    // println!("cnt_b {:?}", cnt_b);

    let mut idx_w = vec![0; n];
    let mut idx_b = vec![0; n];
    for i in 0..2 * n {
        if balls[i].color {
            idx_b[balls[i].num] = i;
        } else {
            idx_w[balls[i].num] = i;
        }
    }
    // println!("{:?}", idx_w);
    // println!("{:?}", idx_b);

    let mut dp = vec![vec![std::usize::MAX; n + 1]; n + 1];
    dp[0][0] = 0;

    for i in 0..n + 1 {
        for j in 0..n + 1 {
            if i > 0 {
                let i_w_pos = idx_w[i - 1];
                dp[i][j] = min(
                    dp[i - 1][j] + cnt_w[i_w_pos][i - 1] + cnt_b[i_w_pos][j],
                    dp[i][j],
                );
            }
            if j > 0 {
                let j_b_pos = idx_b[j - 1];
                dp[i][j] = min(
                    dp[i][j - 1] + cnt_w[j_b_pos][i] + cnt_b[j_b_pos][j - 1],
                    dp[i][j],
                );
            }
        }
    }
    // println!("{:?}", dp);
    println!("{}", dp[n][n]);
}

use std::cmp;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.read();
    let mut black_place = vec![0; n];
    let mut white_place = vec![0; n];
    for i in 0..(2 * n) {
        let c = sc.read::<String>();
        let a: usize = sc.read::<usize>() - 1;
        if c == "W" {
            white_place[a] = i;
        } else {
            black_place[a] = i;
        }
    }

    let back = |place: &Vec<usize>| {
        let mut min_back = vec![0; n];
        for i in 0..n {
            for j in 0..i {
                if place[i] < place[j] {
                    min_back[i] += 1;
                }
            }
        }
        min_back
    };

    let min_back_w = back(&white_place);
    let min_back_b = back(&black_place);

    let calc_cost = |place: &Vec<usize>, min_back: &Vec<usize>, other_place: &Vec<usize>| {
        let mut cost = vec![vec![0; n + 1]; n];
        for a in 0..n {
            let back = min_back[a];
            let place = place[a];
            cost[a][0] = back;
            for b in 0..n {
                cost[a][b + 1] = cost[a][b];
                if other_place[b] > place {
                    cost[a][b + 1] += 1;
                }
            }
        }
        cost
    };

    let cost_w = calc_cost(&white_place, &min_back_w, &black_place);
    let cost_b = calc_cost(&black_place, &min_back_b, &white_place);

    let mut dp = vec![vec![std::usize::MAX; n + 1]; n + 1];
    dp[0][0] = 0;
    for i in 0..(n + 1) {
        for j in 0..(n + 1) {
            if i < n {
                let white_place = white_place[i] + cost_w[i][j] - (i + j);
                dp[i + 1][j] = cmp::min(dp[i + 1][j], dp[i][j] + white_place);
            }

            if j < n {
                let black_place = black_place[j] + cost_b[j][i] - (i + j);
                dp[i][j + 1] = cmp::min(dp[i][j + 1], dp[i][j] + black_place);
            }
        }
    }
    println!("{}", dp[n][n]);
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

