fn base_number(n:usize, x:usize)->Vec<usize>{
    if n == 0{
        return vec![0];
    }
    let mut n = n;
    let mut res = vec![];
    let mut p = 0;
    while(true){
        if usize::pow(x, p)>n{
            break;
        }
        p+=1;
    }

    for i in (0..p).rev(){
        res.push(n/usize::pow(x, i));
        n = n-(n/usize::pow(x, i))*usize::pow(x, i);
    }

    return res
}
struct segtreei64{
    n: usize,
    dat: Vec<i64>,
    e:i64,
}
impl segtreei64
    {

        pub fn new(n_:usize, e:i64)->Self{
            let mut n = 1;
            while(n<n_){n*=2;}
            segtreei64{n: n, dat:vec![e; 2*n-1], e:e}
        }
        pub fn update(&mut self, k:usize, a:i64){
            let mut k = k;
            k += self.n-1;
            self.dat[k] = a;
            while(k>0){
                k = (k-1)/2;
                self.dat[k] = self.dat[k*2 + 1] + self.dat[k*2+2];
            }
        }
        pub fn query(&self, a:usize, b:usize, k:usize, l:usize, r:usize) -> i64{
            if r<=a || b<=l{return self.e;}
            if a<=l && r<=b{return self.dat[k];}
            else{
                let mut vl = self.query(a, b, k*2+1, l, (l+r)/2);
                let mut vr = self.query(a, b, k*2+2, (l+r)/2, r);
                return vl + vr;
            }
        }
    }
