    fn dfs(x:usize, y:usize, N:usize, a:&Vec<Vec<usize>>, b:&Vec<Vec<usize>>, dp:&mut Vec<Vec<i64>>, st:&mut segtreei64)->i64{
        if x==N && y == N{
            return 0;
        }
        if dp[x][y] != -1{
            return dp[x][y];
        }
        let mut res =  INF;
        if x<N{
            st.update(a[x][1], 1);
            res = cmp::min(res, dfs(x+1, y, N, a, b, dp, st)+a[x][1] as i64-st.query(0, a[x][1], 0, 0, st.n));
