use std::cmp::min;
fn main() {
    input! { n, ca: [(char, usize1); 2*n] };
    let mut bi = vec![0; n];
    let mut wi = vec![0; n];
    for i in 0..2 * n {
        if ca[i].0 == 'B' {
            bi[ca[i].1] = i + 1;
        } else {
            wi[ca[i].1] = i + 1;
        }
    }
    let mut dp = vec![vec![std::i64::MAX; n + 1]; n + 1];
    dp[0][0] = 0;
    let mut bit = BinaryIndexedTree::new(n * 2, AddGroup::new(0i64));
    for i in 0..n + 1 {
        for j in 0..n + 1 {
            let ni = i + 1;
            let nj = j + 1;
            if nj <= n {
                let k = wi[j];
                let d = i as i64 + j as i64 - bit.query(k);
                dp[i][nj] = min(dp[i][nj], dp[i][j] + d);
            }
            if ni <= n {
                let k = bi[i];
                let d = i as i64 + j as i64 - bit.query(k);
                dp[ni][j] = min(dp[ni][j], dp[i][j] + d);
            }
            if j < n {
                bit.update(wi[j], 1);
            }
        }
        if i < n {
            bit.update(bi[i], 1);
        }
        for j in 0..n {
            bit.set_val(wi[j], 0);
        }
    }
    println!("{}", dp[n][n]);
}
